window.__Q=window.__Q||{};window.__Q["prev/1/A1"]=[{"q":"对胆汁酸的描述，错误的是","o":["胆汁酸是胆固醇的主要转化产物","胆汁酸具有亲水性和疏水性","胆汁酸可分为初级胆汁酸和次级胆汁酸","胆汁酸可分为游离型和结合型","胆囊中的都是初级胆汁酸"],"a":4,"e":"胆囊中既有初级胆汁酸也有次级胆汁酸，次级胆汁酸由初级胆汁酸经肠菌作用生成；胆汁酸按来源、是否结合可分为不同类型。"},{"q":"己糖激酶以葡萄糖为底物时，Km=1/2[S]，其反应速率v是Vmax的","o":["9%","15%","33%","50%","67%"],"a":4,"e":"由米氏方程，v=Vmax［S］/（Km+［S］）；当Km=1/2［S］时，v=Vmax·［S］/1.5［S］，即反应速率为最大速率的67%。"},{"q":"具有四级结构的蛋白质特征是","o":["分子中必须含有辅基","两条或两条以上具有三级结构多肽链进一步折叠、盘曲形成","以肽键维系四级结构的稳定","每条多肽链都具有独立生物学活性","有两条或两条以上的多肽链组成"],"a":4,"e":"四级结构指两条或两条以上具有完整三级结构的亚基，通过非共价键聚合形成的空间结构，单链蛋白质无四级结构。"},{"q":"逆转录病毒基因组复制时所用的引物为","o":["RNA","DNA","tRNA","mRNA","不需要引物"],"a":2,"e":"逆转录病毒复制时以病毒自身tRNA作为引物，在逆转录酶催化下合成cDNA第一链，随后降解RNA并合成第二链。"},{"q":"在酶浓度和其他反应条件不变的情况下，反应速率v对底物浓度[S]作图可得到","o":["直线","S形曲线","矩形双曲线","抛物线","钟罩形曲线"],"a":2,"e":"酶浓度和其他条件恒定时，反应速率对底物浓度作图呈矩形双曲线，低底物浓度时为一级反应，高浓度时趋近Vmax呈零级反应。"},{"q":"矩形双曲线反映了受体-配体结合的","o":["高度专一性","高度亲和力","可饱和性","可逆性","特定的作用模式"],"a":2,"e":"受体数目有限，增加配体浓度可使结合达到饱和，饱和曲线呈矩形双曲线，反映受体-配体结合的可饱和性。"},{"q":"以下不属于次级胆汁酸的是","o":["脱氧胆酸","牛磺脱氧胆酸","鹅脱氧胆酸","石胆酸","甘氨脱氧胆酸"],"a":2,"e":"次级胆汁酸由初级胆汁酸经肠菌作用生成，包括脱氧胆酸、石胆酸及其与甘氨酸、牛磺酸的结合物；鹅脱氧胆酸属初级胆汁酸。"},{"q":"脂肪酸合成酶系存在于细胞的","o":["细胞质","微粒体","线粒体基质","线粒体内膜","溶酶体"],"a":0,"e":"脂肪酸合成酶系存在于细胞质，乙酰CoA经柠檬酸-丙酮酸循环转运至胞质参与合成；线粒体主要进行脂肪酸β-氧化。"},{"q":"下述序列中，在双链状态下属于完全回文结构的序列是","o":["CTGAGATC","AGTCAGTC","AGTCTGA","GACTCTGA","AGTCGACT"],"a":4,"e":"回文序列指两条链5′→3′方向序列完全相同；AGTCGACT的互补链按5′→3′读仍为AGTCGACT，故为完全回文结构，常作为Ⅱ型限制酶的识别位点。"},{"q":"基因比对主要包括核酸序列比对和下列哪项比对","o":["脂肪酸","单糖结构","多糖链","氨基酸","空间结构"],"a":3,"e":"基因比对包括核酸序列比对和氨基酸（蛋白质）序列比对，后者可据同源性推测编码产物的功能与进化关系，常用BLAST等程序完成。"},{"q":"下列组织不能氧化利用脂肪酸的是","o":["脑","心肌","肝脏","肾脏","肌肉"],"a":0,"e":"脑组织缺乏脂肪酸β-氧化酶系，不能氧化利用脂肪酸，但在葡萄糖不足时能有效利用酮体供能。"},{"q":"重组DNA技术中常用的属于限制性核酸内切酶的哪一类","o":["Ⅰ类酶","Ⅱ类酶","Ⅲ类酶","Ⅳ类酶","Ⅴ类酶"],"a":1,"e":"重组DNA技术中使用的限制酶通常指Ⅱ型酶，能识别回文序列并在识别位点内或其附近定点切割，产生黏性或平末端，便于与载体连接。"},{"q":"指出下列哪项是酵解过程中可被别构调节的限速酶","o":["磷酸己糖异构酶","6-磷酸果糖激酶-1","醛缩酶","3-磷酸甘油醛脱氢酶","乳酸脱氢酶"],"a":1,"e":"磷酸果糖激酶-1是糖酵解流量最重要的调控点，属别构酶，受ATP和柠檬酸别构抑制，受AMP、ADP及果糖-2，6-二磷酸别构激活，其活性直接决定酵解速率。"},{"q":"维生素B6作为酶的辅酶最重要的作用是","o":["参与氨基酸的合成、分解和互变","参与合成神经递质","参与合成δ-氨基-γ-酮基戊酸","参与合成尼克酸","作为糖原磷酸化酶组分，稳定酶分子"],"a":0,"e":"磷酸吡哆醛作为转氨酶和脱羧酶等的辅酶，参与氨基酸的转氨基、脱氨基及脱羧等代谢，是维生素B6最重要的作用。δ-氨基-γ-酮基戊酸合成仅为其部分功能。"},{"q":"原核生物基因表达调控的乳糖操纵子系统属于","o":["复制水平调节","转录水平调节","转录后水平调节","翻译水平调节","翻译后水平调节"],"a":1,"e":"乳糖操纵子通过阻遏蛋白的负性调节和CAP的正性调节控制结构基因的转录起始，属转录水平调节。"},{"q":"蛋白质生物合成时需要信号肽的过程是","o":["线粒体蛋白质的合成","多核糖体的合成","核糖体与mRNA附着","核糖体与内质网附着","肽从核糖体的释放"],"a":3,"e":"信号肽位于分泌蛋白新生肽链的N端，被信号识别颗粒识别后引导核糖体附着于内质网膜，使肽链进入内质网腔。"},{"q":"根据色氨酸和酪氨酸含量对蛋白质进行定量测定的方法为","o":["双缩脲反应","凯氏定氮法","茚三酮反应","紫外吸收法","考马斯亮蓝法"],"a":3,"e":"蛋白质中色氨酸、酪氨酸含共轭双键，在280nm处有特征性吸收峰，其吸光度与蛋白质浓度成正比，可用于定量测定。"},{"q":"DNA复制时，序列5'-TpApGpApCpT-3'指导合成的互补序列是","o":["5'-ApTpCpTpTpA-3'","5'-ApGpTpCpTpA-3'","5'-ApGpUpCpUpA-3'","3'-TpGpTpCpTpA-5'","5'-ApGpGpCpGpA-3'"],"a":1,"e":"按A配T、G配C的互补规则，模板5'-TpApGpApCpT-3'的互补链反向读为3'-ApTpCpTpGpA-5'，按5'→3'书写即ApGpTpCpTpA。"},{"q":"IPTG诱导乳糖操纵子表达的机制是","o":["使乳糖-阻遏蛋白复合物解离","与阻遏蛋白结合，使之丧失DNA结合能力","与乳糖竞争结合阻遏蛋白","与RNA聚合酶结合，使之通过操纵序列","变构修饰RNA聚合酶，提高其活性"],"a":1,"e":"IPTG作为别乳糖类似物与阻遏蛋白结合，使其构象改变而丧失与操纵序列结合的能力，从而解除阻遏、开放操纵子。乳糖本身需经β-半乳糖苷酶转化为别乳糖才起诱导作用。"},{"q":"维生素A参与视紫红质的形式是","o":["全反视黄醇","11-顺视黄醇","全反视黄醛","11-顺视黄醛","9-顺视黄醛"],"a":3,"e":"视紫红质由11-顺视黄醛与视蛋白结合而成，弱光下11-顺视黄醛异构为全反而激活视蛋白；11-顺视黄醛由全反式视黄醇经异构酶作用并氧化生成。"},{"q":"关于癌基因的叙述中错误的是","o":["是细胞增殖的正调节基因","可诱导细胞凋亡","能在体外引起细胞转化","能在体内诱发肿瘤","包括病毒癌基因和细胞癌基因"],"a":1,"e":"与细胞生存相关的原癌基因激活可抑制凋亡，而非诱导凋亡；抑癌基因过量表达才可诱导细胞凋亡。癌基因是细胞增殖的正调节基因，可在体外转化细胞、体内诱发肿瘤。"},{"q":"下列关于核酸理化性质叙述不正确的是","o":["氯化钠、乙醇可使核酸自溶液中沉淀下来","核酸具有两性解离性质","核酸与双缩脲试剂反应，溶液呈紫红色","核酸的线形分子比环形分子黏度要大得多","高温可以使DNA变性"],"a":2,"e":"双缩脲反应是肽键在碱性溶液中与硫酸铜生成的紫色反应，为蛋白质特有的呈色反应；核酸不含肽键，不能呈此反应。"},{"q":"真核生物在蛋白质生物合成中的起始tRNA是","o":["亮氨酰-tRNA","丙氨酰-tRNA","赖氨酰-tRNA","甲酰甲硫氨酰-tRNA","甲硫氨酰-tRNA"],"a":4,"e":"真核生物起始密码子AUG由专门起始tRNA（tRNAiMet）携带甲硫氨酸就位；原核生物则为甲酰甲硫氨酰-tRNA，二者结构不同。"},{"q":"下列激素具有抗脂解作用的是","o":["肾上腺素","胰高血糖素","ACTH","胰岛素","促甲状腺素"],"a":3,"e":"胰岛素能对抗脂解激素的作用、抑制脂肪动员，属抗脂解激素；肾上腺素、胰高血糖素、ACTH均属脂解激素。"},{"q":"下述哪两个酶是产生氮的直接供体，进入尿素生成通路","o":["精氨酸酶和精氨基琥珀酸裂解酶","黄嘌呤氧化酶和鸟嘌呤脱氨酶","谷氨酸脱氢酶和谷氨酰胺酶","精氨基琥珀酸合成酶和鸟氨酸转氨甲酰酶","天冬氨酸转氨酶和氨甲酰磷酸合成酶"],"a":4,"e":"尿素分子的两个氮分别来自氨和天冬氨酸：氨甲酰磷酸合成酶Ⅰ以游离氨为底物生成氨甲酰磷酸，天冬氨酸转氨酶不断生成天冬氨酸提供第二个氮。"},{"q":"以下哪种物质不是肝脏糖异生原料","o":["甘油","乙酰乙酸","谷氨酸","丙酮酸","乳酸"],"a":1,"e":"乙酰乙酸属酮体，分解生成乙酰CoA，不能净生成葡萄糖，故不是糖异生原料；甘油、谷氨酸、丙酮酸和乳酸均可异生为糖。"},{"q":"糖原的1个葡萄糖基经糖酵解可生成","o":["1个ATP","2个ATP","3个ATP","4个ATP","5或6个ATP"],"a":2,"e":"肌糖原中的1分子葡萄糖基经磷酸解生成葡萄糖-6-磷酸，绕过己糖激酶耗能步骤，经无氧氧化净产生3分子ATP。"},{"q":"对乳糖操纵子而言","o":["CAP是正性调节因素，阻遏蛋白是负性调节因素","CAP是负性调节因素，阻遏蛋白是正性调节因素","CAP和阻遏蛋白都是正性调节因素","CAP和阻遏蛋白都是负性调节因素","CAP和阻遏蛋白在不同的反应条件下，均显示是正性和负性双向调节因素"],"a":0,"e":"CAP与cAMP结合后结合于启动子上游，增强RNA聚合酶转录活性，属正性调节；阻遏蛋白结合操纵序列阻碍转录，属负性调节。"},{"q":"调控自身基因转录激活的DNA序列是","o":["顺式作用因子","顺式作用元件","反式作用因子","反式作用元件","顺/反式作用元件"],"a":1,"e":"顺式作用元件是可影响自身基因表达活性的DNA序列，包括启动子、增强子、沉默子及绝缘子。反式作用因子是识别结合该类序列的蛋白质，并非DNA序列。"},{"q":"乙酰CoA的代谢去路不包括","o":["进入三羧酸循环，彻底氧化为二氧化碳和水","羧化为丙二酰CoA，进一步合成脂酸","生成生酮氨基酸","生成酮体，作为能源","合成胆固醇"],"a":2,"e":"乙酰CoA可进入三羧酸循环氧化、羧化后合成脂肪酸、合成胆固醇和酮体；生酮氨基酸由氨基酸分解产生，不能由其转变而来。"},{"q":"下列对于血脂的叙述正确的是","o":["均不溶于水","主要以脂蛋白形式存在","都来自肝脏","与血细胞结合被运输","脂肪与清蛋白结合被转运"],"a":1,"e":"血脂包括胆固醇、甘油三酯、磷脂和游离脂肪酸，均以脂蛋白形式在血中运输和代谢。游离脂肪酸与清蛋白结合转运，脂蛋白中的脂质核心不溶于水但表面载脂蛋白使其具亲水性。"},{"q":"甲硫氨酸循环的需要维生素","o":["维生素PP","生物素","CoA","维生素B12","吡哆醛"],"a":3,"e":"维生素B12是钴胺素，参与甲基转移，作为甲硫氨酸合酶的辅酶使同型半胱氨酸甲基化生成甲硫氨酸，故甲硫氨酸循环需要维生素B12。"},{"q":"对于成熟的红细胞来说，最重要的一条代谢途径是","o":["磷酸戊糖途径","脂肪酸氧化","三羧酸循环","酮体合成","脂肪酸合成"],"a":0,"e":"成熟红细胞缺乏线粒体和细胞核，不能进行三羧酸循环和脂肪酸氧化，糖酵解是其供能途径，磷酸戊糖途径生成NADPH维持GSH还原状态以保护膜结构。"},{"q":"作用于细胞内受体的激素是","o":["甲状旁腺素","胰岛素","肾上腺素","干扰素","雌激素"],"a":4,"e":"雌激素属类固醇激素，脂溶性可透过细胞膜，与胞质或核内受体结合后调节靶基因转录；胰岛素、肾上腺素等肽类或胺类激素作用于膜受体。"},{"q":"利用几根毛发进行基因诊断主要体现了基因诊断的哪项特点","o":["特异性高","灵敏度高","稳定性好","应用范围广","早期诊断"],"a":1,"e":"基因诊断灵敏度高，核酸分子杂交与PCR技术联合可检测微量病原体基因及拷贝数极少的基因突变，故少量毛发即可完成检测。"},{"q":"转录生成的RNA，通常5'端第一个碱基是","o":["pppG","pppC","pppU","pppA","pppT"],"a":0,"e":"转录起始后起始核苷酸保留5′-端三个磷酸基团，第一个核苷酸多为GTP，故新生RNA的5′-端为pppG。"},{"q":"蛋白质分子中α-螺旋和β-折叠都属于","o":["一级结构","二级结构","三级结构","四级结构","五级结构"],"a":1,"e":"α-螺旋与β-折叠均指肽链主链局部原子的空间排布，不涉及氨基酸残基侧链构象，是蛋白质二级结构的主要形式。"},{"q":"合成糖蛋白糖链的酶存在于","o":["细胞核","细胞膜","细胞液","线粒体","内质网"],"a":4,"e":"糖基转移酶分布于内质网和高尔基体，催化糖链与肽链的连接及加工成熟，故合成糖蛋白糖链的酶存在于内质网。"},{"q":"全基因组鸟枪法测序的主要步骤，不包括","o":["建立基因组文库","高效大规模双向测序","序列组装","检测微卫星位点","缺口填补"],"a":3,"e":"全基因组鸟枪法包括构建BAC文库、大规模双向测序、序列组装和缺口填补；微卫星位点检测属遗传标记分析，不是测序步骤。"},{"q":"甘油氧化分解及其异生成糖的共同中间产物是","o":["丙酮酸","2-磷酸甘油酸","3-磷酸甘油酸","磷酸二羟丙酮","磷酸烯醇式丙酮酸"],"a":3,"e":"甘油经甘油激酶生成甘油-3-磷酸，脱氢后转变为磷酸二羟丙酮，后者既可循糖酵解分解，也可经糖异生转变为葡萄糖。"},{"q":"以下哪种胆汁酸不属于结合型次级胆汁酸","o":["甘氨石胆酸","牛磺鹅脱氧胆酸","牛磺脱氧胆酸","牛磺石胆酸","甘氨脱氧胆酸"],"a":1,"e":"牛磺鹅脱氧胆酸由初级胆汁酸鹅脱氧胆酸与牛磺酸结合生成，属初级结合型胆汁酸；甘氨石胆酸、牛磺脱氧胆酸、甘氨脱氧胆酸均由次级胆汁酸再结合而成。"},{"q":"关于痛风症的叙述，错误的是","o":["是指患者血中尿酸含量升高","尿酸盐晶体会沉积于关节、软组织、软骨、肾脏等处，导致关节炎、尿路结石及肾疾病等","多见于成年女性","分原发性和继发性","别嘌呤醇是主要的治疗药物"],"a":2,"e":"痛风多见于成年男性，尿酸盐结晶沉积于关节、软组织、软骨和肾，引起关节炎、尿路结石及肾病；别嘌呤醇抑制黄嘌呤氧化酶。"},{"q":"赖氨酸属于","o":["含硫氨基酸","碱性氨基酸","酸性氨基酸","含羟基的氨基酸","含芳香环的氨基酸"],"a":1,"e":"赖氨酸侧链含ε-氨基，属碱性氨基酸，生理pH下带正电荷；精氨酸、组氨酸同属碱性，天冬氨酸和谷氨酸则为酸性氨基酸。"},{"q":"鸟类和哺乳类维持体温的能量来源都是细胞呼吸。ATP在细胞中易于再生，所以是源源不断的能源。水解时释放出能量较多，是生物体内最直接的能量来源。生物体内ATP最主要的来源是","o":["糖酵解","三羧酸循环","磷酸戊糖途径","氧化磷酸化作用","底物水平磷酸化"],"a":3,"e":"呼吸链电子传递偶联ADP磷酸化生成ATP，是体内ATP最主要的来源，占生成总量的绝大部分。"},{"q":"合成一分子尿素需消耗高能磷酸键数目是","o":["1个","2个","3个","4个","5个"],"a":3,"e":"尿素合成中氨基甲酰磷酸合成酶Ⅰ消耗2个ATP，精氨酸代琥珀酸合成酶消耗1个ATP（AMP+PPi，相当2个高能键），共4个。"},{"q":"人类基因组中，编码蛋白质的基因大多数属于","o":["回文序列","卫星DNA","单拷贝序列","高度重复序列","中度重复序列"],"a":2,"e":"人类基因组中大多数编码蛋白质的基因属单拷贝序列（低度重复序列），其两侧常为散在分布的重复序列，其表达产物体现生物体的各种功能。"},{"q":"将1个完全被放射性标记的DNA分子放于无放射性标记的环境中复制三代后，所产生的全部DNA分子中，有放射性标记的DNA分子有","o":["1个","2个","4个","6个","8个"],"a":1,"e":"DNA复制为半保留复制，亲代两条标记链分别进入两个子代分子，故无论复制多少代，含放射性标记的DNA分子始终为2个。"},{"q":"维持DNA双螺旋稳定因素是","o":["核糖与碱基之间的糖苷键","碱基堆积力和氢键","碱基之间的磷酸二酯键","磷酸基团的亲水性","脱氧核糖上的羟基"],"a":1,"e":"DNA双螺旋的稳定性由互补碱基对间的氢键和疏水性碱基堆积力共同维持，前者维持碱基配对特异性，后者贡献主要稳定能量。"},{"q":"RNA在真核细胞DNA复制过程中所起的作用是","o":["DNA合成的模板","协助辨认复制起始位点","作为酶催化复制反应","参与复制终止阶段进程","作为引物"],"a":4,"e":"DNA复制需引物提供3′-OH末端，真核细胞中该引物为RNA，由引物酶合成，复制起始后由DNA聚合酶延伸。"},{"q":"下列关于DNA分子的叙述，错误的是","o":["腺嘌呤的克分子数等于胸腺嘧啶的克分子数","同种生物体不同组织中的DNA碱基组成极为相似","DNA双螺旋中碱基对位于外侧","两股多核甘酸链通过A与T或C与G之间的氢键连接","维持双螺旋稳定的主要因素是氢键和碱基堆积力"],"a":2,"e":"双螺旋中脱氧核糖和磷酸构成的亲水骨架位于外侧，疏水的碱基对包埋在螺旋内侧，故碱基对位于外侧的说法错误。"},{"q":"法医学个体识别的核心技术是","o":["PCR","DNA测序","Nouthern印迹","Southern印迹","基于STR的DNA指纹技术"],"a":4,"e":"基于STR的DNA指纹技术个体识别力高、所需样本微量且可扩增，已取代核酸杂交图谱，成为法医学个体识别的核心技术。"},{"q":"将蛋白质溶液的pH值调节到其等电点时","o":["可使蛋白质稳定性增加","可使蛋白质稳定性降低，易于沉出","可使蛋白质表面的净电荷不变","可使蛋白质表面的净电荷增加","对蛋白质表面水化膜无影响"],"a":1,"e":"等电点时蛋白质净电荷为零，分子间静电斥力消失，电荷与水化膜两大稳定因素被削弱，蛋白质易于聚集沉淀。"},{"q":"苯丙酮尿症患者是由于缺乏","o":["苯丙氨酸转氨酶","酪氨酸酶","苯丙氨酸羟化酶","苯丙酮酸脱氢酶","酪氨酸羟化酶"],"a":2,"e":"苯丙酮尿症由苯丙氨酸羟化酶基因突变致肝内该酶缺乏，苯丙氨酸不能羟化为酪氨酸而经转氨基生成苯丙酮酸，大量由尿排出。"},{"q":"氨基酰tRNA的3'末端腺苷酸与氨基酸相连的基团是","o":["1'-OH","2'-OH","3'-OH","2'-磷酸","3'-磷酸"],"a":2,"e":"tRNA氨基酸臂CCA末端的腺苷酸以核糖3'-OH与氨基酸羧基形成酯键，故3'-OH为连接基团；反应由氨酰-tRNA合成酶催化并消耗ATP。"},{"q":"下列关于酶的别构调节，错误的是","o":["受别构调节的酶称为别构酶","别构酶催化反应动力学符合米-曼氏方程","别构酶多是关键酶（如限速酶），催化的反应常是不可逆反应","别构调节是快速调节","别构酶分子常含有多个亚基"],"a":1,"e":"别构酶的动力学曲线呈S形，不遵守米氏方程；其多为寡聚酶，受别构效应剂调节，多催化限速反应，属快速调节。"},{"q":"以下关于常见复杂疾病相关基因鉴定技术的正确说法是","o":["GWAS（全基因组的关联研究）技术在单基因遗传病相关基因鉴定过程中具有很大的优势","GWAS（全基因组的关联研究）技术产生庞大数据信息并且假阳性很低","全外显子测序选择性检测蛋白编码序列","GWAS（全基因组的关联研究）与全外显子测序技术相比，在复杂疾病易感基因研究中体现出更高的检测性价比","GWAS（全基因组的关联研究）可以检测出疾病相关罕见突变的发生"],"a":2,"e":"全外显子组测序用序列捕获技术富集全基因组外显子区域后测序，选择性检测蛋白编码序列；GWAS主要用于复杂疾病易感基因定位，不适用于单基因病。"},{"q":"蛋白质多肽链具有方向性，其正确描述是","o":["3'端→5'端","5'端→3'端","N端→C端","C端→N端","羧基到氨基端"],"a":2,"e":"肽链合成自氨基端开始，逐个添加氨基酸向羧基端延伸，故多肽链的方向为N端→C端，即一级结构的方向性。"},{"q":"某种非编码小RNA在生物体参与hnRNA的剪接过程。该种RNA是","o":["mRNA","tRNA","rRNA","sncRNA","snRNA"],"a":4,"e":"snRNA与多种蛋白质组成snRNP，识别内含子5′-端和分支点，装配成剪接体完成hnRNA的剪接。"},{"q":"生物转化反应中参与氧化反应最重要的酶是","o":["单加氧酶（混合功能氧化酶）","加双氧酶","水解酶","胺氧化酶","脱氢酶"],"a":0,"e":"生物转化中的氧化反应主要由肝细胞微粒体依赖细胞色素P450的单加氧酶（混合功能氧化酶）催化，将氧分子中一个氧原子加到底物，另一个还原成水。"},{"q":"可以直接进行未知疾病相关基因鉴定分离的方法是","o":["Northern印迹法","cDNA芯片","RNA酶保护试验","RT-PCR","原位杂交"],"a":1,"e":"cDNA芯片可高通量检测基因表达，用于鉴定未知疾病相关基因；教材指出由可变剪接产生的同一基因不同编码区可通过基因芯片等高通量分析确定。Northern印迹、RNA酶保护试验、RT-PCR和原位杂交均针对已知序列检测。"},{"q":"基因芯片是将哪种成分以何种方式固定于单位面积的支持物上的","o":["许多特定的多肽片段有规律地紧密排列","许多特定的探针有规律地紧密排列","许多特定的DNA片段有规律地紧密排列","许多特定的DNA片段随机地紧密排列","许多特定的 RNA片段有规律地紧密排列"],"a":2,"e":"基因芯片是将大量特定的DNA片段有规律地高密度点样于硅片等支持物上，与荧光标记样品杂交后进行检测分析。"},{"q":"下列不属于酶促共价修饰调节的是","o":["酶蛋白分子中的丝氨酸、苏氨酸及酪氨酸的磷酸化修饰","酶蛋白分子的乙酰化与去乙酰化修饰","核小体组蛋白分子的甲基化和去甲基化修饰","酶蛋白分子的腺苷化与去腺苷化互变","磷蛋白磷酸酶催化酶分子去磷酸化"],"a":2,"e":"酶促共价修饰调节指酶蛋白的磷酸化、腺苷化、乙酰化等修饰；组蛋白甲基化属染色质水平的基因表达调控，不属此列。"},{"q":"肝糖原分解直接补充血糖的原因是","o":["有糖原磷酸化酶","有强大的糖异生能力","有葡萄糖-6-磷酸酶","有葡萄糖激酶","有葡萄糖氧化酶"],"a":2,"e":"肝内含有葡萄糖-6-磷酸酶，可将糖原分解生成的葡萄糖-6-磷酸水解为葡萄糖释入血补充血糖；肌组织缺乏该酶，故肌糖原不能直接补充血糖。"},{"q":"糖、脂类和蛋白质三大营养物质分解的共同代谢途径是","o":["糖酵解途径","β-氧化过程","柠檬酸循环","鸟氨酸循环","磷酸戊糖通路"],"a":2,"e":"糖、脂肪和蛋白质分解生成的乙酰CoA均进入柠檬酸循环彻底氧化，故柠檬酸循环是三大营养物质分解代谢的共同途径。"},{"q":"下述产能过程不在线粒体的是","o":["三羧酸循环","脂肪酸β-氧化","电子传递","糖酵解","氧化磷酸化"],"a":3,"e":"糖酵解在细胞质中进行，其底物水平磷酸化生成的ATP不在线粒体；三羧酸循环、β-氧化和氧化磷酸化均在线粒体完成。"},{"q":"原癌基因的特点不包括","o":["广泛存在于各种生物细胞中","进化过程中基因序列具有高度的保守性","不同原癌基因的功能各不相同","不同原癌基因的定位各不相同","所有的原癌基因一旦被激活，都具有致癌活性"],"a":4,"e":"原癌基因被激活后并非都具有致癌活性，只有经突变或过度表达转变为癌基因才具致癌性。原癌基因广泛存在、高度保守，各基因功能与定位不同。"},{"q":"胰岛素是由胰脏内的胰岛β细胞受内源性或外源性物质等的刺激而分泌的一种蛋白质激素。1922年开始用于临床，使过去称为不治之症的糖尿病患者得到挽救。下列胰岛素对糖代谢影响的论述正确的是","o":["促进糖的异生","促进糖原分解","抑制细胞膜载体转运葡萄糖入细胞","促进糖原合成","合成脂肪的能力降低"],"a":3,"e":"胰岛素使血糖去路增强、来源减弱：激活糖原合酶、抑制磷酸化酶，加速糖原合成并抑制糖原分解，同时促进葡萄糖摄取和转变为脂肪。"},{"q":"在离体肝线粒体悬液中加入氰化物，则一分子β-羟丁酸氧化的P/O比值为","o":["0","1","2","3","4"],"a":0,"e":"氰化物抑制细胞色素氧化酶，阻断电子传递，氧化磷酸化完全停止；β-羟丁酸氧化脱下的氢无法经呼吸链生成ATP，P/O比值为0。"},{"q":"下列不参与构成核小体核心颗粒的蛋白是","o":["H1","H2A","H2B","H3","H4"],"a":0,"e":"核小体核心颗粒由H2A、H2B、H3、H4各两分子组成的八聚体与146bp DNA构成，H1结合于DNA进出口处稳定核小体结构，不参与核心颗粒组成。"},{"q":"下列哪种物质脱下的一对氢经呼吸链传递后P/O比约为2.5","o":["β-羟丁酸","琥珀酸","α-磷酸甘油","维生素C","脂酰CoA"],"a":0,"e":"β-羟丁酸脱氢生成NADH，其氢经NADH呼吸链传递，P/O比约2.5；琥珀酸、α-磷酸甘油和脂酰CoA的氢经FAD进入呼吸链，P/O比约1.5。"},{"q":"关于别构调节的叙述，哪一项是错误的","o":["别构酶常由两个以上亚基组成","别构调节剂常是些小分子代谢物","别构剂通常与酶活性中心以外的某一特定部位结合","途径的终产物通常是该途径起始反应酶的别构抑制剂","调节具有放大效应"],"a":4,"e":"别构调节通过效应剂结合调节亚基改变酶构象，快速而灵敏，但无放大效应；化学修饰调节（如磷酸化）才具有放大效应。"},{"q":"磺胺类药物抑菌作用的机制是抑制","o":["二氢叶酸还原酶","二氢叶酸合成酶","四氢叶酸合成酶","四氢叶酸还原酶","叶酸合成酶"],"a":1,"e":"磺胺类药物与对氨基苯甲酸结构相似，竞争性抑制二氢蝶酸合酶即二氢叶酸合成酶，阻断四氢叶酸生成。"},{"q":"乙酰乙酸在体内不能直接转变生成","o":["丙酮","HMG-CoA","乙酰乙酰CoA","L-β羟丁酸","以上都不能"],"a":1,"e":"乙酰乙酸需先活化为乙酰乙酰CoA，再与乙酰CoA缩合生成HMG-CoA，故乙酰乙酸不能直接转变成HMG-CoA；它可还原为β-羟丁酸或脱羧成丙酮。"},{"q":"血浆脂蛋白密度由低到高的正确顺序是","o":["LDL、VLDL、CM、HDL","CM、VLDL、LDL、HDL","VLDL、LDL、CM、HDL","CM、VLDL、HDL、LDL","HDL、VLDL、CM、LDL"],"a":1,"e":"脂蛋白密度取决于蛋白质与脂质的比例，含甘油三酯越多密度越低，由低到高依次为CM、VLDL、LDL、HDL。"},{"q":"关于DNA复制中化学反应的表述，错误的是","o":["新链走向与模板链走向相反","模板链的走向是3'→5'","新链走向与模板链走向相同","新链的延伸方向是5'→3'","形成3',5'-磷酸二酯键"],"a":2,"e":"DNA聚合酶只能催化新链沿5′→3′方向延伸，而模板链走向为3′→5′，两者方向相反，故新链走向与模板链走向相同是错误的。"},{"q":"下列哪项癌基因的表达产物是生长因子","o":["RAS","SIS","MYC","SRC","RAF"],"a":1,"e":"SIS（C-SIS）编码血小板源生长因子PDGF的β链，属细胞外生长因子类癌基因；RAS、RAF编码细胞内信号转导分子，MYC编码核内转录因子。"},{"q":"参与非线粒体氧化体系的酶类有","o":["加单氧酶","过氧化氢酶","过氧化物酶","琥珀酸脱氢酶","苹果酸脱氢酶"],"a":1,"e":"过氧化氢酶属非线粒体氧化体系，分解H2O2为H2O和O2。琥珀酸脱氢酶、苹果酸脱氢酶为线粒体氧化体系中的脱氢酶。"},{"q":"下列有关酮体的描述错误的是","o":["酮体是肝脏输出能源的一种形式","酮体可作为脑和肌肉组织的重要能源","脂肪动员减少时肝内酮体生成增多","酮体是水溶性物质","丙酮可由呼吸道呼出"],"a":2,"e":"脂肪动员加强时，脂肪酸β-氧化增强、乙酰CoA生成增多，肝内酮体生成增多；脂肪动员减少时酮体生成减少。酮体是水溶性物质，是肝输出能源的形式，可供脑和肌肉利用，丙酮可经呼吸道呼出。"},{"q":"血红素合成的关键酶是","o":["己糖激酶","转氨酶","CPS-Ⅰ","ALA合酶","HMG-CoA合酶"],"a":3,"e":"ALA合酶在线粒体内催化甘氨酸与琥珀酰CoA缩合生成δ-氨基-γ-酮戊酸，是血红素合成的限速酶，受血红素反馈抑制。"},{"q":"结合胆红素是指","o":["胆红素-清蛋白","胆红素-Y蛋白","胆红素-葡糖醛酸","胆红素-Z蛋白","胆红素-珠蛋白"],"a":2,"e":"结合胆红素是胆红素在肝细胞内经胆红素-葡萄糖醛酸基转移酶催化，与葡萄糖醛酸结合生成的葡萄糖醛酸胆红素。"},{"q":"能使蛋白质沉淀而不变性的试剂是","o":["浓盐酸","浓氢氧化钠溶液","硫酸铵溶液","生理盐水","蒸馏水"],"a":2,"e":"硫酸铵溶液通过盐析中和蛋白质表面电荷并破坏水化膜，使蛋白质沉淀而保持结构及生物活性不变。浓酸、浓碱则破坏蛋白质空间结构而致变性。"},{"q":"赖氨酸的脱羧产物是","o":["腐胺","精脒","精胺","尸胺","乙醇胺"],"a":3,"e":"赖氨酸经细菌脱羧酶催化脱去羧基生成尸胺，属肠道腐败作用的产物，具有降低血压的毒性。"},{"q":"与蛋白激酶G（PKG）信息传递途径有关的物质是","o":["环化鸟苷酸（cGMP）","热休克蛋白","1,4,5-三磷酸肌醇（IP3）","Ca2+","环腺苷酸（cAMP）"],"a":0,"e":"cGMP是PKG信息传递途径的第二信使，与PKG结合激活其蛋白激酶活性。cAMP激活PKA，IP3与Ca2+参与另一通路。"},{"q":"糖、脂肪酸与蛋白质三者之间代谢的交叉点是","o":["琥珀酸","丙酮酸","延胡索酸","乙酰辅酶A","磷酸烯醇式丙酮酸"],"a":3,"e":"乙酰CoA是糖、脂肪和蛋白质分解代谢的共同中间产物，三者均经其进入三羧酸循环彻底氧化，故为代谢的交叉点。"},{"q":"糖酵解时哪一对代谢物提供P使ADP生成ATP","o":["3-磷酸甘油醛及磷酸烯醇式丙酮酸","1，3-二磷酸甘油酸及磷酸烯醇式丙酮酸","1-磷酸葡萄糖及1，6-双磷酸果糖","6-磷酸葡萄糖及2-磷酸甘油酸","1，3-二磷酸甘油酸及2-磷酸甘油酸"],"a":1,"e":"糖酵解中甘油酸-1,3-二磷酸和磷酸烯醇式丙酮酸含高能磷酸键，经底物水平磷酸化将磷酸基转给ADP生成ATP。"},{"q":"琥珀酸氧化呼吸链和NADH氧化呼吸链的共同组成部分是","o":["NADH","琥珀酸","CoQ","细胞色素类","FADH2"],"a":2,"e":"NADH呼吸链为NADH→复合体Ⅰ→Q→复合体Ⅲ→Cyt c→复合体Ⅳ→O2，琥珀酸呼吸链经复合体Ⅱ后也汇入Q及其后组分，故两条链共有泛醌（CoQ）。"},{"q":"下列蛋白质混合液通过凝胶过滤层析时，最先被洗脱下来的是","o":["马肝过氧化氢酶（相对分子量247 500）","肌红蛋白（相对分子量16 900）","人血清蛋白（相对分子量68 500）","牛G-乳球蛋白（相对分子量35 000）","牛胰岛素（相对分子量5 733）"],"a":0,"e":"凝胶过滤层析按分子大小分离，大分子不能进入凝胶颗粒内部而先被洗脱。马肝过氧化氢酶相对分子量247 500最大，故最先洗脱。"},{"q":"关于磷酸戊糖途径说法正确的是","o":["是体内产生CO2的主要来源","可生成NADPH供合成代谢需要","是体内生成糖醛酸的途径","饥饿时葡萄糖经此途径代谢增加","可生成NADPH，后者经电子传递链可生成ATP"],"a":1,"e":"戊糖磷酸途径以NADP+为受氢体生成NADPH，作为脂肪酸、胆固醇等合成代谢的供氢体，同时产生核糖-5-磷酸；其NADPH不进入呼吸链产能。"},{"q":"关于抑癌基因的说法错误的是","o":["可促进细胞的分化","可诱发细胞程序性死亡","突变时可能导致肿瘤发生","可抑制细胞过度生长","最早发现的是p53基因"],"a":4,"e":"最早发现的抑癌基因是RB基因，TP53是后来证实与人类肿瘤相关性最高的抑癌基因；抑癌基因可抑制细胞过度生长、促进分化并诱发凋亡。"},{"q":"原核细胞中，识别基因转录起始点的是","o":["阻遏蛋白","转录激活蛋白","基础转录因子","特异转录因子","σ因子"],"a":4,"e":"原核RNA聚合酶的σ因子识别启动子（-10区与-35区）并与之结合，引导核心酶定位至转录起始点，起始完成后σ因子即脱落。"},{"q":"三羧酸循环的限速酶是","o":["丙酮酸脱氢酶","顺乌头酸酶","琥珀酸脱氢酶","延胡索酸酶","异柠檬酸脱氢酶"],"a":4,"e":"三羧酸循环的3个关键酶为柠檬酸合酶、异柠檬酸脱氢酶和α-酮戊二酸脱氢酶复合体，其中异柠檬酸脱氢酶催化第一次氧化脱羧，是限速酶之一。丙酮酸脱氢酶催化的是丙酮酸氧化脱羧，不属三羧酸循环。"},{"q":"维生素B2是下列哪种辅酶或辅基的组成成分","o":["NAD+","NADP+","CoASH","TPP","FAD"],"a":4,"e":"维生素B2（核黄素）是FMN和FAD的组成成分，二者作为黄素脱氢酶辅基传递氢原子；NAD+、NADP+含维生素PP，TPP含维生素B1，CoA含泛酸。"},{"q":"三羧酸循环中催化琥珀酸形成延胡索酸的酶是琥珀酸脱氢酶，此酶的辅因子是","o":["NAD+","CoASH","FAD","TPP","NADP+"],"a":2,"e":"琥珀酸脱氢酶是三羧酸循环中唯一结合在线粒体内膜的酶，其辅基为FAD，脱氢生成FADH2后经呼吸链氧化。"},{"q":"下列哪一种酶经磷酸化修饰后被激活","o":["丙酮酸脱氢酶","磷酸果糖激酶-1","糖原磷酸化酶","糖原合酶","乙酰CoA羧化酶"],"a":2,"e":"糖原磷酸化酶经磷酸化后由无活性的b型转变为有活性的a型，促进糖原分解；糖原合酶磷酸化后反而失活。"},{"q":"不是以胆固醇为原料合成的化合物是","o":["胆汁酸","胆红素","雌二醇","1,25-(OH)2-D3","醛固酮"],"a":1,"e":"胆红素是血红素降解产物，并非以胆固醇为原料；胆汁酸、雌二醇、1,25-(OH)2-D3和醛固酮均由胆固醇合成。"},{"q":"关于钙的生理功能，错误的是","o":["血钙能降低神经肌肉的兴奋性","钙可降低毛细血管通透性","钙是代谢调节的第二信使","钙可降低心肌的兴奋性","钙参与血液凝固的作用"],"a":3,"e":"血钙升高可降低神经肌肉兴奋性、降低毛细血管通透性，并作为第二信使参与代谢调节及血液凝固；钙离子提高心肌兴奋性、增强心肌收缩力，故该项错误。"},{"q":"乳糖操纵子的直接诱导剂是指","o":["β-半乳糖苷酶","β-半乳糖苷透性酶","葡萄糖","乳糖","半乳糖"],"a":4,"e":"乳糖须经β-半乳糖苷酶转变为别乳糖才能结合阻遏蛋白，别乳糖含半乳糖基；葡萄糖则引起降解物阻遏，降低转录。"},{"q":"合成胆固醇的酶系分布于","o":["线粒体+光面内质网","线粒体+高尔基体","细胞质+光面内质网","线粒体+溶酶体","细胞质+高尔基体"],"a":2,"e":"胆固醇合成酶系存在于胞质溶胶和光面内质网膜，HMG-CoA还原酶位于内质网；合成原料为乙酰CoA和NADPH，肝是主要合成器官。"},{"q":"核酸具有紫外吸收特征的原因，是由于嘌呤和嘧啶环中有","o":["共轭双键","氮原子","硫原子","连接了核糖","连接了磷酸基团"],"a":0,"e":"嘌呤和嘧啶是含共轭双键的杂环分子，在260nm附近有特征性紫外吸收，据此可对核酸进行定性和定量分析。"},{"q":"下列关于tRNA叙述，错误的是","o":["通常由几百个核苷酸组成，分子量较大","含有假尿嘧啶","磷酸与核糖的比值为1","含有胸腺嘧啶","含有二氢尿嘧啶"],"a":0,"e":"tRNA由74～95个核苷酸组成，分子量小，约占细胞RNA总量的15%；其含假尿嘧啶、二氢尿嘧啶和胸腺嘧啶等稀有碱基，磷酸与核糖比为1。"},{"q":"下列有关胆汁酸的说法中，哪项是错误的","o":["又称为胆汁","通常以钠盐形式存在","为小肠吸收脂肪所必需","它的缺乏可导致脂溶性维生素的吸收障碍","在肝内以胆固醇为合成原料"],"a":0,"e":"胆汁酸是胆汁中的主要有机成分，通常以钠盐或钾盐形式存在，能乳化脂肪促进其吸收并促进脂溶性维生素吸收；它本身不等于胆汁。"},{"q":"下列对磷生理功能的叙述，错误的是","o":["构成骨盐成分","是核酸的组成成分","不参与细胞膜的组成","参与体内能量代谢","参与维持体内酸碱平衡"],"a":2,"e":"磷是磷脂的组成成分，参与细胞膜构成，故该说法错误；磷还构成骨盐和核酸，并参与能量代谢及酸碱平衡调节。"},{"q":"顺式作用元件是指","o":["基因的5'-端序列","基因的3'-端序列","基因5'-端序列以外的序列","基因3'-端序列以外的序列","具有转录调节功能的特异DNA序列"],"a":4,"e":"顺式作用元件是可影响自身基因表达活性的特异DNA序列，多位于基因附近，包括启动子、增强子、沉默子和绝缘子等。"},{"q":"关于未结合胆红素，下列说法正确的是","o":["称为肝胆红素","凡登白试验间接阳性","是血浆中不与任何物质结合的胆红素","水溶性较大，易在尿中出现","不易进入脑组织产生毒性"],"a":1,"e":"未结合胆红素即间接胆红素，在血浆中与清蛋白结合运输，凡登白试验呈间接反应阳性；其脂溶性强，易透过血脑屏障产生毒性，不能经尿排出。"},{"q":"有关LDL的叙述，不正确的是","o":["富含apo AⅠ和apo B100","可经受体途径降解","胆固醇和胆固醇酯含量丰富","主要在肝脏降解","由VLDL转变生成"],"a":0,"e":"LDL几乎只含apoB100，apoAⅠ主要分布于HDL，故“富含apoAⅠ和apoB100”不正确。LDL由VLDL转变生成，富含胆固醇和胆固醇酯，经apoB/E受体途径主要在肝降解。"},{"q":"定位于线粒体内膜上的酶系统是","o":["糖酵解酶系","磷酸戊糖途径酶系","呼吸链","三羧酸循环酶系","脂肪酸合酶"],"a":2,"e":"呼吸链的四种蛋白质复合体与泛醌、细胞色素c均嵌于线粒体内膜，催化电子传递和氧化磷酸化；糖酵解酶系在胞质，三羧酸循环酶系在线粒体基质。"},{"q":"下列具有受体酪氨酸蛋白激酶活性的是","o":["甲状腺素受体","雌激素受体","乙酰胆碱受体","表皮生长因子受体","肾上腺素受体"],"a":3,"e":"表皮生长因子受体属受体型酪氨酸激酶，配体结合后受体二聚化并自身磷酸化，进而激活下游信号通路；甲状腺素、雌激素受体位于核内。"},{"q":"参与合成人体蛋白质的氨基酸，不是L-α氨基酸的是","o":["甘氨酸","丙氨酸","丝氨酸","亮氨酸","异亮氨酸"],"a":0,"e":"甘氨酸的α-碳原子连接两个氢原子，不是不对称碳原子，无旋光性，故不属L-α-氨基酸；参与蛋白质合成的其余氨基酸均为L-α-氨基酸。"},{"q":"酶的磷酸化修饰常发生在","o":["赖氨酸的ε-氨基","含羧基的氨基酸残基","组氨酸的咪唑基","含羟基的氨基酸残基","半胱氨酸的巯基"],"a":3,"e":"蛋白质激酶催化ATP的γ-磷酸基转移至底物蛋白Ser、Thr、Tyr残基的侧链羟基上，故磷酸化发生在含羟基的氨基酸残基。"},{"q":"克隆的真核基因组DNA可在多种系统表达，但例外的是","o":["E、coli表达体系","哺乳类细胞","酵母表达体系","昆虫表达体系","CHO细胞表达体系"],"a":0,"e":"大肠埃希菌缺乏转录后加工机制，只能表达由cDNA编码的产物，不宜表达含内含子的真核基因组DNA；酵母、昆虫及哺乳类细胞均可对其加工。"},{"q":"通常G蛋白偶联的受体存在于","o":["线粒体","微粒体","细胞核","细胞膜","细胞质"],"a":3,"e":"G蛋白偶联受体为跨膜蛋白，肽链七次跨过细胞膜，分布于细胞膜上，其氨基端在膜外、羧基端在膜内。"},{"q":"关于tRNA分子，下面描述正确的是","o":["tRNA分子多数由80个左右的氨基酸组成","tRNA的功能是结合蛋白质合成所需要的各种辅助因子","tRNA的3'末端有氨基酸臂","反密码环中的反密码子，可以结合DNA中相互补的碱基","tRNA的5'末端有多聚腺苷酸结构"],"a":2,"e":"tRNA由70～90个核苷酸组成，3'端为-CCA氨基酸臂，可结合氨基酸；反密码子与mRNA密码子互补，不结合DNA。"},{"q":"体内合成长链脂酸的主要原料是","o":["乙酰辅酶A","丙酰辅酶A","乙酰乙酰辅酶A","草酰乙酸","葡萄糖"],"a":0,"e":"脂肪酸合成以乙酰CoA为基本原料，先羧化为丙二酰CoA，再经缩合、还原、脱水、还原循环延长碳链。"},{"q":"有关不对称转录，叙述正确的是","o":["模板链并非永远在同一DNA单链","没有规律的转录","双向复制后的转录","同一单链DNA转录时，可以从5′→3′或者3′→5′延长","转录产物翻译生成的多肽中的氨基酸含有不对称碳原子"],"a":0,"e":"不对称转录指DNA双链中只有一条链作为模板，且模板链并非固定于同一条链，不同基因的模板链可位于不同链。"},{"q":"抗霉素A是呼吸链特异抑制剂，它作用于","o":["NADH-辅酶Q还原酶","琥珀酸-辅酶Q还原酶","还原辅酶Q与细胞色素c还原酶","细胞色素b到QN的电子传递","ATP合酶"],"a":3,"e":"抗霉素A结合复合体Ⅲ的Qi位点，阻断电子由Cyt b向QN的传递，使Q循环中断，是复合体Ⅲ的特异性抑制剂。"},{"q":"下列代谢物经相应特异脱氢酶催化脱下的2H，不能经过NADH呼吸链氧化的是","o":["异柠檬酸","苹果酸","α-酮戊二酸","琥珀酸","丙酮酸"],"a":3,"e":"琥珀酸脱氢酶以FAD为辅基，脱下的氢生成FADH2，经复合体Ⅱ和泛醌进入FADH2呼吸链；其余底物脱氢均生成NADH。"},{"q":"下列不参与甘油三酯合成的化合物是","o":["3-磷酸甘油","脂酰辅酶A","CDP-甘油二酯","磷脂酸","甘油二酯"],"a":2,"e":"甘油三酯合成由3-磷酸甘油与脂酰CoA经磷脂酸、甘油二酯逐步生成；CDP-甘油二酯是甘油磷脂合成的活化中间物。"},{"q":"有关同工酶的正确叙述是","o":["同工酶具有相同的理化性质","同工酶对同种底物亲和力相同","同工酶的空间结构一定相同","组成同工酶的亚基一定相同","不同组织中同工酶谱不同"],"a":4,"e":"同工酶是催化相同化学反应但一级结构不同的酶，同一基因在不同组织开放程度不同，形成不同同工酶谱，故不同组织中同工酶谱不同。同工酶活性中心三维结构相似但理化性质存在差异。"},{"q":"关于肿瘤抑制基因的叙述，错误的是","o":["突变时可导致肿瘤发生","p16基因是最早发现的抑癌基因","促进细胞的分化","抑制细胞过度生长","诱发细胞程序性死亡"],"a":1,"e":"最早发现的抑癌基因是RB基因，其失活与视网膜母细胞瘤相关；p16是后来发现的细胞周期负调控基因，并非最早。"},{"q":"有关脂肪酸活化的描述，错误的是","o":["增加水溶性","增加代谢活性","消耗ATP","在线粒体内进行","由脂酰CoA合成酶催化"],"a":3,"e":"脂肪酸活化在胞质溶胶、内质网及线粒体外膜进行，由脂酰CoA合成酶催化并消耗ATP，生成脂酰CoA以增加水溶性和代谢活性，并不在线粒体内完成。"},{"q":"酶原之所以没有酶活性是因为","o":["缺乏辅助因子","活性中心未形成或未暴露","已经变性","酶原分子被其他物质包裹","肽链合成不完全"],"a":1,"e":"酶原激活的实质是酶的活性中心形成或暴露。酶原以无活性前体形式存在，特定肽键断裂后分子构象改变，形成或暴露活性中心才具催化活性，如胰蛋白酶原经肠激酶水解掉六肽后被激活。"},{"q":"目前的基因治疗中，应用最多的载体是","o":["腺病毒载体","腺相关病毒载体","逆转录病毒载体","单纯疱疹病毒载体","慢病毒载体"],"a":2,"e":"逆转录病毒载体可将外源基因整合入宿主染色体而长期表达，具转移效率高、宿主范围广的优点，是基因治疗中应用最多的病毒载体。"},{"q":"关于关键酶的叙述哪一项是错误的","o":["关键酶常位于代谢途径的第一步反应","关键酶在代谢途径中活性最高，所以对整个代谢途径的流量起决定作用","关键酶常是变构酶","受激素调节的酶常是关键酶","关键酶常催化单向反应或非平衡反应"],"a":1,"e":"关键酶常位于代谢途径第一步或分支点，催化单向反应，其活性最低且决定整个途径的速率和方向，而不是活性最高。"},{"q":"1mol软脂酸彻底氧化时可净生成的ATP摩尔数是","o":["30","32","38","106","108"],"a":3,"e":"1分子软脂酸经7次β-氧化生成7分子FADH2、7分子NADH和8分子乙酰CoA，共得108分子ATP，扣除活化消耗的2个高能磷酸键，净生成106分子。"},{"q":"免疫球蛋白多样性产生的机制，是由于发生了基因","o":["整合","转染","转化","转位","转导"],"a":3,"e":"B细胞发育中免疫球蛋白基因的V、(D)、J片段发生重排转位，与恒定区基因拼接，产生种类繁多的抗体，是抗体多样性的遗传基础。"},{"q":"运输外源性甘油三酯的血浆脂蛋白是","o":["CM","VLDL","LDL","HDL","IDL"],"a":0,"e":"乳糜微粒由小肠黏膜细胞利用食物脂肪酸合成，经淋巴系统吸收入血，功能是运输外源性甘油三酯和胆固醇。"},{"q":"脂肪动员增加时，脂酸在肝内分解产生的乙酰CoA最易转变为","o":["非必需氨基酸","二氧化碳、水和能量","肝糖原","酮体","胆固醇"],"a":3,"e":"脂肪动员增加时，脂肪酸在肝内β-氧化生成大量乙酰CoA，超出三羧酸循环处理能力，转而生成酮体向肝外输出。酮体包括乙酰乙酸、β-羟丁酸和丙酮。"},{"q":"体内核苷酸从头合成过程中的底物可由以下哪条代谢通路直接提供","o":["葡萄糖的无氧酵解过程","氨基酸的脱氨基作用","磷酸戊糖通路","甘油三酯的脂肪动员过程","尿素的合成过程"],"a":2,"e":"核苷酸从头合成以磷酸戊糖途径生成的5-磷酸核糖为起始底物，经PRPP合成酶活化为磷酸核糖焦磷酸后，再逐步接上碱基。"},{"q":"具有Ⅱ类启动子的基因是","o":["tRNA编码基因","5S rRNA编码基因","snRNA编码基因","蛋白质编码基因","microRNA编码基因"],"a":3,"e":"Ⅱ类启动子由TATA盒等元件组成，供RNA聚合酶Ⅱ识别，驱动所有蛋白质编码基因转录；Ⅰ类和Ⅲ类分别对应rRNA和tRNA基因。"},{"q":"哪种氨基酸脱氨基产生草酰乙酸","o":["谷氨酰胺","天冬氨酸","丝氨酸","谷氨酸","天冬酰胺"],"a":1,"e":"天冬氨酸经转氨基作用将氨基转移给α-酮戊二酸，自身转变为草酰乙酸；谷氨酸生成α-酮戊二酸，丙氨酸生成丙酮酸。"},{"q":"脂肪酸和胆固醇合成过程中的供氢体NADPH主要来自","o":["糖酵解","磷酸戊糖通路","糖的有氧氧化","脂类代谢","氨基酸分解代谢"],"a":1,"e":"磷酸戊糖途径的6-磷酸葡萄糖脱氢酶以NADP+为受氢体，生成的NADPH是脂肪酸和胆固醇合成的主要供氢体。"},{"q":"下列哪种物质属于维生素D原","o":["胆钙化醇","谷固醇","7-脱氢胆固醇","25-羟胆钙化醇","24,25-羟胆钙化醇"],"a":2,"e":"7-脱氢胆固醇是维生素D3原，储存于皮肤，经紫外线照射转变为维生素D3。胆钙化醇即维生素D3本身，25-羟胆钙化醇为其活化形式。"},{"q":"tRNA分子不仅有稳定的二级结构，还有稳定的三级结构。tRNA分子的三级结构","o":["是三叶草型结构进一步折叠形成倒“L”型","是根据Chargaff规则研究出的","对于不同的tRNA典型结构并不相同","是三叶草结构进一步折叠成双螺旋","是典型的锌指结构"],"a":0,"e":"tRNA的二级结构呈三叶草型，进一步折叠形成稳定的倒“L”形三级结构，由碱基间特殊氢键和碱基堆积力维持。所有tRNA都具有相似的倒“L”形空间结构。"},{"q":"下列维生素中，具有抗氧化作用的是","o":["硫胺素","核黄素","维生素E","维生素K","维生素D"],"a":2,"e":"维生素E是体内最重要的脂溶性抗氧化剂，可保护生物膜及蛋白质的巯基免遭氧化；硫胺素、核黄素、维生素K和D无此主要作用。"},{"q":"酵母双杂交实验可用来检测","o":["蛋白质-蛋白质相互作用","蛋白质-DNA相互作用","蛋白质-RNA相互作用","DNA-DNA相互作用","DNA-RNA相互作用"],"a":0,"e":"酵母双杂交利用转录因子DNA结合域与激活域的重组，通过报告基因表达来检测细胞内蛋白质与蛋白质的相互作用。"},{"q":"体内活性硫酸根是指","o":["PAPS","GABA","GSH","GSSG","SAM"],"a":0,"e":"活性硫酸根即3′-磷酸腺苷5′-磷酰硫酸（PAPS），由硫酸根经ATP活化生成，是硫酸基转移酶的硫酸供体，参与类固醇、酚类等硫酸结合反应。"},{"q":"噬菌体T4连接酶能催化连接的DNA末端是","o":["5'-P和3'-P","5'-OH和3'-P","5'-P和3'-OH","5'-OH和3'-OH","任意两种"],"a":2,"e":"T4 DNA连接酶催化一个DNA片段3'-OH与另一片段5'-磷酸之间形成磷酸二酯键，需ATP供能，不能连接5'-OH。"},{"q":"作用于膜受体的激素是","o":["肾上腺素","雌激素","甲状腺素","孕激素","醛固酮"],"a":0,"e":"肾上腺素属儿茶酚胺类，作用于细胞膜β受体经cAMP传递信号；雌激素、孕激素、醛固酮和甲状腺素均为胞内受体激素。"},{"q":"有氧氧化时，1mol葡萄糖在三羧酸循环中产生多少GTP","o":["2mol","6mol","18mol","24mol","36mol"],"a":0,"e":"1mol葡萄糖经三羧酸循环，琥珀酰CoA合成酶催化琥珀酰CoA生成琥珀酸时，经底物水平磷酸化生成2mol GTP。"},{"q":"不是操纵子组成部分的是","o":["结构基因","启动序列","阻遏物","CAP结合位点","操纵序列"],"a":2,"e":"操纵子由结构基因、启动序列、操纵序列及CAP结合位点等调控元件组成，阻遏物是由调节基因编码的蛋白质，不属于操纵子结构。"},{"q":"霍乱毒素的作用机制是","o":["Go的ADP核糖化","Gq的ADP核糖化","Gsα的ADP核糖化","Gβγ的ADP核糖化","Giα的ADP核糖化"],"a":3,"e":"官方答案为【Gβγ的ADP核糖化】，但依据教材，正确答案为【Gsα的ADP核糖化】。霍乱毒素A亚基进入细胞后使G蛋白α亚基ADP-核糖化，抑制其GTP酶活性，Gsα持续激活而腺苷酸环化酶活性升高。"},{"q":"甲基的直接供体是","o":["胆碱","N10-甲基四氢叶酸","甲硫氨酸","S-腺苷甲硫氨酸","肾上腺素"],"a":3,"e":"S-腺苷甲硫氨酸即SAM，其中的甲基称活性甲基，是体内最重要的甲基直接供体，参与五十余种甲基化反应。"},{"q":"酮体生成过多主要见于","o":["脂肪酸摄入过多","肝内脂肪代谢紊乱","糖供应不足或利用障碍","肝脏功能低下","脂肪运输障碍"],"a":2,"e":"糖供应不足或利用障碍时脂肪动员增强，肝内脂肪酸β-氧化生成大量乙酰CoA，而草酰乙酸不足使乙酰CoA转入酮体生成。"},{"q":"调节氧化磷酸化作用的重要激素是","o":["肾上腺素","甲状腺素","肾上腺皮质激素","胰岛素","生长素"],"a":1,"e":"甲状腺素可促进氧化磷酸化，使基础代谢率升高、耗氧量增加，是调节氧化磷酸化的重要激素。"},{"q":"构成赖氨酰氧化酶组分的元素是","o":["碘","硅","锰","钼","铜"],"a":4,"e":"赖氨酰氧化酶含铜离子，催化胶原和弹性蛋白中赖氨酸残基氧化脱氨生成醛基并进而交联；铜缺乏时结缔组织脆弱、血管弹性下降。"},{"q":"关于DNA复制的表述，错误的是","o":["具有高保真性","需要RNA依赖的DNA聚合酶参加","是半保留复制","是半不连续复制","需要DNA依赖的DNA聚合酶参加"],"a":1,"e":"DNA复制由依赖DNA的DNA聚合酶催化，具半保留、半不连续和高保真特点；依赖RNA的DNA聚合酶即逆转录酶，参与逆转录而非DNA复制。"},{"q":"ALA合酶的辅酶是","o":["烟酰胺腺膘呤二核苷酸（NAD+）","黄素腺膘呤二核苷酸（FAD）","黄素单核苷酸（FMN）","磷酸吡哆醛","硫胺素焦磷酸酯（TPP）"],"a":3,"e":"磷酸吡哆醛是ALA合酶的辅酶，参与血红素的合成，维生素B6缺乏将影响血红素生成。ALA合酶是血红素合成体系的限速酶，受血红素反馈抑制。"},{"q":"DNA复制与转录过程有许多异同点，下列描述中不正确的是","o":["两过程均需DNA链作为模板","在复制和转录中合成方向均为5'→3'","复制的产物通常大于转录产物","两过程均需聚合酶和多种蛋白因子","两过程均需RNA引物"],"a":4,"e":"DNA复制需要RNA引物启动，而RNA聚合酶可直接启动转录，RNA链合成不需要引物。复制与转录的合成方向均为5'→3'，均需DNA模板和多种蛋白因子。"},{"q":"生物素作为辅酶，在酶促反应中","o":["传递CO2","转移酰基","转移甲基","传递氢原子","转移氨基"],"a":0,"e":"生物素与羧化酶中赖氨酸残基的ε-氨基共价结合，作为CO2载体参与羧化反应，如丙酮酸羧化酶和乙酰CoA羧化酶。"},{"q":"不参与脂肪酸氧化过程的化合物是","o":["肉碱","NAD+","NADP+","FAD","CoASH"],"a":2,"e":"脂肪酸β-氧化以FAD和NAD+为受氢体，需肉碱转运脂酰基、CoASH参与，NADP+不参与该过程。NADPH主要作为脂肪酸合成等还原性合成的供氢体。"},{"q":"长链脂酰CoA通过线粒体内膜的载体是","o":["载体蛋白","3-磷酸甘油","柠檬酸","苹果酸","肉碱"],"a":4,"e":"长链脂酰CoA不能直接透过线粒体内膜，须经肉碱脂肪酰转移酶Ⅰ催化生成脂酰肉碱，再由转位酶运入线粒体基质。"},{"q":"阿糖胞苷作为抗肿瘤药物的机制，是抑制了","o":["二氢叶酸还原酶的活性","核糖核苷酸还原酶的活性","二氢乳清酸脱氢酶胸苷酸合成酶的活性","胸苷酸合酶的活性","氨基甲酰基转移酶的活性"],"a":1,"e":"阿糖胞苷是改变核糖结构的核苷类似物，通过抑制核糖核苷酸还原酶活性阻断脱氧核苷酸生成，从而抑制DNA合成。甲氨蝶呤抑制二氢叶酸还原酶，FdUMP抑制胸苷酸合酶。"},{"q":"不参加DNA切除修复过程的酶是","o":["DNA聚合酶Ⅰ","DNA聚合酶Ⅲ","AP内切核酸酶","DNA连接酶","蛋白质UvrA、UvrB等"],"a":1,"e":"切除修复由核酸内切酶、外切酶、DNA聚合酶Ⅰ和连接酶完成，DNA聚合酶Ⅲ参与复制和错配修复，不参加切除修复。"},{"q":"强烈抑制ALA合酶的物质是","o":["高铁血红素","促红细胞生成素","谷胱甘肽","睾酮","细胞色素P"],"a":0,"e":"血红素合成速度超过珠蛋白时，过多血红素氧化为高铁血红素，后者对ALA合酶产生强烈反馈抑制。"},{"q":"酶原激活的生理意义是","o":["避免细胞自身损伤","恢复酶活性","促进生长","加速代谢","保护酶的活性"],"a":0,"e":"消化蛋白酶和凝血因子以酶原形式分泌或存在，激活后才具活性，可避免对胰腺自身及细胞外基质蛋白的消化破坏。"},{"q":"细胞内传递信息的第二信使是","o":["受体","载体","蛋白质","甘油三酯","小分子物质"],"a":4,"e":"第二信使是细胞内可扩散的小分子物质或离子，如cAMP、cGMP、IP3、DAG和Ca2+，负责传递并放大细胞外信号。"},{"q":"长期饥饿时大脑主要的能源物质是","o":["氨基酸","脂肪","葡萄糖","类脂","酮体"],"a":4,"e":"长期饥饿时脂肪动员加强，肝内生成大量酮体，脑利用酮体增加并超过葡萄糖，占总耗氧量60%。酮体为脂溶性小分子，可透过血脑屏障供能。"},{"q":"端粒酶是一种","o":["依赖于DNA的DNA聚合酶","依赖于DNA的RNA聚合酶","依赖于RNA的DNA聚合酶","依赖于RNA的RNA聚合酶","特殊的核酶"],"a":2,"e":"端粒酶由RNA组分和逆转录酶活性蛋白组成，以自身RNA为模板合成端粒DNA重复序列，故属依赖RNA的DNA聚合酶。"},{"q":"反竞争性抑制剂是与","o":["游离酶结合","[S]结合","[ES]结合","酶的活性中心相结合","酶的非必需基团相结合"],"a":2,"e":"反竞争性抑制剂只能与酶-底物复合物结合，使表观Km降低、Vmax降低；其结合位点由底物诱导产生。"},{"q":"原核生物蛋白质生物合成需要多种酶和蛋白质因子的参与。可以促进氨酰-tRNA进入A位，结合并分解GTP的延长因子是","o":["EF-Tu","EF-Ts","EF-G","eRF","RF-1"],"a":0,"e":"EF-Tu与GTP及氨酰tRNA结合成三元复合物，促进氨酰tRNA进入A位并水解GTP；EF-G则催化转位。"},{"q":"可直接激活蛋白激酶C的是","o":["环腺苷酸（cAMP）","环化鸟苷酸（cGMP）","1,4,5-三磷酸肌醇（IP3）","磷脂酰肌醇-4,5-二磷酸（PIP2）","二酯酰甘油（DAG）"],"a":4,"e":"DAG与Ca2+共同激活蛋白激酶C，使其转位至细胞膜而活化；IP3促使钙库释放Ca2+，cAMP激活PKA，cGMP激活PKG。"},{"q":"N5-甲基四氢叶酸中的甲基只能用于合成","o":["甲硫氨酸","嘧啶碱基","N5,N10-甲烯四氢叶酸","N5,N10-甲炔四氢叶酸","嘌呤碱基"],"a":0,"e":"N5-甲基四氢叶酸是体内甲基的间接供体，经甲硫氨酸合成酶把甲基转给同型半胱氨酸，只能用于生成甲硫氨酸。"},{"q":"关于嘌呤和嘧啶核苷酸从头和补救合成途径的比较，描述错误的是","o":["从头合成是以磷酸核糖、氨基酸等简单物质为原料，补救合成是利用体内游离的嘌呤或嘌呤核苷为原料","两者在不同组织中重要性各不相同","肝组织进行从头合成，而脑、骨髓等以补救合成为主","一般情况下，从头合成是合成的主要途径","一般情况下，补救合成是合成的主要途径"],"a":4,"e":"一般情况下从头合成是核苷酸合成的主要途径，补救合成仅在某些缺乏从头合成酶体系的组织（如脑、骨髓）中为主。"},{"q":"关于管家基因的描述，下列最确切的是","o":["在生物个体全生命过程的几乎所有细胞中持续表达","在生物个体全生命过程的部分细胞中持续表达","在生物个体部分生命过程的部分细胞中持续表达","在特定环境下的生物个体全生命过程的所有细胞中持续表达","在特定环境下的生物个体全生命过程的部分细胞中持续表达"],"a":0,"e":"管家基因的产物为生命全过程所必需，在生物个体几乎所有细胞中持续表达，受环境因素影响小，如三羧酸循环各阶段反应的酶基因。"},{"q":"大多数处于活化状态的真核基因对DNaseⅠ","o":["低度敏感","中度敏感","高度敏感","不敏感","不一定"],"a":2,"e":"转录活化的染色质区域DNA双链结构松弛，对DNaseⅠ高度敏感，形成超敏位点，是基因活化的结构标志。"},{"q":"一个家族中有几代中的几位罹患了癌症，这有可能涉及癌基因的突变。下列选项中不是癌基因表达产物的是","o":["转录因子","蛋白酪氨酸激酶","生长因子","蛋白磷酸酶","生长因子受体"],"a":3,"e":"癌基因产物多为生长因子、生长因子受体、蛋白酪氨酸激酶、转录因子等；蛋白磷酸酶多由抑癌基因如PTEN编码。"},{"q":"关于体细胞杂交叙述不正确的是","o":["杂交细胞保留一方染色体，而另一方染色体逐渐丢失","利用碱基互补配对原则","可以利用该方法进行基因定位","杂交细胞含有双亲不同的染色体","胸苷激酶通过该方法定位于17号染色体"],"a":1,"e":"体细胞杂交是细胞水平的染色体融合与丢失，用于基因定位，不涉及碱基互补配对原则。碱基互补配对是核酸分子间识别原则，与细胞杂交无关。"},{"q":"合成甘油三酯能力最强的组织是","o":["肝脏","脂肪组织","小肠","肾脏","肌肉组织"],"a":0,"e":"肝、脂肪组织及小肠均为甘油三酯合成场所，其中肝合成能力最强。肝细胞不能储存甘油三酯，需组装成VLDL分泌入血运至肝外组织。"},{"q":"蛋白质在酶的作用下可完全水解成","o":["多肽","脂蛋白","氨基酸","脂蛋白与氨基酸","氨基酸与多肽"],"a":2,"e":"食物蛋白质经胃蛋白酶、胰液及肠黏膜蛋白酶和肽酶的共同作用，最终完全水解为各种氨基酸，由小肠吸收。"},{"q":"干扰素抑制病毒作用使elF2失活的修饰方式是","o":["磷酸化","羧基化","ADP核糖基化","甲基化","乙酰化"],"a":0,"e":"双链RNA激活的蛋白激酶使eIF-2α磷酸化，从而阻断翻译起始，这是干扰素抗病毒作用的重要机制。"},{"q":"蛋白质的体外表达系统大体上可分为","o":["细菌表达系统与病毒表达系统","昆虫表达系统与酵母表达系统","酵母表达系统与病毒表达系统","原核表达系统与真核表达系统","哺乳动物表达系统与细菌表达系统"],"a":3,"e":"蛋白质体外表达体系按宿主细胞分为原核表达系统与真核表达系统，前者常用大肠埃希菌，后者包括酵母、昆虫和哺乳动物细胞。"},{"q":"下列激素中，可抑制激素敏感性甘油三酯脂肪酶的是","o":["肾上腺素","胰高血糖素","胰岛素","TSH","ACTH"],"a":2,"e":"胰岛素是抗脂解激素，通过激活蛋白磷酸酶使激素敏感性甘油三酯脂肪酶去磷酸化而失活，从而抑制脂肪动员。"},{"q":"第二信使二酯酰甘油（DAG）的来源是由","o":["甘油三酯水解而成","磷脂酰肌醇-4,5-二磷酸（PIP2）水解生成","卵磷脂水解产生","在体内合成","由胆固醇转化而来的"],"a":1,"e":"DAG由磷脂酰肌醇特异性磷脂酶C水解PIP2产生，同时生成IP3；两者均为第二信使，DAG留在膜上激活PKC，IP3促钙库释放Ca2+。"},{"q":"在细胞内，葡萄糖无氧氧化生成","o":["乳酸","脂肪酸","酮体","乙酰乙酸","核糖"],"a":0,"e":"葡萄糖在细胞质中经糖酵解生成丙酮酸，缺氧时丙酮酸在乳酸脱氢酶催化下接受NADH的氢还原为乳酸，净生成2分子ATP。"},{"q":"合成血红素的基本原料是","o":["乙酸、CO、Fe2+","珠蛋白、Fe2+","琥珀酰CoA、Fe3+","乙酰CoA、甘氨酸、Fe2+","琥珀酰CoA、甘氨酸、Fe2+"],"a":4,"e":"血红素合成的原料是甘氨酸、琥珀酰CoA和Fe2+，在ALA合酶等催化下经多步反应生成血红素。"},{"q":"丙酮酸脱氢酶复合体为直径约30nm的多角形，含有3种酶和5种辅酶。在糖的有氧氧化过程中，丙酮酸经丙酮酸脱氢酶复合体催化后的产物不包括","o":["乙酰CoA","FADH2","NADH＋H＋","CO2","丙酮"],"a":4,"e":"丙酮酸脱氢酶复合体催化丙酮酸氧化脱羧，产物为乙酰CoA、NADH+H+和CO2；复合体含FAD为辅因子，但脱下的氢最终交给NAD+，反应不生成丙酮。"},{"q":"可用于基因表达谱分析的是","o":["Western blotting","原位杂交","PCR","DNA芯片","Southern blotting"],"a":3,"e":"基因芯片将大量探针固定于固相载体，与标记的cDNA或cRNA杂交，可同时检测成千上万基因的表达水平，是基因表达谱分析的常用方法。"},{"q":"载体构建是基因工程常用的基本技术。要将外源的基因片段插入某个载体的多克隆位点，首先需要","o":["核酸外切酶","核酸内切酶","限制性的核酸内切酶","DNase","RNase"],"a":2,"e":"多克隆位点由多种限制性核酸内切酶的识别序列串联而成，须用相应限制酶切开载体与外源片段产生匹配末端，才能拼接成重组体。"},{"q":"体内非必需氨基酸合成的主要途径是","o":["转氨基作用","联合脱氨基作用","嘌呤核苷酸循环","氧化脱氨基作用","还原脱氨基作用"],"a":1,"e":"联合脱氨基作用由转氨基与L-谷氨酸氧化脱氨偶联，反应可逆，其逆向过程使α-酮酸氨基化，是体内合成非必需氨基酸的主要途径。"},{"q":"重组DNA技术领域常用的质粒DNA来自于","o":["原核细胞染色体DNA","原核细胞染色体外独立遗传单位","真核细胞染色体的DNA","真核细胞染色体外独立遗传单位","病毒DNA"],"a":1,"e":"质粒是细菌染色体外能自主复制、稳定遗传的双链环状DNA分子，经人工改造后用作重组DNA技术的克隆载体。"},{"q":"下列关于tRNA分子的叙述，正确的是","o":["5'端是羟基化的","不具茎环结构","含有乙酰化的碱基","3'端的碱基顺序为-CCA","含有dTMP"],"a":3,"e":"tRNA的3′-端为-CCA序列，其末端腺苷酸的3′-OH是与氨基酸结合的部位。tRNA具有茎环结构，含稀有碱基但非乙酰化碱基，也不含dTMP。"},{"q":"肿瘤的发生除了与癌基因的异常活化以及肿瘤抑制基因的异常失活密切相关外，也与生长因子及其受体的高度活化密切相关，下列哪种生长因子的活化不能导致肿瘤的发生","o":["EGF","VEGF","TNF","IGF","EPO"],"a":4,"e":"EPO由肾产生，主要调节红细胞发育，不属于促进细胞恶性转化的生长因子。EGF、VEGF、IGF等生长因子及其受体高度活化与肿瘤发生相关。"},{"q":"克隆某一目的DNA的基本过程，不包括以下哪一项","o":["基因载体的选择与构建","外源基因与载体的拼接","重组DNA分子导入受体细胞","重组体的筛选","表达目的基因编码的蛋白质"],"a":4,"e":"DNA克隆包括目的DNA分离获取、载体选择与构建、外源基因与载体拼接、重组分子导入受体细胞及重组体筛选鉴定；表达目的蛋白属基因表达，是基因工程的最终目标而非克隆步骤。"},{"q":"原核生物非依赖Rho因子的转录终止方式是","o":["形成终止复合物","形成终止空泡","形成发夹结构","形成poly(A)的尾巴","形成三叶草的结构"],"a":2,"e":"非依赖ρ因子的转录终止依赖转录产物3′-端形成富含GC的发夹结构，其后紧跟一段寡聚U序列，使RNA聚合酶脱离模板。"},{"q":"使细胞内环化腺苷酸（cAMP）水平降低的因素有","o":["蛋白激酶C","蛋白激酶A","磷酸二酯酶","腺苷酸环化酶","磷脂酶C"],"a":2,"e":"磷酸二酯酶催化cAMP水解为5′-AMP，使细胞内cAMP水平降低；腺苷酸环化酶则催化ATP生成cAMP而升高其水平。"},{"q":"反竞争性抑制作用的描述正确的是","o":["抑制剂既与酶相结合又与酶-底物复合物相结合","抑制剂只与酶-底物复合物相结合","抑制剂使酶促反应的Km值降低，Vmax增高","抑制剂使酶促反应的Km值升高，Vmax降低","抑制剂不改变酶促反应的Km值，只降低Vmax"],"a":1,"e":"反竞争性抑制剂只能与酶-底物复合物结合，其结合位点由底物诱导产生，使表观Km降低、Vmax降低，双倒数图呈平行线。"},{"q":"在正常呼吸的线粒体中，不包含在复合体中的细胞色素是","o":["细胞色素a","细胞色素b","细胞色素c","细胞色素c1","细胞色素P450"],"a":2,"e":"细胞色素c是呼吸链中可流动的电子传递体，游离于线粒体内膜外侧，不包含在复合体中。Cyt a、b、c1分别属于复合体Ⅳ、Ⅲ、Ⅲ的组分。"},{"q":"氰化物中毒引起缺氧是由于","o":["微循环障碍","干扰氧的运输","中枢性肺换气不良","抑制细胞呼吸","氧耗增加"],"a":3,"e":"氰化物抑制细胞色素氧化酶，电子不能传递给氧，组织细胞无法利用氧进行生物氧化，故表现为内呼吸障碍性缺氧。"},{"q":"原核DNA复制中，①DNA聚合酶Ⅲ，②解旋酶，③DNA聚合酶Ⅰ，④引物酶，⑤DNA连接酶，⑥SSB的作用顺序是","o":["④③①②⑤⑥","②③⑥④①⑤","④②①⑤⑥③","④②⑥①③⑤","②⑥④①③⑤"],"a":4,"e":"复制起始时解旋酶先解开双链，SSB稳定单链，引物酶合成引物，DNA聚合酶Ⅲ延伸子链，DNA聚合酶Ⅰ切除引物并填补缺口，最后由DNA连接酶连接片段。"},{"q":"反竞争性抑制剂对酶促反应速率的影响是","o":["Km升高，Vmax不变","Km下降，Vmax下降","Km不变，Vmax下降","Km下降，Vmax升高","Km下降，Vmax不变"],"a":1,"e":"反竞争性抑制剂只与ES复合物结合，使表观Km降低、Vmax降低，双倒数作图呈平行线。"},{"q":"在色氨酸操纵子中，衰减子存在于","o":["启动序列","操纵序列","调节序列","结构基因","前导序列"],"a":4,"e":"trp操纵子的衰减子位于前导序列内，前导mRNA可形成2/3或3/4发卡结构，随色氨酸浓度升高而提前终止转录，起精调作用。"},{"q":"白喉毒素可共价修饰下列哪种因子","o":["eIF-5","eEF-2","eIF-2","EF-1","eIF-4F"],"a":1,"e":"白喉毒素作为修饰酶使eEF2发生ADP核糖基化而失活，从而抑制真核细胞蛋白质合成。eEF2与原核EF-G功能相似，参与肽链延长。"},{"q":"下列哪种物质对巯基酶有直接的保护作用","o":["NADH","GSSG","GSH","FAD","泛酸"],"a":2,"e":"还原型谷胱甘肽的巯基具有还原性，可直接保护酶分子中的巯基免遭氧化，维持酶活性；GSSG为其氧化型。"},{"q":"利用恰当的方法，把正在进行DNA复制的细胞里的冈崎片段分离出来，这些短链DNA应具有的特性是","o":["它们是双链的DNA","它们是一组短的单链DNA片段","它们是DNA/RNA杂化双链","它们的碱基序列具有一致性","它们是环状双链DNA"],"a":1,"e":"冈崎片段是后随链上不连续合成的短链DNA，分离时呈一组长度不等的单链片段，其5′-端带有RNA引物。"},{"q":"蛋白质的含氮量是","o":["0、12","0、14","0、16","0、18","0、20"],"a":2,"e":"蛋白质含氮量平均为16%，即0.16，故可用凯氏定氮测定含氮量再乘以6.25推算蛋白质含量。"},{"q":"有关呼吸链叙述正确的是","o":["两条呼吸链由四种酶复合体组成","递电子体同时也是递氢体","递氢体同时也是递电子体","抑制Cyt a3，则呼吸链中各组分都呈氧化态","呼吸链的组分通常按E0由大到小的顺序排列"],"a":2,"e":"递氢体传递氢时必然同时传递电子，故递氢体也是递电子体；递电子体不一定传递氢，如细胞色素只传递电子。"},{"q":"胆固醇合成的限速酶是","o":["HMG-CoA裂解酶","HMG-CoA还原酶","HMG-CoA合成酶","甲羟戊酸激酶","鲨烯环氧合酶"],"a":1,"e":"HMG-CoA还原酶催化HMG-CoA还原为甲羟戊酸，是胆固醇合成的限速步骤，其活性受胆固醇别构抑制、受胰岛素诱导并呈昼夜节律变化。"},{"q":"脂肪酸合成酶催化合成的脂肪酸只能是","o":["硬脂酸","20碳脂酸","15碳脂酸","软脂酸","不饱和脂肪酸"],"a":3,"e":"脂肪酸合酶复合体经缩合、还原、脱水、再还原循环，每轮延长2个碳，7轮后由硫酯酶水解释放16碳的软脂酸，更长碳链的脂肪酸需另行延长。"},{"q":"精氨酸酶主要存在于哪种组织","o":["脾脏","小肠","肝脏","肌肉","脑组织"],"a":2,"e":"精氨酸酶是尿素生成的关键酶，主要存在于肝脏，催化精氨酸水解生成尿素和鸟氨酸。肝脏是尿素合成的主要器官。"},{"q":"氨基酸脱羧基的辅酶是","o":["FAD","生物素","TPP","磷酸吡哆胺","磷酸吡哆醛"],"a":4,"e":"氨基酸脱羧酶的辅酶是磷酸吡哆醛，即维生素B6的磷酸酯。转氨基反应中磷酸吡哆醛与磷酸吡哆胺相互转变传递氨基，脱羧反应由磷酸吡哆醛直接参与。"},{"q":"Southern blotting的基本过程是","o":["将DNA转移到膜上，用DNA探针杂交","将蛋白质转移到膜上，用抗体做探针杂交","将RNA转移到膜上，用DNA探针杂交","将DNA转移到膜上，用RNA探针杂交","将RNA转移到膜上，用RNA探针杂交"],"a":0,"e":"DNA印迹法将凝胶电泳分离的DNA变性后转移至硝酸纤维素膜或尼龙膜，再用标记的DNA探针杂交，用于基因组DNA的定性与定量分析。"},{"q":"以下不是维生素A的生理功能是","o":["作为视紫红质的成分参与视觉","维持上皮组织的结构和功能","抗氧化作用","调节血钙浓度促进生长、发育","增强机体抵抗力，有一定抗癌作用"],"a":3,"e":"维生素A的视黄醛参与构成视紫红质维持暗视觉，视黄酸调节基因表达、维持上皮分化并具抗氧化作用；调节血钙浓度、促进骨骼发育是维生素D的功能。"},{"q":"乳糖操纵子中，能够和阻遏蛋白结合的部位是","o":["P序列","-35区","O序列","-10区","CAP位点"],"a":2,"e":"阻遏蛋白由I基因编码，与操纵序列O结合使操纵子处于关闭状态，阻碍RNA聚合酶与P序列结合。别乳糖等诱导剂结合阻遏蛋白使其构象改变而与O序列解离。"},{"q":"下列哪类氨基酸都是必需氨基酸","o":["碱性氨基酸","含硫氨基酸","分支氨基酸","芳香族氨基酸","脂肪族氨基酸"],"a":2,"e":"支链氨基酸包括缬氨酸、亮氨酸和异亮氨酸，三者均为营养必需氨基酸。碱性、含硫及芳香族氨基酸中并非全部为必需氨基酸。"},{"q":"用于检测体内蛋白质-DNA相互作用的技术是","o":["酵母双杂交实验","电泳迁移率变动测定（EMSA）","GST pull-down实验","染色质免疫沉淀（ChIP）","免疫共沉淀（CoIP）"],"a":3,"e":"染色质免疫沉淀（ChIP）利用特异性抗体沉淀蛋白质-DNA复合体，经序列分析确定所结合的DNA序列，是研究体内DNA与蛋白质相互作用的主要方法。EMSA用于体外分析DNA与蛋白质相互作用。"},{"q":"与下列α-氨基酸相应的α-酮酸，是三羧酸循环的中间产物的是","o":["丙氨酸","谷氨酸","精氨酸","胱氨酸","苏氨酸"],"a":1,"e":"谷氨酸经转氨基或氧化脱氨基生成α-酮戊二酸，后者是三羧酸循环的中间产物；丙氨酸对应的丙酮酸不属循环中间物。"},{"q":"下列血浆脂蛋白中甘油三酯含量最高、最低的分别是","o":["CM，VLDL","LDL，HDL","VLDL，HDL","HDL，CM","CM，HDL"],"a":4,"e":"CM以转运外源性甘油三酯为主，甘油三酯含量最高，可达80%以上；HDL蛋白质含量高、甘油三酯含量最低，主要逆向转运胆固醇。"},{"q":"关于环腺苷酸（cAMP）的描述，错误的是","o":["在腺苷酸环化酶催化下由ATP生成","由磷酸二酯酶水解成5'-AMP","合成与分解反应都在细胞膜上进行","它是多数含氮激素的第二信使","胰岛素能够降低细胞内cAMP的浓度"],"a":2,"e":"cAMP由腺苷酸环化酶在质膜内侧催化生成，而水解它的磷酸二酯酶存在于细胞质，故合成与分解并非都在膜上进行。"},{"q":"下列关于tRNA的叙述，错误的是","o":["含有密码子环","通常由70～80个核苷酸组成","参与蛋白质生物合成","三级结构呈倒L型","含有大量的稀有碱基"],"a":0,"e":"tRNA含的是反密码子环而非密码子环，其中居中的3个核苷酸与mRNA密码子互补配对；tRNA约70～80个核苷酸，富含稀有碱基，三级结构呈倒L型。"},{"q":"原核生物RNA聚合酶的全酶组成是","o":["α2βσ","αββ'σ","α2ββ'ωσ","αββ'","ααβ'"],"a":2,"e":"原核生物RNA聚合酶全酶由核心酶α2ββ'ω与σ因子组成，σ因子识别启动子并引导全酶结合，起始转录后脱落。"},{"q":"有些疾病是由于基因的过度表达引起的，因此可通过向患者体内导入有抑制基因表达作用的核酸，阻断致病基因的异常表达，从而达到治疗疾病的目的，这种基因治疗策略是","o":["基因矫正","基因置换","基因增补","基因失活","基因敲除"],"a":3,"e":"向患者导入反义RNA、核酶或siRNA等抑制性核酸，阻断致病基因的异常表达，称基因失活或基因干扰。"},{"q":"当肝细胞内ATP供应充分时，下列叙述中哪项是错误的","o":["丙酮酸激酶被抑制","6-磷酸果糖激酶-1被抑制","异柠檬酸脱氢酶被抑制","果糖双磷酸酶-1被抑制","进入三羧酸循环的乙酰辅酶A减少"],"a":3,"e":"ATP供应充分时，果糖双磷酸酶-1被激活而非抑制，以促进糖异生。此时磷酸果糖激酶-1、丙酮酸激酶及异柠檬酸脱氢酶均受抑制，糖酵解与三羧酸循环减慢。"},{"q":"有关蛋白质亚基的描述，正确的是","o":["一条多肽链卷曲成螺旋结构","两条以上多肽链卷曲形成的二级结构","两条以上多肽链与辅基结合成蛋白质","每个亚基都有各自的三级结构","一条多肽链就是一个亚基"],"a":3,"e":"亚基是四级结构中具有完整三级结构的多肽链，各亚基以非共价键相连成特定空间排布；仅由一条肽链构成的蛋白质无四级结构。"},{"q":"以NAD+为辅酶的脱氢酶有","o":["葡萄糖-6-磷酸脱氢酶","6-磷酸葡糖酸脱氢酶","脂酰CoA脱氢酶","苹果酸脱氢酶","琥珀酸脱氢酶"],"a":3,"e":"苹果酸脱氢酶以NAD+为辅酶，催化苹果酸脱氢生成草酰乙酸，脱下的氢由NAD+接受形成NADH+H+。琥珀酸脱氢酶和脂酰CoA脱氢酶的辅基为FAD，葡萄糖-6-磷酸脱氢酶和6-磷酸葡糖酸脱氢酶以NADP+为辅酶。"},{"q":"环化腺苷酸（cAMP）能别构激活","o":["磷脂酶A","蛋白激酶A","蛋白激酶C","蛋白激酶G","酪氨酸蛋白激酶"],"a":1,"e":"cAMP是蛋白激酶A的别构激活剂，与其调节亚基结合后释出催化亚基，从而激活蛋白激酶A。"},{"q":"苯妥英钠降低血清未结合胆红素的机制是","o":["刺激肝细胞合成更多的Z蛋白","诱导肝细胞线粒体内UDP-葡萄糖醛酸基转移酶的生成","诱导肝细胞滑面内质网UDP-葡萄糖醛酸基转移酶的生成","使UDP-葡萄糖醛酸供应增加","改变未结合胆红素的分子构型"],"a":2,"e":"苯妥英钠诱导肝细胞滑面内质网UDP-葡萄糖醛酸基转移酶生成，加速胆红素与葡萄糖醛酸结合，从而降低血清未结合胆红素。"},{"q":"泛酸是下列哪种辅酶或辅基的组成成分","o":["FMN","NAD+","CoASH","TPP","NADP+"],"a":2,"e":"泛酸是辅酶A（CoASH）的组成成分，CoA参与酰基转移反应；FMN、FAD含维生素B2，NAD+、NADP+含维生素PP，TPP含维生素B1。"},{"q":"原核生物的核糖体上有3个重要的功能部位，该功能部位可以释放已经卸载的氨酰-tRNA，将tRNA排出。该重要的功能部位称为","o":["A位","P位","E位","氨基酰位","肽酰位"],"a":2,"e":"E位即排出位，负责释放已卸载氨基酸的tRNA；A位结合氨酰-tRNA，P位结合肽酰-tRNA。"},{"q":"决定氧化磷酸化速率的最主要的生理因素是","o":["ADP浓度","呼吸链抑制剂","解偶联剂","激素","线粒体突变"],"a":0,"e":"氧化磷酸化速率主要取决于ADP浓度，ADP/ATP比值升高时电子传递加快、耗氧量增加，ATP生成增多。"},{"q":"真核细胞转染的常用方法有","o":["氯化钙转染","DEAE纤维素介导转染","超声波穿孔","脂质体转染","噬菌体载体介导"],"a":3,"e":"脂质体转染以人工脂质膜包裹DNA形成囊泡，经与细胞膜融合将外源基因导入真核细胞，操作简单、重复性好、对细胞无毒；氯化钙法多用于细菌转化。"},{"q":"中心法则阐明的遗传信息表达方式是","o":["蛋白质→RNA→DNA","RNA→DNA→蛋白质","RNA→蛋白质→DNA","DNA→RNA→蛋白质","DNA→蛋白质→RNA"],"a":3,"e":"中心法则指遗传信息由DNA转录为RNA，再由RNA翻译成蛋白质，即DNA→RNA→蛋白质。"},{"q":"由插入序列和转座子介导的基因移位或重排称","o":["转座","转导","转染","转化","接合"],"a":0,"e":"由插入序列或转座子介导的基因移位或重排称为转座重组，即转座。"},{"q":"内皮型NO合酶的编码区G894T位点的SNP，可能与原发性高血压有关。下列哪种策略可以研究这一机制","o":["蛋白质结构分析","条件性基因敲除","GWAS关联分析","紫外交联免疫共沉淀测序","基因捕获"],"a":0,"e":"该SNP位于编码区，可使所编码氨基酸改变，通过蛋白质结构分析比较突变前后蛋白质的空间构象与功能，能阐明其影响内皮型NO合酶的机制。"},{"q":"发生在同源序列间的重组是","o":["位点特异的重组","随机重组","非位点特异的重组","基本重组","人工重组"],"a":3,"e":"同源重组又称基本重组，发生在两个相似或相同DNA分子的同源序列之间，进行核苷酸序列的互换。"},{"q":"绝大多数血浆蛋白质的合成场所是","o":["肾","骨髓","肝","肌肉","脾"],"a":2,"e":"绝大多数血浆蛋白质在肝合成，如清蛋白、纤维蛋白原和纤维粘连蛋白等，仅少量由其他组织细胞合成，如γ球蛋白由浆细胞合成。"},{"q":"关于酶的化学修饰调节的叙述，错误的是","o":["酶以有活性（高活性）和无活性（低活性）两种形式存在","属于快速调节","两种形式的转变由不同酶催化","别构酶不存在化学修饰调节","具有级联放大效应"],"a":3,"e":"化学修饰调节与别构调节可并存于同一酶，如磷酸果糖激酶、乙酰CoA羧化酶既受别构调节又受磷酸化修饰，故别构酶不存在化学修饰调节的说法错误。"},{"q":"原核生物DNA复制中的引物是","o":["以DNA为模板合成的DNA片段","以RNA为模板合成的RNA片段","以DNA为模板合成的RNA片段","以RNA为模板合成的DNA片段","引物仍存在于复制完成的DNA链中"],"a":2,"e":"DNA复制需引物提供3'-OH末端，引物是以DNA为模板经引物酶催化合成的短链RNA片段。复制完成后引物被切除并由DNA片段填补。"},{"q":"下列哪种辅酶中不含维生素","o":["CoASH","FAD","NAD+","FMN","CoQ"],"a":4,"e":"辅酶Q即泛醌，为脂溶性醌类化合物，不含维生素成分；CoASH含泛酸，FAD和FMN含维生素B2，NAD+含维生素PP。"},{"q":"参与维持DNA单链模版状态，避免形成超螺旋结构的酶是","o":["引发前体","拓扑异构酶Ⅰ","单链DNA结合蛋白","解链酶","拓扑异构酶Ⅱ"],"a":2,"e":"单链DNA结合蛋白（SSB）结合已解开的单链DNA，维持模板单链稳定状态并保护其免受核酸酶降解。拓扑异构酶Ⅱ（促旋酶）的作用是解开复制中形成的超螺旋，理顺DNA链结构。"},{"q":"抑癌基因是一类抑制细胞过度生长、增殖从而遏制肿瘤形成的基因。对于正常细胞，调控生长的基因（如原癌基因）和调控抑制生长的基因（如抑癌基因）的协调表达是调节控制细胞生长的重要分子机制之一。这两类基因相互制约，维持正负调节信号的相对稳定。抑癌基因的丢失或失活也可能导致肿瘤发生。癌症是原癌基因激活和抑癌基因失活双重事件导致的。第一个被克隆的抑癌基因是","o":["p16","Rb","p53","DCC","APC"],"a":1,"e":"1986年克隆的视网膜母细胞瘤RB基因是第一个被克隆的抑癌基因，其失活与视网膜母细胞瘤及骨肉瘤等发生有关。"},{"q":"下列物质，可作为磷脂酰胆碱和磷脂酰乙醇胺合成中的共同原料是","o":["Gly","SAM","Ser","Thr","Met"],"a":2,"e":"丝氨酸脱羧生成乙醇胺，乙醇胺经SAM提供甲基生成胆碱；二者分别活化为CDP-乙醇胺和CDP-胆碱，再与甘油二酯缩合生成磷脂酰乙醇胺和磷脂酰胆碱。"},{"q":"有关肝脏在维生素代谢作用的描述中，哪项有错误","o":["肝脏是贮存维生素的重要器官","肝脏分泌胆汁酸为吸收脂溶性维生素所必须","脂肪吸收不良时肝脏脂溶性维生素贮存量下降","肝病的出血倾向与维生素K作用延长有关","肝病的出血倾向与维生素K吸收减少有关"],"a":4,"e":"官方答案为【肝病的出血倾向与维生素K吸收减少有关】，但依据教材，正确答案为【肝病的出血倾向与维生素K作用延长有关】。肝病时胆汁酸减少致维生素K吸收障碍、凝血因子合成不足而出血，“作用延长”无依据。"},{"q":"嘌呤核苷酸从头合成的直接原料，不包括","o":["甘氨酸","天冬氨酸","谷氨酸","CO2","一碳单位"],"a":2,"e":"嘌呤环从头合成需甘氨酸、天冬氨酸、谷氨酰胺、CO2和一碳单位；谷氨酸不直接参与提供嘌呤环的碳氮原子。"},{"q":"真核生物mRNA的3'-末端尾巴结构是","o":["约200个核苷酸的poly(C)","约200个核苷酸的poly(A)","约100个核苷酸的poly(G)","约200个核苷酸的poly(U)","约300个核苷酸的poly(U)"],"a":1,"e":"真核生物mRNA转录后在其3'端加上poly(A)尾，长度一般为100～200个核苷酸，可保护mRNA并增强其翻译模板活性。"},{"q":"肝脏中合成的酮体不能氧化的器官是","o":["心肌","肾脏","脑","骨骼肌","肝脏"],"a":4,"e":"肝缺乏琥珀酰CoA转硫酶等酮体利用酶，只能生成酮体而不能氧化酮体；心肌、肾、脑和骨骼肌等肝外组织可利用酮体。"},{"q":"丙酮酸羧化酶的描述正确的是","o":["活性可被柠檬酸激活","活性可被乙酰辅酶A激活","是糖酵解的关键酶","存在于细胞质中","催化所有的糖异生原料的异生过程"],"a":1,"e":"丙酮酸羧化酶以生物素为辅基，仅存在于线粒体，催化丙酮酸羧化为草酰乙酸；乙酰CoA是其别构激活剂，柠檬酸无此作用，该酶也不属糖酵解关键酶。"},{"q":"可识别分泌蛋白新生肽链N端的物质是","o":["转肽酶","信号肽识别颗粒","GTP酶","RNA酶","mRNA的聚A尾部"],"a":1,"e":"信号识别颗粒识别并结合分泌蛋白新生肽链N端的信号肽，引导核糖体附着内质网并使肽链进入内质网腔。"},{"q":"组氨酸生成组胺是通过","o":["脱氨基作用","氧化作用","还原作用","脱羧基作用","转氨基作用"],"a":3,"e":"组氨酸由组氨酸脱羧酶催化脱去羧基生成组胺，属氨基酸脱羧基作用。组胺是强烈的血管扩张剂，能增加毛细血管通透性。"},{"q":"未结合胆红素的特点是","o":["胆红素丙酸侧链的羧基可参与分子内氢键的形成","比结合胆红素更难通过生物膜","易在尿中出现","不加尿素或乙醇就能与重氮试剂呈阳性反应","水溶性强"],"a":0,"e":"未结合胆红素分子内形成6个氢键，其丙酸侧链羧基参与氢键形成，使分子呈刚性折叠而具疏水亲脂性，易透过细胞膜，不能直接与重氮试剂反应，尿中不出现。"},{"q":"关于细胞色素特点正确的是","o":["细胞色素也可分布在线粒体外","血红素A是Cyt c的辅基","呼吸链中有许多种细胞色素可被CN-抑制","细胞色素C氧化酶其本质不是细胞色素","所有的细胞色素与线粒体内膜紧密结合，不易分离"],"a":0,"e":"细胞色素并非都结合于线粒体内膜，微粒体中的细胞色素P450、b5即分布于线粒体外。"},{"q":"糖组学研究的主要技术，不包括","o":["色谱","质谱","糖微阵列技术","限制性片段长度多态性分析","生物信息学"],"a":3,"e":"糖组学常用色谱、质谱、糖微阵列及生物信息学分析聚糖的结构与功能；限制性片段长度多态性分析用于DNA水平基因突变检测。"},{"q":"下述属于基因沉默技术的是","o":["PCR","体外转录","逆转录","RNAi","原位杂交"],"a":3,"e":"RNAi由与靶基因同源的双链RNA引发，经Dicer作用生成siRNA，诱导同源mRNA特异性降解，实现转录后基因沉默，是研究基因功能的重要工具。"},{"q":"胆固醇生物合成的限速步骤是","o":["二甲丙烯焦磷酸生成焦磷酸法尼酯","鲨烯生成羊毛固醇","羊毛固醇生成胆固醇","HMG-CoA生成甲羟戊酸","乙酰乙酰CoA生成HMG-CoA"],"a":3,"e":"HMG-CoA还原酶催化HMG-CoA还原为甲羟戊酸，是胆固醇合成的限速酶，其活性受产物别构抑制、磷酸化修饰及酶蛋白合成量的调节。"},{"q":"不参与DNA复制的酶是","o":["解螺旋酶","连接酶","引物酶","拓扑酶","核酶"],"a":4,"e":"DNA复制需解螺旋酶解开双链、拓扑酶理顺超螺旋、引物酶合成RNA引物、连接酶连接片段；核酶是具催化功能的RNA分子，不属复制酶系。"},{"q":"控制长链脂酰辅酶A进入线粒体氧化速度的因素是","o":["脂酯CoA合成酶的活性","肉碱-脂酰基转移酶活性","脂酰CoA脱氢酶的活性","脂酰CoA的含量","细胞内ATP的水平"],"a":1,"e":"长链脂酰CoA不能直接透过线粒体内膜，须经肉碱脂酰转移酶Ⅰ催化生成脂酰肉碱进入基质，该酶活性是β-氧化的限速环节，决定氧化速度。"},{"q":"磷酸二羟丙酮是哪两种物质代谢之间的交叉点","o":["糖-氨基酸","糖-脂酸","糖-甘油","糖-胆固醇","糖-核酸"],"a":2,"e":"糖酵解产生的磷酸二羟丙酮可还原生成甘油-3-磷酸，进而参与甘油三酯合成，是糖代谢与甘油代谢的连接点。"},{"q":"有关蛋白质β-折叠的描述，错误的是","o":["主链骨架呈锯齿状","氨基酸侧链交替位于扇面上下方","β-折叠的肽链之间不存在化学键","肽链充分伸展","β-折叠有反平行式和平行式结构"],"a":2,"e":"β-折叠肽段间通过肽键羰基氧与亚氨基氢形成氢键维系，并非不存在化学键；其主链呈锯齿状伸展，侧链交替位于扇面上下，分平行与反平行两式。"},{"q":"1mol乙酰乙酸生成过程中参与反应的乙酰CoA有多少","o":["1mol","2mol","3mol","4mol","5mol"],"a":1,"e":"2分子乙酰CoA先缩合为乙酰乙酰CoA，再与1分子乙酰CoA缩合成HMG-CoA，后者裂解时又释出1分子乙酰CoA，故净消耗2mol乙酰CoA。"},{"q":"Ca2+-依赖的蛋白激酶是","o":["受体型酪氨酸蛋白激酶","非受体型酪氨酸蛋白激酶","蛋白激酶C","蛋白激酶A","蛋白激酶G"],"a":2,"e":"蛋白激酶C含C1和C2结构域，需DAG与Ca2+共同激活，属Ca2+依赖的蛋白激酶；PKA由cAMP激活，PKG由cGMP激活，酪氨酸蛋白激酶不依赖钙。"},{"q":"基因重组过程中，对于载体DNA，内切酶的切点应在","o":["复制起点","遗传标志的上游","遗传标志的下游","多克隆位点","启动子结构中"],"a":3,"e":"载体须具备多克隆位点，即多种限制性核酸内切酶的单一切点，供外源基因插入；复制起点、选择标志和启动子分别承担复制、筛选和表达功能。"},{"q":"在已知序列的情况下，最方便的获取目的DNA的方法是","o":["化学合成法","聚合酶链式反应","直接从组织中提取","从基因组文库中筛选","基因芯片"],"a":1,"e":"已知目的基因序列时，可依据两端序列设计引物，用PCR在短时间内特异性扩增出目的DNA，简便快速，优于从基因组文库筛选或从组织直接提取。"},{"q":"病毒癌基因来自","o":["自身基因突变","细胞原癌基因的转导","细胞抑癌基因的突变","与其他病毒基因重组","自身基因重排"],"a":1,"e":"逆转录病毒将宿主细胞的原癌基因转导进入病毒基因组，经改造成为具有致癌能力的病毒癌基因。"},{"q":"在线粒体中，氧化磷酸化解偶联意味着","o":["线粒体代谢停止","线粒体膜ATP酶被抑制","线粒体三羧酸循环被终止","ATP持续形成并且氧被利用","ATP生成停止，但氧被利用"],"a":4,"e":"解偶联剂破坏线粒体内膜的质子电化学梯度，ATP合成停止，但电子仍沿呼吸链传递并消耗氧，能量以热能释放。"},{"q":"β地中海贫血是我国华南地区最常见的常染色体隐性遗传性血液病之一。患者由于血红蛋白的β珠蛋白基因突变，导致β珠蛋白缺失（β0）或合成不足（β+），从而引发遗传性溶血性贫血。国际上已报道约170种β珠蛋白基因的突变体，我国也已发现20多种突变体。在临床上，如果要对β地中海贫血患者进行β珠蛋白基因多个突变位点的检测，选择下述哪种方法较为合适","o":["Southern印迹","Northern印迹","变性高效液相色谱（DHPLC）","等位基因特异寡核苷酸（ASO）分子杂交","聚合酶链式反应-限制性片段长度多态性（PCR-RFLP）"],"a":2,"e":"PCR-变性高效液相色谱可借异源双链的保留时间差异扫描目的基因序列，适合多个突变位点的快速筛查。"},{"q":"红细胞内主要的抗氧化物是","o":["NADH","COQH","GSH","FADH2","FMNH2"],"a":2,"e":"还原型谷胱甘肽是体内重要的抗氧化剂，可保护含巯基的蛋白质或酶免受氧化剂损害，红细胞中NADPH维持GSH含量使其免遭氧化损伤。NADH、COQH、FADH2和FMNH2不是红细胞内主要的抗氧化物。"},{"q":"谷胱甘肽的功能主要是","o":["参与氧化还原反应","脱羧基反应","脱氨基反应","甲基化反应","磷酸化反应"],"a":0,"e":"谷胱甘肽的巯基具有还原性，是体内重要还原剂，参与氧化还原反应，保护含巯基的酶和蛋白质免遭氧化。"},{"q":"脂肪酸合成的限速酶是","o":["甘油三酯脂肪酶","甘油二酯脂肪酶","甘油一酯脂肪酶","乙酰辅酶A羧化酶","脂蛋白脂肪酶"],"a":3,"e":"乙酰CoA羧化酶催化乙酰CoA羧化为丙二酸单酰CoA，是脂肪酸合成的限速酶，受柠檬酸别构激活、AMPK磷酸化抑制。甘油三酯脂肪酶等为脂肪动员的酶。"},{"q":"印迹技术中所使用的支持物为","o":["滤纸","醋酸纤维薄膜","硝酸纤维素膜","琼脂糖","聚丙烯酰胺凝胶"],"a":2,"e":"印迹技术将电泳分离的核酸或蛋白质转移至硝酸纤维素膜等固相支持物上，再与探针杂交或进行免疫学检测。"},{"q":"Lac阻遏蛋白是由","o":["Z基因编码","Y基因编码","A基因编码","I基因编码","P序列编码"],"a":3,"e":"Lac操纵子的I基因有独立启动子，编码阻遏蛋白，后者与O序列结合使操纵子关闭；Z、Y、A基因分别编码β-半乳糖苷酶、通透酶和转乙酰酶。"},{"q":"最常用的两大双序列比对工具是FASTA和","o":["ASCL","BLAST","PERL","MatLab","SPSS"],"a":1,"e":"FASTA和BLAST是最常用的双序列比对工具，BLAST基于局部比对搜索，可快速在数据库中查找同源序列。"},{"q":"催化mRNA 3'端poly(A)尾生成的酶是","o":["RNA聚合酶","核苷酸转移酶","RNase P","RNase D","多聚A聚合酶"],"a":4,"e":"真核mRNA 3'端的多聚腺苷酸尾在转录后由多聚A聚合酶催化，以ATP为底物逐个添加腺苷酸生成。"},{"q":"磷酸化作用可使下列哪种酶受到抑制","o":["糖原合酶","已糖激酶","糖原磷酸化酶","磷酸化酶b激酶","甘油三酯脂肪酶"],"a":0,"e":"糖原合酶磷酸化后由活性型a转为无活性型b，糖原合成受抑；而糖原磷酸化酶经磷酸化则被激活，二者调节方向相反。"},{"q":"下列关于酮体代谢的叙述，不正确的是","o":["肝不能氧化利用酮体","生成酮体是肝特有的功能","饥饿时酮体生成减少","糖尿病患者酮体生成可增多","脑不能氧化脂酸，但能利用酮体"],"a":2,"e":"饥饿时脂肪动员增强，脂肪酸β-氧化和酮体生成增多，故饥饿时酮体生成减少的说法错误；长期饥饿时酮体成为脑的主要能源。"},{"q":"关于同工酶的叙述，正确的是","o":["它们催化相同的化学反应","它们的分子结构相同","它们的理化性质相同","它们分子量相同","它们有相同的免疫学性质"],"a":0,"e":"同工酶是催化相同化学反应而酶蛋白分子结构、理化性质及免疫学特性各不相同的一组酶，其活性中心三维结构相同或相似。"},{"q":"糖酵解的脱氢反应步骤是","o":["1，6-双磷酸果糖→3-磷酸甘油醛+磷酸二羟丙酮","3-磷酸甘油醛→磷酸二羟丙酮","3-磷酸甘油醛→1，3-二磷酸甘油酸","1，3-二磷酸甘油酸→3-磷酸甘油酸","3-磷酸甘油酸→2-磷酸甘油酸"],"a":2,"e":"糖酵解第6步甘油醛-3-磷酸氧化为1,3-二磷酸甘油酸，由甘油醛-3-磷酸脱氢酶催化，以NAD+接受氢，是唯一的脱氢反应。"},{"q":"运输内源性胆固醇的血浆脂蛋白主要是","o":["CM","LDL","VLDL","HDL","IDL"],"a":1,"e":"LDL是运输内源性胆固醇的主要形式，肝是降解LDL的主要器官，约50%在肝内降解；CM转运外源性甘油三酯及胆固醇，VLDL则转运内源性甘油三酯。"},{"q":"可合成甲状腺素、儿茶酚胺及黑色素的氨基酸是","o":["甲硫氨酸","色氨酸","组氨酸","谷氨酸","酪氨酸"],"a":4,"e":"酪氨酸经酪氨酸羟化酶作用生成多巴，进而合成儿茶酚胺；在黑色素细胞中经酪氨酸酶羟化生成多巴，最终聚合为黑色素；酪氨酸也是甲状腺素合成的前体。"},{"q":"关于蛋白质二级结构的描述，错误的是","o":["蛋白质局部或某一段肽链有规则的重复构象","蛋白质部分主链的空间构象","主链构象由每个肽键的两个二面角所确定","整条多肽链中全部氨基酸的位置","无规卷曲也属于二级结构范畴"],"a":3,"e":"二级结构是多肽链局部主链有规则的重复构象，由肽键两个二面角决定，包括α-螺旋、β-折叠、β-转角和无规卷曲；整条肽链全部氨基酸残基的空间位置属三级结构。"},{"q":"下列各组中终止密码子是","o":["UAG UAA UGA","AAA CCG GCC","UGA AUG GAU","UAA GAA CAA","GUU CUU AUU"],"a":0,"e":"终止密码子有UAA、UAG、UGA三个，均不编码任何氨基酸，而是作为肽链合成的终止信号。AUG为起始密码子，其余各组均含编码氨基酸的密码子。"},{"q":"原核生物的切除修复过程需要：①DNA连接酶；②DNA polⅠ；③Uvr蛋白类。其作用先后次序是","o":["①，②，③","②，③，①","②，①，③","③，②，①","③，①，②"],"a":3,"e":"核苷酸切除修复先由Uvr蛋白识别并切除含损伤的片段，再由DNA polⅠ填补缺口，最后由DNA连接酶封接。"},{"q":"关于β-折叠结构的叙述，正确的是","o":["只存在于α-角蛋白中","只有反平行式结构，没有平行式结构","α-螺旋是右手螺旋，β-折叠是左手螺旋","肽平面的二面角与α-螺旋的相同","主链骨架呈锯齿状形成折叠的片层"],"a":4,"e":"β-折叠中多肽链充分伸展，以Cα为旋转点依次折叠成锯齿状，相邻肽段间以氢键相连形成片层，有平行与反平行两种形式。"},{"q":"脂肪酸在肝脏进行β-氧化不生成的化合物是","o":["H2O","乙酰CoA","脂酰CoA","NADH+H+","FADH2"],"a":0,"e":"β-氧化的加水步骤消耗水，脱氢生成FADH2和NADH，硫解生成乙酰CoA和缩短两碳的脂酰CoA，全过程不产生水。"},{"q":"下列哪种因素与脂肪肝的病因相关","o":["摄入高蛋白饮食","高糖饮食","肝内磷脂缺乏，合成VLDL能力下降","摄入高脂饮食","肝脏有转化脂肪的能力"],"a":2,"e":"肝内磷脂合成障碍时VLDL组装和分泌减少，甘油三酯运出受阻而在肝内堆积，是脂肪肝发生的重要机制。"},{"q":"关于TFⅡD的叙述下列不正确的是","o":["是一种由多亚基组成的复合物","TFⅡD通过TBP识别、结合TATA盒","为PolⅠ、Ⅱ和Ⅲ三种转录过程所必需","由TATA组成的最简单的启动子只需TFⅡD","与原核基因转录无关"],"a":3,"e":"含TATA盒的最简单启动子仍需TFⅡA、TFⅡB、TFⅡE、TFⅡF、TFⅡH及RNA聚合酶Ⅱ共同组装起始复合物，并非只需TFⅡD。"},{"q":"肝脏在脂肪代谢中产生过多酮体的主要原因是由于","o":["肝功能不好","肝中脂肪代谢紊乱","脂肪运转障碍","脂肪摄食过多","糖供给不足或利用障碍"],"a":4,"e":"糖供给不足或利用障碍时草酰乙酸生成减少，乙酰CoA不能顺利进入三羧酸循环而在肝内大量转化为酮体，导致酮血症。"},{"q":"最普遍进行的生物转化第二相反应是代谢物与","o":["谷胱甘肽结合","葡糖醛酸结合","硫酸结合","乙酰基结合","甲基结合"],"a":1,"e":"葡萄糖醛酸结合是肝内最普遍的第二相反应，UDPGA提供葡萄糖醛酸基与含羟基、羧基的脂溶性物质结合，生成物水溶性增强而便于排出。"},{"q":"关于生物氧化能量的释放，正确的是","o":["生物氧化过程中总能量变化与反应途径无关","生物氧化过程中总能量变化与反应途径有关","细胞质是生物氧化和产能的主要部位","只能通过氧化磷酸化生成ATP","生物氧化释放的能量只能用来产热供能"],"a":0,"e":"生物氧化总能量变化取决于始态与终态，与反应途径无关，途径只影响反应速度和方式。生物氧化分步进行、能量逐步释放，主要在线粒体进行，能量可储存于ATP或产热。"},{"q":"原核生物和真核生物翻译起始不同之处在于","o":["真核生物先靠Shine Dalgarno序列使mRNA结合核糖体","真核生物帽子结合蛋白是翻译起始因子之一","IF比eIF种类多","原核生物和真核生物使用不同起始密码","原核生物有TATAAT作为翻译起始序列，真核生物则是TATA"],"a":1,"e":"真核生物翻译起始需帽子结合蛋白（eIF4E）识别mRNA 5′-帽，原核生物则靠Shine-Dalgarno序列与16S rRNA配对。"},{"q":"糖酵解的最重要的关键酶是","o":["葡萄糖激酶","己糖激酶","丙酮酸激酶","6-磷酸果糖激酶-1","磷酸甘油酸激酶"],"a":3,"e":"磷酸果糖激酶-1是糖酵解最重要的关键酶和首要调控点，可被果糖-2,6-二磷酸别构激活、被ATP抑制。"},{"q":"关于蛋白质合成的终止阶段，正确的叙述是","o":["终止密码子有两种","终止密码子都由U、G、A三种脱氧核苷酸构成","一种特异的tRNA可识别终止密码子","某种蛋白质因子可识别终止密码子","肽酰-tRNA在核蛋白体“受位”上脱落"],"a":3,"e":"终止密码子有UAA、UAG、UGA三种，不被任何tRNA识别，由释放因子识别并结合A位，水解肽酰-tRNA酯键释放新生肽链。"},{"q":"已知某酶Km值为0、05mol/L，欲使其所催化的反应速率达Vmax的80%时，底物浓度应是","o":["0、04mol/L","0、05mol/L","0、1mol/L","0、2mol/L","0、8mol/L"],"a":3,"e":"按米氏方程，v/Vmax=［S］/（Km+［S］），代入0.8=［S］/（0.05+［S］）得［S］=4Km=0.2mol/L，即底物浓度为Km的4倍时反应速率达最大速率的80%。"},{"q":"重组DNA技术中实现目的基因与载体DNA拼接的是","o":["DNA聚合酶","RNA聚合酶","DNA连接酶","RNA连接酶","限制性核酸内切酶"],"a":2,"e":"重组DNA技术中，目的基因与载体DNA的共价拼接由DNA连接酶催化完成；限制性核酸内切酶负责切割DNA产生黏端或平端，不承担连接功能。"},{"q":"同源重组是指","o":["同一种属来源的DNA间重组","同一细胞来源的DNA间重组","同一DNA分子中两链间的重组","DNA双链的同源区间重组","DNA的专一重组"],"a":3,"e":"同源重组发生在两个相似或相同DNA分子的同源区段之间，通过链间交换实现遗传信息重排，是基本的DNA重组方式。"},{"q":"丙二酸对琥珀酸脱氢酶的抑制作用是","o":["反馈抑制","竞争性抑制","非竞争抑制","不可逆抑制","反竞争性抑制"],"a":1,"e":"丙二酸与琥珀酸结构类似，与底物竞争结合琥珀酸脱氢酶的活性中心，属于竞争性抑制，其特点是表观Km增大而Vmax不变。"},{"q":"蛋白质分子中β-转角属于蛋白质的","o":["四级结构","三级结构","二级结构","一级结构","侧链结构"],"a":2,"e":"β-转角是肽链主链局部盘曲形成的二级结构，常含3～4个氨基酸残基，多位于蛋白质分子表面。"},{"q":"大肠杆菌合成的所有未修饰的多肽链，其-N末端的氨基酸残基应是","o":["甲硫氨酸","丝氨酸","甲酰甲硫氨酸","甲酰丝氨酸","谷氨酸"],"a":2,"e":"原核生物起始密码子AUG代表甲酰甲硫氨酸，故新合成的多肽链N端均为甲酰甲硫氨酸，其后可经脱甲酰基酶或氨基肽酶修饰。"},{"q":"健康人饥饿3天时，血浆代谢物浓度变化最大的可能是","o":["脂酸","葡萄糖","乙酰乙酸","亮氨酸","丙酮酸"],"a":2,"e":"饥饿3天时脂肪动员加强，肝生成酮体显著增多，血中乙酰乙酸与β-羟丁酸可升高数十倍，是变化幅度最大的代谢物；血糖仅轻度下降。"},{"q":"以下属于直接针对目的DNA进行筛选的方法是","o":["青霉素抗药性","四环素抗药性","分子杂交","蓝白斑筛选","电泳"],"a":2,"e":"分子杂交用标记探针与目的DNA直接配对，可鉴定重组体中是否含特定序列；抗药性筛选和蓝白斑筛选依据载体标志，属间接筛选。"},{"q":"依赖Ca2＋的蛋白激酶是","o":["蛋白激酶A（PKA）","蛋白激酶C（PKC）","蛋白激酶G（PKG）","受体型酪氨酸蛋白激酶（RTK）","非受体型酪氨酸蛋白激酶"],"a":1,"e":"PKC是受DAG和Ca2+调控的蛋白质丝氨酸/苏氨酸激酶，属肌醇磷脂系统重要酶。PKA、PKG分别受环核苷酸调控，并非依赖Ca2+。"},{"q":"下列哪个不是一碳单位","o":["甲基","甲烯基","甲炔基","甲酰基","一氧化碳"],"a":4,"e":"一碳单位是某些氨基酸分解代谢产生的含一个碳原子的基团，包括甲基、甲烯基、甲炔基、甲酰基和亚氨甲基，由FH4携带。一氧化碳是血红素分解产物，不属于一碳单位。"},{"q":"存在于肝脏，但不存在于肌肉的酶是","o":["己糖激酶","葡萄糖-6-磷酸酶","乳酸脱氢酶","丙酮酸脱氢酶","糖原磷酸化酶"],"a":1,"e":"葡萄糖-6-磷酸酶仅存在于肝和肾，肌组织缺乏该酶，故肌糖原分解生成的葡萄糖-6-磷酸不能水解成葡萄糖补充血糖。"},{"q":"下列哪一种物质不能作为基因载体","o":["pBR322质粒","λ噬菌体","噬菌体","病毒RNA","逆转录病毒DNA"],"a":3,"e":"载体须为能自我复制的DNA分子，如质粒、噬菌体和病毒DNA，病毒RNA不能直接作为基因载体。"},{"q":"地球上有极少数人可能永远不会被艾滋病毒感染，即便他们接触艾滋病毒的机会比其他人高。你认为这些为数不多的幸运儿是因为","o":["他们的趋化因子受体的基因发生了突变，导致HIV无法进入宿主细胞","他们体内含有特殊的核酸酶，能将进入细胞内的HIV基因组RNA迅速水解","他们体内含有特殊的抑制剂，能强烈抑制HIV编码的蛋白酶","他们体内含有特殊的抑制剂，能强烈抑制HIV编码的逆转录酶","他们的基因组DNA上缺乏原病毒DNA整合的特异性位点"],"a":0,"e":"趋化因子受体CCR5是HIV进入宿主细胞的辅助受体，其基因缺失突变使HIV无法进入细胞，从而产生抗性。"},{"q":"关于糖蛋白O-连接型聚糖的叙述，错误的是","o":["合成部位是内质网和高尔基体","聚糖与多肽链丝氨酸/苏氨酸残基连接","O-连接型聚糖的合成发生在多肽链合成后","需要由N-乙酰葡糖胺和半乳糖构成的核心二糖","糖基化位点由多肽链的二、三级结构决定"],"a":3,"e":"O-连接型聚糖的核心二糖由N-乙酰半乳糖胺与半乳糖构成，并非N-乙酰葡糖胺；其合成在多肽链合成后由糖基转移酶逐个加糖，不需聚糖载体。"},{"q":"当ATP/ADP比值降低时，可产生的效应是","o":["抑制丙酮酸羧化酶","抑制丙酮酸激酶","激活6-磷酸果糖激酶-1","抑制丙酮酸脱氢酶","激活果糖双磷酸酶-1"],"a":2,"e":"ATP/ADP比值降低提示能量消耗增多，可激活磷酸果糖激酶-1和丙酮酸激酶，加快糖酵解流量。果糖-2，6-二磷酸是磷酸果糖激酶-1最强的别构激活剂。"},{"q":"醛缩酶的产物包括","o":["G-6-P","F-6-P","F-2，6-BP","1,3-二磷酸甘油酸","3-磷酸甘油醛"],"a":4,"e":"醛缩酶催化果糖-1,6-二磷酸裂解为磷酸二羟丙酮和3-磷酸甘油醛，二者再经丙糖磷酸异构酶相互转变，产物均是丙糖磷酸。"},{"q":"合成尿素首步反应的产物是","o":["鸟氨酸","氨基甲酰磷酸","瓜氨酸","精氨酸","天冬氨酸"],"a":1,"e":"尿素合成的首步反应在肝线粒体由氨基甲酰磷酸合成酶Ⅰ催化，以NH3与CO2为原料、消耗ATP生成氨基甲酰磷酸，后者再与鸟氨酸缩合生成瓜氨酸。"},{"q":"磺胺类药物可抑制细菌体内哪种物质的合成","o":["维生素B12","吡哆醛","辅酶A","四氢叶酸","生物素"],"a":3,"e":"磺胺类药物与对氨基苯甲酸结构相似，竞争性抑制二氢蝶酸合酶，阻断细菌四氢叶酸合成，使核酸合成受阻而抑菌。"},{"q":"多数氨基酸都具有两个以上密码子，但以下哪项除外","o":["苏氨酸、甘氨酸","脯氨酸、精氨酸","丝氨酸、亮氨酸","色氨酸、甲硫氨酸","天冬氨酸和天冬酰胺"],"a":3,"e":"色氨酸和甲硫氨酸各只有一个密码子，分别为UGG和AUG；其余氨基酸均有2个或2个以上密码子。"},{"q":"血浆脂蛋白琼脂糖凝胶电泳，从负极到正极的电泳图谱顺序是","o":["CM→前β-脂蛋白→β-脂蛋白→α-脂蛋白","CM→α-脂蛋白→前β-脂蛋白→β-脂蛋白","α-脂蛋白→前β-脂蛋白→β-脂蛋白→CM","CM→β-脂蛋白→前β-脂蛋白→α-脂蛋白","α-脂蛋白→β-脂蛋白→前β-脂蛋白→CM"],"a":3,"e":"血浆脂蛋白琼脂糖电泳从负极到正极依次为CM、β-脂蛋白、前β-脂蛋白和α-脂蛋白，CM不泳动留在原点，α-脂蛋白泳动最快。"},{"q":"由泛酸组成的辅酶参与","o":["脱羧反应","羧化反应","脱氢反应","转酰基作用","转氨基作用"],"a":3,"e":"泛酸在体内转变为辅酶A和酰基载体蛋白，二者作为酰基转移酶的辅因子参与转酰基反应，广泛参与糖、脂质和蛋白质代谢。"},{"q":"蛋白质的等电点是","o":["蛋白质溶液pH值为7、0时溶液的pH值","蛋白质溶液pH值为7、4时溶液的pH值","蛋白质分子呈正离子状态时溶液的pH值","蛋白质分子呈负离子状态时溶液的pH值","蛋白质的正电荷与负电荷相等时溶液的pH值"],"a":4,"e":"等电点时蛋白质解离成正、负离子的趋势相等，净电荷为零，此时溶液的pH即为该蛋白质的等电点。"},{"q":"同一质粒DNA分子沉降系数最大的状态是","o":["超螺旋","环状","线性","有一个或几缺口的双链环状分子","变性后"],"a":0,"e":"同一质粒分子的几种构象中，超螺旋盘绕最紧密、体积最小，在离心场中沉降最快，其沉降系数最大。"},{"q":"关于蛋白聚糖和糖蛋白的叙述，正确的是","o":["蛋白聚糖分子中聚糖比例小于蛋白","糖蛋白中糖所占的比例较蛋白多","糖蛋白和蛋白聚糖中糖链的结构相同","糖蛋白和蛋白聚糖在体内的分布相同","二者的糖链延长都需要特异性糖基转移酶催化"],"a":4,"e":"糖蛋白与蛋白聚糖的糖链合成都依赖糖基转移酶特异性、有序地将供体糖基转移至接受体，糖基转移酶由基因编码。蛋白聚糖以聚糖为主、糖蛋白以蛋白为主，二者糖链结构与分布均不同。"},{"q":"亚硝酸盐造成的DNA的损伤是","o":["形成TT二聚体","使A甲基化","转换T为C","取代A并异构成G","使C脱氨成U"],"a":4,"e":"亚硝酸属碱基修饰剂，可使胞嘧啶脱氨生成尿嘧啶，造成U与A配对而改变DNA序列；腺嘌呤脱氨则生成次黄嘌呤，与胞嘧啶配对。"},{"q":"下列哪项不是构成呼吸链的成员","o":["细胞色素","铁硫蛋白","辅酶Q","FAD","血红素"],"a":4,"e":"呼吸链成员包括细胞色素、铁硫蛋白、辅酶Q和FAD等；血红素是血红蛋白、肌红蛋白及细胞色素的辅基，本身不构成呼吸链组分。"},{"q":"能识别DNA特异序列并在识别位点或其周围切割双链DNA的一类酶是","o":["限制性外切核酸酶","非限制性核酸外切酶","限制性核酸内切酶","DNase","DNA内切酶"],"a":2,"e":"限制性核酸内切酶能识别DNA的特异序列，多为回文结构，并在识别位点处或其附近切断双链DNA。"},{"q":"在肝细胞内尿素合成的部位是","o":["线粒体","溶酶体","粗面内质网","滑面内质网","细胞质及线粒体"],"a":4,"e":"尿素合成的鸟氨酸循环起始于线粒体，氨甲酰磷酸合成与瓜氨酸生成在线粒体内完成；精氨酸代琥珀酸合成、裂解及精氨酸水解则在细胞质进行。"},{"q":"下列属于脂肪动员产物的是","o":["甘油","3-磷酸甘油","3-磷酸甘油醛","1,3-二磷酸甘油酸","2,3-二磷酸甘油酸"],"a":0,"e":"脂肪动员时甘油三酯在脂肪酶作用下逐步水解，释放游离脂肪酸和甘油入血，供其他组织氧化利用。"},{"q":"PCR技术不可用于","o":["目的基因的克隆","微量目的基因的检测","某些遗传病的检测","蛋白质结构分析","体外突变目的基因"],"a":3,"e":"PCR用于扩增和检测核酸，可克隆目的基因、检测微量基因和遗传病、体外突变基因；蛋白质结构分析不属其用途。"},{"q":"有机磷化合物可结合于胆碱酯酶活性中心的","o":["丝氨酸残基的羟基","半胱氨酸残基的巯基","色氨酸残基的吲哚基","组氨酸残基的咪唑基","精氨酸残基的胍基"],"a":0,"e":"有机磷化合物与胆碱酯酶活性中心丝氨酸残基的羟基共价结合，使酶磷酰化而失活，属不可逆抑制，可用解磷定恢复酶活性。"},{"q":"氮杂丝氨酸抗肿瘤作用的原理是","o":["其结构与谷胺酰胺相似，可抑制嘌呤核苷酸的合成","叶酸类似物，抑制嘌呤核苷酸的合成","结构与次黄嘌呤相似，从而抑制嘌呤核苷酸的合成","抑制一碳单位的转运","丝氨酸类似物，可抑制一碳单位的生成"],"a":0,"e":"氮杂丝氨酸结构与谷氨酰胺相似，可干扰谷氨酰胺在嘌呤核苷酸合成中的作用，从而抑制嘌呤核苷酸生成。"},{"q":"在原核生物翻译起始时，所形成的70S起始复合物中不包括的物质是","o":["核糖体的大亚基","核糖体的小亚基","mRNA","fMet-tRNA","起始因子"],"a":4,"e":"原核生物70S起始复合物由30S小亚基、50S大亚基、mRNA和fMet-tRNA组成，起始因子在复合物形成后释放，不包含在复合物中。"},{"q":"合成初级游离型胆汁酸的直接原料是","o":["乙酰CoA","胆固醇","7α-羟胆固醇","胆固醇酯","结合胆红素"],"a":1,"e":"肝细胞以胆固醇为原料，经7α-羟化等反应直接合成胆酸和鹅脱氧胆酸，二者即初级游离型胆汁酸。"},{"q":"组成蛋白质的氨基酸有","o":["10种","15种","20种","25种","30种"],"a":2,"e":"参与蛋白质合成的氨基酸有20种，均为L-α-氨基酸（甘氨酸除外），此为组成蛋白质的基本结构单位。不同蛋白质仅氨基酸含量与排列顺序不同。"},{"q":"真核基因表达调控具有典型的多级调控特点，已知诱导剂A能诱导B基因的表达，关于诱导剂A调控B基因表达层次研究的实验体系中描述正确的是","o":["如果加入DNA甲基转移酶抑制剂，B基因的表达没有改变，说明诱导剂A对B基因表达的调控不发生在染色质水平","如果加入放线菌酮，B基因的表达没有改变，说明诱导剂A对B基因表达的调控不发生在蛋白质水平","如果加入鹅膏蕈碱，B基因的mRNA表达没有改变，说明诱导剂A对B基因表达的调控不发生在转录水平","如果加入蛋白酶体抑制剂，B基因的表达没有改变，说明诱导剂A对B基因表达的调控不发生在翻译后水平","如果诱导剂A能诱导特异mRNA生成并导致B基因的表达改变，说明诱导剂A对B基因表达的调控发生在转录后或翻译水平"],"a":4,"e":"诱导剂A能诱导特异mRNA生成，说明转录已经启动，B基因表达的后续改变位于mRNA生成之后，故调控环节在转录后加工或翻译水平。"},{"q":"关于化学渗透假说，错误的叙述是","o":["由Peter Mitchell首先提出","需要在线粒体内膜两侧形成电位差","必须将内膜外侧的H＋泵到膜内来","质子泵的作用在于存储能量","H＋顺浓度由膜外回流时驱动ATP的生成"],"a":2,"e":"化学渗透假说认为呼吸链复合体Ⅰ、Ⅲ、Ⅳ将质子从基质侧泵至膜间隙，形成跨内膜质子电化学梯度储存能量，质子顺梯度回流至基质时驱动ATP合酶合成ATP。泵出方向为基质到膜间隙，而非膜外泵入膜内。"},{"q":"酶不可逆抑制的机制是","o":["抑制剂与酶的活性中心以共价键结合","抑制剂使酶蛋白变性","抑制剂与酶的辅助因子结合","抑制剂以次级键结合在酶活性中心外","抑制剂与酶表面的极性基团结合"],"a":0,"e":"不可逆抑制剂与酶活性中心必需基团以共价键结合，透析、超滤均不能去除，酶活性不可恢复；有机磷农药结合胆碱酯酶丝氨酸羟基即属此类。"},{"q":"酶促反应动力学是研究","o":["酶分子的空间构象","酶的电泳行为","酶的活性中心","影响酶促反应速率的因素","酶的合成"],"a":3,"e":"酶促反应动力学研究酶催化反应的速度及影响反应速度的因素，包括酶浓度、底物浓度、pH、温度、抑制剂及激活剂等。"},{"q":"三羧酸循环中哪1个化合物前后各放出1个分子CO2","o":["柠檬酸","乙酰CoA","琥珀酸","α-酮戊二酸","异柠檬酸"],"a":3,"e":"异柠檬酸脱氢酶催化异柠檬酸氧化脱羧生成α-酮戊二酸并释出CO2，α-酮戊二酸脱氢酶复合体再催化其脱羧释出第二个CO2，故α-酮戊二酸前后各放出一个CO2。"},{"q":"不发生在心肌细胞的代谢途径是","o":["糖酵解","糖异生","脂肪酸氧化","TCA循环","氧化磷酸化"],"a":1,"e":"心肌缺乏葡萄糖-6-磷酸酶，糖异生关键酶表达很低，不能进行糖异生；其能量主要来自脂肪酸β-氧化、三羧酸循环和氧化磷酸化。"},{"q":"RNA组学研究的RNA分子，不包括","o":["snRNA","mRNA","siRNA","miRNA","scRNA"],"a":1,"e":"RNA组学研究snmRNA，包括snRNA、siRNA、miRNA、scRNA等非编码小RNA；mRNA编码蛋白质，不属其研究范围。"},{"q":"含B族维生素的辅酶在酶促反应中的作用是","o":["传递电子，原子和化学基团的作用","稳定酶蛋白的构象","决定酶促反应的催化机制","决定酶的专一性","提高酶的催化活性"],"a":0,"e":"B族维生素衍生的辅酶作为运载体，在酶促反应中传递电子、质子或醛基、氨基、酰基、一碳单位等基团，其本身并无催化作用。"},{"q":"人类游离型胆汁酸不包括","o":["胆酸","鹅脱氧胆酸","甘氨石胆酸","石胆酸","脱氧胆酸"],"a":2,"e":"游离型胆汁酸包括胆酸、鹅脱氧胆酸、脱氧胆酸和石胆酸；甘氨石胆酸是石胆酸与甘氨酸的结合产物，属结合型胆汁酸。"},{"q":"食物淀粉的消化起始部位是","o":["小肠","大肠","胃","口腔","肾"],"a":3,"e":"淀粉的消化自口腔开始，唾液α-淀粉酶水解淀粉分子内的α-1，4-糖苷键；因食物在口腔停留时间很短，消化的主要场所仍在小肠。"},{"q":"钙调蛋白中钙离子的结合位点数为","o":["3个","4个","5个","6个","7个"],"a":1,"e":"钙调蛋白为哑铃形钙结合蛋白，分子中有4个结构域，每个结构域结合1个Ca2+；结合钙后构象改变，可激活钙调蛋白依赖的蛋白激酶等靶分子。"},{"q":"参加肠道次级结合胆汁酸生成的氨基酸是","o":["鸟氨酸","精氨酸","甘氨酸","甲硫氨酸","瓜氨酸"],"a":2,"e":"次级胆汁酸在肠菌作用下生成后，可与甘氨酸或牛磺酸结合形成次级结合胆汁酸，故甘氨酸参与其生成。"},{"q":"果糖双磷酸酶-1的抑制剂是","o":["磷酸果糖","2,6-双磷酸果糖","ATP","GTP","柠檬酸"],"a":1,"e":"果糖-2,6-二磷酸既是磷酸果糖激酶-1的别构激活剂，又是果糖二磷酸酶-1的别构抑制剂，二者反向调节第一个底物循环。"},{"q":"有关转录延长阶段，叙述不正确的是","o":["RNA聚合酶全酶催化此过程","RNA聚合酶与模板结合松弛","转录过程未终止时，即开始翻译","σ因子从转录起始复合物上脱落","RNA聚合酶与模板的结合无特异性"],"a":0,"e":"转录延长阶段σ亚基已从起始复合物脱落，由核心酶催化RNA链延伸，故全酶催化延长的说法错误。"},{"q":"关于pH对酶促反应速率影响的叙述，错误的是","o":["pH影响酶、底物或辅助因子的解离程度，从而影响酶促反应速率","溶液pH过高或过低会使酶活性降低，但不会引起酶蛋白变性","动物体内多数酶的最适pH接近中性","pH可影响酶活性中心的空间构象","酶的最适pH受底物浓度、缓冲液种类及浓度的影响"],"a":1,"e":"pH过高或过低不仅使酶活性降低，还会使酶蛋白变性失活，故该说法错误；最适pH受底物浓度、缓冲液种类和浓度影响，不是特征性常数。"},{"q":"受体的特异性取决于","o":["受体与G蛋白分子构象","受体与细胞膜的分子构象","受体与配体的分子构象","细胞膜的选择通透性","受体的类型"],"a":2,"e":"受体与配体的结合具有高度专一性，其特异性由两者的分子空间构象互补决定，构象匹配才能形成稳定的受体-配体复合物。"},{"q":"某种RNA在生物体内总量最多，约占RNA的80%以上。其与核糖体蛋白结合形成核糖体，为蛋白质的生物合成提供空间环境，其类似于一个移动的多肽链“装配厂”。该种RNA是","o":["mRNA","rRNA","tRNA","ncRNA","sncRNA"],"a":1,"e":"rRNA是细胞中含量最多的RNA，约占RNA总量的80%以上，与核糖体蛋白共同构成核糖体，为蛋白质合成提供场所。"},{"q":"关于真核生物蛋白质合成描述正确的是","o":["边转录，边翻译","先转录，后直接进行翻译","经转录后加工再进行翻译","核糖体大亚基先与小亚基结合","mRNA先与tRNA结合"],"a":2,"e":"真核生物转录在核内进行，前体mRNA须经加帽、加尾和剪接等转录后加工，成熟mRNA才转运至胞质翻译，转录与翻译不同时进行。"},{"q":"长期不食用植物油，会缺乏下列哪种物质","o":["亚麻酸","油酸","棕榈酸","硬脂酸","软脂酸"],"a":0,"e":"亚油酸和α-亚麻酸属必需脂肪酸，体内不能合成，须由植物油供给；长期缺乏可致生长迟缓、皮肤损害及脂质代谢异常。"},{"q":"缺乏时会引起坏血病的维生素是","o":["维生素B1","维生素B2","维生素C","维生素PP","硫辛酸"],"a":2,"e":"维生素C是胶原合成中脯氨酸羟化酶和赖氨酸羟化酶的辅因子，缺乏时胶原成熟障碍，毛细血管脆性增加而致坏血病。"},{"q":"关于RB基因的叙述，错误的是","o":["RB蛋白是p105","最初在视网膜母细胞瘤中发现","磷酸化形式是活性型","RB蛋白的磷酸化程度与细胞周期有关","低磷酸化RB蛋白是活性型"],"a":2,"e":"RB基因编码105kDa的RB蛋白，去磷酸化或低磷酸化形式为活性型，能结合E2F抑制细胞增殖；磷酸化使其失活，磷酸化程度随细胞周期变化。"},{"q":"增加双向电泳蛋白样品的溶解性的试剂，不包括","o":["变性剂","表面活性剂","氧化剂","还原剂","起载体作用的两性电解质"],"a":2,"e":"双向电泳样品溶解液含变性剂尿素、表面活性剂CHAPS、还原剂DTT和载体两性电解质，分别起变性、增溶、打开二硫键和维持pH梯度作用；氧化剂会使蛋白质氧化聚集。"},{"q":"磷脂酶C水解甘油磷脂后的产物是","o":["甘油","甘油二酯","溶血磷脂1","溶血磷脂2","脂酸"],"a":1,"e":"磷脂酶C作用于甘油磷脂的磷酸二酯键，水解生成甘油二酯和磷酸胆碱等。甘油二酯是磷脂酰胆碱、磷脂酰乙醇胺合成甘油二酯途径的重要中间物。"},{"q":"肝脏输出肝内合成的甘油三酯的形式是","o":["直接释放","参与合成CM形式","参与合成HDL形式","参与合成VLDL形式","参与合成LDL"],"a":3,"e":"肝合成的甘油三酯与载脂蛋白B100、磷脂和胆固醇组装成VLDL分泌入血，运至肝外组织供利用。"},{"q":"经脱羧基作用后生成γ-氨基丁酸的是","o":["半胱氨酸","谷氨酸","甘氨酸","谷氨酰胺","天冬氨酸"],"a":1,"e":"谷氨酸经L-谷氨酸脱羧酶催化脱去羧基生成γ-氨基丁酸，该酶以磷酸吡哆醛为辅酶，GABA是中枢抑制性神经递质。"},{"q":"脂肪酸进行β-氧化的部位是","o":["线粒体内膜上","线粒体基质内","微粒体","细胞质","细胞核"],"a":1,"e":"脂肪酸β-氧化的酶系存在于线粒体基质，活化的脂酰CoA经肉碱穿梭进入基质后完成脱氢、加水、再脱氢和硫解。"},{"q":"影响酶促反应速率的因素不包括","o":["底物浓度","酶的浓度","反应环境的酸碱度","反应温度","变性剂"],"a":4,"e":"影响酶促反应速率的因素为酶浓度、底物浓度、pH、温度、激活剂和抑制剂；变性剂破坏酶的空间结构，不属于动力学因素。"},{"q":"丙酮酸氧化时在哪个环节上进入呼吸链","o":["CoQ","NADH-CoQ还原酶","CoQH2-Cyt b","Cyt氧化酶","琥珀酸脱氢酶"],"a":1,"e":"丙酮酸氧化脱羧生成的NADH经复合体Ⅰ即NADH-泛醌还原酶将电子交给泛醌，其还原当量由此环节进入呼吸链。"},{"q":"高脂血症患者进行血清代谢组学分析，降低的成分有","o":["LDL","Apo E","CM","胆固醇","HDL"],"a":4,"e":"代谢组学分析显示，高脂血症患者血清HDL含量降低，HDL参与胆固醇逆向转运，其水平下降不利于胆固醇清除。"},{"q":"关于解偶联剂，错误的是","o":["可抑制氧化反应","使氧化反应和磷酸化反应脱节","使ATP生成减少","使呼吸加快，耗氧增加","常见的解偶联剂是二硝基苯酚"],"a":0,"e":"解偶联剂使氧化与磷酸化脱节，电子仍沿呼吸链传递，质子梯度被破坏，ATP生成减少，呼吸加快、耗氧增加，并不抑制氧化反应。"},{"q":"DNA双螺旋结构每旋转一周，沿轴上升高度是","o":["0、15nm","0、34nm","3、54nm","5、40nm","6、80nm"],"a":2,"e":"DNA双螺旋每旋转一周沿轴上升的高度即螺距，为3.54nm。B型DNA每圈含10.5个碱基对，相邻碱基对垂直间距0.34nm，二者乘积即螺距。"},{"q":"生物转化作用中属于第二相反应的是","o":["氧化","还原","水解","氧化+还原+水解","结合"],"a":4,"e":"生物转化第二相为结合反应，非营养物质与葡萄糖醛酸、硫酸或乙酰基等结合，极性进一步增强而易于排出。"},{"q":"鉴定疾病相关基因的关键是","o":["通过疾病家系的连锁分析对染色体进行定位","确定疾病表型和基因之间的实质联系","借助生物信息数据库对比待定基因的信息","利用生物化学和细胞生物学等方法确定基因功能","使用疾病动物模型确定导致异常表型的基因"],"a":1,"e":"鉴定疾病相关基因的关键是确定疾病表型与基因之间的实质联系，明确基因序列改变与表型的关系；定位、数据库比对和功能研究均为手段。"},{"q":"血红素合成的限速酶是","o":["血红素合酶","ALA脱水酶","ALA合酶","尿卟啉原Ⅰ同合酶","亚铁螯合酶"],"a":2,"e":"ALA合酶催化血红素合成的起始反应，是限速酶，其辅酶为磷酸吡哆醛，受血红素反馈抑制，半衰期约1小时。"},{"q":"磷脂酰肌醇二磷酸（PIP2）经磷脂酰肌醇激酶（PI-K）作用后的产物是","o":["PI","PI3","PIP","IP3","PIP3"],"a":4,"e":"PI3K催化PIP2肌醇环第3位磷酸化生成PIP3，PIP3作为第二信使募集并激活含PH结构域的PKB等信号分子。"},{"q":"限制性内切核酸酶以GGG▼CGCCC方式切割产生的末端突出部分含","o":["1个核苷酸","2个核苷酸","3个核苷酸","4个核苷酸","5个核苷酸"],"a":1,"e":"该酶在识别序列的对应位置交错切割双链，产生的黏性末端突出部分为2个核苷酸，可与其他片段互补连接。"},{"q":"关于阻塞性黄疸，下列说法错误的是","o":["常见于肠道阻塞","胆道阻塞，胆道压力增大破裂，结合胆红素反流入血","也称肝后性黄疸","尿胆红素阳性","粪便颜色可以变浅"],"a":0,"e":"阻塞性黄疸由胆管阻塞引起，常见于胆管炎、肿瘤、胆结石等，而非肠道阻塞。胆道压力增大致结合胆红素反流入血，尿胆红素阳性，粪便可变浅甚至呈白陶土色。"},{"q":"下述有关胆固醇合成的叙述，错误的是","o":["几乎全身组织均可合成，脑组织除外","需要NADPH供氢","主要在细胞质及内质网进行","关键酶是HMG-CoA还原酶","肝脏是合成的主要场所"],"a":0,"e":"除成年动物脑组织及成熟红细胞外，几乎全身各组织均可合成胆固醇，故“脑组织除外”的表述不准确。合成需NADPH供氢，关键酶为HMG-CoA还原酶，肝是主要场所。"},{"q":"下列哪种方法用于筛选与特定蛋白结合的未知RNA","o":["酵母单杂交系统","酵母双杂交系统","酵母三杂交系统","组织芯片","原位杂交"],"a":2,"e":"酵母三杂交系统引入RNA与蛋白质融合的第三个杂交组分，可筛选与特定蛋白质结合的未知RNA；双杂交用于蛋白质间相互作用。"},{"q":"关于病毒癌基因的叙述中，错误的是","o":["能使培养细胞转化为癌细胞","存在于逆转录病毒","又称病毒原癌基因","感染宿主能引起肿瘤","感染宿主细胞后可整合于宿主细胞"],"a":2,"e":"病毒癌基因（v-onc）来源于宿主细胞原癌基因，是原癌基因的转导与活化形式，不能称为“病毒原癌基因”。"},{"q":"关于疾病相关基因的鉴定和功能研究，以下说法中错误的是","o":["疾病相关基因的克隆可采取非染色体定位克隆和染色体定位克隆两大策略","GWAS可以覆盖外显子绝大部分疾病相关基因变异","人类新基因的克隆大都是从同源EST分析开始的","基因的功能即基因编码的蛋白质功能和非编码基因RNA的功能","基因功能可从生物化学、细胞和整体三个水平描述"],"a":1,"e":"GWAS在全基因组水平检测常见单核苷酸变异与疾病的关联，不覆盖外显子全部变异；覆盖外显子绝大部分变异的是全外显子组测序。"},{"q":"与蛋白质在电场中泳动的方向和速度无关的是","o":["蛋白质分子的大小","蛋白质分子所带的电荷","蛋白质的等电点","蛋白质溶液的pH","蛋白质溶液的温度"],"a":4,"e":"蛋白质在电场中的泳动方向取决于其所带电荷，而电荷性质由溶液pH与等电点的关系决定，泳动速度与分子大小、电荷量有关。温度不影响泳动方向和速度。"},{"q":"有关竞争性抑制作用的叙述，错误的是","o":["抑制剂与底物结构相似","与酶的结合是可逆的","与酶的活性中心结合","与酶非共价结合","抑制程度只与抑制剂的浓度有关"],"a":4,"e":"竞争性抑制的程度取决于抑制剂与底物的浓度比以及二者对酶的相对亲和力，并非仅由抑制剂浓度决定。"},{"q":"仅在肝中合成的化合物是","o":["糖原","尿素","脂肪酸","胆固醇","血浆蛋白"],"a":1,"e":"尿素生成仅在肝细胞经鸟氨酸循环完成，肝是合成尿素的唯一器官；糖原、脂肪酸、胆固醇可在多种组织合成，血浆蛋白也非仅由肝合成。"},{"q":"关于线粒体DNA（mtDNA）的特点，错误的是","o":["编码tRNA数目少于核基因是影响氧化磷酸化的主要因素","人mtDNA编码13条多肽链","mtDNA突变常可影响氧化磷酸化","mtDNA缺乏保护而容易受到损伤","遗传性mtDNA疾病以母系遗传居多"],"a":0,"e":"人mtDNA编码13条多肽、22种tRNA和2种rRNA，均与氧化磷酸化有关；其突变率高主要因呈裸露环状、缺乏蛋白质保护和损伤修复系统。"},{"q":"下列局部比对搜索工具BLAST序列数据库，哪一个是通过查询DNA序列比对蛋白质数据库的","o":["BLASTN","BLASTP","BLASTX","TBLASTN","TBLASTX"],"a":2,"e":"BLASTX以核苷酸序列为查询序列，翻译成六种阅读框的蛋白质序列后比对蛋白质数据库，适用于从DNA序列推测编码产物。"},{"q":"在8AcetylCoA+nATP+14 NADPH→palmitic acid+8CoASH+nADP+nPi+14NADP中，以下哪个是最强的激动剂","o":["Acetyl-CoA","Malonyl-CoA","Malate","Citrate","Oxaloacetate"],"a":3,"e":"柠檬酸是乙酰CoA羧化酶的别构激活剂，可使无活性原聚体聚合成有活性多聚体，是脂肪酸合成中最强的激动剂。"},{"q":"能使蛋白质溶液稳定的因素是","o":["蛋白质不带电荷","蛋白质溶液的黏度大","蛋白质分子表面带有水化膜和电荷层","蛋白质分子表面的疏水基因相互排斥","蛋白质分子中的肽键"],"a":2,"e":"蛋白质胶粒表面亲水基团形成水化膜，同时表面电荷相互排斥，两者共同阻止蛋白质颗粒聚集沉淀，是溶液稳定的主要因素。"},{"q":"以下选项中，建议通过功能克隆进行分离鉴定疾病相关基因的是","o":["镰状细胞贫血相关基因","类风湿性关节炎相关基因","2型糖尿病相关基因","哮喘相关基因","胰腺癌相关基因"],"a":0,"e":"镰状细胞贫血已知珠蛋白的氨基酸序列异常，据此设计简并探针筛选cDNA文库而获得基因，属功能克隆策略。"},{"q":"以下有关端粒酶的描述，除了哪一项，其他都是正确的","o":["其RNA组分是合成DNA片段的模板","向端粒的3'端添加DNA链","它协助线性染色体的合成","是低等原核生物特有的酶","是一种逆转录酶"],"a":3,"e":"端粒酶由RNA与逆转录酶组成，见于真核生物，以自身RNA为模板向染色体3'端添加端粒重复序列，补偿复制所致的末端缩短。"},{"q":"下列有关酮体的叙述错误的是","o":["酮体是脂酸在肝分解氧化时特有的中间产物","肝有活性较强的合成酮体的酶系","肝存在利用酮体的酶系","酮体是肝输出能源的一种方式","酮体是脑组织的重要能源"],"a":2,"e":"肝有活性较强的酮体合成酶系，但缺乏利用酮体的酶，酮体须经血液运至肝外组织氧化，故该说法错误。"},{"q":"氰化物是剧毒物，使人中毒致死的原因是","o":["与肌红蛋白中Fe3+结合使之不能储氧气","与Cyt b中Fe3+结合使之不能传递电子","与Cyt c中Fe3+结合使之不能传递电子","与Cyt a3中Fe3+结合使之不能激活1/2 O2","与血红蛋白中Fe3+结合使之不能运输氧气"],"a":3,"e":"氰化物与细胞色素a3的Fe3+结合，使Cyta3-CuB双核中心不能将电子传给氧，细胞色素氧化酶失活，呼吸链中断而迅速致死。"},{"q":"从IMP合成GMP需要","o":["谷氨酸","谷氨酰胺","天冬氨酸","天冬酰胺","甘氨酸"],"a":1,"e":"IMP先被NAD+氧化，再由谷氨酰胺提供氨基生成GMP，该过程由ATP供能；生成AMP时才由天冬氨酸提供氨基、GTP供能。"},{"q":"使乳糖操纵子实现高表达的条件是","o":["乳糖存在，葡萄糖缺乏","乳糖缺乏，葡萄糖存在","乳糖和葡萄糖均存在","乳糖和葡萄糖均不存在","只要乳糖存在"],"a":0,"e":"lac操纵子的强诱导既需乳糖存在以解除阻遏，又需葡萄糖缺乏使cAMP升高、CAP发挥正调节作用；葡萄糖存在时引起分解代谢阻遏。"},{"q":"肝内脂肪大量动员时，生成的乙酰辅酶A主要转变为","o":["胆固醇","葡萄糖","脂酸","酮体","胆固醇酯"],"a":3,"e":"肝内脂肪酸β-氧化生成大量乙酰CoA，因草酰乙酸不足不能充分进入三羧酸循环，转而由酮体合成酶系在肝线粒体生成酮体。"},{"q":"下列关于逆转录酶的叙述，正确的是","o":["是以mRNA为模板催化合成RNA的酶","其催化合成反应方向是3'→5'","催化合成时需先合成冈崎片段","此酶具有RNase活性","不需要引物"],"a":3,"e":"逆转录酶具有RNA依赖的DNA聚合酶、DNA依赖的DNA聚合酶和RNaseH三种活性，可水解RNA/DNA杂化链中的RNA。"},{"q":"脂肪细胞合成脂肪所需的甘油主要来自","o":["糖异生","葡萄糖分解","磷脂水解","脂肪水解","经甘油激酶作用生成的甘油磷酸提供"],"a":1,"e":"脂肪细胞缺乏甘油激酶，不能直接利用游离甘油，合成甘油三酯所需的甘油-3-磷酸主要由葡萄糖分解代谢的中间产物转变而来。"},{"q":"基因芯片检测的原理是基于","o":["抗原-抗体标记系统的应用","双色荧光探针系统的应用","化学发光信号标记系统的应用","放射性核素标记系统的应用","地高辛-配基标记系统的应用"],"a":1,"e":"基因芯片将大量已知序列探针有序固定于载体，基于双色或多色荧光标记样品与探针杂交，实现基因表达的大规模并行检测。"},{"q":"与DNA修复过程缺陷有关的疾病是","o":["着色性干皮病","黄嘌呤尿症","卟啉症","痛风","黄疸"],"a":0,"e":"着色性干皮病因DNA损伤核苷酸切除修复系统基因缺陷所致，患者皮肤对紫外线敏感，易在幼年发生皮肤癌，属修复缺陷型遗传病。"},{"q":"多核苷酸链由于链的5'-端和3'-端所含的基团不同，从而使得链具有了5'→3'的方向性。下面关于多核苷酸链叙述正确的是","o":["5'末端是指链的一末端核苷酸上C-5'上的羟基是自由的，对此核苷酸称为链的5'-羟基末端","5'末端是指链的一末端核苷酸上C-5'连接的磷酸只形成一个酯键，对此核苷酸称为链的5'-磷酸末端","3'末端是指链的另一末端核苷酸上C-3'连接的磷酸只形成一个酯键，对此核苷酸称为链的3'-磷酸末端","3'末端是指链的另一末端核苷酸上C-3'上没有氧原子，对此核苷酸称为链的3'-末端","3'末端是指链的另一末端核苷酸上C-3'连接的磷酸形成不止一个酯键，对此核苷酸称为链的3'-磷酸末端"],"a":1,"e":"多核苷酸链5′-端核苷酸的C-5′磷酸只与一个戊糖成酯，即游离的5′-磷酸末端；3′-端为游离的3′-羟基末端。"},{"q":"1,4,5-三磷酸肌醇（IP3）受体位于","o":["核膜","线粒体内膜","细胞膜","内质网","溶酶体"],"a":3,"e":"IP3为水溶性分子，可在细胞内扩散至内质网或肌质网膜上并与其受体结合，该受体即Ca2+通道，结合后开放促使钙库释放Ca2+。"},{"q":"tRNA分子3'末端的碱基序列是","o":["CCC-3'","AAC-3'","AAA-3'","CCA-3'","ACA-3'"],"a":3,"e":"tRNA的3'末端为CCA序列，氨基酸通过酯键连接于末端腺苷酸的3'-羟基上，是氨基酸的接受位点。该序列由tRNA核苷酸转移酶添加，不依赖模板。"},{"q":"关于高能磷酸键，叙述正确的是","o":["有高能磷酸键变化的反应都是不可逆反应","高能磷酸键只能通过氧化磷酸化生成","体内参与反应最多的高能磷酸键存在于ATP中","体内高能化合物都含有高能磷酸键","高能磷酸键是高能磷酸化合物中键能最高的化学键"],"a":2,"e":"ATP是体内能量代谢的共同中间载体，其末端高能磷酸键可转移给葡萄糖、UTP等多种底物，参与的反应最多；高能化合物还包括磷酸肌酸。"},{"q":"下列关于DNA双螺旋模型的叙述，错误的是","o":["是DNA的二级结构","双股链相互平行、走向相反","碱基位于双螺旋外侧","碱基间以非共价键相连","磷酸与脱氧核糖组成了双螺旋的骨架"],"a":2,"e":"双螺旋中脱氧核糖与磷酸构成亲水性骨架位于外侧，碱基对埋在螺旋内侧；两链反向平行而非平行，碱基间以氢键相连，属DNA二级结构。"},{"q":"质子泵抑制剂在强酸环境下，能与壁细胞膜表面的H+/K+-ATP酶的巯基共价结合，抑制H+/K+-ATP酶活性，用于十二指肠溃疡治疗。下列可以评价抑制效果的策略是","o":["RT-qPCR","Western Blotting","Northern Blotting","免疫组化","酶活性检测"],"a":4,"e":"该药与H+/K+-ATP酶巯基共价结合而不可逆抑制其活性，直接检测该酶活性可评价抑制效果；RT-qPCR、印迹等检测的是表达量而非活性。"},{"q":"关于病毒癌基因的叙述，正确的是","o":["主要存在于RNA病毒基因组中","无法与宿主细胞基因整合","不能使培养细胞癌变","又称癌基因","由病毒自身基因突变而来"],"a":0,"e":"病毒癌基因主要存在于RNA肿瘤病毒基因组中，由逆转录病毒“劫持”宿主原癌基因改造而来，成为病毒基因组的一部分。DNA病毒的癌基因（如HPV的E6、E7）则为其基因组不可或缺的部分。"},{"q":"下列哪种条件不符合DNA载体的要求","o":["分子量小","一种内切酶只有1个切口","有基因标志便于筛选","易于引入细胞","不能复制"],"a":4,"e":"载体必须能在宿主细胞内自主复制，才能随细胞分裂稳定传代并扩增外源DNA；不能复制的DNA分子无法作为克隆载体。"},{"q":"关于质粒的叙述，下列哪项是错误的","o":["大小约为数千个碱基对","易从一个细菌转移入另一个细菌","双链的线性分子","存在于大多数细菌的胞质中","常带抗药基因"],"a":2,"e":"质粒是存在于细菌胞质中的共价闭合环状双链DNA，可独立复制并常携带抗药基因，并非线状分子。"},{"q":"基因芯片事实上就是高通量的","o":["核酸分子杂交","ChIP","蛋白质印迹","EMSA","实时PCR"],"a":0,"e":"基因芯片将探针固定于载体并与标记的核酸样品杂交，本质上是高通量的核酸分子杂交技术。"},{"q":"结合胆红素理化性质不包括","o":["水溶性大，脂溶性小","与血浆白蛋白结合力大","对细胞的通透性与毒性小","能透过肾小球从尿中排出","与重氮试剂直接反应"],"a":1,"e":"结合胆红素水溶性大、脂溶性小，与白蛋白结合疏松，可经肾小球滤过随尿排出，并能直接与重氮试剂反应；与白蛋白结合力大是未结合胆红素的特点。"},{"q":"机体缺乏维生素B6引起的贫血，其原因是","o":["维生素B6（磷酸吡哆醛）是ALA合酶的辅酶","维生素B6（磷酸吡哆醛）是ALA脱水酶的辅酶","维生素B6（磷酸吡哆醛）是亚铁螯合酶的辅酶","维生素B6（磷酸吡哆醛）是尿卟啉原Ⅲ同合酶的辅酶","维生素B6（磷酸吡哆醛）是尿卟啉原Ⅰ同合酶的辅酶"],"a":0,"e":"磷酸吡哆醛是血红素合成限速酶ALA合酶的辅酶，维生素B6缺乏使血红素合成减少，引起小细胞低色素性贫血。"},{"q":"下列情况不属于酶含量调节的是","o":["鸟氨酸循环底物增加，诱导参与鸟氨酸循环的酶合成增加","HMG-CoA还原酶在肝内的合成被胆固醇阻遏","溶酶体蛋白水解酶非特异降解酶蛋白质","酶蛋白分子的泛素化降解途径","胰蛋白酶原在十二指肠中形成胰蛋白酶"],"a":4,"e":"胰蛋白酶原经肠激酶水解掉六肽而激活，属于酶原激活即酶活性中心的形成或暴露，是酶结构的改变而非酶含量的调节。"},{"q":"关于溶血性黄疸，下列说法正确的是","o":["患者尿胆红素阳性","由破坏红细胞释放出的珠蛋白可以抑制肝细胞处理胆红素的能力","患者血清总胆红素不变","患者肝细胞处理胆红素的能力下降","过多的胆红素超过了肝细胞的处理能力"],"a":4,"e":"溶血性黄疸时红细胞大量破坏，胆红素生成过多，超过肝细胞摄取、转化和排泄能力，血中未结合胆红素升高，尿胆红素阴性。"},{"q":"对增强子特点的描述，正确的是","o":["增强子距离转录起始点不能太远","仅存在于启动子的上游","增强子作用的发挥不依赖启动子","在结构基因5'-端的DNA序列","是较短的能增强转录的DNA序列"],"a":4,"e":"增强子是较短的DNA序列，与特异调节蛋白结合后增强启动子的转录活性，其作用与方向和距离无关。"},{"q":"线粒体中丙酮酸彻底氧化发生","o":["3次脱羧，7次脱氢","3次脱羧，5次脱氢","4次脱羧，6次脱氢","4次脱羧，7次脱氢","2次脱羧，5次脱氢"],"a":1,"e":"丙酮酸氧化脱羧时脱羧1次、脱氢1次，乙酰CoA经三羧酸循环脱羧2次、脱氢4次，合计3次脱羧、5次脱氢。"},{"q":"原核生物转录起始前-10区的核苷酸序列被称为","o":["TATA盒","CAAT盒","增强子","Pribnow盒","沉默子"],"a":3,"e":"原核生物启动子-10区的一致序列TATAAT称Pribnow盒，是RNA聚合酶与之形成稳定复合物的部位。"},{"q":"基因的功能包括编码基因的蛋白质功能和哪项功能","o":["代谢产物","非编码RNA","启动子","增强子","内含子"],"a":1,"e":"基因的功能包括编码蛋白质与编码非编码RNA两类，后者如rRNA、tRNA、miRNA、lncRNA等，参与遗传信息传递和基因表达调控。"},{"q":"当溶液的pH值与某种氨基酸的pI一致时，该氨基酸在此溶液中的存在形式是","o":["兼性离子","非兼性离子","带单价正电荷","带单价负电荷","疏水分子"],"a":0,"e":"pH等于pI时氨基酸解离成阳离子和阴离子的趋势相等，净电荷为零，在电场中不泳动，呈兼性离子状态。"},{"q":"DNA损伤后，机体可通过①核酸内切酶；②DNA连接酶；③DNA聚合酶Ⅰ；④DNA聚合酶Ⅰ5'→3'外切酶活性这四种酶的协同作用将损伤加以修复，四种酶的工作顺序是","o":["①，②，③，④","①，④，③，②","②，③，④，①","③，②，①，④","④，③，②，①"],"a":1,"e":"DNA损伤修复时先由核酸内切酶切除损伤片段，再由DNA聚合酶Ⅰ的5′→3′外切活性切除缺口，继以DNA聚合酶Ⅰ的5′→3′聚合活性填补，最后由DNA连接酶封合缺口。"},{"q":"下列哪条途径需要单次跨膜受体","o":["cGMP-蛋白激酶通路","cAMP-蛋白激酶途径","酪氨酸蛋白激酶体系","细胞膜上Ca2+通道开放","Ca2+-依赖性蛋白激酶途径"],"a":2,"e":"受体型酪氨酸激酶（RTK）为单次跨膜蛋白，胞内段含酪氨酸激酶催化结构域，配体结合后直接磷酸化底物蛋白。cAMP、cGMP及Ca2+通路均经G蛋白偶联的七次跨膜受体或离子通道发挥作用。"},{"q":"核糖体、甲酰甲硫氨酰tRNA和mRNA共同结合于蛋白质合成的","o":["氨基酸活化阶段","氨基酸搬运阶段","启动阶段","肽链延长阶段","终止阶段"],"a":2,"e":"mRNA、起始氨酰tRNA（原核为fMet-tRNA）与核糖体结合装配成翻译起始复合物，属于肽链合成的起始阶段。"},{"q":"原核生物转录终止需要的因子是","o":["释放因子","ρ因子","信号肽","σ因子","Dna B"],"a":1,"e":"ρ因子具有解旋酶活性，结合转录产物RNA后沿RNA移动，使RNA聚合酶停顿并拆离DNA/RNA杂化双链，实现转录终止。"},{"q":"β-羟丁酸脱下的氢经呼吸链传递，最终将电子传递给","o":["细胞色素a3","水","氢离子","氧原子","氧分子"],"a":3,"e":"β-羟丁酸脱氢生成的NADH经NADH呼吸链传递，最终将电子交给氧原子并与H+结合生成水，氧是呼吸链的最终电子受体。"},{"q":"有机汞化合物能抑制","o":["巯基酶","羟基酶","胆碱酯酶","含-S-S-的酶","碱性酶"],"a":0,"e":"有机汞等重金属离子与酶分子中的巯基结合，使巯基酶失活而代谢紊乱；有机磷则抑制胆碱酯酶，两者中毒机制不同。"},{"q":"生成酮体的主要原料来源于","o":["葡萄糖氧化分解所产生的乙酰CoA","甘油转变的乙酰CoA","脂酸β-氧化所形成的乙酰CoA","丙氨酸转变而成的乙酰CoA","甘氨酸转变而成的乙酰CoA"],"a":2,"e":"酮体在肝线粒体以脂肪酸β-氧化生成的乙酰CoA为原料合成，先缩合生成HMG-CoA，再裂解生成乙酰乙酸、β-羟丁酸和丙酮。"},{"q":"由整合酶催化、在两个DNA序列的特异位点间发生的整合是","o":["人工重组","基本重组","随机重组","同源重组","位点特异的重组"],"a":4,"e":"位点特异性重组发生在具有特定序列的同源位点之间，由整合酶催化，如λ噬菌体attP与宿主attB的整合，不依赖长段同源序列。"},{"q":"关于基因组的描述，错误的是","o":["一个细胞DNA分子中全部的编码序列","一个细胞所载的全部遗传信息","在真核生物，基因组还包括线粒体或叶绿体DNA","细菌基因组包括质粒中的DNA序列","病毒基因组可以为DNA，也可以为RNA"],"a":0,"e":"基因组指生物体或细胞中一套完整单倍体遗传信息的总和，既含编码序列也含非编码序列；细菌质粒DNA、真核线粒体DNA均属其基因组范畴。"},{"q":"蛋白质生物合成时转肽酶活性存于","o":["EFTu","EFG","IR","核糖体大亚基","核糖体小亚基"],"a":3,"e":"转肽酶催化P位肽酰基转移至A位氨酰-tRNA的α-氨基形成肽键，其活性中心位于核糖体大亚基。"},{"q":"可以使非糖物质转化为活性葡萄糖的是","o":["糖的有氧氧化","磷酸戊糖途径","糖酵解","三羧酸循环","糖异生"],"a":4,"e":"糖异生可将甘油、乳酸、生糖氨基酸等非糖物质转变为葡萄糖，是空腹时补充血糖的重要途径。"},{"q":"真核基因转录中起正性调节作用的是","o":["启动子","操纵子","增强子","衰减子","沉默子"],"a":2,"e":"增强子是远离转录起始位点、与方向距离无关的DNA调控元件，可增强启动子转录活性，属正性调节；沉默子则起负性调节。"},{"q":"下列不属于基因定位的方法是","o":["荧光原位杂交","体细胞杂交","全基因组关联研究","连锁分析","免印印迹"],"a":4,"e":"基因定位方法包括荧光原位杂交、体细胞杂交、连锁分析和全基因组关联研究等。印迹法用于生物大分子定性定量分析，不属于基因定位方法。"},{"q":"糖组学研究的主要对象是","o":["糖原","聚糖","血糖","乳糖","葡萄糖"],"a":1,"e":"糖组学研究生物体所有聚糖或聚糖复合物的组成、结构、功能及与疾病的关系。糖原、血糖、乳糖和葡萄糖均属单一糖类物质，不是糖组学的研究对象。"},{"q":"由葡萄糖合成糖原时，每增加1个葡萄糖单位消耗高能磷酸键数为","o":["1","2","3","4","5"],"a":1,"e":"葡萄糖活化为葡萄糖-6-磷酸消耗1个ATP，生成UDPG时焦磷酸水解又损失1个高能磷酸键，故每增加1个葡萄糖单位消耗2个高能磷酸键。"},{"q":"下列对酶原的描述错误的是","o":["酶原是细胞内合成及初分泌的没有活性的酶","酶原激活可使酶在特定的部位和环境中发挥作用","酶原分子无活性是因为活性中心未形成或未暴露","绝大多数酶都以酶原形式存在","酶原可在细胞内或外经激活而成为有活性的酶"],"a":3,"e":"酶原激活是蛋白酶水解去除部分肽段，使酶的一级结构改变、构象调整，从而形成或暴露活性中心；并非所有酶都以酶原形式存在。"},{"q":"LPL的作用是水解","o":["脂肪细胞内甘油三酯","肝细胞内甘油三酯","CM和VLDL中的甘油三酯","LDL中的甘油三酯","HDL中的甘油三酯"],"a":2,"e":"脂蛋白脂肪酶位于组织毛细血管内皮细胞表面，水解CM和VLDL中的甘油三酯，释放游离脂肪酸和甘油供组织摄取利用。"},{"q":"O-连接型聚糖的二糖核心为","o":["N-乙酰半乳糖胺-半乳糖","N-乙酰葡糖胺-葡萄糖","N-乙酰葡糖胺-半乳糖","N-乙酰半乳糖胺-葡萄糖","N-乙酰半乳糖胺-甘露糖"],"a":0,"e":"O-连接型聚糖以N-乙酰半乳糖胺与半乳糖构成核心二糖，其GalNAc与多肽链丝氨酸或苏氨酸的羟基相连。"},{"q":"含修饰核苷酸最多的RNA是","o":["rRNA","tRNA","mRNA","5SrRNA","hnRNA"],"a":1,"e":"tRNA含修饰核苷酸最多，二氢尿嘧啶、假尿嘧啶、次黄嘌呤等稀有碱基可占其核苷酸总数的10%以上，与其结构稳定和密码子识别有关。"},{"q":"根据中心法则，遗传信息的传递方式是","o":["DNA-RNA-蛋白质","蛋白质-RNA-DNA","RNA-DNA-蛋白质","RNA-RNA-DNA","DNA-DNA-蛋白质"],"a":0,"e":"中心法则指遗传信息从DNA转录为RNA，再翻译为蛋白质，即DNA→RNA→蛋白质。逆转录现象说明RNA在某些生物中也可传代遗传信息。"},{"q":"下列能使血浆胆固醇升高的激素是","o":["氢化可的松","胰岛素","胰高血糖素","肾上腺素","甲状腺素"],"a":1,"e":"胰岛素可促进HMG-CoA还原酶合成，使胆固醇合成增加，血浆胆固醇升高；甲状腺素则促进胆固醇转化为胆汁酸而降低血胆固醇。"},{"q":"原核生物的核糖体上有3个重要的功能部位，其中某功能部位在肽链合成中可以结合氨酰-tRNA，作为氨酰-tRNA进入的位置。该重要的功能部位称为","o":["A位","P位","E位","肽酰位","出口位"],"a":0,"e":"核糖体A位即氨酰位，结合新进入的氨酰-tRNA；P位为肽酰位，结合肽酰-tRNA；E位为排出位，释放已卸载氨基酸的tRNA。"},{"q":"下列哪种物质不用作探针","o":["RNA片段","DNA片段","蛋白质","氨基酸","人工合成的寡核苷酸片段"],"a":3,"e":"探针是带标记的已知核酸片段，包括DNA、RNA和人工合成的寡核苷酸，通过与靶序列互补杂交进行检测；氨基酸不能与核酸互补配对。"},{"q":"维生素D被列为激素的依据是","o":["维生素D与类固醇激素同由胆固醇转变而来","维生素D与类固醇结构上类似","维生素D能在体内合成","维生素D能溶于脂肪和有机溶剂","维生素D能在体内羟化转变成有生物活性的物质"],"a":4,"e":"维生素D3经肝25-羟化酶和肾1α-羟化酶两步羟化生成活性形式1,25-二羟维生素D3，可在体内合成并作用于肠、骨、肾等靶器官，故被列为激素。"},{"q":"S-腺苷甲硫氨酸最重要的生理功能是","o":["补充甲硫氨酸","生成嘌呤核苷酸","提供甲基","生成嘧啶核苷酸","合成四氢叶酸"],"a":2,"e":"S-腺苷甲硫氨酸是体内最重要的甲基直接供体，参与肌酸、磷脂等多种物质的甲基化反应。甲硫氨酸循环中由N5-CH3-FH4提供甲基生成甲硫氨酸，再通过SAM提供甲基。"},{"q":"可使激动型G蛋白中的α亚基发生ADP核糖基化从而丧失GTP酶活性的是","o":["霍乱毒素","百日咳毒素","白喉毒素","铜绿假单胞菌外毒素","肉毒毒素"],"a":0,"e":"霍乱毒素A亚基进入细胞后使激动型G蛋白α亚基发生ADP-核糖化修饰，抑制其GTP酶活性，导致α亚基持续激活。百日咳毒素作用于抑制型G蛋白。"},{"q":"柠檬酸循环被认为是一个需氧代谢途径，是因为","o":["循环的某些反应是以氧作为底物的","产生了H2O","CO2是该循环的1个产物","还原型辅酶需通过电子传递链被氧化","以上都不对"],"a":3,"e":"三羧酸循环本身不直接以氧为底物，但其脱氢生成的NADH和FADH2必须经电子传递链由氧氧化，故表现为需氧过程。"},{"q":"患者，男，乳房发育，皮肤出现蜘蛛痣，是由于","o":["雌激素分泌过多","雌激素灭活不足","雄激素分泌过少","雄激素失去活性","雌激素受体表达增多"],"a":1,"e":"肝细胞严重损伤时激素灭活功能降低，体内雌激素水平升高，引起男性乳房女性化、蜘蛛痣和肝掌。"},{"q":"下列机体状态下，脑组织可利用酮体氧化供能的是","o":["饥饿1～3天","轻型糖尿病","空腹","长期饥饿","剧烈运动"],"a":3,"e":"长期饥饿时脂肪动员进一步加强，肝内生成大量酮体，脑利用酮体供能超过葡萄糖，可占总耗氧量的60%。"},{"q":"最常用于原核表达的体系","o":["酵母","昆虫细胞","噬菌体","真菌","大肠杆菌"],"a":4,"e":"原核表达体系以大肠埃希菌最为常用，培养方法简单、迅速、经济且适合大规模生产；其缺点是不能对表达产物进行糖基化等翻译后加工。"},{"q":"治疗尿路感染的环丙沙星（ciprofloxacin）和萘啶酸（nalidixicacid）能够特异性抑制细菌体内的","o":["DNA连接酶","RNA聚合酶","DNA拓扑异构酶Ⅰ","DNA解旋酶","DNA解链酶"],"a":2,"e":"环丙沙星等喹诺酮类特异性抑制细菌DNA拓扑异构酶，使DNA复制受阻而杀菌；其对细菌酶的选择性远高于真核细胞相应酶。"},{"q":"1,4,5-三磷酸肌醇（IP3）与相应受体结合后，细胞质内浓度升高的离子是","o":["K＋","Na＋","HCO3-","Ca2＋","Mg2＋"],"a":3,"e":"IP3是水溶性分子，扩散至内质网或肌质网膜与其受体结合，使钙通道开放，细胞钙库释放Ca2+，胞质Ca2+浓度迅速升高。"},{"q":"下列哪种物质是肝细胞特异合成的","o":["脂肪","蛋白质","糖原","尿素","ATP"],"a":3,"e":"尿素是肝细胞通过鸟氨酸循环特异合成的氮代谢终产物，其他组织不能合成尿素。脂肪、蛋白质、糖原和ATP在多种组织均可合成。"},{"q":"有关游离胆红素的叙述，错误的是","o":["又称为间接胆红素","属于脂溶性物质，易通过细胞膜对脑产生毒性作用","又称肝胆红素","不易经肾随尿排出","与重氮试剂反应间接阳性"],"a":2,"e":"结合胆红素又称肝胆红素、直接胆红素，呈水溶性，与重氮试剂直接反应阳性；游离胆红素为间接胆红素，脂溶性、不能经肾排出。"},{"q":"关于基因诊断的描述，正确的是","o":["羊水不适合作为样本用于基因诊断","唾液和尿液可以作为样本用于基因诊断","精液和毛发不适合作为样本用于基因诊断","与常规诊断方法相比，基因诊断的主要劣势是价格显著高于常规诊断方法","恶性肿瘤、心脑血管等复杂性疾病不适合进行基因诊断"],"a":1,"e":"基因诊断样本来源广泛，血液、组织、精液、唾液、尿液、羊水、绒毛和毛囊均可；唾液和尿液取材方便，可作为基因诊断样本。"},{"q":"核酸变性后，可发生哪种效应","o":["Tm值升高","增色效应","失去对紫外线的吸收能力","最大吸收波长发生转移","溶液黏度增加"],"a":1,"e":"核酸变性后双链解离为单链，碱基由堆积状态暴露，260nm紫外吸收增强，称为增色效应，其黏度下降。"},{"q":"关于哺乳动物嘧啶核苷酸从头合成的调节，描述正确的是","o":["天冬氨酸氨基甲酰转移酶是主要调节酶","嘧啶磷酸核糖转移酶是嘧啶核苷酸主要调节酶","氨基甲酰磷酸合成酶Ⅱ是主要调节酶","二清乳清酸酶是主要调节酶","乳清酸核苷酸脱羧酶是主要调节酶"],"a":2,"e":"哺乳动物嘧啶核苷酸从头合成的主要调节酶是氨基甲酰磷酸合成酶Ⅱ，受UMP反馈抑制；细菌中则为天冬氨酸氨基甲酰转移酶。"},{"q":"蛋白质的一级结构是空间构象的基础，蛋白质的功能依赖特定的空间结构，如果蛋白质的折叠发生错误，尽管一级结构不变，但空间构象发生改变仍可影响其功能，严重时可导致疾病——蛋白质构象病，例如","o":["疯牛病","糖尿病","冠心病","脑卒中","痛风症"],"a":0,"e":"疯牛病由朊蛋白错误折叠并相互聚集，形成抗蛋白水解酶的淀粉样纤维沉淀而致病，是典型的蛋白质构象病。"},{"q":"关于酶原及其激活的叙述，错误的是","o":["酶原是酶的贮存形式","酶原激活时需要水解肽键","体内所有的酶均有酶原形式","酶原激活能形成酶的活性中心","酶原激活是酶原向酶的转化过程"],"a":2,"e":"酶原激活通过水解一个或几个肽键，使酶形成或暴露活性中心；但并非体内所有酶都以酶原形式存在，如多数胞内酶不是。"},{"q":"尿素生成的限速酶是","o":["精氨酸酶","CPS-Ⅰ","CPS-Ⅱ","精氨酸代琥珀酸合成酶","鸟氨酸氨基甲酰转移酶"],"a":3,"e":"尿素合成的酶系中精氨酸代琥珀酸合成酶活性最低，是尿素合成启动后的关键酶，可调节尿素生成速度。"},{"q":"下列对嘧啶核苷酸从头合成途径的描述，正确的是","o":["先合成嘧啶环，再与PRPP中的磷酸核糖相连","在PRPP的基础上，与氨基酸及CO2作用逐步合成","UMP的合成需要有一碳单位的参加","主要是在线粒体内合成","需要有氨基甲酰磷酸合成酶Ⅰ参加"],"a":0,"e":"嘧啶核苷酸从头合成先合成含嘧啶环的乳清酸，再与PRPP反应连接核糖-5-磷酸。一碳单位参与的是胸苷酸合成，氨基甲酰磷酸合成酶Ⅱ参与嘧啶合成。"},{"q":"关于糖蛋白N-连接型聚糖的叙述，错误的是","o":["合成需要长萜醇载体","合成场所是粗面内质网和高尔基体","N-连接型聚糖合成是在蛋白肽链合成后进行","N-连接型聚糖有五糖核心","聚糖中的N-乙酰葡糖胺与多肽链中天冬酰胺残基的酰胺氮共价连接"],"a":2,"e":"O-连接型聚糖的合成是在多肽链合成后进行的，且不需要聚糖载体；N-连接型聚糖合成需长萜醇载体，在粗面内质网和高尔基体加工，其N-乙酰葡糖胺与天冬酰胺残基的酰胺氮共价连接。"},{"q":"以下关于多基因病说法错误的是","o":["一般有家族性遗传倾向","表现为2个以上基因的“微效作用”的相加，或者多基因间相互作用","单一基因的变异一般仅增加对疾病的易感性","包含肿瘤、代谢性疾病等","环境因素往往影响较弱"],"a":4,"e":"多基因病由遗传因素与环境因素共同作用，环境因素影响显著而非较弱，这是与单基因病的重要区别。"},{"q":"真核细胞染色质的基本结构单位是","o":["组蛋白","核心颗粒","核小体","超螺旋筒","α-螺旋"],"a":2,"e":"核小体由约200bp DNA与组蛋白八聚体组成，是染色质的基本组成单位。核心颗粒仅为核小体的组成部分，组蛋白是核小体的成分而非结构单位。"},{"q":"构成细菌的限制修饰体系的酶有","o":["限制性核酸内切酶和DNA聚合酶","限制性核酸内切酶和RNA聚合酶","限制性核酸内切酶和甲基化酶","限制性核酸外切酶和甲基化酶","限制性核酸外切酶和DNA聚合酶"],"a":2,"e":"限制性核酸内切酶识别并切割外源DNA，相伴的甲基化酶使自身DNA甲基化而受保护，二者共同构成细菌的限制修饰体系。"},{"q":"在三羧酸循环和尿素循环中存在的共同中间产物为","o":["草酰乙酸","丙酮酸","延胡索酸","柠檬酸","苹果酸"],"a":2,"e":"延胡索酸既是三羧酸循环中延胡索酸加水生成苹果酸的前体，也是尿素循环中精氨酸代琥珀酸裂解产生的中间产物。"},{"q":"组成核蛋白体的成分为","o":["蛋白质和RNA","RNA和DNA","DNA和蛋白质","tRNA和蛋白质","蛋白质和多糖"],"a":0,"e":"核蛋白体即核糖体，由rRNA与蛋白质共同组成，是蛋白质合成的场所；DNA不参与其组成。"},{"q":"下列关于线粒体DNA（mtDNA）的描述有误的是","o":["mtDNA是线状分子","mtDNA共编码37个基因","mtDNA是细胞核外遗传物质","mtDNA结构特点与原核生物相似","mtDNA独立编码线粒体中的一些蛋白质"],"a":0,"e":"mtDNA是裸露的共价闭合双链环状分子，全长16569bp，共编码37个基因，并非线状分子。"},{"q":"原核生物嘧啶二聚体的主要修复方式为","o":["SOS修复","碱基切除修复","核苷酸切除修复","跨越损伤修复","光复活修复"],"a":4,"e":"嘧啶二聚体可由光复活酶直接识别并修复，称光复活修复；原核生物以此为主要直接修复方式，核苷酸切除修复亦参与。"},{"q":"生物体内ATP最主要的来源是","o":["糖酵解","三羧酸循环","磷酸戊糖途径","氧化磷酸化作用","底物水平磷酸化作用"],"a":3,"e":"氧化磷酸化是ATP生成的主要方式，1mol葡萄糖彻底氧化生成的30或32mol ATP中，26或28mol来自NADH和FADH2经呼吸链的氧化磷酸化。"},{"q":"转录与DNA复制的不同点是","o":["遗传信息储存于碱基序列中","新生链的合成遵守碱基配对原则","RNA聚合酶缺乏校正功能","合成方向为5'→3'","需要消耗能量"],"a":2,"e":"RNA聚合酶缺乏3'→5'外切酶活性，无校对功能，转录错误率高于DNA复制；其余各项是复制与转录共有的特点。"},{"q":"对原核和真核蛋白质生物合成均有抑制作用的抗生素是","o":["放线菌酮（环己酰亚胺）","四环素","链霉素","氯霉素","嘌呤霉素"],"a":4,"e":"嘌呤霉素结构与酪氨酰-tRNA相似，可进入原核和真核核糖体A位，使肽酰基转移到它的氨基上而肽链脱落，故对两类细胞的蛋白质合成均有抑制作用。"},{"q":"在乳糖操纵子中，cAMP能对转录进行调控，但先与","o":["CAP结合","RNA聚合酶结合","G蛋白结合","操纵序列结合","阻遏蛋白结合"],"a":0,"e":"葡萄糖缺乏时cAMP浓度升高，cAMP先与CAP结合成复合物，再结合于启动子上游的CAP位点，促进RNA聚合酶转录。"},{"q":"合成磷脂酰胆碱及磷脂酰肌醇时均需要下列哪种物质","o":["丝氨酸","甲硫氨酸","CTP","H2O","甘油二酯"],"a":2,"e":"胆碱须活化为CDP-胆碱，磷脂酰肌醇合成需CDP-甘油二酯，两者都以CTP为活化载体，故CTP是共同需要的物质。"},{"q":"用亮氨酸喂养实验性糖尿病犬时，下列哪种物质从尿中排出增加","o":["酮体","脂肪","乳酸","葡萄糖","非必需氨基酸"],"a":0,"e":"亮氨酸是生酮氨基酸，糖尿病犬给予亮氨酸后其分解生成的乙酰CoA增多，酮体生成增加并从尿排出，故尿中酮体增多。"},{"q":"限制性核酸内切酶切割双链DNA后产生的是","o":["5'磷酸基和3'羟基基团的末端","5'羟基和3'羟基基团的末端","3'磷酸基和5'羟基基团的末端","5'磷酸基和3'磷酸基团的末端","两个断裂点都是腺嘌呤核苷酸的末端"],"a":0,"e":"限制性核酸内切酶切割DNA双链后产生5'磷酸基和3'羟基末端，此末端可被DNA连接酶封合。"},{"q":"关于DNA pol Ⅲ亚基功能的表述，错误的是","o":["θ亚基有5'→3'外切酶活性","ε亚基有3'→5'外切酶活性","α亚基有5'→3'聚合活性","β亚基使酶沿模板滑动","ε亚基有碱基选择功能"],"a":0,"e":"DNApolⅢ的ε亚基具3′→5′核酸外切酶活性及碱基选择功能，α亚基具5′→3′聚合活性，θ亚基未发现催化活性。5′→3′外切酶活性由DNApolⅠ小片段具有。"},{"q":"下列化合物对嘌呤核苷酸的生物合成不产生直接反馈抑制作用的是","o":["TMP","IMP","AMP","GMP","ADP"],"a":0,"e":"嘌呤核苷酸从头合成的产物IMP、AMP、GMP以及ADP、GDP均可反馈抑制PRPP合成或相关关键酶；TMP属嘧啶核苷酸，不参与嘌呤合成的反馈调节。"},{"q":"在体内可转变生成胆色素的原料是","o":["胆汁","胆固醇","胆绿素","血红素","胆素"],"a":3,"e":"血红素在血红素加氧酶和胆绿素还原酶催化下，经胆绿素生成胆红素，是胆色素生成的原料。"},{"q":"类脂在体内的主要功能是","o":["氧化供能","保护内脏器官","保持体温防止散热","维持正常生物膜的结构和功能","空腹或禁食时体内能量的主要来源"],"a":3,"e":"类脂主要包括磷脂、糖脂和胆固醇及其酯，是构成生物膜的基本成分，维持膜的结构和功能；氧化供能主要由脂肪承担。"},{"q":"磷脂酰胆碱的合成需要下列哪种物质的参与","o":["FAD","维生素C","GTP","SAM","NADPH"],"a":3,"e":"胆碱由乙醇胺经SAM提供甲基生成，故磷脂酰胆碱合成需要SAM参与甲基化；经CDP-胆碱途径合成时则需CTP供能。"},{"q":"用于检测体外蛋白质-蛋白质相互作用的技术是","o":["基因芯片","免疫共沉淀（CoIP）","GST pull-down实验","Western Blotting","EMSA"],"a":2,"e":"GST pull-down将GST融合蛋白固定于谷胱甘肽琼脂糖珠，捕获体外与之直接结合的蛋白质，用于检测蛋白质-蛋白质相互作用。"},{"q":"O-连接型聚糖的合成需要","o":["长萜醇载体","糖基化位点Asn-X-Ser/Thr","N-乙酰半乳糖胺与半乳糖构成的核心二糖","2个N-GlcNAc和3个Man形成的五糖核心","单糖活化为CDP的衍生物"],"a":2,"e":"O-连接型聚糖合成不需载体，其核心二糖由N-乙酰半乳糖胺与半乳糖构成，核心二糖可重复延长及分支。长萜醇载体和Asn-X-Ser/Thr序列子属于N-连接型糖蛋白。"},{"q":"稳定蛋白质分子中α-螺旋和β-折叠的化学键是","o":["肽键","氢键","盐键","二硫键","磷酸二酯键"],"a":1,"e":"α-螺旋和β-折叠均靠肽链中羰基氧与亚氨基氢之间形成的氢键维系，二者同属蛋白质二级结构。"},{"q":"基因重组技术中，载体选择的最重要条件是","o":["环状DNA","至少有一个选择标志","具有适宜的RE单一切点","能够自主复制","分子量小"],"a":3,"e":"载体是能自主复制的DNA分子，可携带外源DNA在受体细胞中增殖或表达；自主复制是载体最基本、最重要的条件。"},{"q":"长期饥饿时脑组织的能量主要来源于","o":["糖的氧化","乳酸氧化","脂酸氧化","酮体的氧化","氨基酸的氧化"],"a":3,"e":"长期饥饿时脂肪动员加强，肝内生成大量酮体，脑利用酮体增加并超过葡萄糖，占总耗氧量的60%。酮体是长期饥饿时脑组织的主要能源。"},{"q":"由于血型不匹配输血引起的溶血性黄疸，其特点是","o":["尿胆红素阴性","尿胆素原下降","粪胆素原下降","血清结合胆红素明显升高","血清未结合胆红素下降"],"a":0,"e":"血管内溶血使未结合胆红素生成增多，超过肝摄取转化能力，血中未结合胆红素升高而结合胆红素不增多，故尿胆红素阴性，尿胆素原与粪胆素原均增多。"},{"q":"相同分子量的DNA电泳时，迁移率最大的是","o":["具有单切口的DNA链","线性DNA","环状DNA","完整的超螺旋DNA","具有多切口的DNA链"],"a":3,"e":"同等分子量时，完整的超螺旋DNA构象最紧密，在凝胶中迁移率最大；开环和线性DNA迁移较慢。"},{"q":"镰状细胞贫血病是异常血红蛋白纯合子基因的临床表现，β链变异的类型是","o":["交换","插入","缺失","染色体不分离","点突变"],"a":4,"e":"镰状细胞贫血由β-珠蛋白基因第6密码子发生A→T单碱基置换，使谷氨酸变为缬氨酸，是点突变导致蛋白质一级结构改变的典型例子。"},{"q":"下列物质仅在肝脏中进行合成的是","o":["糖原","尿素","酮体","脂蛋白","糖酵解"],"a":2,"e":"酮体以脂肪酸β-氧化生成的乙酰CoA为原料，仅在肝线粒体由酮体合成酶系催化生成；肝缺乏利用酮体的酶，故须运至肝外组织氧化。"},{"q":"基因组DNA文库是","o":["一个转化子细胞包含所有染色体片段","一个转化子细胞包含所有cDNA片段","携带各种基因组DNA片段的所有转化子细胞的集合","携带各种cDNA片段的所有转化子细胞的集合","一个转化子细胞包含所有基因组DNA"],"a":2,"e":"基因组DNA文库是含某种生物全部基因组DNA片段的克隆总集，即携带各种基因组片段的所有转化子细胞的集合。"},{"q":"三羧酸循环主要是在哪一亚细胞部位进行的","o":["细胞核","细胞质","微粒体","线粒体","内质网"],"a":3,"e":"三羧酸循环的酶系位于线粒体基质，其中琥珀酸脱氢酶结合于线粒体内膜，故该循环在线粒体进行。"},{"q":"鸟氨酸循环中，合成尿素的第二分子氨来自","o":["半胱氨酸","谷氨酸","天冬酰胺","天冬氨酸","氨基甲酰磷酸"],"a":3,"e":"尿素合成中第一分子氨来自氨基甲酰磷酸，第二分子氨由天冬氨酸提供，后者与瓜氨酸缩合生成精氨酸代琥珀酸。"},{"q":"将肌肉中的氨以无毒形式运送至肝脏的是","o":["枸橼酸-丙酮酸循环","丙氨酸-葡萄糖循环","鸟氨酸循环","乳酸循环","三羧酸循环"],"a":1,"e":"骨骼肌以丙酮酸为氨基受体转氨基生成丙氨酸，经血液运至肝，肝内脱氨后丙酮酸异生为葡萄糖再回运肌肉，此即丙氨酸-葡萄糖循环，是氨的无毒转运形式。"},{"q":"dTMP的嘧啶环中第五位碳原子上的甲基来源于","o":["S-腺苷甲硫氨酸","N5，N10-CH2-FH4","N5-CH3-FH4","N10-CHO-FH4","N5，N10=CH-FH4"],"a":1,"e":"dTMP由dUMP经胸苷酸合酶催化生成，其甲基由N5,N10-亚甲基四氢叶酸提供，同时FH4再生。S-腺苷甲硫氨酸是体内甲基的直接供体，参与其他甲基化反应。"},{"q":"关于原核生物蛋白质生物合成的描述，错误的是","o":["启动阶段核糖体小亚基先与mRNA的启动信号AUG部位结合","肽链延长阶段分为进位、转肽、脱落、移位四个步骤","每合成一个肽键须消耗2分子GTP","在“受位”上出现UAA以后转入终止阶段","释放因子只有一种可识别3种终止密码子"],"a":4,"e":"原核生物有RF1、RF2、RF3三种释放因子，RF1识别UAA与UAG，RF2识别UAA与UGA；只有真核生物仅有一种eRF。"},{"q":"巴斯德效应是指","o":["有氧氧化抑制糖酵解","糖酵解抑制糖异生","糖酵解抑制有氧氧化","有氧氧化抑制磷酸戊糖途径","有氧氧化抑制糖醛酸途径"],"a":0,"e":"巴斯德效应指糖的有氧氧化抑制无氧氧化的现象，酵母菌转入有氧环境后乙醇生成即被抑制，其意义在于有氧时产能更经济。"},{"q":"重组噬菌体DNA转入宿主细胞的过程属于","o":["感染","转导","转化","转染","转位"],"a":0,"e":"以噬菌体等病毒颗粒作为运载体将外源DNA导入宿主细胞的过程称为感染；转化指直接摄取裸露DNA，转染多指噬菌体DNA导入细菌。"},{"q":"胰高血糖素诱导环腺苷酸（cAMP）生成的过程是","o":["激素受体复合物使G蛋白活化，再激活腺苷酸环化酶","激素直接激活腺苷酸环化酶","激素受体复合物活化腺苷酸环化酶","激素激活受体，受体再激活腺苷酸环化酶","激素直接抑制磷酸二酯酶"],"a":0,"e":"胰高血糖素与膜受体结合形成激素受体复合物，激活Gs使G蛋白解离，Gαs再激活腺苷酸环化酶，催化ATP生成cAMP，进而激活蛋白激酶A。"},{"q":"饥饿可以使肝内哪种代谢途径增强","o":["脂肪合成","糖原合成","糖酵解","糖异生","磷酸戊糖途径"],"a":3,"e":"饥饿时血糖下降、胰高血糖素升高，肝内糖异生关键酶活性增强，利用氨基酸、乳酸和甘油异生葡萄糖以维持血糖。"},{"q":"脂肪酸β-氧化，酮体生成及胆固醇合成的共同中间产物是","o":["MVA","乙酰乙酰辅酶A","HMG CoA","甲基二羟戊酸","乙酰乙酸"],"a":1,"e":"脂肪酸β-氧化硫解、酮体生成及胆固醇合成均以乙酰乙酰CoA为中间产物，后者再与乙酰CoA缩合生成HMG-CoA。"},{"q":"氨酰-tRNA中，tRNA与氨基酸的结合键是","o":["盐键","磷酸二酯键","肽键","糖苷键","酯键"],"a":4,"e":"氨基酸的羧基与tRNA 3′-CCA末端腺苷酸核糖的游离羟基脱水缩合，以酯键相连生成氨酰tRNA。"},{"q":"限制性核酸内切酶切割双链DNA后产生","o":["3'磷酸基末端和5'羟基末端","5'磷酸基末端和3'羟基末端","5'羟基末端和3'羟基末端","3'磷酸基末端和5'磷酸基末端","3'羟基末端、5'羟基末端和磷酸"],"a":1,"e":"限制性核酸内切酶水解磷酸二酯键，在切口处生成5′-磷酸基末端和3′-羟基末端，可被DNA连接酶封接。"},{"q":"下列关于tRNA的叙述正确的是","o":["具有PolyA尾结构","分子量较小","三级结构形似三叶草","可携带不同的氨基酸","不含稀有碱基"],"a":1,"e":"tRNA分子量较小，约70～90个核苷酸组成，是RNA中分子量最小的一类。其二级结构呈三叶草形，三级结构为倒L形；3′-端为CCA，可携带氨基酸但每种tRNA只携带一种特定氨基酸。"},{"q":"5-羟色胺的前体是","o":["胆碱","胆胺","色氨酸","酪氨酸","丝氨酸"],"a":2,"e":"5-羟色胺以色氨酸为前体，经色氨酸羟化酶生成5-羟色氨酸，再脱羧生成5-羟色胺。"},{"q":"下列关于结合胆红素的叙述，错误的是","o":["胆红素与葡糖醛酸结合","水溶性较大","易透过生物膜","可通过肾脏随尿排出","与重氮试剂呈直接反应"],"a":2,"e":"结合胆红素水溶性大，不易透过细胞膜，可随胆汁排入肠道并经肾随尿排出，与重氮试剂呈直接反应。"},{"q":"体内产生游离NH3的主要方式","o":["转氨基作用","脱水脱氨基作用","联合脱氨基作用","腐败作用","氧化脱氨基作用"],"a":2,"e":"转氨基作用并未真正释放氨，须与L-谷氨酸脱氢酶催化的氧化脱氨偶联，即联合脱氨基作用，才能生成游离氨。"},{"q":"目前在PCR中催化PCR反应的常用酶是","o":["反转录酶","DNA聚合酶Ⅰ","klenow片段","DNA聚合酶Ⅱ","TaqDNA聚合酶"],"a":4,"e":"Taq DNA聚合酶从嗜热水生菌提取，最适温度72℃，95℃时半衰期长，耐热性使其在PCR变性步骤中不被破坏。"},{"q":"酪氨酸蛋白激酶可使蛋白质中","o":["酪氨酸残基磷酸化","丝氨酸/苏氨酸残基磷酸化","氨基酸残基去磷酸化","天冬氨酸残基酰胺化","谷氨酸残基酰胺化"],"a":0,"e":"蛋白质酪氨酸激酶催化ATP的磷酸基转移至蛋白质酪氨酸残基的酚羟基，使酪氨酸磷酸化，参与细胞增殖与分化信号转导。"},{"q":"肝性脑病前后机体各器官有出血倾向，主要是由于","o":["维生素C少","维生素K少","维生素A少","凝血酶原少","纤维蛋白原多"],"a":1,"e":"维生素K参与肝合成凝血因子Ⅱ、Ⅶ、Ⅸ、Ⅹ，肝病时胆汁酸分泌减少致其吸收障碍，凝血因子合成不足而出血。"},{"q":"通过蛋白激酶G（PKG）通路发挥作用的是","o":["肾上腺素","维A酸","胰高血糖素","心房钠尿肽","胰岛素"],"a":3,"e":"心房钠尿肽与细胞膜受体结合后激活鸟苷酸环化酶，使cGMP升高并激活蛋白激酶G，参与心肌和平滑肌收缩的调节。"},{"q":"下列有关DNA变性描述正确的是指DNA分子","o":["磷酸二酯键的断裂","糖苷键的断裂","碱基的水解","碱基间氢键的断裂","与蛋白质间的疏水键断裂"],"a":3,"e":"DNA变性是双链互补碱基对间氢键及碱基堆积力被破坏，双链解离为单链，不涉及磷酸二酯键断裂或碱基水解。"},{"q":"下列有关代表性差异分析（RDA）技术的描述错误的是","o":["RDA技术是RT-PCR技术和聚丙烯胺凝胶电泳技术的结合","RDA技术是建立在核酸差异杂交基础上的PCR技术","RDA技术可检测正常和疾病组织间DNA或cDNA中的表达差异","是克隆未知疾病相关基因的常用技术方法之一","RDA技术对正常和异常DNA片段区分能力强，富集效率高，对起始材料要求低"],"a":0,"e":"RDA是建立在核酸差异杂交基础上的PCR技术，可检测组织间DNA或cDNA差异并克隆未知疾病相关基因；RT-PCR与聚丙烯酰胺凝胶电泳结合的是mRNA差异显示技术。"},{"q":"胆色素是下列哪种物质的代谢产物","o":["血红素","胆固醇","脂蛋白","胆汁酸","脂肪酸"],"a":0,"e":"胆色素是铁卟啉类化合物的分解代谢产物，主要来自衰老红细胞中血红蛋白所释放的血红素的降解。"},{"q":"美国国家生物技术信息中心（NCBI）提供的GEO数据库，可检索到何种信息","o":["mRNA的表达水平","SNP位点","蛋白质序列","限制性片段长度多态性","STS序列"],"a":0,"e":"GEO即基因表达综合数据库，收录基因芯片和转录组测序等实验的表达数据，可检索不同样本、不同条件下mRNA的表达水平。"},{"q":"下列关于酮体的叙述错误的是","o":["肝脏可以生成酮体，但不能氧化酮体","酮体是脂肪酸部分氧化分解的中间产物","合成酮体的起始物质是乙酰CoA","酮体包括β-羟丁酸","机体仅在病理情况下才产生酮体"],"a":4,"e":"酮体是脂肪酸在肝内正常代谢的中间产物，饥饿或糖利用障碍时生成增多，并非仅在病理情况下产生；肝生成酮体但不能利用。"},{"q":"血浆中运输胆红素的载体是","o":["清蛋白","Y蛋白","Z蛋白","α-球蛋白","γ-球蛋白"],"a":0,"e":"胆红素为亲脂疏水分子，入血后主要与清蛋白结合成复合体运输，既增加水溶性又限制其透出血管；Y蛋白和Z蛋白是肝细胞内的胆红素载体。"},{"q":"容易发生磷酸化与去磷酸化的氨基酸是","o":["G1y、Ser、Val","Thr、Ser、Tyr","Ala、Ile、Leu","Phe、Thr、Val","Tyr、Val、G1y"],"a":1,"e":"蛋白质磷酸化由蛋白激酶催化，ATP的γ-磷酸基共价结合于酶蛋白的Ser、Thr或Tyr残基侧链羟基上，去磷酸化由磷蛋白磷酸酶水解完成。"},{"q":"关于ATP合成酶正确的是","o":["它是呼吸链复合体Ⅳ的一个亚基","F0和F1都是亲水的","在F0中含有OSCP（寡霉素敏感蛋白）组分","F0中仅含有α、β和γ三种亚基","F0是H+通道"],"a":4,"e":"ATP合酶的F0嵌于线粒体内膜构成H+通道，F1伸向基质催化ATP生成；OSCP属F1组分，α、β、γ亚基也位于F1。"},{"q":"在DNA复制中，对于引物描述正确的是","o":["提供起始模板","激活引物酶","提供复制所需的5'-磷酸","提供复制所需的3'-羟基","激活DNA pol Ⅲ"],"a":3,"e":"DNA聚合酶不能从头起始合成，引物提供3'-OH末端，使dNTP的α-磷酸与之形成磷酸二酯键而延长子链。"},{"q":"关于核苷酸在体内的生物学功能，描述错误的是","o":["作为核酸合成的原料","体内能量的利用形式","参与代谢和生理调节","催化生物化学反应","作为辅酶"],"a":3,"e":"核苷酸可作为核酸合成原料、能量利用形式及辅酶参与代谢调节，但其本身不具催化作用，催化功能由酶承担。"},{"q":"当培养液内色氨酸浓度较大时，色氨酸操纵子将处于","o":["诱导表达","阻遏表达","基本表达","组成表达","协调表达"],"a":1,"e":"色氨酸浓度高时，色氨酸作为辅阻遏物与阻遏蛋白结合，使其结合操纵序列而关闭结构基因转录，同时前导肽翻译通畅引发转录衰减。"},{"q":"龋齿发病率增高主要是因为缺乏","o":["铁","硒","氟","锌","钴"],"a":2,"e":"氟与羟基磷灰石结合形成氟磷灰石，增强牙釉质抗酸能力并抑制致龋菌，缺氟时龋齿发病率增高。"},{"q":"通过鸟氨酸循环生成尿素时，其分子中的两个氮原子，一个直接来自游离的氮，另一个直接来源于","o":["瓜氨酸","鸟氨酸","精氨酸","甘氨酸","天冬氨酸"],"a":4,"e":"尿素分子中一个氮来自游离氨，经氨甲酰磷酸引入；另一个来自天冬氨酸，由精氨酸代琥珀酸合成酶催化掺入，裂解后保留于精氨酸分子中。"},{"q":"下列用于基因定位（DNA）和特定基因表达定位（RNA）的方法是","o":["Northern Blotting","Southern Blotting","Dot Blotting","FISH","ChIP"],"a":3,"e":"荧光原位杂交用荧光标记探针与中期染色体或细胞内的RNA杂交，既可定位特定DNA序列，也可显示基因的表达定位。"},{"q":"酶的Km值大小与下列哪项无关","o":["酶浓度","酶结构","作用温度","底物结构","反应环境pH值"],"a":0,"e":"Km与酶的结构、底物结构、反应温度、pH及离子强度有关，而与酶浓度无关，改变酶浓度不影响Km值。"},{"q":"蛋白质变性不包括","o":["氢键断裂","肽键断裂","盐键断裂","疏水键断裂","二硫键断裂"],"a":1,"e":"蛋白质变性是空间构象破坏，涉及氢键、盐键、疏水键和二硫键等次级键断裂，一级结构中的肽键并不断裂。"},{"q":"联系糖、脂代谢的重要枢纽物质是","o":["丙酮酸","磷酸二羟丙酮","草酰乙酸","葡萄糖-6-磷酸","α-酮戊二酸"],"a":1,"e":"磷酸二羟丙酮是糖酵解中间产物，可还原为甘油-3-磷酸，因而是联系葡萄糖代谢与脂肪代谢的重要枢纽；它与甘油醛-3-磷酸互为同分异构体。"},{"q":"下列酶促反应，需要消耗ATP的是","o":["乙酰CoA与草酰乙酸缩合成柠檬酸","脂酰CoA转变成反Δ2烯酰CoA","丙酮酸转变成磷酸烯醇式丙酮酸","谷氨酸脱氨生成α-酮戊二酸","6-磷酸葡萄糖转变为6-磷酸葡萄糖酸"],"a":2,"e":"糖异生中丙酮酸羧化酶催化丙酮酸羧化为草酰乙酸，需消耗1分子ATP，故丙酮酸转变为磷酸烯醇式丙酮酸耗能；其余反应或产能、或仅脱氢，均不消耗ATP。"},{"q":"线粒体的研究是从1857年开始的，瑞士解剖学家及生理学家阿尔伯特·冯·科立克在肌肉细胞中发现了颗粒状结构。美国化学家莱昂诺尔·米歇利斯推断线粒体参与某些氧化反应。德国生物化学家奥托·海因里希·沃伯格成功完成线粒体的粗提取且分离得到一些催化与氧有关的反应的呼吸酶被授予诺贝尔生理学或医学奖。下列完全发生在线粒体中的反应是","o":["糖酵解","糖异生","磷酸戊糖途径","糖的有氧氧化","三羧酸循环"],"a":4,"e":"三羧酸循环的酶系全部分布于线粒体，糖酵解在细胞质进行，糖异生则兼跨细胞质与线粒体。"},{"q":"脂肪酸β-氧化中，以FAD为辅基的酶催化的反应是","o":["脂酸活化","β-羟脂酰辅酶A脱氢酶","还原不饱和脂酸","脂酰辅酶A脱氢酶","以上都不是"],"a":3,"e":"脂酰辅酶A脱氢酶以FAD为辅基，催化脂肪酸β-氧化第一步脱氢，脱下的氢生成FADH2。β-羟脂酰辅酶A脱氢酶以NAD+为辅酶，催化第二步脱氢。"},{"q":"乳糖操纵子上Z、Y、A基因产物分别是","o":["脱氢酶、黄素酶、辅酶Q","β-半乳糖苷酶、β-半乳糖苷透性酶、乙酰转移酶","乳糖还原酶、乳糖合成酶、别构酶","葡萄糖-6-磷酸酶、变位酶、醛缩酶","乳糖酶、乳糖磷酸化酶、激酶"],"a":1,"e":"乳糖操纵子含Z、Y、A三个结构基因，分别编码β-半乳糖苷酶、通透酶和乙酰基转移酶。"},{"q":"人类基因组计划是指","o":["对所有生物基因进行定位并测序","对真核生物基因进行定位并测序","对原核生物基因进行定位并测序","对人类活性基因进行定位并测序","对人类全部基因进行定位并测序"],"a":4,"e":"人类基因组计划的目标是测定人类基因组全部DNA序列并绘制遗传图、物理图，即对人类全部基因进行定位并测序。"},{"q":"线粒体DNA是","o":["环状DNA，其遗传密码与核DNA的遗传密码完全相同","环状DNA，其遗传密码与核DNA的遗传密码不完全相同","环状DNA，其遗传密码与核DNA的遗传密码完全不同","线状DNA，其遗传密码与核DNA的遗传密码完全相同","线状DNA，其遗传密码与核DNA的遗传密码不完全相同"],"a":1,"e":"mtDNA为环状双链分子，其遗传密码与核DNA的通用密码不完全相同，如UGA在线粒体编码色氨酸。"},{"q":"人体的营养非必需氨基酸是","o":["赖氨酸","甲硫氨酸","谷氨酸","亮氨酸","缬氨酸"],"a":2,"e":"谷氨酸可由α-酮戊二酸接受氨基生成，属营养非必需氨基酸；赖氨酸、甲硫氨酸、亮氨酸和缬氨酸均为体内不能合成的必需氨基酸。"},{"q":"血红蛋白与肌红蛋白的结构，不同之处在于","o":["血红素辅基不同","α-螺旋结构不同","结合的配体不同","蛋白的空间结构不同","血红蛋白为球形，肌红蛋白为棒状结构"],"a":3,"e":"血红蛋白为四聚体，具四级结构并表现协同效应；肌红蛋白为单链，仅三级结构。两者辅基均为血红素，均含α-螺旋，区别在于空间结构层次。"},{"q":"蛋白质多肽链合成终止的机制是","o":["已达到mRNA分子的尽头","特异的tRNA识别终止密码子","终止密码子本身具酯酶作用，可水解肽酰基与tRNA之间的酯键","释放因子能识别终止密码子并进入“受位”","终止密码子部位有较强阻力，核糖体无法沿mRNA移动"],"a":3,"e":"终止密码子不被任何氨酰tRNA识别，只有释放因子能识别并结合于A位，进而水解肽酰-tRNA的酯键释放新生肽链。"},{"q":"DNA中的共价键不包括","o":["3'，5'-磷酸二酯键","β-糖苷键","磷酸-脱氧核糖的5'-OH的酯键","磷酸-脱氧核糖的2'-OH的酯键","磷酸-脱氧核糖的3'-OH的酯键"],"a":3,"e":"DNA中脱氧核糖只有3'-OH和5'-OH，不能形成2'-OH的磷酸酯键；核苷酸间以3',5'-磷酸二酯键相连，碱基与糖以β-糖苷键相连。"},{"q":"下列化合物中琥珀酸脱氢酶的辅酶是","o":["生物素","FAD","NADP+","NAD+","CoASH"],"a":1,"e":"琥珀酸脱氢酶即呼吸链复合体Ⅱ，以FAD为辅基催化琥珀酸脱氢生成延胡索酸，FADH2再经铁硫蛋白将电子传给泛醌。"},{"q":"糖有氧氧化，甘油氧化及磷酸戊糖途径的共同中间产物是","o":["3-磷酸甘油","3-磷酸甘油酸","磷酸二羟丙酮","3-磷酸甘油醛","丙酮酸"],"a":3,"e":"3-磷酸甘油醛是糖有氧氧化、甘油氧化及磷酸戊糖途径的共同中间产物。磷酸二羟丙酮经丙糖磷酸异构酶转变为3-磷酸甘油醛后进入糖酵解。"},{"q":"各种蛋白质的含氮量很接近，平均为","o":["15%","16%","17%","18%","19%"],"a":1,"e":"各种蛋白质含氮量接近，平均为16%，故测定样品含氮量乘以6.25可估算蛋白质含量。"},{"q":"盐析法沉淀蛋白质的原理是","o":["降低蛋白质溶液的介电常数","无机盐与蛋白质结合成不溶性的沉淀复合物","破坏蛋白质的一级结构","调节蛋白质溶液的等电点","破坏蛋白质的水化膜并中和其电荷"],"a":4,"e":"高浓度中性盐可中和蛋白质表面电荷并破坏其水化膜，去除胶体稳定因素而使蛋白质沉淀，此即盐析，不引起变性。"},{"q":"蛋白质在胃内的消化主要依靠","o":["寡肽酶","二肽酶","肠激酶","胰蛋白酶","胃蛋白酶"],"a":4,"e":"胃蛋白酶由胃底腺主细胞以酶原形式分泌，经胃酸激活后水解食物蛋白质为多肽和少量氨基酸，是胃内蛋白质消化的主要酶。"},{"q":"下列关于双链DNA的Watson-Crick结构模型叙述正确的是","o":["碱基平面与螺旋长轴垂直","核糖平面螺旋长轴垂直","核糖位于内侧","碱基位于外侧","磷酸位于内侧"],"a":0,"e":"Watson-Crick模型中碱基对平面与双螺旋长轴近乎垂直，碱基对位于内侧，脱氧核糖和磷酸构成的亲水性骨架位于外侧。"},{"q":"甲亢病人的甲状腺激素分泌增高，不出现","o":["ATP合成增多","ATP分解增快","耗氧量增多","产热增加","氧化磷酸化反应受抑制"],"a":4,"e":"甲状腺激素诱导解偶联蛋白表达并促进Na⁺,K⁺-ATP酶表达，使ATP分解加速、耗氧与产热增加，同时促进氧化磷酸化，故不出现氧化磷酸化受抑制。"},{"q":"大肠杆菌DNA的复制是","o":["单起始点单向复制","双起始点单向复制","单起始点双向复制","多起始点双向复制","双起始点双向复制"],"a":2,"e":"大肠杆菌基因组为环状DNA，只有一个复制起点，复制从起点向两个方向解链，呈单点起始双向复制。多起点双向复制是真核生物染色体的特征。"},{"q":"生物转化第一相反应中最主要的反应是","o":["水解","还原","加成","氧化","裂合"],"a":3,"e":"第一相反应包括氧化、还原和水解，其中以细胞色素P450单加氧酶催化的氧化反应最为多见。"},{"q":"蛋白质在电场中移动的方向取决于","o":["二级结构","三级结构","空间结构","等电点","电荷"],"a":4,"e":"蛋白质在电场中的泳动方向取决于其所带净电荷的正负，带正电荷者向负极移动，带负电荷者向正极移动。等电点决定蛋白质在特定pH下所带电荷的性质与数量。"},{"q":"在相同条件下，基因组突变率最低的病毒是","o":["HIV","禽流感病毒","SARS病毒","丙肝病毒","SV40"],"a":4,"e":"SV40为双链DNA病毒，其基因组复制依赖宿主DNA聚合酶，保真性高，突变率最低。HIV、禽流感病毒、SARS病毒和丙肝病毒均为RNA病毒，RNA复制或逆转录缺乏校对功能，突变率高。"},{"q":"下述辅助因子用于脂酸的合成的是","o":["FAD","FADH2","辅酶Ⅰ","NADPH","NADH"],"a":3,"e":"脂肪酸合成需NADPH供氢，同时消耗ATP、HCO3-和Mn2+；FAD、NADH等不参与脂肪酸合成的还原步骤。"},{"q":"乙酰辅酶A羧化酶和丙酮酸羧化酶的共同点是","o":["受柠檬酸的调节","受乙酰辅酶A的调节","辅酶都是FAD","辅酶都是CoASH","以生物素为辅基"],"a":4,"e":"乙酰CoA羧化酶与丙酮酸羧化酶均属羧化酶，都以生物素为辅基催化CO2固定；前者受柠檬酸激活，后者受乙酰CoA别构激活，调节剂不同。"},{"q":"以下有关DNA拓扑异构酶的叙述错误的是","o":["Ⅰ型DNA拓扑异构酶切开一条链，让另一条链通过切口","Ⅰ型DNA拓扑异构酶使用ATP水解释放的能量松弛负超螺旋DNA","Ⅱ型DNA拓扑异构酶一次改变连环数的值是2","Ⅰ型和Ⅱ型DNA拓扑异构酶在催化中都与DNA形成共价中间物","所有的DNA拓扑异构酶都能够催化DNA链的断裂和结合"],"a":1,"e":"Ⅰ型拓扑异构酶切开一条链使另一条链通过缺口再连接，反应不需ATP水解；依赖ATP并一次改变连环数2的是Ⅱ型酶。"},{"q":"有关疾病相关基因的克隆，下列说法错误的是","o":["人类基因组计划的完成可以促进疾病相关基因的克隆","可从疾病的表型差异出发发现疾病相关基因","在了解异常蛋白的功能以前无法克隆相关基因","可以先纯化功能异常的蛋白分子，再克隆相关基因","全基因组关联分析和全外显子测序极大地提高疾病相关基因克隆效率"],"a":2,"e":"功能克隆可先纯化功能异常蛋白、测序后设计探针或引物再克隆基因；表型克隆则从表型差异入手，故尚未了解蛋白功能时也能克隆相关基因。"},{"q":"下列叙述，不属于蛋白质组学研究的是","o":["研究蛋白的动态表达过程","研究蛋白质的共价修饰","研究蛋白质的功能","利用二维电泳/质谱技术进行蛋白质鉴定","利用磁共振技术分析蛋白质代谢产物"],"a":4,"e":"蛋白质组学研究蛋白质的表达、修饰、定位、功能及相互作用，常用二维电泳和质谱鉴定；磁共振分析代谢产物属代谢组学范畴。"},{"q":"糖的有氧氧化的最终产物是","o":["CO2+H2O+ATP","乳酸","丙酮酸","乙酰CoA","NADH"],"a":0,"e":"糖有氧氧化将葡萄糖彻底氧化为CO2和H2O，同时释放能量生成ATP；乳酸是无氧氧化产物，丙酮酸和乙酰CoA只是中间代谢物。"},{"q":"乙酰CoA在肝脏中的直接代谢去路，不包括","o":["还原缩合生成脂肪酸","在线粒体内彻底氧化分解生成CO2和H2O","合成胆固醇","转化为生酮氨基酸","缩合生成酮体"],"a":3,"e":"乙酰CoA在肝内可进入三羧酸循环氧化、羧化为丙二酰CoA合成脂肪酸、合成胆固醇和酮体；生酮氨基酸由氨基酸分解产生，不能由其生成。"},{"q":"缺铁容易引起贫血，这是由于","o":["铁离子可以促进珠蛋白的合成","铁离子可以促进亚铁螯合酶的活性","血红素合成的原料之一是Fe2+","血红素合成的原料之一是Fe3+","铁离子是ALA合酶的辅助因子"],"a":2,"e":"血红素合成的原料为琥珀酰CoA、甘氨酸和Fe2+，缺铁使血红素合成障碍，珠蛋白不能与之结合成血红蛋白，导致小细胞低色素性贫血。"},{"q":"二酯酰甘油+NDP-胆碱→NMP+磷脂酰胆碱，此反应中，NMP代表的是","o":["AMP","CMP","TMP","GMP","UMP"],"a":1,"e":"甘油二酯与CDP-胆碱缩合生成磷脂酰胆碱并释出CMP；CDP-胆碱由胆碱与CTP反应生成，同时释出焦磷酸，故反应的核苷酸产物为CMP。"},{"q":"原核生物蛋白质生物合成需要多种酶和蛋白质因子的参与。可以占据核糖体A位，防止A位结合其他tRNA的起始因子是","o":["IF-1","IF-2","IF-3","eIF-1","eIF-2"],"a":0,"e":"IF-1结合核糖体A位，占据该位点防止起始tRNA过早进入，保证起始复合物正确装配；IF-2促进fMet-tRNA结合小亚基。"},{"q":"Ⅱ型启动子中最典型的核心元件是","o":["TATA盒","CAAT盒","GC盒","八联体元件","Pribnow盒"],"a":0,"e":"典型的Ⅱ类启动子以TATA盒为核心元件，决定RNA合成的起始位点，其上游可另有CAAT盒、GC盒等元件。"},{"q":"下述哪步反应通过底物水平磷酸化方式生成一分子高能磷酸化合物","o":["柠檬酸→α-酮戊二酸","α-酮戊二酸→琥珀酸","琥珀酸→延胡索酸","延胡索酸→苹果酸","苹果酸→草酰乙酸"],"a":1,"e":"α-酮戊二酸氧化脱羧生成含高能硫酯键的琥珀酰CoA，后者在琥珀酰CoA合成酶催化下生成琥珀酸，同时使GDP磷酸化为GTP，属底物水平磷酸化。"},{"q":"在嘌呤核苷酸的合成中，第4位及5位的碳原子和第7位氮原子主要来源于","o":["天冬氨酸","谷氨酸","谷氨酰胺","丙氨酸","甘氨酸"],"a":4,"e":"嘌呤核苷酸从头合成中，甘氨酸与PRA缩合提供嘌呤环第4、5位碳及第7位氮。谷氨酰胺、天冬氨酸提供其他位置的氮，一碳单位提供第2、8位碳。"},{"q":"对致病基因的突变碱基进行纠正，这种基因治疗策略是","o":["基因矫正","基因置换","基因增补","基因失活","基因敲除"],"a":0,"e":"基因修正针对致病基因的突变碱基直接原位纠正，不引入外源序列；以正常基因原位替换致病基因者称基因置换，二者同属基因修复策略。"},{"q":"在有氧条件下，线粒体内下述反应中能产生FADH2步骤是","o":["琥珀酸→延胡索酸","异柠檬酸→α-酮戊二酸","α-酮戊二酸→琥珀酰CoA","苹果酸→草酰乙酸","柠檬酸→α-酮戊二酸"],"a":0,"e":"三羧酸循环中琥珀酸脱氢生成延胡索酸，由琥珀酸脱氢酶催化，辅基FAD接受氢生成FADH2；其余步骤生成NADH。"},{"q":"在肿瘤的发生发展过程中，正常组织可以从增生，异型变，良性肿瘤，原位癌发展到浸润癌和转移癌。每个阶段都涉及数种基因的变化。下列哪种基因在结肠癌的晚期腺瘤阶段丢失","o":["FAP","MCC","K-RAS","DCC","NM23"],"a":4,"e":"官方答案为【NM23】，但依据教材，正确答案为【DCC】。DCC即结肠癌缺失基因，其丢失见于晚期腺瘤阶段，而NM23突变与血管生长因子表达增高见于转移癌阶段。"},{"q":"针对大肠杆菌Ⅱ型拓扑异构酶的抗生素可以抑制其催化活性。这些化合物被用于治疗感染和化疗的原理是","o":["直接导致DNA片段的丢失","总是涉及同源重组","直接抑制核糖体组装","可干扰DNA复制的进行","引起DNA突变"],"a":3,"e":"Ⅱ型拓扑异构酶参与DNA解链、解连环和超螺旋转型，其抑制剂使复制中DNA无法正常解旋，从而干扰DNA复制，用于抗菌和化疗。"},{"q":"关于三羧酸循环哪个是错误的","o":["是糖、脂肪及蛋白质分解的最终途径","受ATP/ADP比值的调节","NADH可激活柠檬酸合酶","NADH氧化需要线粒体穿梭系统","受ATP/AMP比值的调节"],"a":2,"e":"NADH对柠檬酸合酶呈别构抑制而非激活，并同时抑制丙酮酸脱氢酶复合体和α-酮戊二酸脱氢酶复合体，使丙酮酸氧化脱羧与三羧酸循环协同减慢。"},{"q":"血氨的主要来源","o":["氨基酸脱氨基作用","氨基酸在肠道细菌作用下产生","尿素在肠道细菌尿素酶水解产生","肾小管谷氨酰胺的水解","胺类的分解"],"a":0,"e":"体内氨的主要来源是氨基酸脱氨基作用，肠道吸收的氨和肾小管谷氨酰胺水解产生的氨次之。"},{"q":"dTMP合成的直接前体是","o":["dUMP","TMP","TDP","dUDP","DCMP"],"a":0,"e":"dUMP在胸苷酸合酶催化下经甲基化生成dTMP，甲基供体为N5,N10-亚甲四氢叶酸，故dUMP是dTMP的直接前体。"},{"q":"DNA双螺旋结构中，氢键形成的因素不包括","o":["碱基中的共轭双键","碱基中的酮基或氨基","介质中的pH","酮式-烯醇式互变","氨基-亚氨基互变"],"a":0,"e":"DNA双螺旋中氢键形成取决于碱基的酮基、氨基及酮式-烯醇式、氨基-亚氨基互变，并受介质pH影响；共轭双键决定碱基的紫外吸收。"},{"q":"可定量比较正常脑组织与脑胶质瘤组织的基因表达差异的方法是","o":["LC/MS","2D-DIGE/MS","SAGE","NMR","高通量测序技术"],"a":2,"e":"SAGE即基因表达系列分析，可规模化检测基因表达种类及丰度，用于定量比较不同组织间基因表达差异。高通量测序技术虽也可分析表达谱，但本题所问为SAGE这一经典方法。"},{"q":"核糖核苷酸还原酶催化的反应是","o":["ATP→dAT","GTP→dGTP","ADP→dADP","AMP→dAMP","GMP→dGMP"],"a":2,"e":"核糖核苷酸还原酶作用于核苷二磷酸，将其还原为脱氧核苷二磷酸，故其催化ADP→dADP。"},{"q":"下列关于胆红素与血浆蛋白质结合的叙述，正确的是","o":["增加其溶解度便于随尿液排出","使它易于进入细胞内储存","限制它自由地进入细胞内，避免对细胞造成毒性作用","胆红素主要与血浆中的球蛋白结合","胆红素与血浆蛋白质后即称为结合胆红素"],"a":2,"e":"胆红素与清蛋白结合后水溶性增加便于运输，同时限制其自由透过细胞膜，避免对组织细胞尤其是神经细胞的毒性。"},{"q":"EcoRⅠ切割DNA双链后产生","o":["平端","5'突出黏端","3'突出黏端","钝性末端","配伍末端"],"a":1,"e":"EcoRⅠ识别GAATTC序列并在G与A之间切割，产生5′-端突出的黏性末端，便于与载体连接。"},{"q":"关于单加氧酶系在生物转化中作用的叙述，哪项有错误","o":["单加氧酶系是一个复合物","又称羟化酶","它所催化反应中一个氧分子发挥两种功能，故又称为混合功能氧化酶","此酶系特异性较差，可催化多种底物","该酶的羟化作用可降低非营养物质的水溶性"],"a":4,"e":"单加氧酶系羟化作用增加药物或毒物的水溶性而利于排出，并非降低水溶性。该酶系为复合物，又称混合功能氧化酶，特异性较差。"},{"q":"恶性肿瘤可以破坏组织、器官的结构和功能，引起坏死出血合并感染，患者最终可能由于器官功能衰竭而死亡。肿瘤发生的分子基础中，下列哪项不正确","o":["肿瘤发生的本质系细胞生长/增殖失去了控制","多因素所致（物理、化学、病毒等）","多步骤、长期演化的结果","多基因累积突变","原癌基因不是维持机体正常生命活动所必需的"],"a":4,"e":"原癌基因是维持细胞正常生长、增殖和分化所必需的基因，其产物参与信号转导与增殖调控，只有发生突变激活后才具致癌作用。"},{"q":"下列哪一个氨基酸为必需氨基酸","o":["苯丙氨酸","半胱氨酸","胱氨酸","谷氨酸","精氨酸"],"a":0,"e":"苯丙氨酸为人体不能合成、必须由食物供给的必需氨基酸；半胱氨酸、胱氨酸和谷氨酸可自身合成，精氨酸合成量少但属非必需。"},{"q":"DNA变性时会导致","o":["溶液黏度升高","浮力密度降低","260nm处的吸光度增加","易被蛋白酶降解","分子量降低"],"a":2,"e":"DNA变性时双螺旋解离，包埋于内部的碱基暴露，260nm处吸光度增加即增色效应。变性不改变核苷酸序列和分子量，溶液黏度降低而非升高。"},{"q":"线粒体DNA的复制","o":["采用滚环式复制","采用D环复制模式","两条亲代双链同时复制","两条亲代双链在同一起点复制","前导链与后随链同时合成"],"a":1,"e":"线粒体DNA按D环方式复制，复制起点不在双链同一位点，内、外环复制有时序差别，由DNApolγ催化。"},{"q":"合成软脂酸时需要的原料是","o":["8分子乙酰辅酶A","8分子乙酰辅酶A和1分子丙二酰辅酶A","7分子乙酰辅酶A和1分子丙二酰辅酶A","7分子丙二酰辅酶A和1分子乙酰辅酶A","8分子丙二酰辅酶A"],"a":3,"e":"软脂酸合成由1分子乙酰CoA与7分子丙二酸单酰CoA缩合而成，乙酰CoA提供末端甲基碳，丙二酸单酰CoA提供其余碳单位。乙酰CoA羧化酶催化乙酰CoA转化为丙二酸单酰CoA。"},{"q":"下列属于多不饱和脂肪酸的是","o":["油酸、软脂酸","软脂酸、亚油酸","亚油酸、亚麻酸","油酸、亚油酸","硬脂酸、花生四烯酸"],"a":2,"e":"亚油酸和α-亚麻酸含两个以上双键，属多不饱和脂肪酸且为必需脂肪酸；油酸为单不饱和脂肪酸，软脂酸、硬脂酸为饱和脂肪酸。"},{"q":"当脂肪酸β氧化在肝脏中为主时，线粒体中的丙酮酸很可能","o":["氧化脱羧成为乙酰辅酶A进而生成酮体","氧化脱羧成为乙酰辅酶A进入三羧酸循环","还原为乳酸进而异生成糖","羧化为磷酸烯醇丙酮酸进而异生成糖","羧化为草酰乙酸进而异生成糖"],"a":4,"e":"脂肪酸β-氧化旺盛时乙酰CoA和NADH增多，抑制丙酮酸脱氢酶复合体，丙酮酸转向羧化生成草酰乙酸，作为糖异生原料。"},{"q":"变性蛋白质的特性，描述错误的是","o":["生物活性丧失","一级结构未改变","空间结构被破坏","260nm的吸光值显著增加","加热、酸碱、有机溶剂是常见的变性因素"],"a":3,"e":"蛋白质变性时空间结构破坏、生物活性丧失而一级结构不变，因肽键暴露使280nm吸光度升高，260nm是核酸的吸收峰。"},{"q":"在细胞质中合成脂肪酸的限速酶是","o":["β-酮脂酰合成酶","水化酶","乙酰CoA羧化酶","脂酰转移酶","β-酮脂酰还原酶"],"a":2,"e":"乙酰CoA羧化酶催化乙酰CoA羧化为丙二酰CoA，是脂肪酸合成的限速酶，受柠檬酸别构激活、长链脂酰CoA别构抑制，并受磷酸化修饰调节。"},{"q":"δ-氨基-γ-酮基戊酸（ALA）合成酶的辅基中含","o":["维生素B1","维生素B2","维生素B6","维生素B12","维生素PP"],"a":2,"e":"ALA合酶的辅基是磷酸吡哆醛，即维生素B6的活性形式；维生素B6缺乏可影响血红素合成。"},{"q":"研究蛋白质相互作用的方法包括","o":["SDS-聚丙烯酰胺凝胶电泳","免疫共沉淀","琼脂糖凝胶电泳","蛋白质的紫外分光光度技术","免疫组化"],"a":1,"e":"免疫共沉淀利用特异性抗体沉淀靶蛋白及其结合的蛋白质，是研究体内蛋白质相互作用的常用方法；电泳和紫外分光光度法不能直接鉴定相互作用。"},{"q":"胆固醇在体内代谢的主要去路是","o":["构成脂蛋白","构成生物膜","转变为胆汁酸","从肠道排出","转变为类固醇激素"],"a":2,"e":"胆固醇的环戊烷多氢菲母核在体内不能被降解，其主要代谢去路是在肝细胞转化为胆汁酸，每日约0.4～0.6g胆固醇在肝内转变为胆汁酸。"},{"q":"体内氨基酸代谢库中，游离的氨基酸的主要去路是","o":["合成胺类","合成蛋白质","分解产生能量","参与许多含氮物质的合成","脱去氨基生成相应的α-酮酸"],"a":1,"e":"氨基酸最主要的生理功能是合成蛋白质和多肽，以满足组织蛋白质更新、修复及细胞生长的需要，其消耗量远超分解产能和转变其他含氮化合物。"},{"q":"酶促反应中决定酶特异性的是","o":["酶蛋白","酶作用物的类别","辅基或辅酶","催化基团","金属离子"],"a":0,"e":"酶蛋白决定酶促反应的特异性及催化机制，辅因子决定反应类型；故特异性由酶蛋白决定。"},{"q":"在呼吸链中，将复合物Ⅰ和复合物Ⅱ与细胞色素系统连接的物质是","o":["FMN","Fe-S蛋白","CoQ","Cyt b","Cyt a"],"a":2,"e":"泛醌为脂溶性递氢体，既接受复合体Ⅰ经FMN、铁硫蛋白传来的氢，也接受复合体Ⅱ中琥珀酸脱氢酶经FAD传递的氢，再交给细胞色素系统。"},{"q":"与受体型酪氨酸蛋白激酶（RTK）信号转导途径有关的物质是","o":["IP3","Ca2+","JAK","Raf","热休克蛋白"],"a":3,"e":"生长因子与受体型酪氨酸激酶结合后，经Ras激活Raf，再激活MAPK级联，调节基因表达；Raf属该途径的胞内信号分子。"},{"q":"天然蛋白质中不存在的氨基酸是","o":["半胱氨酸","瓜氨酸","丝氨酸","色氨酸","丙氨酸"],"a":1,"e":"瓜氨酸是尿素合成途径的中间产物，以游离形式存在，不参与蛋白质合成，故不属于天然蛋白质中的氨基酸。"},{"q":"载脂蛋白B（apo B）是乳糜微粒和低密度脂蛋白（LDL）的必需成分，在脂类代谢、胆固醇转运过程中起关键作用。载脂蛋白B分为apo B100和apo B48。二者是同一基因不同转录模式的产物。Apo B100 mRNA第6666位上的C变成U，此处编码谷氨酰胺的CAA密码子变成UAA终止密码子，导致截短的apo B48生成。这一过程是真核生物前体mRNA加工中的哪一种加工方式","o":["剪接","碱基修饰","选择性加工","RNA编辑","自我剪接"],"a":3,"e":"小肠黏膜细胞胞嘧啶核苷脱氨酶使apoB mRNA第2153位密码子CAA变为终止密码子UAA，转录后碱基序列改变，属RNA编辑。"},{"q":"下列哪个物质可激活蛋白激酶A（PKA）","o":["GMP","cGMP","cAMP","AMP","ATP"],"a":2,"e":"cAMP与PKA的调节亚基结合，使催化亚基释放而激活；cGMP激活PKG，AMP和GMP无此作用。"},{"q":"采用定位克隆策略鉴定的第一个疾病相关基因是","o":["假肥大型肌营养不良基因","X-连锁慢性肉芽肿病基因","马方综合征基因","苯丙酮尿症基因","白化病基因"],"a":1,"e":"采用定位克隆策略鉴定的第一个疾病相关基因是X连锁慢性肉芽肿病基因，其后RB等基因也通过该策略克隆。"},{"q":"关于继发性痛风导致血中尿酸升高的情况，描述不正确的是","o":["与进食高嘌呤食物无关","体内核酸大量分解时（如恶性肿瘤）","肾功能不全导致尿酸排泄障碍时","临床常用别嘌呤醇进行治疗","尿酸盐结晶的沉积会导致关节和软组织的病变"],"a":0,"e":"高嘌呤食物是血尿酸升高的重要诱因，继发性痛风同样受其影响，故称其“无关”不成立；核酸大量分解和尿酸排泄障碍亦为常见原因。"},{"q":"糖尿病是由于什么原因所引起","o":["血糖浓度过高","糖代谢异常","糖异生异常","糖原合成异常","糖原分解异常"],"a":1,"e":"糖尿病是胰岛素绝对或相对不足所引起的糖代谢紊乱，以高血糖为主要特征，并非单纯的糖原合成或分解异常。"},{"q":"与pCAGCT互补的DNA序列是","o":["pAGCTG","pGTCGA","pGUCGA","pAGCUG","pAGCCG"],"a":0,"e":"DNA双链互补遵循A-T、G-C配对，且方向反向平行。pCAGCT的互补链为pAGCTG，即按碱基互补并反向读取原序列得到。"},{"q":"下列关于物质代谢特点的描述，错误的是","o":["物质代谢的方向、速度和强度受到精细调节","代谢池中的内源性和外源性物质代谢途径不同","各种物质的代谢是相互联系的","不同的生理状态下，物质的代谢速度和方向可能改变","进入体内的能源物质超过需要，可以以脂肪形式储存"],"a":1,"e":"内源性和外源性物质进入共同的代谢池，按机体需要进入相同代谢途径，并无不同途径；物质代谢相互联系并受精细调节。"},{"q":"基因表达过程中仅在原核生物中出现而并不出现在真核生物的是","o":["tRNA的稀有碱基","σ因子","冈崎片段","DNA连接酶","起始密码子AUG"],"a":1,"e":"σ因子是原核生物RNA聚合酶的组成亚基，负责识别并结合启动序列，真核生物RNA聚合酶不含σ因子。"},{"q":"临床上自毁容貌征，是由于","o":["腺嘌呤磷酸核糖转移酶缺陷","次黄嘌呤脱氢酶缺陷","次黄嘌呤-鸟嘌呤磷酸核糖转移酶缺陷","鸟嘌呤合成酶缺陷","PRPP合成酶缺陷"],"a":2,"e":"次黄嘌呤-鸟嘌呤磷酸核糖转移酶缺陷使嘌呤补救合成受阻，PRPP蓄积促进嘌呤从头合成，尿酸生成过多，伴神经系统异常和自残行为。"},{"q":"SOX9是调控软骨细胞增殖与分化的重要转录因子之一。现发现某一蛋白质的表达可以显著降低SOX9的表达，SOX9的表达不影响该蛋白的表达。下列哪种方法可以确定该蛋白是否直接通过调控SOX9的转录影响其表达的","o":["染色体免疫共沉淀（ChIP）","原位杂交（ISH）","染色体构象捕获（3C）","启动子活性检测","酵母双杂交"],"a":0,"e":"ChIP用特异抗体沉淀与DNA结合的蛋白质复合体，再检测共沉淀的DNA序列，可判断该蛋白是否结合于SOX9启动子区，从而确定其是否直接调控转录。"},{"q":"肝脏在物质代谢中的作用，哪项不正确","o":["肝脏是维持血糖水平稳定的重要器官","肝脏是酮体生成的主要器官","肝脏可以进行生物转化作用","维生素D3转变成1-OH-D3","肝脏可以合成胆汁酸"],"a":3,"e":"维生素D3先在肝25-羟化生成25-OH-D3，再在肾小管上皮细胞1α-羟化酶作用下生成1，25-（OH）2-D3，1位羟化发生在肾而非肝。"},{"q":"关于β-氨基异丁酸，叙述错误的是","o":["是胸腺嘧啶的分解产物","食入含DNA丰富的食物时，尿中排出会增多","肿瘤病人放化疗时，尿中排出会增多","是尿嘧啶的分解产物","可直接随尿排出或者进一步分解"],"a":3,"e":"β-氨基异丁酸由胸腺嘧啶分解生成，可直接随尿排出或进一步分解；尿嘧啶降解的终产物是β-丙氨酸及NH3、CO2，二者来源不同。"},{"q":"蛋白激酶A（PKA）中的每个调节亚基可结合环腺苷酸（cAMP）的分子数为","o":["2个","3个","4个","5个","6个"],"a":0,"e":"PKA是由2个催化亚基和2个调节亚基组成的四聚体，每个调节亚基可结合2分子cAMP，结合后构象改变释放催化亚基。"},{"q":"蛋白激酶A（PKA）所含亚基数为","o":["1","2","3","4","5"],"a":3,"e":"PKA由2个调节亚基和2个催化亚基组成，共4个亚基，故亚基数为4。cAMP结合调节亚基后释放催化亚基而激活。"},{"q":"某有机化合物，是合成脂肪酸、胆固醇、柠檬酸的原料，但不是糖异生的原料。该物质最可能是","o":["1,3-二磷酸甘油酸","丙酮酸","苹果酸","乙酰辅酶A","草酰乙酸"],"a":3,"e":"乙酰CoA是合成脂肪酸和胆固醇的原料，也是柠檬酸合成的前体；糖异生不能利用乙酰CoA，因丙酮酸脱氢酶催化的反应不可逆。"},{"q":"能够合成酮体的器官是","o":["骨骼肌","脑","心","肝","肾"],"a":3,"e":"酮体在肝线粒体由酮体合成酶系催化生成，肝缺乏利用酮体的酶，生成后经血运至肝外组织氧化利用。"},{"q":"下列物质中，人体不能消化的是","o":["果糖","蔗糖","乳糖","纤维素","糖原"],"a":3,"e":"人体缺乏β-葡萄糖苷酶，不能消化纤维素；果糖、蔗糖、乳糖和糖原均可被消化吸收利用。"},{"q":"提出DNA双螺旋结构最直接的科学证据是","o":["Chargaff规则","特定组织的DNA，嘧啶和嘌呤克分子数的等量关系","X线衍射图","A=T，G=C","在电镜下观察到了双螺旋结构"],"a":2,"e":"Franklin获得的DNA分子X线衍射照片直接提示DNA呈螺旋状，是Watson和Crick提出双螺旋结构模型最直接的科学证据。Chargaff规则提供碱基组成依据。"},{"q":"关于生长因子的叙述中，正确的是","o":["属于类固醇激素的一种","是调节细胞生长增殖的多肽类物质","是细胞内信息物质","化学本质是氨基酸及其衍生物","化学本质是脂酸衍生物"],"a":1,"e":"生长因子是调节细胞生长增殖的多肽类物质，通过受体介导信号转导发挥作用，并非类固醇激素或氨基酸、脂酸衍生物。"},{"q":"胃幽门部黏膜病变可导致缺乏的维生素是","o":["维生素A","维生素E","维生素C","维生素B6","维生素B12"],"a":4,"e":"胃壁细胞分泌的内因子是维生素B12吸收所必需，胃幽门部黏膜病变或胃切除可致其缺乏，引起巨幼细胞贫血。"},{"q":"蛋白质的α-螺旋结构，每上升一圈需要的氨基酸残基数目是","o":["2、5","2、7","3","3、6","4、5"],"a":3,"e":"α-螺旋中每3.6个氨基酸残基沿中心轴旋转一圈，螺距0.54nm，每个残基上升0.15nm。"},{"q":"糖酵解过程中催化1mol六碳糖裂解为2mol三碳糖的反应的酶是","o":["磷酸己糖异构酶","6-磷酸果糖激酶-1","醛缩酶","磷酸丙糖异构酶","烯醇化酶"],"a":2,"e":"醛缩酶催化果糖-1，6-二磷酸裂解为磷酸二羟丙酮和甘油醛-3-磷酸，即1mol六碳糖裂解为2mol三碳糖。磷酸己糖异构酶仅催化醛酮互变，磷酸丙糖异构酶作用于三碳糖之间。"},{"q":"可磷酸化蛋白质上酪氨酸残基的蛋白激酶是","o":["蛋白激酶C","依赖于cAMP的蛋白激酶","依赖于cGMP的蛋白激酶","Src蛋白激酶","磷酸化酶b激酶"],"a":3,"e":"Src蛋白激酶属非受体型蛋白质酪氨酸激酶，可使蛋白质的酪氨酸残基磷酸化；PKA、PKC和磷酸化酶b激酶作用于丝/苏氨酸残基。"},{"q":"N-连接型聚糖合成所必需的物质或步骤不包括","o":["单糖活化为UDP或GDP的衍生物","糖基转移酶","长萜醇","高尔基体内糖链加工成熟","细胞核内糖链加工"],"a":4,"e":"N-连接型聚糖先在內质网合成核心寡糖并转移至肽链，再在高尔基体内加工成熟，细胞核内不进行糖链加工。"},{"q":"通常与G蛋白偶联的受体含有的跨膜螺旋的数目为","o":["5个","6个","7个","8个","9个"],"a":2,"e":"G蛋白偶联受体肽链反复跨膜七次，故称七次跨膜受体，其胞内部分与异源三聚体G蛋白结合，经G蛋白转导细胞外信号。"},{"q":"以下选项中属于癌基因的是","o":["Rb","p53","p16","APC/MCC","C-MYC"],"a":4,"e":"C-MYC是原癌基因，其扩增或染色体易位可使表达持续增高而促进细胞增殖；Rb、p53、p16和APC/MCC均属抑癌基因。"},{"q":"大鼠出生后饲以去脂膳食，结果将引起脂质缺乏的是","o":["磷脂酰胆碱","甘油三酯","胆固醇","鞘磷脂","前列腺素"],"a":4,"e":"亚油酸等必需脂肪酸是前列腺素合成的前体，去脂膳食使必需脂肪酸缺乏，廿碳多不饱和脂肪酸衍生物生成减少，以前列腺素缺乏最明显。"},{"q":"下列对葡萄糖有氧氧化和脂肪酸β-氧化的比较中，错误的是","o":["酶系均存在线粒体和细胞质中","乙酰辅酶A为二者的共同中间产物","三羧酸循环为共有的代谢途径","肝脏主要通过葡萄糖有氧氧化功能","单位重量葡萄糖氧化产能少于单位重量脂肪酸氧化"],"a":3,"e":"肝主要氧化脂肪酸供能，并生成酮体供肝外组织利用，而非以葡萄糖有氧氧化为主要供能方式；糖有氧氧化与β-氧化均经三羧酸循环。"},{"q":"印迹技术的操作程序是","o":["电泳→转移→杂交→显色","杂交→电泳→转移→显色","电泳→显色→转移→杂交","转移→电泳→杂交→显色","电泳→显色→杂交→转移"],"a":0,"e":"印迹技术的基本程序为电泳分离、转移至固相膜、与探针杂交、显色或显影检测，据此判断待测大分子的有无与大小。"},{"q":"苹果酸穿梭作用的生理意义在于","o":["将草酰乙酸带人线粒体彻底氧化","维持线粒体内外有机酸的平衡","进行谷氨酸、草酰乙酸转氨基作用","为三羧酸循环提供足够的草酰乙酸","将细胞质中NADH+H+的2H带入线粒体内"],"a":4,"e":"苹果酸-天冬氨酸穿梭将细胞质NADH的2H经苹果酸带入线粒体基质，重新生成NADH进入呼吸链氧化，是胞质还原当量进入线粒体的途径之一。"},{"q":"都含铁卟啉的两种物质是","o":["铁硫蛋白和血红蛋白","过氧化物酶和过氧化氢酶","细胞色素C氧化酶和乳酸脱氧酶","过氧化物酶和琥珀酸脱氢酶","细胞色素b和乳酸脱氢酶"],"a":1,"e":"体内铁卟啉类化合物包括血红蛋白、肌红蛋白、细胞色素、过氧化氢酶和过氧化物酶；乳酸脱氢酶、琥珀酸脱氢酶不含铁卟啉，铁硫蛋白的铁属非铁卟啉铁。"},{"q":"由肌肉组织通过血液向肝进行转运的过程是","o":["三羧酸循环","鸟氨酸循环","甲硫氨酸循环","γ-谷氨酰基循环","丙氨酸-葡萄糖循环"],"a":4,"e":"骨骼肌中丙酮酸经转氨基生成丙氨酸，随血液运至肝，在肝内脱氨基生成丙酮酸并异生为葡萄糖，再运回肌肉，构成丙氨酸-葡萄糖循环。"},{"q":"原癌基因是","o":["抑制细胞过度生长和增殖的基因","体外引起细胞转化的基因","存在于正常细胞基因组中的癌基因","突变的p53基因","携带有转导基因的病毒癌基因"],"a":2,"e":"原癌基因是正常细胞基因组中存在的、进化上高度保守的正常功能基因，其表达产物参与细胞正常生理活动，本身不具致癌活性，只有经突变或过度活化后才转变为癌基因。"},{"q":"下列关于DNA变性描述正确的是","o":["DNA变性时糖苷键断裂","磷酸二酯键断裂","解链温度的最高点称为Tm","A260nm降低","双链间氢键被破坏"],"a":4,"e":"DNA变性时双链互补碱基间的氢键断裂、碱基堆积力被破坏，两链解离为单链，糖苷键和磷酸二酯键并不断裂，A260升高。"},{"q":"PCR引物设计时，不需要考虑","o":["模板的GC含量","引物的GC含量","引物之间互补","引物长度","引物内部互补"],"a":0,"e":"PCR引物设计需考虑引物长度、GC含量、Tm值以及引物自身和引物间互补形成的发夹与二聚体；模板的GC含量影响解链温度，但不属引物设计参数。"},{"q":"启动子捕获技术（promoter trapping）的原理是","o":["双荧光素酶报告基因","染色体免疫沉淀","基因表达的定量","电泳迁移率变动实验","PCR克隆"],"a":0,"e":"启动子捕获技术利用报告基因指示启动子活性，双荧光素酶报告基因系统是检测启动子活性的常用方法。报告基因表达后可产生易检测的荧光信号。"},{"q":"核酸分子杂交是分子生物学常用的实验技术，下面哪种技术不涉及核酸杂交","o":["Southern印迹杂交","Northern印迹杂交","PCR扩增","斑点印迹","琼脂糖凝胶电泳"],"a":4,"e":"琼脂糖凝胶电泳仅按核酸分子大小和电荷分离片段，不涉及探针与靶序列互补结合；Southern、Northern和斑点印迹均以核酸杂交为核心。"},{"q":"STS（sequence-tagged site）是指","o":["指人类基因组中长度2～6bp的串联重复序列","指人类基因组中长度约200～600bp的单拷贝片段","指人类基因组中长度约20～60bp的单拷贝片段","指人类基因组中长度约2～6bp的反向串联重复序列","指人类基因组中长度随机的片段"],"a":1,"e":"序列标签位点（STS）是基因组中长度约200～600bp的单拷贝片段，其序列已知、位置确定，可作为染色体定位和基因组作图的标志。"},{"q":"促甲状腺素发挥作用时，其第二信使是","o":["cCMP","cGMP","cAMP","cUMP","AMP"],"a":2,"e":"促甲状腺素与甲状腺细胞膜受体结合，经Gs激活腺苷酸环化酶，生成cAMP作为第二信使，促进甲状腺激素合成和分泌。"},{"q":"蛋白质分子一定具有","o":["α-螺旋","β-折叠","三级结构","四级结构","亚基"],"a":2,"e":"三级结构指整条肽链折叠成的完整三维空间构象，是蛋白质发挥功能必备的层次；四级结构仅见于两条以上肽链构成的蛋白质。"},{"q":"下列关于肽键的叙述，错误的是","o":["肽键属于一级结构","肽键中C-N键所连的四个原子处于同一平面","肽键具有部分双键性质","肽键旋转而形成了β-折叠","肽键中的C-N键长度比N-Cα单键短"],"a":3,"e":"β-折叠由肽链充分伸展、以Cα为旋转点折叠成锯齿状并经肽链间氢键稳固形成，肽键本身不能旋转，旋转的是Cα两侧的Ф角和ψ角。"},{"q":"维系蛋白质一级结构的化学键是","o":["氢键","疏水键","盐键","肽键","范德华力"],"a":3,"e":"氨基酸通过肽键相连成多肽链，肽键是维系一级结构的主要化学键，二硫键的位置也属一级结构范畴；氢键、盐键等维持高级结构。"},{"q":"表达序列标签（EST）是指","o":["具有遗传多态性的遗传标记","一段已知核苷酸序列的DNA标志","从组织提取的mRNA序列","代表完整基因一小部分的一段短cDNA序列","人类基因组中编码结构基因的DNA序列"],"a":3,"e":"EST是从cDNA文库随机挑取克隆测序所得的部分cDNA序列，长300～500bp，仅代表完整基因的一小部分。"},{"q":"需要NADPH提供还原当量的代谢反应有","o":["糖原合成","糖异生","胆固醇合成","酮体生成","蛋白质的生物合成"],"a":2,"e":"胆固醇合成需NADPH供氢，合成1分子胆固醇消耗18分子乙酰CoA、36分子ATP和16分子NADPH。"},{"q":"呼吸链中的递氢体是","o":["烟酰胺","黄素蛋白","铁硫蛋白","细胞色素","泛醌"],"a":4,"e":"泛醌即辅酶Q，是呼吸链中脂溶性的递氢体，可同时传递电子和质子；细胞色素与铁硫蛋白只传递电子。"},{"q":"肝外组织利用乙酰乙酸时首先生成的是","o":["HMG-CoA","乙酰乙酰CoA","丁脂酰CoA","丙二酰CoA","乙酰CoA"],"a":1,"e":"乙酰乙酸在肝外组织利用时先经琥珀酰CoA转硫酶或乙酰乙酸硫激酶催化活化为乙酰乙酰CoA，再硫解为乙酰CoA氧化。HMG-CoA是酮体生成途径的中间物。"},{"q":"一种高能化合物小分子，低浓度时是作为6-磷酸果糖激酶-1的底物；高浓度时是作为6-磷酸果糖激酶-1的抑制剂，它是","o":["ATP","UTP","GTP","CTP","ADP"],"a":0,"e":"ATP既是磷酸果糖激酶-1的底物又是其别构抑制剂：低浓度时与活性中心的催化部位结合作为底物，高浓度时与别构部位结合而抑制酶活性。"},{"q":"关于致癌病毒的描述，正确的是","o":["可以将正常细胞转化为癌细胞","能直接引起肿瘤","以DNA为遗传物质","以RNA为模板合成mRNA","含有转化酶"],"a":0,"e":"致癌病毒携带病毒癌基因，感染细胞后可使体外培养的正常细胞失去接触抑制、发生形态改变而转化为癌细胞。"},{"q":"胆固醇在体内可转化为","o":["维生素A","辅酶A","乙酰辅酶A","肾上腺素","氢化可的松"],"a":4,"e":"胆固醇在肾上腺皮质可转化为皮质醇即氢化可的松等类固醇激素，在性腺转化为性激素，在皮肤转化为维生素D3，在肝转化为胆汁酸。"},{"q":"催化α-酮戊二酸和氨生成谷氨酸的酶是","o":["谷氨酸脱羧酶","谷草转氨酶","谷氨酸脱氢酶","谷氨酰胺转肽酶","谷氨酰胺合成酶"],"a":2,"e":"L-谷氨酸脱氢酶催化L-谷氨酸氧化脱氨生成α-酮戊二酸和氨，该反应可逆，故也能催化α-酮戊二酸氨化生成谷氨酸。谷草转氨酶催化转氨基，谷氨酰胺合成酶催化谷氨酸与氨合成谷氨酰胺。"},{"q":"DNA变性是指","o":["寡核苷酸链解聚","DNA分子由超螺旋转变为双螺旋","分子中磷酸二酯键断裂","互补碱基间氢键断裂","碱基与脱氧戊糖间糖苷键断裂"],"a":3,"e":"DNA变性是双链互补碱基间的氢键断裂、碱基堆积力破坏，两条链解离为单链，不涉及磷酸二酯键和糖苷键的断裂。"},{"q":"人体嘌呤核苷酸分解代谢的特征性终产物是","o":["NH3","CO2","黄嘌呤","次黄嘌呤","尿酸"],"a":4,"e":"尿酸是人体嘌呤核苷酸分解代谢的特征性终产物，水溶性差，生成过多或排泄障碍可致高尿酸血症与痛风。"},{"q":"属于营养必需脂肪酸的是","o":["亚麻酸","软脂酸","硬脂酸","月桂酸","油酸"],"a":0,"e":"亚油酸、α-亚麻酸因人体缺乏Δ9以上去饱和酶不能合成，必须由食物提供，属必需脂肪酸；软脂酸、硬脂酸、油酸均可自身合成。"},{"q":"以大肠杆菌体系生产真核生物基因产物，常常利用含有乳糖操纵子的质粒，将须表达DNA片段插入其某一区域，此区域常是","o":["O（操纵部位）","P（启动子）","Z基因","Y基因","A基因"],"a":2,"e":"将外源基因插入lacZ基因内部会干扰其表达，使lacZ失活，在X-gal和IPTG培养基上呈白色菌落，此即蓝白筛选原理。故表达片段常插入Z基因区，用于筛选重组子。"},{"q":"下列哪种抑制作用属竞争性抑制作用","o":["磺胺类药物对细菌二氢叶酸合成酶的抑制作用","敌敌畏对胆碱酯酶的抑制作用","砷化合物对巯基酶的抑制作用","氰化物对细胞色素氧化酶的抑制作用","重金属盐对某些酶的抑制作用"],"a":0,"e":"磺胺类药物与对氨基苯甲酸结构相似，竞争性抑制细菌二氢蝶酸合酶，阻碍四氢叶酸合成；敌敌畏、砷化合物等属不可逆抑制。"},{"q":"脂肪大量动员时肝内生成的乙酰CoA主要转变为","o":["葡萄糖","胆固醇","脂肪酸","酮体","丙二酰CoA"],"a":3,"e":"脂肪大量动员时脂肪酸β-氧化生成大量乙酰CoA，草酰乙酸不足使其不能顺利进入三羧酸循环，转而缩合生成酮体。"},{"q":"冈崎片段的生成是由于","o":["真核生物有多个复制起始点","拓扑酶的作用","RNA引物合成不足","后随链合成方向与解链方向相反","DNA连接酶缺失"],"a":3,"e":"DNA聚合酶只能沿5'→3'方向合成，后随链合成方向与解链方向相反，只能分段生成引物并合成短片段，即冈崎片段。"},{"q":"下列化合物，哪项是乙酰CoA羧化酶的别构激活剂","o":["异柠檬酸","脂酰CoA","胰高血糖素","葡萄糖","乙酰乙酸"],"a":0,"e":"乙酰CoA羧化酶为别构酶，柠檬酸和异柠檬酸使其由无活性原聚体聚合成有活性多聚体；软脂酰CoA则别构抑制。"},{"q":"以下不属于初级胆汁酸成分是","o":["脱氧胆酸","胆酸","甘氨鹅脱氧胆酸","牛磺胆酸","牛磺鹅脱氧胆酸"],"a":0,"e":"初级胆汁酸在肝内由胆固醇生成，包括胆酸、鹅脱氧胆酸及二者与甘氨酸或牛磺酸的结合产物；脱氧胆酸由胆酸脱去7α-羟基生成，属次级胆汁酸。"},{"q":"体内合成胆固醇的原料是","o":["乙酰CoA","丙酮酸","胆汁酸","铁卟啉","胆色素"],"a":0,"e":"胆固醇合成的唯一碳源是乙酰CoA，后者经柠檬酸-丙酮酸循环由线粒体转入胞质，先合成HMG-CoA再逐步生成胆固醇。"},{"q":"下列基因调节模式涉及基因重组的是","o":["乳糖操纵子机制","色氨酸操纵子机制","阿拉伯糖操纵子机制","大肠杆菌的SOS反应","沙门氏菌的相变异"],"a":1,"e":"官方答案为【色氨酸操纵子机制】，但依据教材，正确答案为【沙门氏菌的相变异】。沙门氏菌鞭毛相变异由启动子区DNA片段倒位即位点特异性重组切换基因表达，色氨酸操纵子则靠转录衰减调节。"},{"q":"CoQ的特点是","o":["它是脂溶性物质，能在线粒体内膜中扩散","它是水溶性很强的物质","它是维生素之一","它仅仅是电子传递体","它只存在人体中"],"a":0,"e":"CoQ为脂溶性醌类，能在线粒体内膜中自由扩散，其苯醌部分可进行双、单电子传递。CoQ并非维生素，也不只存在于人体。"},{"q":"关于生物氧化，叙述错误的是","o":["总是伴有ATP的生成","可在细胞的线粒体内进行","可在细胞的内质网内进行","在温和条件下进行","需要一系列酶催化"],"a":2,"e":"生物氧化是物质在体内温和条件下经一系列酶催化逐步脱氢氧化并释能的过程，主要在线粒体内膜呼吸链进行；内质网不含呼吸链，不承担生物氧化。"},{"q":"通过代谢组学的方法分析急性肝损伤病人的代谢物，其尿液中含量显著升高的是","o":["尿胆素原","尿胆素","尿胆红素","尿素","尿酸"],"a":2,"e":"肝细胞性黄疸时结合胆红素反流入血，其水溶性高可经肾小球滤过，故尿中胆红素呈阳性。"},{"q":"Hb的α亚基与O2结合后产生变构效应，从而","o":["促进α亚基与O2结合，抑制β亚基与O2结合","促进β亚基与O2结合，抑制α亚基与O2结合","促进其他亚基与O2结合","抑制其他亚基与O2结合","促进其他亚基与CO2结合"],"a":2,"e":"血红蛋白第一个亚基结合O2后引起亚基间盐键断裂、构象松弛，产生正协同效应，促进其余亚基依次结合O2。"},{"q":"在呼吸链中，既可作为NADH脱氢酶的受氢体，又可作为琥珀酸脱氢酶的受氢体的是","o":["Cyt c","Cyt b","CoQ","FAD","铁硫蛋白"],"a":2,"e":"泛醌是呼吸链中脂溶性递氢体，既接受复合体Ⅰ中NADH脱氢酶传来的氢，也接受复合体Ⅱ中琥珀酸脱氢酶经FAD传递的氢。"},{"q":"在长期服用异烟肼时，易引起缺乏的维生素是","o":["维生素C","维生素A","维生素PP","维生素D","维生素K"],"a":2,"e":"异烟肼结构与维生素PP相似，二者有拮抗作用，长期服用异烟肼可致维生素PP缺乏，出现糙皮病样表现。"},{"q":"基因芯片是建立在哪种技术基础之上的","o":["核酸分子杂交","酵母双杂交","免疫印迹","EMSA","定量PCR"],"a":0,"e":"基因芯片技术本质上是一种核酸分子杂交技术，通过探针与目的核酸杂交检测信号实现大规模基因诊断。"},{"q":"下列不参与调控真核基因特异性表达的是","o":["转录抑制因子","基本转录因子","转录激活因子","增强子","沉默子"],"a":1,"e":"基本转录因子是RNA聚合酶结合启动子所必需、参与所有基因转录起始的通用蛋白，不决定基因特异性；特异性表达由转录激活因子、抑制因子及增强子、沉默子调控。"},{"q":"下列哪个数据库可以最便捷的检索到基因组信息","o":["Nucleotide","Genome","Structures","PubMed","OMIM"],"a":1,"e":"Genome数据库收录各物种完整基因组序列及注释信息，是检索基因组信息最便捷的专门资源。Nucleotide侧重核酸序列，PubMed为文献库，OMIM侧重遗传病。"},{"q":"DNA损伤修复方式中不包括","o":["切除修复","互补修复","光复活修复","重组修复","SOS修复"],"a":1,"e":"DNA损伤修复包括直接修复（光复活）、切除修复、重组修复和跨越损伤修复，不存在“互补修复”这一方式。"},{"q":"信号转导及转录激活因子（STAT）与下述哪个信号传递过程有关","o":["甲状旁腺素","肾上腺素","心房钠尿肽","干扰素","雌激素"],"a":3,"e":"干扰素与受体结合后激活JAK，使STAT磷酸化并形成二聚体转入核内，调控特定基因转录。"},{"q":"下列对脂肪酸生物合成的描述中，正确的是","o":["脂肪酸主要是在线粒体内合成","脂肪酸合成是脂酸β-氧化的逆过程","脂肪酸的生物合成由NADH提供氢","脂肪酸的合成是以丙二酰CoA为中心的一种连续性缩合作用","脂肪酸生物合成的产物是硬脂酸"],"a":3,"e":"脂肪酸合成在细胞质进行，以丙二酰CoA为二碳单位供体，经缩合、加氢、脱水、再加氢的循环延长碳链，由NADPH供氢。"},{"q":"以下关于嘌呤核苷酸合成的调节，描述错误的是","o":["以反馈调节方式为主","PRPP增加可抑制PRPP酰胺转移酶活性","IMP、AMP及GMP能使PRPP酰胺转移酶从活性形式转变为无活性形式","在合成调节中，PRPP合成酶比PRPP酰胺转移酶作用更大","PRPP酰胺转移酶是一类别构酶"],"a":1,"e":"PRPP增加可别构激活PRPP酰胺转移酶，加速5-磷酸核糖胺生成；IMP、AMP和GMP才反馈抑制该酶，故该描述错误。"},{"q":"1mol葡萄糖酵解时净生成ATP的摩尔数为","o":["1","2","3","4","5"],"a":1,"e":"1分子葡萄糖酵解共生成4分子ATP，扣除葡萄糖和果糖-6-磷酸两次磷酸化消耗的2分子，净生成2分子ATP。"},{"q":"糖、脂肪及氨基酸分解代谢的共同中间产物是","o":["磷酸烯醇式丙酮酸","丙酮酸","乙酰CoA","琥珀酸","延胡索酸"],"a":2,"e":"糖、脂肪、氨基酸分解代谢最终都生成乙酰CoA，再经三羧酸循环彻底氧化，故乙酰CoA是三者共同的中间代谢物。"},{"q":"下列关于启动子的描述，不正确的是","o":["核心序列是TATA盒","本质是DNA分子","蛋白质也是组成成分之一","属于顺式作用元件","与转录起始有关"],"a":2,"e":"启动子本质是一段DNA序列，属顺式作用元件，含TATA盒等核心序列，决定转录起始的准确性与频率，其组成中不含蛋白质。"},{"q":"下列对蛋白质α-螺旋的描述，错误的是","o":["通过氢键维持其结构稳定","通过侧链（R基团）之间的相互作用维持其结构稳定","通过分子内肽键之间的氢键维持其结构稳定","是蛋白质的一种二级结构类型","脯氨酸残基可打断α-螺旋"],"a":1,"e":"α-螺旋靠主链肽键的C=O与N-H形成链内氢键维持稳定；侧链R基团相互作用主要维持三级和四级结构，不是α-螺旋的稳定因素。"},{"q":"温度与酶促反应速率关系的叙述，错误的是","o":["最适温度是酶的特征性常数","最适温度时，反应速率最快","超过最适温度酶促反应速率降低","酶的最适温度与反应时间有关","酶在短时间内可耐受较高温度"],"a":0,"e":"最适温度不是酶的特征性常数，它随反应时间延长而降低；温度升高加快反应与酶蛋白变性失活两种效应综合决定最适温度，故该项错误。"},{"q":"缺乏维生素B12可引起下列哪种疾病","o":["夜盲症","脚气病","贫血","坏血病","佝偻病"],"a":2,"e":"维生素B12缺乏使N5-甲基四氢叶酸上的甲基不能转移，四氢叶酸再生障碍，核酸合成受阻，引起巨幼细胞贫血。"},{"q":"生物转化的第一项反应，不包括","o":["单胺氧化酶催化的氧化反应","还原反应","水解反应","结合反应","加单氧酶催化的氧化反应"],"a":3,"e":"生物转化第一相反应包括氧化、还原和水解三类，结合反应属第二相反应，故不属于第一相反应。"},{"q":"各种不同的底物都借助于同一呼吸链传递电子至氧是因为","o":["底物在线粒体被氧化","许多底物的氧化与NAD+或FAD为辅助因子氧化酶有关","底物通过一些酶类全部被氧化","来自各种底物的电子全部都传递给共同的电子受体","来自各种底物的质子都用于生成水"],"a":3,"e":"不同底物脱下的氢分别经NADH或FAD递给呼吸链，但电子最终都交给同一受体氧，故各种底物共用同一呼吸链。"},{"q":"关于神经节苷脂功能的叙述，错误的是","o":["在神经冲动传递中起重要作用","参与细胞相互识别","在细胞生长、分化时起重要作用","霍乱毒素的受体","参与血液凝固和细胞黏着过程"],"a":4,"e":"神经节苷脂位于细胞膜表面，参与神经冲动传递、细胞识别以及细胞生长分化，也是霍乱毒素的受体；血液凝固与细胞黏着非其主要功能。"},{"q":"下列哪个酶是糖酵解和磷酸戊糖途径所共有的","o":["丙酮酸激酶","己糖激酶","6-磷酸果糖激酶-1","6-磷酸葡萄糖酸脱氢酶","葡萄糖-6-磷酸脱氢酶"],"a":1,"e":"糖酵解与磷酸戊糖途径均以葡萄糖-6-磷酸为中间产物，己糖激酶催化葡萄糖磷酸化生成葡萄糖-6-磷酸，为两途径共有。"},{"q":"关于N-连接型聚糖的叙述，错误的是","o":["糖基须活化成UDP或GDP的衍生物","糖基化位点是Asn-X-Ser/Thr","N-连接型聚糖分为高甘露糖型、复杂型和杂合型","糖基与多肽链丝氨酸残基连接","需要糖基转移酶催化"],"a":3,"e":"N-连接型聚糖的糖基与多肽链天冬酰胺残基的酰胺氮共价连接，糖基化位点为Asn-X-Ser/Thr；与丝氨酸/苏氨酸羟基连接的是O-连接型聚糖。"},{"q":"食物蛋白质的互补作用是","o":["几种蛋白质食物混合食用，提高营养价值","脂肪与蛋白质食物混合食用，提高营养价值","糖、脂肪和蛋白质几种食物混合食用，提供营养价值","供应各种维生素，可节约食物蛋白质的摄入量","用蛋白质食物代替脂肪性高的食物，提高营养价值"],"a":0,"e":"食物蛋白质互补作用指几种营养价值较低的蛋白质混合食用，彼此补充必需氨基酸的种类和比例，从而提高蛋白质的营养价值。"},{"q":"丙酮酸氧化分解时，净生成ATP分子数是","o":["10","12、5","13","20","12"],"a":1,"e":"丙酮酸氧化脱羧生成1分子NADH（约2.5分子ATP）和1分子乙酰CoA，后者经三羧酸循环彻底氧化生成10分子ATP，合计12.5分子。"},{"q":"关于酶活性中心的叙述中正确的是","o":["所有酶的活性中心都含有辅酶","所有酶的活性中心都含有金属离子","酶的必需基团都位于活性中心内","所有的抑制剂都作用于酶活性中心","所有的活性中心都具有结合基团和催化基团"],"a":4,"e":"酶活性中心内的必需基团分为结合基团和催化基团，前者识别并专一结合底物，后者催化化学键断裂与形成；并非所有酶都含辅酶或金属离子，抑制剂也未必作用于活性中心。"},{"q":"脂肪酸在肝脏进行β-氧化时，不生成的物质是","o":["NADH","FADH2","水","乙酰CoA","脂酸CoA"],"a":2,"e":"β-氧化经脱氢、加水、再脱氢和硫解四步，其中加水反应消耗水而非生成水；产物为FADH2、NADH、乙酰CoA和缩短两碳的脂酰CoA。"},{"q":"下列关于维生素D的描述，哪项是正确的","o":["是胆固醇的主要转化产物","是一种水溶性维生素","可以与核受体进行结合","25-OH-VitD3是其完全活性形式","是多种代谢关键酶的辅酶"],"a":2,"e":"维生素D的活性形式1,25-(OH)2-D3与靶细胞核受体结合，调节钙结合蛋白、骨钙蛋白等基因表达；它属脂溶性维生素，不是多种酶的辅酶。"},{"q":"原核生物中，某种代谢途径相关的几种酶往往通过何种机制进行协调表达","o":["顺反子","操纵子","转录因子","衰减子","沉默子"],"a":1,"e":"原核生物功能相关的基因串联排列，与共同的启动子、操纵序列和调节基因组成操纵子，受同一调控序列协调表达。"},{"q":"组蛋白修饰在时间与空间上的组合与生物学功能的关系可以作为一种重要的标志或语言，被称为“组蛋白密码”。研究组蛋白密码对药物开发具有战略意义，多种组蛋白修饰酶已经成为相关疾病治疗的靶标。比如，组蛋白去乙酰化酶（HDACs）抑制剂已应用于临床治疗多种肿瘤。下列关于“组蛋白密码”叙述错误的是","o":["组蛋白修饰属于染色质水平上的基因表达调控方式","组蛋白修饰主要包括组蛋白的乙酰化、磷酸化、甲基化、泛素化以及ADP核糖基化","组蛋白甲基化修饰既可抑制也可增强基因表达","组蛋白乙酰化修饰一般选择性地使某些染色质区域的结构从松散变得紧密","组蛋白乙酰化修饰和甲基化修饰一般相互排斥"],"a":3,"e":"乙酰化中和组蛋白尾部碱性氨基酸残基的正电荷，减弱组蛋白与带负电DNA的结合，使染色质由紧密变松散而利于转录，故该选项所述方向正好相反。"},{"q":"原核生物和真核生物的蛋白质合成过程虽有很多不同之处，但在基本机制等方面又有诸多共同之处。对于原核生物和真核生物的蛋白质合成都是必需的是","o":["核糖体小亚基与S-D序列结合","fMet-tRNA","mRNA从细胞核转运至细胞质","起始因子识别5'-帽子结构","肽酰基-tRNA从A位转位至P位"],"a":4,"e":"转位是肽酰-tRNA由A位移至P位、A位空出并对应下一密码子，为原核与真核肽链延长共有的步骤；S-D序列、fMet及5'-帽子识别均具特异性。"},{"q":"催化三羧酸循环与脂肪酸β-氧化的酶分布在细胞的","o":["细胞质","细胞膜","细胞核","内质网","线粒体"],"a":4,"e":"三羧酸循环的酶系在线粒体基质和内膜，脂肪酸β-氧化酶系在线粒体基质，两者均分布于线粒体。"},{"q":"下列关于RNA组学的叙述错误的是","o":["研究非编码RNA的集合","研究非编码RNA对基因表达的调控","研究小分子RNA的种类、表达情况及生物学意义","研究长非编码RNA的表达调控及生物学功能","是结构基因组学的重要组成部分"],"a":4,"e":"RNA组学研究细胞中全部非编码RNA及其对基因表达的调控，属于功能基因组学范畴；结构基因组学的任务是基因组作图与序列测定。"},{"q":"磷酸戊糖途径的真正意义在于产生许多中间物如核糖，同时还产生","o":["NADPH＋H＋","NAD＋","ADP","CoASH","含有不同糖原子的糖类物质"],"a":0,"e":"磷酸戊糖途径生成核糖-5-磷酸和NADPH，后者作为供氢体参与脂肪酸、胆固醇等合成，并维持谷胱甘肽还原性。该途径不产生NAD+、ADP或CoASH。"},{"q":"喜树碱（camptothecin）具有抗癌活性，是因为它在癌细胞内选择性地抑制","o":["DNA聚合酶","RNA聚合酶","DNA拓扑异构酶Ⅰ","DNA解链酶","DNA连接酶"],"a":2,"e":"喜树碱选择性抑制DNA拓扑异构酶Ⅰ，阻断DNA复制过程中超螺旋的解除，从而抑制癌细胞增殖。拓扑异构酶Ⅰ通过切断和再连接单链改变DNA超螺旋状态。"},{"q":"肝对血糖的调节不是通过","o":["糖异生","糖原合成","糖原分解","糖转变成非糖物质","加速氨基酸代谢"],"a":4,"e":"肝通过糖原合成与分解、糖异生以及将糖转变为脂肪等非糖物质来调节血糖，加速氨基酸代谢不属其调节血糖的方式。"},{"q":"转氨基作用可生成谷氨酸的α-酮酸是","o":["丙酮酸","草酰乙酸","乙酰乙酸","苯丙酮酸","α-酮戊二酸"],"a":4,"e":"转氨基反应中α-酮戊二酸接受氨基生成谷氨酸，故与谷氨酸对应的α-酮酸是α-酮戊二酸；丙酮酸、草酰乙酸分别生成丙氨酸和天冬氨酸。"},{"q":"关于双向电泳的叙述正确的是","o":["第一向为聚丙烯酰胺凝胶电泳","第一向为变性聚丙烯酰胺凝胶电泳","第二向为聚丙烯酰胺凝胶电泳","第一向为等电聚焦电泳","第二向为琼脂糖凝胶电泳"],"a":3,"e":"双向凝胶电泳第一向为等电聚焦电泳，按蛋白质等电点分离；第二向为SDS-聚丙烯酰胺凝胶电泳，按分子量分离，两向结合可分辨复杂蛋白混合物。"},{"q":"合成脂肪酸的乙酰CoA的主要来源是","o":["细胞质直接提供","细胞质的乙酰肉碱提供","在线粒体产生并以乙酰CoA的形式转运到细胞质","在线粒体产生并由肉碱携带转运到细胞质","在线粒体产生并转化为柠檬酸而转运到细胞质"],"a":3,"e":"官方答案为【在线粒体产生并由肉碱携带转运到细胞质】，但依据教材，正确答案为【在线粒体产生并转化为柠檬酸而转运到细胞质】。乙酰CoA不能直接透过线粒体内膜，须与草酰乙酸缩合成柠檬酸转运至胞质再裂解；肉碱转运的是脂酰CoA。"},{"q":"巯基酶所含的巯基来自哪种氨基酸","o":["胱氨酸","亮氨酸","半胱氨酸","甲硫氨酸","谷氨酸"],"a":2,"e":"半胱氨酸侧链含巯基，是巯基酶活性中心巯基的来源。两个半胱氨酸脱氢后以二硫键相连形成胱氨酸，胱氨酸本身不含游离巯基。"},{"q":"嘧啶核苷酸生物合成途径的反馈抑制，是由于控制了","o":["二氢乳清酸酶的活性","乳清酸磷酸核糖转移酶的活性","二氢乳清酸脱氢酶的活性","天冬氨酸转氨甲酰酶的活性","胸苷酸合酶的活性"],"a":3,"e":"嘧啶核苷酸从头合成的关键酶是氨基甲酰磷酸合成酶Ⅱ和天冬氨酸转氨甲酰酶，后者受UTP、CTP等终产物反馈抑制。"},{"q":"没有引物，DNA聚合酶不能复制DNA，这是因为","o":["DNA聚合酶需要单链DNA模板","没有引物，DNA聚合酶无法进行新链合成","所有的RNA聚合酶和DNA聚合酶需要引物提供游离的3＇-羟基","需要引物来装配好滑动钳结构","需要引物解开DNA双链，以暴露模板链"],"a":1,"e":"DNA聚合酶只能催化游离dNTP加到已有核酸链的3′-OH末端，不能使两个游离dNTP之间直接成键，故没有引物便无法起始新链合成。"},{"q":"肾上腺素发挥作用时，其第二信使是","o":["cUMP","cGMP","cCMP","GMP","cAMP"],"a":4,"e":"肾上腺素与β受体结合，经Gs激活腺苷酸环化酶，使ATP生成cAMP，cAMP激活PKA而发挥代谢调节作用。"},{"q":"通过膜受体起调节作用的激素是","o":["性激素","糖皮质激素","甲状腺素","肾上腺素","活性维生素D3"],"a":3,"e":"肾上腺素属儿茶酚胺类，不能透过脂双层，需与靶细胞膜受体结合后经跨膜信号转导发挥调节作用；类固醇激素和甲状腺素则作用于胞内受体。"},{"q":"脂肪酸β-氧化过程生成的1分子FADH2经呼吸链传递给氧生成水，同时经氧化磷酸化反应可生成ATP的分子数是","o":["0","1","1、5","2、5","3"],"a":2,"e":"线粒体内每分子FADH2经呼吸链氧化磷酸化生成1.5分子ATP，NADH则生成2.5分子ATP。"},{"q":"有关糖原代谢的叙述，正确的是","o":["CTP参与糖原的合成","糖原合成的关键酶的分支酶","在糖原引物上每添加1个葡萄糖基需要消耗3个ATP","糖原磷酸化酶催化的磷酸解生成6-磷酸葡萄糖","葡萄糖-6-磷酸酶不存在于肌肉中"],"a":4,"e":"葡萄糖-6-磷酸酶存在于肝内质网，可将葡萄糖-6-磷酸水解为葡萄糖释放入血，肌组织缺乏此酶，故肌糖原不能直接补充血糖。糖原合成每添加1个葡萄糖基消耗2个ATP，关键酶为糖原合酶。"},{"q":"脂肪动员的限速酶是","o":["甘油三酯脂肪酶","甘油二酯脂肪酶","甘油一酯脂肪酶","腺苷酸环化酶","蛋白激酶A"],"a":0,"e":"脂肪动员的关键酶是甘油三酯脂肪酶（ATGL），催化甘油三酯水解的第一步，是脂肪动员的限速酶。HSL主要催化甘油二酯水解，并非限速步骤。"},{"q":"在分子生物学领域，自然界的DNA重组不包括","o":["同源重组","位点特异性重组","聚合酶链式反应","转座重组","接合作用"],"a":2,"e":"自然界的DNA重组包括同源重组、位点特异性重组和转座重组，细菌接合转移DNA亦经同源重组实现；PCR是体外酶促扩增技术，不属重组。"},{"q":"既可以分离蛋白质、也可以测定其分子量的实验技术是","o":["亲和层析","超速离心","透析","离子交换层析","盐析"],"a":1,"e":"超速离心依蛋白质颗粒沉降行为的差异，既可分离纯化蛋白质，也可通过沉降速度测定其分子量，是蛋白质研究的常用手段。"},{"q":"汉斯·克雷布斯于1937年发现了三羧酸循环。揭示了生物体内糖经酵解途径变为三碳物质后，进一步氧化为二氧化碳和水的途径以及代谢能的主要来源。这一循环与糖、蛋白质、脂肪等的代谢都有密切关系，是所有需氧生物代谢中的重要环节。这一发现被公认为代谢研究的里程碑。在三羧酸循环中，下列哪一阶段的产物可以进行氧化磷酸化","o":["乙酰CoA→柠檬酸","异柠檬酸→α-酮戊二酸","琥珀酰CoA→琥珀酸","延胡索酸→苹果酸","柠檬酸→异柠檬酸"],"a":1,"e":"异柠檬酸脱氢酶催化异柠檬酸氧化脱羧生成α-酮戊二酸，脱下的氢交给NAD+生成NADH，后者经呼吸链氧化磷酸化产能。"},{"q":"mRNA差异显示（mRNA-DD）实验中分离PCR扩增产物使用的方法是","o":["SDS-聚丙酰胺凝胶电泳","聚丙酰胺凝胶电泳","琼脂糖凝胶电泳","亲和层析","双向电泳"],"a":1,"e":"mRNA差异显示将逆转录PCR产物用聚丙烯酰胺凝胶电泳分离，比较不同状态细胞间条带的差异，故不需SDS和琼脂糖。"},{"q":"关于糖原合酶的调节，不正确的叙述是","o":["糖原合成酶受磷蛋白磷酸酶-1作用而失活","依赖cAMP蛋白激酶可使磷蛋白磷酸酶抑制物有抑制作用","依赖cAMP蛋白激酶可使糖原合酶失活","糖原合酶有活性和无活性两种形式","糖原合酶活性的调节受多种机制的调节"],"a":0,"e":"磷蛋白磷酸酶-1使糖原合酶去磷酸化而活化，cAMP依赖的蛋白激酶则使糖原合酶磷酸化而失活，两者调节方向相反。"},{"q":"DNA上的一个点突变不一定影响蛋白质的一级结构，是因为","o":["DNA的修复作用","遗传密码的简并性","校正tRNA的作用","核糖体对mRNA的校正","以上都正确"],"a":1,"e":"遗传密码具有简并性，同一氨基酸可由多个密码子编码，故碱基置换后仍可能编码同一氨基酸，蛋白质一级结构不变。"},{"q":"下列器官中能氧化酮体但几乎不能氧化脂肪酸的是","o":["肝","肾","脑","肌肉","心"],"a":2,"e":"脑组织缺乏氧化脂肪酸的酶系，不能利用脂肪酸，但含酮体利用酶，饥饿时以酮体为主要能源。"},{"q":"45S rRNA是","o":["核糖体大亚单位的rRNA","由不同转录单位转录后组合而成","可翻译成组蛋白","除5S rRNA外的其余3种rRNA的前身","由RNA聚合酶Ⅱ催化转录"],"a":3,"e":"45S rRNA由RNA聚合酶Ⅰ转录，是18S、5.8S和28S三种rRNA的共同前身，5S rRNA另由RNA聚合酶Ⅲ转录。"},{"q":"将下述分子按信号传递通路中的先后顺序排列，居第五位的是","o":["受体","腺苷酸环化酶","环腺苷酸（cAMP）","G蛋白","蛋白激酶A（PKA）"],"a":4,"e":"信号按受体、G蛋白、腺苷酸环化酶、cAMP、蛋白激酶A的顺序传递，故居第五位的是蛋白激酶A。"},{"q":"人表皮生长因子受体2（HER2）T790M突变是非小细胞肺癌的耐药机制之一，能够分析HER2突变位点的方法是","o":["BLAST分析","免疫共沉淀分析","基因测序分析","质谱分析","2-DE分析"],"a":2,"e":"基因测序可直接读取HER2相应外显子序列，明确T790M等耐药突变的碱基改变，是最直接确切的突变位点分析方法；BLAST为序列比对，质谱和电泳分析的是蛋白质。"},{"q":"当乙酰CoA羧化酶受到抑制时，下列会受影响的代谢是","o":["糖异生","胆固醇的合成","酮体的合成","脂酸的氧化","脂酸的合成"],"a":4,"e":"乙酰CoA羧化酶催化乙酰CoA羧化为丙二酸单酰CoA，是脂肪酸合成的关键酶和限速步骤；该酶受抑制时脂肪酸合成受阻，与酮体生成、胆固醇合成无直接关系。"},{"q":"ISH可以用于在组织原位定性分析哪项水平的变化","o":["基因组","转录","转录后","翻译","翻译后"],"a":1,"e":"原位杂交以标记核酸探针与组织切片中的mRNA互补结合，在保持细胞形态的原位直接显示基因转录水平，属转录水平分析。"},{"q":"下列与生物素有关的代谢反应有","o":["丙酮酸氧化脱羧反应","氨基酸脱羧反应","一碳基团的转移","加氧反应","乙酰CoA羧化生成丙二酸单酰CoA"],"a":4,"e":"乙酰CoA羧化酶含生物素辅基，以Mn2+为激活剂，催化乙酰CoA羧化为丙二酸单酰CoA，是脂肪酸合成的第一步和关键反应。"},{"q":"蛋白质分子中的下列氨基酸哪一种没有遗传密码","o":["色氨酸","羟脯氨酸","天冬氨酸","甲硫氨酸","赖氨酸"],"a":1,"e":"羟脯氨酸由脯氨酸在蛋白质翻译后羟化修饰生成，无对应的遗传密码；色氨酸、天冬氨酸、甲硫氨酸和赖氨酸均有密码子编码。"},{"q":"脂肪酸在肝进行β-氧化的限速酶是","o":["肉碱脂酰转移酶Ⅰ","肉碱脂酰转移酶Ⅱ","脂酰辅酶A脱氢酶","脂酰辅酶A合成酶","β-酮脂酰辅酶A硫解酶"],"a":0,"e":"肉碱脂酰转移酶Ⅰ催化脂酰CoA转化为脂酰肉碱进入线粒体，是脂肪酸β-氧化的限速步骤，其活性受丙二酰CoA抑制。"},{"q":"饥饿时肝中代谢途径活性增强的是","o":["糖有氧氧化","脂肪合成","糖酵解","磷酸戊糖途径","糖异生"],"a":4,"e":"饥饿时胰岛素降低、胰高血糖素升高，果糖-2，6-二磷酸减少，糖酵解受抑而糖异生增强以维持血糖；脂肪合成与磷酸戊糖途径均减弱。"},{"q":"需经细胞质和线粒体完成的糖代谢途径有","o":["磷酸戊糖途径","三羧酸循环","糖异生途径","糖醛酸途径","糖原合成途径"],"a":2,"e":"糖异生途径的酶分别位于细胞质和线粒体，故需经两处完成。磷酸戊糖途径、糖原合成在细胞质，三羧酸循环在线粒体。"},{"q":"以下蛋白质或酶的作用不依赖于ATP的是","o":["DNA聚合酶Ⅰ","DNA连接酶","拓扑异构酶Ⅱ","DNA解旋酶","氨基酰tRNA合成酶"],"a":0,"e":"DNA聚合酶Ⅰ催化dNTP聚合，能量来自dNTP水解产生的焦磷酸，不需ATP供能；DNA连接酶、拓扑异构酶Ⅱ、解旋酶及氨基酰tRNA合成酶均消耗ATP。"},{"q":"使蛋白质变性的因素是","o":["透析","超滤","有机溶剂","离心","盐析"],"a":2,"e":"乙醇、丙酮等有机溶剂可破坏蛋白质的空间结构而使之变性；透析、超滤、离心和盐析均属物理分离或盐析沉淀，不引起蛋白质变性。"},{"q":"血红蛋白β链编码基因发生突变，是镰状细胞贫血的发生机制。β链编码基因发生的突变是","o":["插入","断裂","缺失","点突变","交联"],"a":3,"e":"镰状细胞贫血由β-珠蛋白基因第6密码子发生单个碱基A→T置换，属点突变，使谷氨酸变为缬氨酸。"},{"q":"DNA拓扑异构酶不能","o":["切开DNA","松弛DNA","改变DNA的超螺旋密度","催化DNA链的断裂和结合","将环状DNA变为线状DNA"],"a":4,"e":"拓扑异构酶可切开DNA、松弛DNA、改变超螺旋密度并催化链的断裂与再连接，但不将环状DNA变为线状DNA。"},{"q":"研究蛋白质间相互作用的技术中不包括","o":["酵母双杂交","免疫共沉淀","基因组编辑技术","双分子荧光互补技术（BIFC）或生物发光共振能量转移技术（BRET）","模拟大分子空间结构的计算生物学软件技术"],"a":2,"e":"酵母双杂交、免疫共沉淀、双分子荧光互补与生物发光共振能量转移及计算模拟均可研究蛋白质间相互作用；基因组编辑用于定向改造基因序列。"},{"q":"下列结构中不属于结构模体的是","o":["锌指","Ω环","螺旋-环-螺旋","碱性亮氨酸拉链","螺旋-转角-螺旋"],"a":1,"e":"锌指、螺旋-环-螺旋、碱性亮氨酸拉链及螺旋-转角-螺旋均由两个以上二级结构肽段构成特定空间构象，属结构模体；Ω环是蛋白质二级结构类型。"},{"q":"人体储存能量的高能化合物是","o":["ATP","GTP","磷酸肌酸","葡萄糖","脂肪酸"],"a":2,"e":"磷酸肌酸是储存能量的高能化合物，ATP充足时其末端高能磷酸基转移给肌酸生成磷酸肌酸，储存于骨骼肌、心肌和脑组织，ATP消耗加快时再转移给ADP生成ATP。"},{"q":"5-氟尿嘧啶在体内发挥作用时，必须转变成","o":["FdTTP","FdUMP","FdUDP","FdUTP","FdTMP"],"a":1,"e":"5-氟尿嘧啶本身无活性，在体内转变为FdUMP后抑制胸苷酸合酶，阻断dTMP合成；其另一产物FUTP可掺入RNA干扰功能。"},{"q":"正常生理条件下，人体所需能量的60%以上来源于","o":["糖","脂肪","蛋白质","DNA","RNA"],"a":0,"e":"糖是人体最主要的供能物质，正常生理条件下其氧化供能约占人体所需能量的60%以上，脂肪次之，蛋白质一般不作为主要能源物质。"},{"q":"机体会增强糖异生来生成葡萄糖的情况是","o":["提高某种酶的活性时","饥饿状态下","疾病状态下","血糖浓度过高时","ATP供应不足时"],"a":1,"e":"饥饿时胰岛素降低、胰高血糖素升高，糖异生关键酶表达增强，肝和肾利用氨基酸、乳酸、甘油异生葡萄糖以维持血糖。"},{"q":"CpG序列的高度甲基化对多数基因而言是","o":["染色质呈转录活性状态","促进转录","抑制转录","既不抑制也不促进转录","与基因表达无关"],"a":2,"e":"CpG岛高度甲基化后，转录因子与启动子结合受阻，并招募染色质重塑蛋白形成致密结构，从而抑制基因转录。"},{"q":"Km值与酶对底物亲和力大小的关系是","o":["Km值越小，亲和力越大","Km值越大，亲和力越大","Km值越小，亲和力越小","Km值大小与酶对底物的亲和力无关","酶对不同亲和力的底物Km值是一定的"],"a":0,"e":"Km等于反应速率为最大速率一半时的底物浓度，Km越小表示达到半数饱和所需底物越少，即酶对底物的亲和力越大。"},{"q":"下列有关核酸变性与复性叙述正确的是","o":["热变性DNA缓慢冷却可复性","复性的最适pH值为7、5","热变性DNA迅速降温过程也称作退火","复性最佳温度为25℃","缓慢升温可以使DNA变性"],"a":0,"e":"热变性DNA经缓慢冷却，两条互补单链可重新配对恢复双螺旋，此过程称退火；若迅速冷却至4℃，互补链来不及配对而不能复性。"},{"q":"利用信息学分析某分泌蛋白可能有糖基化修饰，用于分析该蛋白糖基化位点的技术是","o":["色谱/质谱技术","双向电泳/质谱技术","MPSS技术","基因芯片技术","ETS序列分析"],"a":0,"e":"糖基化位点分析需先将糖肽分离并测定肽段序列，色谱与质谱联用可完成糖肽的分离、定性和位点定位。"},{"q":"DNA复制时，以5'TAGA3'为母链模板，则合成的子链相应序列为","o":["5'TCTA3'","5'UCUA3'","5'ATCT3'","5'AUCU3'","5'GCGA3'"],"a":0,"e":"子链与模板反平行互补，模板5'-TAGA-3'对应子链3'-ATCT-5'，按5'→3'书写即5'-TCTA-3'。"},{"q":"四环素族抗生素对人体蛋白质合成影响不大是因为","o":["可与30S亚基结合","可与50S亚基结合","易进入菌体，但不易透过哺乳类细胞的细胞膜","可与40S亚基结合","可与60S亚基结合"],"a":0,"e":"四环素作用于原核核糖体30S小亚基，阻断氨酰-tRNA与小亚基结合；人体细胞质核糖体为80S，对该药不敏感，故对人体蛋白质合成影响较小。"},{"q":"未结合胆红素的称法很多，但不包括下列哪种","o":["间接反应胆红素","血胆红素","间接胆红素","肝胆红素","游离胆红素"],"a":3,"e":"未结合胆红素又称间接胆红素、游离胆红素或血胆红素；肝胆红素是结合胆红素的同义名称，已与葡萄糖醛酸结合并呈直接反应。"},{"q":"合成RNA的原料是","o":["dNMP","dNDP","dNTP","NTP","NDP"],"a":3,"e":"RNA合成的原料是四种核苷三磷酸ATP、GTP、CTP和UTP；dNTP是DNA合成的原料。"},{"q":"下列描述可考虑作为“管家基因”候选的是","o":["电刺激后细胞表达“A”分子增加","电刺激后细胞表达“A”分子减少","电刺激前后细胞表达“A”分子水平相同","电刺激前细胞表达“A”分子增加","电刺激前细胞表达“A”分子减少"],"a":2,"e":"管家基因的产物是维持细胞基本生命活动所必需，表达水平受环境变化影响小，故刺激前后表达量保持相同者可作为管家基因候选。"},{"q":"关于Km值的意义，错误的是","o":["是酶的特征性常数","Km越大，酶与底物亲和力越小","Km值与酶所催化的底物有关","Km值等于反应速率为最大速率一半时的底物浓度","Km值与酶浓度有关"],"a":4,"e":"Km是酶的特征性常数，等于反应速率为最大速率一半时的底物浓度，与酶的结构、底物及环境有关，与酶浓度无关。"},{"q":"肾上腺素与膜上β受体结合，激活G蛋白后能","o":["激活鸟苷酸环化酶","抑制鸟苷酸环化酶","激活腺苷酸环化酶","抑制腺苷酸环化酶","激活磷脂酶C"],"a":2,"e":"肾上腺素激动β受体后Gs活化，激活腺苷酸环化酶使ATP生成cAMP，进而激活蛋白激酶A。"},{"q":"可以用于基因及表达产物定位分析的杂交技术是","o":["Southern blotting","Northern blotting","Western blotting","FISH","ChIP"],"a":3,"e":"FISH以荧光标记探针与中期染色体或间期细胞核原位杂交，可在细胞水平显示基因及其转录本的定位，用于基因定位和表达产物定位分析。"},{"q":"关于酶的共价修饰，错误的是","o":["一般不需消耗能量","活性和非活性两种形式在不同酶催化下可以互变","催化互变的酶受激素等因素的控制","一般都有活性和非活性两种形式","最常见的共价修饰是多肽链的磷酸化和去磷酸化"],"a":0,"e":"酶的共价修饰是酶促反应，磷酸化与去磷酸化均需消耗ATP，属耗能调节。化学修饰使酶在活性与非活性两种形式间互变，催化互变的酶受激素等因素控制，最常见形式为磷酸化与去磷酸化。"},{"q":"心房钠尿肽发挥调节作用是通过","o":["cAMP-蛋白激酶途径","cGMP-蛋白激酶途径","Ca2+-CaM激酶途径","RTK-Ras-MAPK途径","JAKs-STAT途径"],"a":1,"e":"心房钠尿肽与靶细胞受体结合，激活鸟苷酸环化酶使GTP生成cGMP，cGMP激活蛋白激酶G，促进排钠利尿和血管舒张。"},{"q":"下面有关血红素的叙述，哪一项不正确","o":["是含铁卟啉化合物","有四个吡咯环","是ALA合酶直接催化生成","可进一步转变成胆红素","可与珠蛋白结合生成血红蛋白"],"a":2,"e":"血红素是含铁卟啉化合物，由4个吡咯环构成，可与珠蛋白结合成血红蛋白并降解为胆红素；ALA合酶催化的是琥珀酰CoA与甘氨酸生成ALA。"},{"q":"PRPP酰胺转移酶活性过高可以导致痛风症，此酶催化","o":["从R-5-P生成PRPP","从甘氨酸合成嘧啶环","从PRPP生成磷酸核糖胺","从IMP合成AMP","从IMP生成GMP"],"a":2,"e":"PRPP酰胺转移酶催化谷氨酰胺的酰胺基取代PRPP上的焦磷酸，生成5-磷酸核糖胺，是嘌呤从头合成的关键步骤。"},{"q":"下列关于rRNA分子的叙述，错误的是","o":["体内含量最多的RNA","真核细胞有4种rRNA","构成核糖体的组分","是体内最不稳定的RNA","原核生物有3种"],"a":3,"e":"体内含量最多的是rRNA，寿命最短、最不稳定的是mRNA；rRNA真核有4种、原核有3种，是核糖体的组成成分。"},{"q":"胰岛素可促进脂肪合成的原因中，不正确的是","o":["可诱导脂酸合成酶的合成","可诱导ATP-柠檬酸裂解酶的合成","可诱导乙酰CoA羧化酶的合成","使乙酰CoA羧化酶磷酸化","促进游离脂肪酸进入脂肪组织"],"a":3,"e":"胰岛素通过激活蛋白磷酸酶使乙酰CoA羧化酶去磷酸化而激活，磷酸化则使其失活，故该表述与事实相反。"},{"q":"在分子生物学技术领域所说的分子克隆是指","o":["建立单克隆抗体","无性繁殖DNA","建立多克隆抗体","构建重组DNA","有性繁殖DNA"],"a":1,"e":"分子克隆即无性繁殖DNA，指将目的DNA片段插入载体后导入受体细胞进行无性繁殖，获得大量相同DNA分子的过程。"},{"q":"以下属于单基因遗传病的有","o":["肥胖","肿瘤","高血压","糖尿病","Duchenne氏肌营养不良"],"a":4,"e":"Duchenne型肌营养不良由抗肌萎缩蛋白基因突变引起，属单基因遗传病；肥胖、肿瘤、高血压和糖尿病均为多基因病。"},{"q":"外显子是指","o":["基因表达中的调控序列","DNA链中的断裂基因","能够被翻译的编码序列","修饰时被剪除","不能转录的序列"],"a":2,"e":"外显子是断裂基因中保留于成熟mRNA并可被翻译的编码序列，内含子在剪接加工时被去除。"},{"q":"研究转录起始点（TSS）的基本方法是","o":["5'RACE","5'SAGE","5'CAGE","报告基因","足迹法"],"a":0,"e":"5′-RACE是基于PCR从低丰度转录本快速扩增cDNA 5′末端的方法，用于确定转录起始点。报告基因指示启动子活性，足迹法分析核酸-蛋白质相互作用。"},{"q":"下列途径与核酸合成关系密切的是","o":["糖酵解","糖异生","糖原合成","磷酸戊糖途径","三羧酸循环"],"a":3,"e":"磷酸戊糖途径生成5-磷酸核糖，为嘌呤、嘧啶核苷酸的从头合成提供核糖原料，故与核酸合成关系最密切。"},{"q":"以下不属于不依赖染色体定位的疾病相关基因克隆策略的是","o":["依据蛋白质氨基酸序列信息鉴定克隆疾病相关基因","用蛋白质特异性抗体鉴定疾病基因","从疾病的表型差异出发发现疾病相关基因","体细胞杂交法鉴定疾病相关基因","采用动物模型鉴定和克隆疾病相关基因"],"a":3,"e":"体细胞杂交法通过分析杂种细胞中染色体丢失与表型关系进行基因定位，属依赖染色体定位的策略。"},{"q":"有维生素C参与的胶原分子中，羟化反应的氨基酸是","o":["甲硫氨酸","谷氨酸","亮氨酸","赖氨酸","精氨酸"],"a":3,"e":"维生素C是胶原脯氨酸羟化酶和赖氨酸羟化酶的辅因子，参与脯氨酸和赖氨酸残基的羟化，促进胶原纤维成熟。"},{"q":"关于酮体的叙述，不正确的是","o":["酮体是肝细胞合成的","酮体的利用主要在肝外组织","酮体合成的原料是乙酰CoA","脑组织不能利用酮体","肝脏不能利用酮体"],"a":3,"e":"脑组织虽不能氧化脂肪酸，却可利用酮体供能，饥饿时酮体是其重要能源，故“脑组织不能利用酮体”错误。"},{"q":"有关乳糖操纵子的描述，以下说法错误的是","o":["别乳糖是阻遏蛋白的诱导剂","分解代谢物基因激活蛋白的结合部位是CAP位点","cAMP不是乳糖操纵子正性调控所必需的","低葡萄糖，高乳糖的时候乳糖操纵子高效表达","乳糖操纵子可以保证细菌优先利用葡萄糖"],"a":2,"e":"CAP须先与cAMP结合才能结合CAP位点并促进RNA聚合酶与启动子结合，故cAMP是乳糖操纵子正性调控所必需；葡萄糖低时cAMP升高，操纵子高效表达。"},{"q":"在体内生成胆汁酸的原料是","o":["胆汁","胆固醇","胆绿素","血红素","胆素"],"a":1,"e":"肝细胞以胆固醇为原料合成初级胆汁酸，这是胆固醇在体内代谢的主要去路；胆汁酸再经肠菌作用生成次级胆汁酸。"},{"q":"关于葡糖激酶说法正确的是","o":["基本上是肌肉中的酶","比其他己糖激酶的Km值高","催化生成F-6-P","可被G-6-P激活","催化葡萄糖与无机磷酸生成G-6-P"],"a":1,"e":"葡糖激酶为肝细胞的己糖激酶Ⅳ型，对葡萄糖亲和力低，Km约10mmol/L，远高于己糖激酶Ⅰ，故血糖升高时才充分发挥作用。"},{"q":"关于糖蛋白生物合成的叙述，错误的是","o":["N-连接型聚糖的合成部位是内质网和高尔基体","N-连接型聚糖的合成与蛋白肽链合成同步进行","O-连接型聚糖的合成在多肽链合成后进行","O-连接型聚糖的合成需要聚糖载体","O-连接型聚糖是在多肽链上逐个加上糖基"],"a":3,"e":"O-连接型聚糖合成不需聚糖载体，而是在GalNAc转移酶催化下将UDP-GalNAc的糖基转移至丝/苏氨酸羟基后逐个延长；需长萜醇载体的是N-连接型。"},{"q":"1,4,5-三磷酸肌醇（IP3）作用是","o":["在细胞内供能","是肌醇的活化形式","是细胞内第二信使","可直接激活蛋白激酶C（PKC）","细胞膜组成成分"],"a":2,"e":"IP3是磷脂酶C水解PIP2生成的细胞内第二信使，作用于内质网促Ca2+释放；直接激活PKC的是DAG。"},{"q":"利用数据库中不同物种间的序列比较分析，拼接，预测新的全长基因等，进而通过实验证实，从组织细胞中克隆该基因的方法称为","o":["电子克隆","定位克隆","细胞克隆","分子克隆","器官克隆"],"a":0,"e":"电子克隆借助生物信息学，将已知序列与数据库中各物种序列比对、拼接，预测全长基因，再经实验验证并从组织细胞中克隆该基因。"},{"q":"关于基因治疗的描述，正确的是","o":["可以使用生殖细胞作为靶细胞","最常用的载体是腺病毒载体","单基因遗传病非常适合进行基因治疗","恶性肿瘤、心脑血管等复杂性疾病不适合进行基因治疗","最为理想的基因治疗方法就是基因增补"],"a":2,"e":"单基因遗传病只受一对等位基因影响，致病基因清楚，基因治疗方案相对容易确定，适合进行基因治疗。生殖细胞基因治疗受伦理限制，目前重点是体细胞治疗。"},{"q":"底物水平磷酸化指","o":["ATP水解为ADP和Pi","底物经分子重排后形成高能磷酸键，经磷酸基团转移使ADP磷酸化为ATP分子","呼吸链上H+传递过程中释放能量使ADP磷酸化为ATP分子","使底物分子加上1个磷酸根","使底物分子水解掉1个ATP分子"],"a":1,"e":"底物水平磷酸化是底物分子重排形成高能磷酸键后，将磷酸基直接转移给ADP生成ATP，与呼吸链无关。"},{"q":"DNA的一级结构实质上就是","o":["DNA分子中的碱基排列顺序","DNA分子中的碱基配对关系","DNA分子中的各碱基所占的比例","DNA分子的双螺旋结构","DNA分子中的碱基种类"],"a":0,"e":"核酸的一级结构指核苷酸从5′-端到3′-端的排列顺序，核苷酸之间的差异仅在碱基，故一级结构也就是碱基序列。"},{"q":"在肝中与胆汁酸结合的化合物有","o":["葡萄糖醛酸","牛磺酸","硫酸","甲酸","S-腺苷甲硫氨酸"],"a":1,"e":"胆汁酸在肝内与甘氨酸或牛磺酸结合生成结合胆汁酸，牛磺酸由半胱氨酸转变而来，结合后水溶性增大更利于排泌。"},{"q":"糖蛋白与蛋白聚糖中的蛋白质与糖之间通过哪种作用方式相连","o":["共价键","氢键","疏水作用","范德华力","离子键"],"a":0,"e":"糖蛋白中聚糖与蛋白质以共价键相连，N-连接型连于天冬酰胺的酰胺氮，O-连接型连于丝氨酸或苏氨酸残基的羟基。"},{"q":"复制中维持DNA单链状态的蛋白质是","o":["RecA","LexA","SSB","DnaB","UvrB"],"a":2,"e":"SSB即单链结合蛋白，与解开的DNA单链结合，防止其重新配对或被降解，维持复制叉的单链状态；DnaB为解旋酶。"},{"q":"有关酶的活性中心的叙述，正确的是","o":["酶的活性中心包括结合基团和催化基团","酶的活性中心是由一级结构上相互邻近的基团组成的","酶的活性中心在与底物结合时不会发生构象改变","所有酶活性中心都含有辅助因子","酶活性中心外的必需基团也参与对底物的催化作用"],"a":0,"e":"酶的活性中心由结合基团和催化基团组成，结合基团识别并专一性结合底物，催化基团催化底物化学键断裂与形成。活性中心外的必需基团仅维持活性中心空间构象，不直接参与催化。"},{"q":"参与胆固醇逆向转运的血浆脂蛋白是","o":["CM","LDL","HDL","VLDL","IDL"],"a":2,"e":"HDL将肝外组织多余胆固醇经血循环转运至肝，转化为胆汁酸排出，此即胆固醇逆向转运，故HDL是其载体。"},{"q":"下列物质合成时，需要谷氨酰胺分子上酰胺基的是","o":["TMP上的2个氮原子","嘌呤环上的2个氮原子","UMP上的2个氮原子","嘧啶环上的2个氮原子","腺嘌呤上的氨基"],"a":1,"e":"嘌呤环的N3和N9来自谷氨酰胺的酰胺氮；甘氨酸、天冬氨酸、一碳单位和CO2提供其余原子。"},{"q":"酶原激活的实质是","o":["酶原结合了辅酶或辅基","酶蛋白发生了别构调节","激活剂与酶结合使酶激活","酶原分子的空间构象发生了变化而一级结构不变","酶原分子一级结构发生改变，从而形成或暴露出酶的活性中心"],"a":4,"e":"酶原激活经蛋白酶水解去除一个或几个肽段，使一级结构改变、空间构象调整，从而形成或暴露活性中心。"},{"q":"链霉素阻断蛋白质生物合成的机制是","o":["与核糖体小亚基结合","与核糖体大亚基结合","阻碍氨基酸-tRNA进入“受位”","抑制转肽酶活性","过早终止多肽链合成"],"a":0,"e":"链霉素与细菌核糖体30S小亚基结合，低浓度即引起读码错误，高浓度抑制蛋白质合成起始；与50S亚基结合并抑制转肽酶的是大环内酯类。"},{"q":"乳糖、阿拉伯糖、色氨酸等小分子物质在基因表达调控中作用的共同特点是","o":["与转录起始位点结合影响模板活性","与RNA聚合酶结合影响其活性","与启动序列结合影响模板活性","与操纵序列结合影响模板活性","与蛋白质结合影响后者结合DNA"],"a":4,"e":"乳糖、阿拉伯糖、色氨酸等小分子作为效应物与阻遏蛋白等调节蛋白结合，改变后者与DNA操纵序列的结合能力，从而调控转录。"},{"q":"可检索已知基因的SNP位点的数据库是","o":["NCBI的dbSNP数据库","NCBI的GEO数据库","SWISS-PROT数据库","LIPID Maps数据库","CCSD数据库"],"a":0,"e":"dbSNP数据库收录人类及多种生物的单核苷酸多态性及其频率、位置等信息，是检索已知基因SNP位点的主要数据库。"},{"q":"在同一种哺乳动物细胞中，理论上叙述正确的是","o":["在过剩的DNA存在下，所有RNA都能与DNA杂交","在过剩的RNA存在下，所有DNA片段能与RNA杂交","RNA与DNA有相同的碱基比例","RNA与DNA有相同核苷酸组成","RNA和DNA含量相同"],"a":0,"e":"细胞内各种RNA均转录自DNA，故DNA过量时每条RNA都能找到互补序列而杂交；DNA含大量非转录序列，不能全部与RNA杂交。"},{"q":"以下不是嘧啶核苷酸分解代谢产物的是","o":["NH3","CO2","β-丙氨酸","β-氨基异丁酸","尿酸"],"a":4,"e":"嘧啶核苷酸分解生成NH3、CO2、β-丙氨酸和β-氨基异丁酸；尿酸是嘌呤核苷酸的分解终产物，与痛风相关。"},{"q":"奇数碳原子脂肪酸分解产生丙酰辅酶A彻底氧化分解时，需首先转变为","o":["琥珀酰辅酶A","酮体","乙酰辅酶A","丙酮酸","苹果酸"],"a":0,"e":"奇数碳脂肪酸β-氧化生成的丙酰CoA，经β-羧化酶及异构酶作用转变为琥珀酰CoA，进入三羧酸循环彻底氧化。"},{"q":"小G蛋白是","o":["G蛋白的亚基","Grb-2结合蛋白","蛋白激酶G","Ras蛋白","Raf蛋白"],"a":3,"e":"Ras蛋白是低分子量GTP结合蛋白，即小G蛋白，活化后结合GTP并可激活MAPKKK，启动MAPK级联。G蛋白的α亚基属异三聚体G蛋白，Grb2为接头蛋白，均非小G蛋白。"},{"q":"在催化反应中不需要模版的酶是","o":["RNA聚合酶","引物酶","DNA聚合酶","端粒酶","DNA拓扑异构酶Ⅰ"],"a":4,"e":"DNA拓扑异构酶Ⅰ切断并重新连接DNA单链，改变超螺旋状态，此过程不需模板；RNA聚合酶、引物酶、DNA聚合酶和端粒酶均需模板。"},{"q":"调节血糖最主要的器官是","o":["肾","脑","肌肉","肾上腺","肝"],"a":4,"e":"肝是调节血糖的主要器官，通过糖原合成与分解、糖异生及其他单糖转化维持血糖相对恒定。"},{"q":"一个利用poly(A)引物制备的肝细胞cDNA文库包含","o":["肝细胞的全部基因信息","肝细胞来源个体的全部基因信息","肝细胞的全部RNA信息","肝细胞来源个体的全部RNA信息","在获取肝细胞时，其所转录的mRNA信息"],"a":4,"e":"以poly(A)为引物、mRNA为模板逆转录构建的cDNA文库，只含取材时该细胞正在转录的mRNA信息，不含内含子及未表达基因的序列。"},{"q":"处方药抗凝血剂华法林，在给出处方前，需要对CYP2C9、VKORC1进行基因检测，该研究属于","o":["药物基因组学","结构基因组学","SNP位点分析","疾病基因组学","转录组学"],"a":0,"e":"药物基因组学研究基因序列变异与药物效应及安全性的关系；CYP2C9、VKORC1基因型影响华法林的代谢与抗凝敏感性，据此调整剂量即属该领域。"},{"q":"与甲硫氨酸、胆碱、脱氧胸苷酸等合成有关的维生素是","o":["维生素B6","维生素B12","维生素C","维生素PP","维生素A"],"a":1,"e":"维生素B12以甲钴胺素形式作为甲硫氨酸合成酶的辅因子，参与甲硫氨酸循环和甲基转移，与胆碱合成、FH4再生及脱氧胸苷酸生成密切相关。"},{"q":"别嘌呤醇治疗痛风的原理是","o":["别嘌呤醇与次黄嘌呤结构类似，可抑制黄嘌呤氧化酶，从而抑制尿酸的生成","降低HGPRT活性，限制嘌呤核苷酸的补救合成","促进尿酸的排泄","增加尿酸的水溶性","促进尿酸的分解"],"a":0,"e":"别嘌呤醇是次黄嘌呤类似物，抑制黄嘌呤氧化酶，减少尿酸生成；其与PRPP生成的别嘌呤核苷酸还可反馈抑制嘌呤合成。"},{"q":"能直接结合氧的细胞色素类是","o":["Cyt b","Cyt a3","Cyt c1","Cyt c","Cyt P"],"a":1,"e":"Cyt a3与CuB组成双核中心，能把电子直接传递给氧分子使其还原为水；其余细胞色素仅承担电子传递。"},{"q":"通过胞内受体发挥作用的信息物质为","o":["乙酰胆碱","γ-氨基丁酸","胰岛素","甲状腺素","表皮生长因子"],"a":3,"e":"甲状腺素为疏水性激素，可透过细胞膜与胞内受体结合，通过激素-受体复合物调节基因表达；乙酰胆碱、胰岛素等作用于膜受体。"},{"q":"必需氨基酸是指","o":["体内合成量少，需由食物供给的氨基酸","合成蛋白质的编码氨基酸","合成蛋白质与核苷酸不可缺少的氨基酸","体内不能合成，需由食物供给的氨基酸","非成糖氨基酸"],"a":3,"e":"必需氨基酸是体内需要但不能自身合成、必须由食物供给的氨基酸，共9种；能合成但合成量不足的精氨酸不属此类。"},{"q":"HDL的生理功能是","o":["转运内源性TG","转运外源性TG","将胆固醇从肝外组织转运至肝","从肝内到肝外组织转运胆固醇","运输自由的脂酸"],"a":2,"e":"HDL主要在肝合成，通过胆固醇逆向转运将肝外组织多余胆固醇运回肝并转化为胆汁酸排出，是唯一逆向转运胆固醇的脂蛋白。"},{"q":"关于关键酶的叙述，哪一项是错误的","o":["关键酶常位于代谢途径的第一步反应","关键酶在代谢途径中活性最低","关键酶常是别构酶","受激素调节的酶常是关键酶","关键酶催化反应是可逆的"],"a":4,"e":"关键酶催化代谢途径中单向、不可逆的限速反应，其活性最低、常为别构酶并受激素调节，多位于途径起始或分叉处；可逆反应由非关键酶催化，不能决定流量。"},{"q":"关于核糖体转肽酶，错误的描述是","o":["转肽酶的化学本质不是蛋白质","转肽酶可以催化两个氨基酸间肽键的形成","活性中心在小亚基","活性中心在大亚基","活性中心与rRNA有关"],"a":2,"e":"转肽酶催化肽键形成，其活性中心位于核糖体大亚基，本质是rRNA构成的核酶，故“活性中心在小亚基”错误。"},{"q":"在人体禁食阶段，脂肪动员释放出来的甘油主要的去向是","o":["在脂肪组织氧化成CO2和H2O","在肝细胞转变成酮体","在脂肪组织合成甘油三酯","在肝细胞合成葡萄糖","在肝细胞氧化成CO2和H2O"],"a":3,"e":"禁食时脂肪动员释放的甘油经血液入肝，在甘油激酶和磷酸甘油脱氢酶作用下生成磷酸二羟丙酮，沿糖异生途径合成葡萄糖。"},{"q":"下列哪种物质仅由肝脏合成","o":["糖原","胆固醇","脂肪酸","血浆蛋白","尿素"],"a":4,"e":"尿素主要在肝细胞经鸟氨酸循环合成，是氨的主要去路；糖原、胆固醇、脂肪酸在肝外组织亦可合成，血浆蛋白虽主要由肝合成但并非仅由肝产生。"},{"q":"营养物质代谢脱下的成对氢原子以还原当量形式存在，再通过多种酶和辅酶催化的氧化还原的连锁反应逐步传递，最终与氧结合成水。在氧化呼吸链中，参与氧化还原作用的酶和辅酶按一定顺序排列在线粒体内膜上。在呼吸链电子传递过程中偶联ATP的生成，这就是氧化磷酸化。1个完整的三羧酸循环中生成的FADH2，在进入氧化磷酸化后可以产生多少ATP","o":["1","1、5","3","4","2"],"a":1,"e":"FADH2经复合体Ⅱ进入呼吸链，只通过复合体Ⅲ、Ⅳ两个质子泵部位，P/O比值约1.5，故1分子FADH2氧化磷酸化生成约1.5分子ATP。"},{"q":"胰高血糖素与相应受体结合激活Gs蛋白后主要引起","o":["激活受体型酪氨酸蛋白激酶","激活非受体型酪氨酸蛋白激酶","激活磷脂酰肌醇特异的磷脂酶C（PI-PLC","激活鸟甘酸环化酶","激活腺苷酸环化酶"],"a":4,"e":"胰高血糖素与受体结合后激活Gs蛋白，进而激活腺苷酸环化酶使ATP生成cAMP，激活蛋白激酶A启动肝糖原分解。受体型酪氨酸蛋白激酶是胰岛素等生长因子受体的信号方式。"},{"q":"关于启动子的叙述，正确的是","o":["mRNA开始被翻译的序列","开始转录生成mRNA的DNA序列","RNA聚合酶开始结合的DNA序列","阻遏蛋白结合DNA的部位","产生阻遏物的基因"],"a":2,"e":"启动子是RNA聚合酶识别、结合并启动转录的一段DNA序列，位于转录起始点上游，决定转录起始的准确性与频率；阻遏蛋白结合的是操纵序列。"},{"q":"只能传递电子的物质是","o":["NAD＋","cyt c","FAD","FMN","CoQ"],"a":1,"e":"Cyt c是单电子传递体，只能传递电子而不传递质子；NAD+、FAD、FMN和CoQ均可传递氢。"},{"q":"N-连接型聚糖的五糖核心为","o":["GlcNAc-GlcNAc-Man-(Man)2","GlcNAc-GalNAc-Man-(Man)2","alNAc-GlcNAc-Man-(Man)2","GalNAc-GalNAc-Man-(Man)2","GlcNAc-GlcNAc-GalNAc-(Man)2"],"a":0,"e":"N-连接型聚糖共有的五糖核心为GlcNAc-GlcNAc-Man-(Man)2，通过N-糖苷键连接于天冬酰胺残基；高甘露糖型、复杂型和杂合型均在此基础上延伸。"},{"q":"别乳糖在乳糖操纵子表达中的作用是","o":["作为辅阻遏物结合阻遏物","作为阻遏物结合操纵序列","作为引物引导聚合反应","使阻遏物变构而失去结合DNA的能力","作为该操纵子结构基因的产物"],"a":3,"e":"别乳糖结合阻遏蛋白使其构象改变，丧失与操纵序列结合的能力，阻遏解除，结构基因得以转录。"},{"q":"AMP分子中第六位碳原子上的氨基来源于","o":["谷氨酰胺的酰胺基","谷氨酸","天冬酰胺的酰胺基","甘氨酸","天冬氨酸"],"a":4,"e":"嘌呤核苷酸从头合成时，AMP C6位氨基由天冬氨酸提供；甘氨酸、谷氨酰胺、一碳单位和CO2参与嘌呤环其他原子的构成。"},{"q":"AUC为异亮氨酸的密码子，tRNA中与其相应的反密码子应为","o":["UAG","TAG","GAU","GAT","LAG"],"a":2,"e":"密码子5'-AUC-3'与反密码子反向互补配对，反密码子按5'→3'书写为GAU。"},{"q":"将标记的核酸探针与细胞或组织中的核酸进行杂交，称为","o":["杂交前处理","预杂交","原位杂交","Northern印迹杂交","免疫印迹"],"a":2,"e":"原位杂交以标记核酸探针直接与细胞涂片或组织切片中的DNA/RNA杂交，通过信号检测对特定序列定位、定性和定量；以荧光素标记者称FISH。"},{"q":"绝大多数真核生物mRNA的5'端有","o":["poly(A)","终止密码","帽子结构","Pribnow盒","起始密码"],"a":2,"e":"真核生物mRNA的5′-端有帽子结构，即7-甲基鸟苷-5-三磷酸通过5′-5′方式与mRNA相连，具有保护mRNA和调控翻译起始的功能；3′-端为多聚腺苷酸尾。"},{"q":"真核生物基因组中没有的是","o":["内含子","外显子","增强子","转录因子","高度重复序列"],"a":3,"e":"转录因子是蛋白质，由基因编码并存在于细胞中，不属于基因组DNA的组成成分。内含子、外显子、增强子和高度重复序列均为基因组DNA序列。"},{"q":"核酸分子杂交可发生在DNA与DNA之间、DNA与RNA之间。可与单链DNA5'-CGGTA-3'发生杂交的RNA是","o":["5'-GCCAU-3'","5'-GCCUU-3'","5'-UACCG-3'","5'-UAGGC-3'","5'-AUCCG-3'"],"a":2,"e":"核酸分子杂交依据碱基互补配对，且两条链方向相反。单链DNA 5'-CGGTA-3'的互补序列为3'-GCCAT-5'，按5'→3'书写即5'-UACCG-3'，与RNA配对时以U代替T。"},{"q":"对原核肽链合成延长的转位步骤叙述，正确的是","o":["卸载tRNA直接从P位分离","转位由延长因子EF-G促进","肽酰-tRNA从P位进入A位","转位过程需水解ATP提供能量","转位后肽酰-tRNA占据E位"],"a":1,"e":"转位由延长因子EF-G即转位酶催化，需GTP水解供能，使肽酰-tRNA由A位移至P位，卸载tRNA进入E位后脱落。"},{"q":"三羧酸循环中底物水平磷酸化产生的高能化合物是","o":["ATP","GTP","CTP","TTP","UTP"],"a":1,"e":"琥珀酰CoA合成酶催化琥珀酰CoA转变为琥珀酸，同时使GDP磷酸化生成GTP，这是三羧酸循环中唯一的底物水平磷酸化反应。"},{"q":"肝脏所特有的代谢反应是","o":["将糖转变为脂肪","由胆固醇转变为胆汁酸","糖异生","生物转化","生物氧化"],"a":1,"e":"肝细胞以胆固醇为原料合成胆汁酸，这是胆固醇在体内最主要的代谢去路，也是肝特有的代谢反应。"},{"q":"维生素K依赖性γ-羧化酶激活凝血因子是使","o":["谷氨酸残基羧化","天冬氨酸残基羧化","酪氨酸残基羧化","组氨酸残基羧化","赖氨酸残基羧化"],"a":0,"e":"维生素K是γ-谷氨酰羧化酶的辅因子，催化凝血因子前体中的谷氨酸残基羧化为γ-羧基谷氨酸，从而获得结合Ca2+的能力。"},{"q":"下列哪种信息分子所激发的信号转导与STAT（信号转导及转录激活因子）关系最密切","o":["心房钠尿肽","甲状旁腺激素","肾上腺素","孕激素","干扰素"],"a":4,"e":"干扰素通过JAK-STAT信号通路发挥作用，STAT为其关键转录因子。瘦素亦经JAK-STAT3转导，而心房钠尿肽经鸟苷酸环化酶、肾上腺素经cAMP、孕激素经核受体途径。"},{"q":"白血病是恶性增殖性疾病，白血病细胞在机体内无限增殖，合成代谢和分解代谢都很旺盛，导致蛋白质和氨基酸代谢紊乱，使机体状况恶化。对白血病人血浆进行代谢组学的分析，以下哪种成分会较正常人低","o":["Glu","Gln","Gly","Phe","Lys"],"a":1,"e":"白血病细胞增殖旺盛，大量摄取并消耗谷氨酰胺作为氮源和能源，血浆谷氨酰胺水平较正常人降低，而其他氨基酸可升高。"},{"q":"可用于基因组DNA分析的方法是","o":["Southern blotting","Northern blotting","Western blotting","斑点杂交","质谱技术"],"a":0,"e":"DNA印迹法（Southern blotting）将电泳分离的DNA转移至硝酸纤维素膜，再用标记探针杂交，可显示50～20000bp片段，用于基因组DNA分析；Northern检测RNA，Western检测蛋白质。"},{"q":"不能利用酮体的细胞是","o":["脑细胞","骨骼肌细胞","心肌细胞","脂肪细胞","肝细胞"],"a":4,"e":"肝细胞有活性很强的酮体合成酶系，却缺乏利用酮体的酶，故肝只能生成酮体而不能利用酮体；脑、骨骼肌、心肌均可利用。"},{"q":"下面关于必需氨基酸的叙述错误的是","o":["食物蛋白质的营养价值取决于其中所含必需氨基酸的有无和多少","人体所需要的氨基酸有8种，其中包括半胱氨酸和酪氨酸","必需氨基酸的必需性可因生理状态而改变","动物的种类不同，其所需要的必需氨基酸也不同","植物含有人体所必需的各种氨基酸，有些氨基酸是人体不能合成的"],"a":1,"e":"人体必需氨基酸为9种，包括亮氨酸、异亮氨酸、苏氨酸、缬氨酸、赖氨酸、甲硫氨酸、苯丙氨酸、色氨酸和组氨酸；半胱氨酸和酪氨酸属非必需氨基酸，可由甲硫氨酸和苯丙氨酸转变生成。"},{"q":"某蛋白在肺癌中高表达，若确定该蛋白在肺癌发生过程中的作用，可采用的方法","o":["Crispr/Cas9","EST序列分析","SNP分析","BLAST分析","SAGE分析"],"a":0,"e":"判定某蛋白在肿瘤发生中的作用需在基因组水平定向敲除或修饰其编码基因，再观察细胞表型改变，CRISPR/Cas9可特异实现该目的。"},{"q":"DNA的生物合成方向是","o":["3'→5'","C→N","5'→3'","N→C","从两侧向中心"],"a":2,"e":"DNA生物合成方向为5′→3′，新链沿此方向延伸，与模板链反向平行。RNA合成方向亦为5′→3′，核苷酸间以3′，5′-磷酸二酯键连接。"},{"q":"使细胞内环化腺苷酸（cAMP）水平升高的因素有","o":["蛋白激酶A","磷酸二脂酶","磷脂酶C","腺苷酸环化酶","蛋白激酶C"],"a":3,"e":"腺苷酸环化酶催化ATP环化生成cAMP，是使细胞内cAMP水平升高的酶；磷酸二酯酶则水解cAMP使其降低。"},{"q":"基因组代表一个细胞或生物体的","o":["整套遗传信息","部分遗传信息","可转录基因","非转录基因","可表达基因"],"a":0,"e":"基因组是指生物体或细胞中一套完整遗传信息的总和，全部遗传信息均贮存于基因组中。"},{"q":"当肝功能严重受损时，合成及释入血中的LCAT降低，因此血中将出现","o":["胆固醇总量降低","游离胆固醇量降低","游离胆固醇占总胆固醇的比例降低","胆固醇酯占总胆固醇的比例降低","胆固醇酯占总胆固醇的比例升高"],"a":3,"e":"LCAT由肝合成释入血浆，催化卵磷脂C2位脂酰基转移至游离胆固醇生成胆固醇酯；肝严重受损时LCAT减少，酯化受阻，胆固醇酯占总胆固醇比例下降。"},{"q":"稀有核苷酸一般存在于","o":["tRNA","mRNA","rRNA","线粒体DNA","核仁DNA"],"a":0,"e":"tRNA中稀有碱基占所有碱基的10%～20%，且均为转录后修饰而成，故稀有核苷酸主要存在于tRNA。"},{"q":"缺氧情况下，糖酵解途径生成的NADH和H+的去路是","o":["进入呼吸链氧化供应能量","丙酮酸还原为乳酸","3-磷酸甘油酸还原为3-磷酸甘油醛","醛缩酶的辅助因子合成1，6-双磷酸果糖","醛缩酶的辅助因子分解1，6-双磷酸果糖"],"a":1,"e":"缺氧时糖酵解第6步生成的NADH+H+不由呼吸链氧化，而是经乳酸脱氢酶将丙酮酸还原为乳酸，使NAD+再生以保证糖酵解继续。"},{"q":"能被甲氨蝶呤拮抗的维生素是","o":["硫胺素","维生素A","叶酸","生物素","核黄素"],"a":2,"e":"甲氨蝶呤是叶酸类似物，竞争性抑制二氢叶酸还原酶，使FH4生成减少，一碳单位供应不足，从而抑制胸腺嘧啶核苷酸及嘌呤核苷酸的合成。"},{"q":"关于核酶，下列描述不正确的是","o":["可催化特定的RNA降解","在研究rRNA的自剪接过程中发现的","具有酶活性的RNA分子","是核酸与蛋白质共同组成的酶","于20世纪80年代发现"],"a":3,"e":"核酶是具有催化活性的RNA分子，20世纪80年代在研究rRNA自我剪接时发现，可催化特定RNA降解，其化学本质是RNA而非核酸与蛋白质的复合物。"},{"q":"下列哪种物质，抑制电子从Cyt a3到氧之间的传递","o":["鱼藤酮","2,4-二硝基苯酚","抗毒素","寡毒素","一氧化碳"],"a":4,"e":"一氧化碳与复合体Ⅳ中氧化型Cyt a3紧密结合，阻断电子由Cyt a到CuB-Cyt a3的传递，即抑制Cyt a3到氧之间的传递。抗霉素A抑制复合体Ⅲ，鱼藤酮抑制复合体Ⅰ。"},{"q":"能通过线粒体内膜的物质有","o":["苹果酸","α-磷酸甘油","谷氨酰胺","草酰乙酸","琥珀酸"],"a":0,"e":"苹果酸可经线粒体内膜的苹果酸-α-酮戊二酸转运体进出线粒体，而草酰乙酸、乙酰CoA等不能自由通过内膜。"},{"q":"终产物不是尿酸的是","o":["AMP","UMP","IMP","GMP","ATP"],"a":1,"e":"嘧啶核苷酸分解产物为NH3、CO2、β-丙氨酸和β-氨基异丁酸，均易溶于水；尿酸是嘌呤核苷酸分解的终产物。"},{"q":"tRNA分子上3′端序列的功能是","o":["稳定tRNA分子","提供3'-羟基与氨基酸结合","形成局部双链","识别mRNA分子","便于翻译蛋白质"],"a":1,"e":"tRNA氨基酸臂的-CCA末端腺苷酸3′-OH是氨基酸结合部位，可与氨基酸结合形成氨酰tRNA。识别mRNA的是反密码环中的反密码子。"},{"q":"下列哪种RNA不需要在细胞核内进一步加工修饰","o":["pre-tRNA","mRNA","pre-rRNA","hnRNA","pri-miRNA"],"a":1,"e":"真核生物mRNA的前体hnRNA需在细胞核内进行首尾修饰和剪接加工；pre-tRNA、pre-rRNA、pri-miRNA同样需核内加工。mRNA即成熟信使RNA，已是加工产物。"},{"q":"可产生五碳糖的途径是","o":["磷酸戊糖途径","糖酵解","糖异生","糖有氧氧化","糖原代谢"],"a":0,"e":"磷酸戊糖途径生成5-磷酸核糖和NADPH，是体内产生五碳糖的主要途径；糖酵解、有氧氧化和糖异生不直接生成五碳糖。"},{"q":"在代谢的研究中，第一个被阐明的循环途径是","o":["鸟氨酸循环","三羧酸循环","丙氨酸-葡萄糖循环","Cori循环","尿素的肠肝循环"],"a":0,"e":"1932年Krebs和Henseleit根据肝切片实验提出鸟氨酸循环学说，即尿素循环，是代谢研究中第一个被阐明的循环途径。"},{"q":"在生理pH情况下，下列氨基酸的混合物在电场中有多种氨基酸向正极移动，其中移动最快的是","o":["Pro","Lys","His","Glu","Gly"],"a":3,"e":"谷氨酸含两个羧基，pI约3.22，在生理pH下带较多负电荷，向正极泳动最快；赖氨酸、组氨酸带正电荷，向负极移动。"},{"q":"脂蛋白脂肪酶催化","o":["脂肪细胞中甘油三酯的水解","肝细胞中甘油三酯的水解","VLDL中甘油三酯的水解","HDL中甘油三酯的水解","Lp(a)中的甘油三酯的水解"],"a":2,"e":"脂蛋白脂肪酶位于毛细血管内皮细胞表面，水解CM和VLDL中的甘油三酯，释放甘油和游离脂肪酸供组织摄取。"},{"q":"谷胱甘肽过氧化物酶中含有的微量元素是","o":["铬","锌","锰","硒","铜"],"a":3,"e":"谷胱甘肽过氧化物酶是含硒的抗氧化酶，以硒代半胱氨酸形式存在于活性中心，催化H2O2和过氧化物还原。"},{"q":"假设目的基因插入载体lacZ基因内，利用α互补筛选转化子细胞，其阳性菌落应为","o":["白色","红色","蓝色","绿色","黄色"],"a":0,"e":"目的基因插入lacZ基因后使其失活，不能产生有活性的β-半乳糖苷酶分解X-gal，故重组菌落呈白色。"},{"q":"关于真核细胞RNA的叙述，错误的是","o":["mRNA主要存在于细胞质中","tRNA分子中的稀有碱基是转录后修饰而成的","有mRNA、tRNA、rRNA三种","mRNA中含有遗传密码","rRNA在细胞内含量最多"],"a":2,"e":"真核细胞除mRNA、rRNA和tRNA外，还含snRNA、miRNA和lncRNA等非编码RNA，故RNA并非仅三种。mRNA携带遗传密码并主要在细胞质中翻译，tRNA稀有碱基由转录后修饰生成，rRNA含量最多。"},{"q":"下列对于突变的描述正确的是","o":["都是由有害因素引起的有害结果","反映遗传的保守性","自然突变频率很低，可以忽略","一定会引起功能受损","是进化的基础"],"a":4,"e":"基因突变是DNA序列的随机改变，可产生遗传多样性，为生物进化提供分子基础；多数突变中性或有害，自然突变频率虽低但不可忽略。"},{"q":"1'-焦磷酸-5'-磷酸核糖（PRPP）不参与的反应是","o":["由腺嘌呤转变为腺苷酸","由鸟嘌呤转变为鸟苷酸","由次黄嘌呤转变为次黄苷酸","乳清酸的生成","嘧啶生物合成中乳清酸核苷酸的生成"],"a":3,"e":"乳清酸由氨基甲酰磷酸经多步反应生成，此过程不需PRPP；PRPP参与其后乳清酸核苷酸的生成及嘌呤补救合成。"},{"q":"下列有关水溶性维生素的叙述哪项是对的","o":["不易溶于水，吸收难","体内储存量较大","摄入量超过机体饱和程度，即导致相应维生素中毒","它们多是构成酶的辅基或辅酶成分","不需要经常摄入"],"a":3,"e":"水溶性维生素在体内主要构成酶的辅因子，包括B族维生素和维生素C。水溶性维生素易溶于水、体内储存少、需经常摄入，过量一般随尿排出而不易中毒。"},{"q":"1969年，哈里斯将癌细胞与同种正常成纤维细胞融合，所获杂种细胞的后代，只要保留某些正常亲本染色体时就可表现为正常表型，但是随着染色体的丢失又可重新出现恶变细胞。这一现象表明，正常染色体内可能存在某些抑制肿瘤发生的基因，它们的丢失、突变或失去功能，使激活的癌基因发挥作用而致癌。这些基因为抑癌基因。关于抑癌基因的叙述，正确的是","o":["具有抑制细胞增殖的作用","与癌基因的表达无关","缺失与细胞增殖和分化无关","不存在于人类正常细胞","在所有肿瘤细胞正常表达"],"a":0,"e":"抑癌基因对细胞增殖起负性调控作用，其编码产物抑制细胞周期推进或促进凋亡，功能丧失后细胞增殖失去约束。"},{"q":"下列物质在体内彻底氧化时，生成ATP最多的是","o":["3分子葡萄糖","1分子硬脂酸","6分子甘油","6分子丙酮酸","9分子乙酰CoA"],"a":1,"e":"1分子硬脂酸（18C）彻底氧化净生成120分子ATP，远多于其他各项。3分子葡萄糖净生成90～96分子ATP，6分子丙酮酸生成75分子ATP，9分子乙酰CoA生成90分子ATP。"},{"q":"蛋白质生物合成中肽链延长所需要的能量来源于","o":["ATP","GTP","GDP","UTP","CTP"],"a":1,"e":"肽链延长阶段每生成一个肽键，进位与转位各水解1分子GTP，共消耗2个高能磷酸键，故延长所需能量由GTP提供；ATP用于氨基酸活化。"},{"q":"白化病是由哪种酶缺陷造成","o":["苯丙氨酸转氨酶","酪氨酸酶","苯丙氨酸羟化酶","苯丙酮酸脱氢酶","酪氨酸羟化酶"],"a":1,"e":"酪氨酸酶催化酪氨酸羟化为多巴并最终生成黑色素，该酶先天缺乏时不能合成黑色素，故患白化病。"},{"q":"蛋白质生物合成中多肽链的氨基酸排列顺序取决于","o":["相应tRNA中的核苷酸排列顺序","相应氨酰-tRNA合成酶的专一性","相应tRNA上的反密码子","相应mRNA中核苷酸排列顺序","相应rRNA的专一性"],"a":3,"e":"mRNA可读框中从5′-端到3′-端排列的核苷酸顺序决定肽链从N-端到C-端的氨基酸排列顺序。tRNA反密码子仅按密码子配对运载氨基酸，不决定序列。"},{"q":"蛋白质的一级结构是指","o":["N端到C端氨基酸残基的排列顺序","C端到N端氨基酸残基的排列顺序","多肽链的形状和大小","氨基酸种类的数目","分子中的共价键"],"a":0,"e":"蛋白质一级结构指多肽链中氨基酸自N端至C端的排列顺序，由肽键连接，是空间构象和生物学功能的基础。"},{"q":"血液中的葡萄糖称为血糖。由于颗粒小，拥有良好的生物活性，易于透过人体血脑屏障，体内各组织细胞活动所需的能量大部分来自葡萄糖，所以血糖必须保持一定的水平才能维持体内各器官和组织的需要。葡萄糖进入肌肉细胞后不可以进行的代谢是","o":["糖异生","糖原合成","有氧氧化","糖酵解","进行乳酸循环"],"a":0,"e":"肌组织缺乏葡萄糖-6-磷酸酶，也缺乏糖异生关键酶，故不能进行糖异生，肌糖原分解产物只能供肌自身利用。"},{"q":"降低血糖的激素是","o":["胰高血糖素","肾上腺素","甲状腺素","胰岛素","肾上腺皮质激素"],"a":3,"e":"胰岛素由胰岛β细胞分泌，促进肌和脂肪组织摄取葡萄糖并加速糖原合成，是体内唯一降低血糖的激素。"},{"q":"内质网软脂酸碳链加长所需二碳单位供体为","o":["乙酰CoA","丁酰CoA","丙二酰CoA","乙酰乙酰CoA","羟甲基戊二酸单酰CoA"],"a":2,"e":"内质网脂肪酸延长酶体系以丙二酰CoA为二碳单位供体，NADPH供氢，脂酰基连于CoA而非ACP，每轮缩合、还原、脱水、再还原延长2个碳原子。"},{"q":"Ⅰ型高脂蛋白血症患者空腹血浆","o":["CM升高","VLDL升高","LDL升高","VLDL及LDL升高","CM及VLDL升高"],"a":0,"e":"Ⅰ型脂蛋白异常血症由脂蛋白脂肪酶缺陷使乳糜微粒清除障碍所致，空腹血浆以CM升高为主，甘油三酯显著升高。"},{"q":"结合RNA聚合酶并启动转录的DNA序列是","o":["启动子","操纵子","增强子","沉默子","衰减子"],"a":0,"e":"启动子是依赖DNA的RNA聚合酶识别、结合并启动转录的一段DNA序列，一般位于转录起始点上游。操纵子是原核生物基因表达调控单位，增强子、沉默子为调控序列。"},{"q":"DNA对哪一波长紫外光具有强烈的吸收","o":["220nm","240nm","260nm","280nm","300nm"],"a":2,"e":"碱基、核苷、核苷酸和核酸在中性条件下最大吸收峰均在260nm附近，据此可对核酸定量。280nm为蛋白质吸收峰，220nm与240nm非核酸特征吸收波长。"},{"q":"催化软脂酸碳链延长的酶系存在于","o":["细胞质","细胞质膜","线粒体","溶酶体","高尔基复合体"],"a":2,"e":"软脂酸碳链延长在内质网和线粒体进行，线粒体途径以乙酰CoA为二碳单位供体，经缩合、还原、脱水、再还原延长碳链。"},{"q":"N-连接型聚糖的糖基化位点为","o":["Asp-X-Ser/Thr","Asn-X-Ser/Thr","Gln-X-Ser/Thr","Glu-X-Ser/Thr","Asn-X-Thr/Tyr"],"a":1,"e":"N-连接型聚糖与天冬酰胺残基的酰胺氮共价相连，其糖基化位点为Asn-X-Ser/Thr序列子。"},{"q":"参与形成蛋白质一级结构的化学键有","o":["二硫键、氢键","疏水键、氢键","范德华力、肽键","肽键、二硫键","氢键、盐键"],"a":3,"e":"一级结构中氨基酸的排列顺序由肽键维系，二硫键的位置同属一级结构范畴，氢键、疏水键等维系高级结构。"},{"q":"真核细胞DNA复制发生在细胞周期的","o":["G1期","S期","G2期","M期","G0期"],"a":1,"e":"真核染色体DNA复制只出现于细胞周期的S期，且每个复制起点在每个周期只激活一次，该激活受CDK2严格调控。"},{"q":"最常用的从cDNA文库中筛选含目的基因的克隆方法是","o":["核酸分子杂交法","免疫筛选法","蛋白质功能测定筛选法","PCR法","Western Blotting法"],"a":0,"e":"从cDNA文库筛选含目的基因的克隆最常用核酸分子杂交法，即以标记探针与菌落或噬斑影印膜进行原位杂交；免疫筛选须有表达产物及相应抗体，适用面较窄。"},{"q":"两段DNA序列非常相似时，下列描述正确的是","o":["来自同一物种","具有相似的功能","编码产物相似","可能功能差异很大","基因组中的重复序列"],"a":3,"e":"两段DNA序列非常相似并不意味功能相同，序列相似程度与功能相关性并不等同，相似序列可能因调控元件或编码区的差异而功能差异很大。"},{"q":"下列关于RNA和DNA聚合酶的叙述，正确的是","o":["RNA聚合酶用二磷酸核苷合成多核苷酸链","RNA聚合酶需要引物，并在延长链的5'端加接碱基","DNA聚合酶可在链的两端加接核苷酸","仅能以DNA为模板合成DNA或RNA","所有RNA聚合酶和DNA聚合酶只能在生长中的多核苷酸链的3'端加接核苷酸"],"a":4,"e":"DNA聚合酶与RNA聚合酶均只能催化核苷酸加合到生长链的3′-OH末端，故链的延长方向为5′→3′。"},{"q":"自然界游离核苷酸中的磷酸最常位于","o":["戊糖的C-2'上","戊糖的C-3'上","戊糖的C-5'上","戊糖的C-2'及C-3'","戊糖的C-2'及C-5'上"],"a":2,"e":"生物体内游离存在的核苷酸多为5′-核苷酸，即磷酸与戊糖C-5′原子上的羟基酯化生成。"},{"q":"生物素是哪个酶的辅酶","o":["丙酮酸脱氢酶","丙酮酸羧化酶","烯醇化酶","醛缩酶","磷酸烯醇式丙酮酸羧激酶"],"a":1,"e":"生物素是丙酮酸羧化酶、乙酰CoA羧化酶等羧化酶的辅因子，参与CO2固定；丙酮酸羧化酶仅存在于线粒体，催化丙酮酸羧化为草酰乙酸。"},{"q":"影响离子通道开关的配体主要是","o":["神经递质","类固醇激素","生长因子","无机离于","甲状腺素"],"a":0,"e":"配体门控离子通道的配体主要为神经递质，通道开放或关闭直接受化学配体控制，N型乙酰胆碱受体即典型代表。类固醇激素、甲状腺素属细胞内受体配体，生长因子作用于酶偶联受体。"},{"q":"关于丝氨酸在体内的生物转化过程，下列哪个说法是错误的","o":["丝氨酸可在羟甲基转移酶的作用下转化生成N5,N10-甲烯四氢叶酸和甘氨酸","丝氨酸可以转化生成丙酮酸，并进一步彻底氧化分解","丝氨酸可以与CDP-甘油二酯直接缩合生成磷脂酰丝氨酸","丝氨酸可以脱羧生成乙醇胺，并进一步生物转化合成磷脂酰乙醇胺","丝氨酸可以在氨基甲酰磷酸合成酶Ⅱ的作用下转化生成氨基甲酰磷酸，并进一步生成嘧啶"],"a":4,"e":"嘧啶合成所需氨基甲酰磷酸由CPSⅡ在细胞质中以谷氨酰胺为氮源催化生成，其氮源并非丝氨酸，丝氨酸不通过CPSⅡ转化为氨基甲酰磷酸。"},{"q":"肾脏中产生的氨主要来自","o":["胺的氧化","氨基酸的联合脱氨基","氨基酸的氧化脱氨基","谷氨酰胺的水解","尿素的水解"],"a":3,"e":"肾小管上皮细胞分泌的氨主要来自谷氨酰胺，经谷氨酰胺酶水解生成谷氨酸和氨，氨与尿中H+结合成铵盐排出，对调节酸碱平衡有重要作用。"},{"q":"催化转录产生snRNA的酶是","o":["RNA聚合酶Ⅰ","RNA聚合酶Ⅱ","RNA聚合酶Ⅲ","RNA聚合酶核心酶","RNA聚合酶全酶"],"a":2,"e":"真核RNA聚合酶Ⅲ负责转录tRNA、5S rRNA及snRNA等小分子RNA；聚合酶Ⅰ生成rRNA前体，聚合酶Ⅱ生成mRNA前体。"},{"q":"有关竞争性抑制剂的叙述，错误的是","o":["与底物结构相似","与酶的活性中心相结合","抑制程度与[S]和[I]有关","增加底物浓度可解除抑制","与酶共价结合"],"a":4,"e":"竞争性抑制剂与底物结构相似，以非共价键竞争结合酶活性中心，增加底物浓度可解除抑制；与酶共价结合是不可逆抑制的特征。"},{"q":"下列哪个因素不会破坏蛋白质的空间构象","o":["盐析","加热","酸碱","β-巯基乙醇","重金属盐"],"a":0,"e":"盐析仅中和蛋白质表面电荷并破坏水化膜，不破坏其空间构象；加热、酸碱、重金属盐和β-巯基乙醇均可引起变性。"},{"q":"环腺苷酸（cAMP）激活依赖cAMP蛋白激酶的作用方式是","o":["cAMP与蛋白激酶的活性中心结合","cAMP与蛋白激酶活性中心外的必需基团结合","cAMP使蛋白激酶磷酸化","cAMP与蛋白激酶的调节亚基结合，使其与催化亚基解离","cAMP使蛋白激酶去磷酸化"],"a":3,"e":"cAMP与PKA的调节亚基结合使其变构，释放出游离的催化亚基，从而激活蛋白激酶，并非直接结合活性中心。"},{"q":"作为基因治疗靶细胞，具有高度自我更新和分化能力的是","o":["造血干细胞","成纤维细胞","生殖细胞","肌细胞","癌细胞"],"a":0,"e":"造血干细胞具有高度自我更新能力，可进一步分化为各系血细胞并保持基因组DNA稳定，是基因治疗最有前途的靶细胞，脐带血为其丰富来源。"},{"q":"1分子氨基酸活化为氨酰-tRNA，消耗高能键数为","o":["1","2","3","4","5"],"a":1,"e":"氨酰-tRNA合成酶催化氨基酸与tRNA结合时，ATP分解为AMP和焦磷酸，消耗2个高能磷酸键，产物为氨酰-tRNA、AMP和PPi。"},{"q":"糖酵解进行的部位是在细胞的","o":["线粒体基质","细胞质中","内质网膜上","细胞核内","线粒体基质和细胞质中"],"a":1,"e":"糖酵解指一分子葡萄糖在细胞质中裂解为两分子丙酮酸，是葡萄糖无氧氧化和有氧氧化的共同起始途径，其全部反应均在细胞质中进行。"},{"q":"长期饥饿时大脑的能量来源主要是","o":["葡萄糖","氨基酸","甘油","酮体","糖原"],"a":3,"e":"长期饥饿4～7天后酮体生成显著增加，脑利用酮体供能超过葡萄糖，成为主要能源，以减少葡萄糖消耗。"},{"q":"紫外线辐射造成的DNA损伤最易形的二聚体是","o":["CC","TT","TC","AU","CU"],"a":1,"e":"紫外线使同一条链上相邻的两个胸腺嘧啶以共价键连接，形成胸腺嘧啶二聚体（TT），也可形成CT、CC二聚体。"},{"q":"G蛋白是指","o":["蛋白激酶A","鸟苷酸环化酶","蛋白激酶G","Grb-2结合蛋白","鸟苷酸结合蛋白"],"a":4,"e":"G蛋白即鸟苷酸结合蛋白，结合GTP时为活化构象、结合GDP时为失活构象，在跨膜信号转导中起分子开关作用。"},{"q":"食品中的添加剂，色素等作为外源性非营养物质经生物转化后","o":["极性增加，利于排泄","极性减小，利于排泄","分子以原形排泄","极性增加，易于肠肝循环","极性减小，易于肠肝循环"],"a":0,"e":"生物转化增加非营养物质的极性和水溶性，使其易于随尿或胆汁排出；脂溶性物质才需转化，转化后并不增强肠肝循环。"},{"q":"核糖体“受位”的功能是","o":["催化肽键生成","从tRNA水解新生肽链","转肽","接受新进位的氨酰-tRNA","活化氨基酸"],"a":3,"e":"核糖体A位即氨酰位，功能是接受新进位的氨酰-tRNA；P位结合肽酰-tRNA，E位排出已卸载的tRNA。"},{"q":"蛋白质的一级结构及高级结构取决于","o":["分子中的氢键","分子中的盐键","分子内部疏水键","氨基酸的组成及排列顺序","氨基酸残基的性质"],"a":3,"e":"蛋白质一级结构即氨基酸的组成与排列顺序，它决定肽链折叠形成的二级、三级乃至四级结构，故高级结构最终由一级结构决定。"},{"q":"蛋白质变性是由于","o":["蛋白质空间构象的破坏","蛋白质亚基的解聚","蛋白质的水解","蛋白质一级结构的改变","辅基的脱落"],"a":0,"e":"蛋白质变性是物理化学因素破坏二硫键和非共价键，使特定空间构象变为无序，导致理化性质改变和生物学活性丧失，一级结构氨基酸序列不变。"},{"q":"1分子乙酰CoA经三羧酸循环氧化后的产物是","o":["草酰乙酸","草酰乙酸和CO2","CO2+H2O","草酰乙酸+CO2+H2O","2CO2+4分子还原当量+GTP"],"a":4,"e":"1分子乙酰CoA经三羧酸循环4次脱氢、2次脱羧，生成2分子CO2、3分子NADH、1分子FADH2及1分子GTP，中间产物量不变。"},{"q":"DNA分子中G+C含量越高","o":["解链越容易","氢键破坏所需要温度越高","50%复性时需要的温度越高","信息含量越丰富","50%变性时需要的温度越低"],"a":1,"e":"DNA的Tm值与GC含量正相关，GC含量越高，双链间氢键越多，解链所需温度越高，故氢键破坏所需温度越高。"},{"q":"当肝细胞内ATP/AMP降低时，下列叙述错误的是","o":["丙酮酸激酶激活","磷酸果糖激酶-1激活","丙酮酸脱氢酶复合体激活","磷酸果糖激酶-2激活","丙酮酸羧化酶激活"],"a":4,"e":"能荷降低时磷酸果糖激酶-1、丙酮酸激酶被激活，糖酵解加快；丙酮酸羧化酶由乙酰CoA别构激活、属糖异生关键酶，不会因ATP/AMP降低而激活。"},{"q":"在线粒体中，脂肪酸碳链延长的原料是","o":["丙二酰CoA","乙酰CoA","既用乙酰CoA，也用丙二酰CoA","一碳单位","甘油"],"a":1,"e":"线粒体脂肪酸延长酶体系以乙酰CoA为二碳单位供体，经缩合、还原、脱水、再还原使碳链延长；内质网途径才以丙二酸单酰CoA为供体。"},{"q":"下列关于质粒的描述中，作为克隆载体最基本的原因是","o":["小型环状双链DNA分子","有一定遗传标志","在细胞分裂时恒定地传给子代细胞","具有自我复制能力","有多克隆位点"],"a":3,"e":"质粒是细菌染色体外能自主复制和稳定遗传的双链环状DNA，具有自我复制能力是其作为克隆载体的最基本条件。"},{"q":"DNA分子与RNA分子具有很多不同的特点。但它们共同的特点是","o":["电泳时移向正极","是线性单链分子","是线性双链分子","通常在序列中A与T浓度相等","含有脱氧胸苷"],"a":0,"e":"DNA和RNA的磷酸基团在生理pH下解离带负电荷，电泳时均向正极移动；DNA为双链、RNA多为单链，碱基组成也不同。"},{"q":"肝脏生成乙酰乙酸的直接前体是","o":["β-羟丁酸","乙酰乙酰CoA","丙酮酸","甲羟戊酸","羟甲基戊二酸单酰CoA"],"a":4,"e":"两分子乙酰CoA缩合生成乙酰乙酰CoA，再与一分子乙酰CoA缩合成HMG-CoA，后者经HMG-CoA裂解酶作用生成乙酰乙酸，故HMG-CoA是直接前体。"},{"q":"α地中海贫血主要是由于α珠蛋白基因缺失，使α珠蛋白链的合成受到抑制而引起的溶血性贫血。对这种α珠蛋白基因缺失进行快速检测的首选方法是","o":["Northern印迹","PCR","反向斑点杂交","变性高效液相色谱","DNA指纹技术"],"a":1,"e":"PCR及衍生技术可快速检测样品中微量、序列已知的基因片段，α珠蛋白基因缺失属序列已知的缺失突变，故PCR是快速检测的首选方法。裂口PCR可跨越缺失断裂点，以扩增片段大小直接判断缺失。"},{"q":"有机磷杀虫剂对胆碱酯酶的抑制作用属于","o":["不可逆性抑制作用","可逆性抑制作用","竞争性抑制作用","反竞争性抑制作用","非竞争性抑制作用"],"a":0,"e":"有机磷农药与胆碱酯酶活性中心丝氨酸残基羟基共价结合，使酶永久失活，属不可逆性抑制；可逆性抑制可经透析去除抑制剂而恢复活性。"},{"q":"胆固醇生物合成不需要","o":["乙酰CoA","NADPH","ATP","HMG-CoA还原酶","HMG-CoA裂解酶"],"a":4,"e":"胆固醇合成以乙酰CoA为原料，经HMG-CoA还原酶催化生成甲羟戊酸，需NADPH和ATP；HMG-CoA裂解酶参与酮体生成而不参与胆固醇合成。"},{"q":"不是由RNA poll催化转录生成的rRNA是","o":["5、8rRNA","16rRNA","18rRNA","28rRNA","45rRNA"],"a":1,"e":"真核生物RNA聚合酶Ⅰ转录45S rRNA前体，加工为18S、5.8S和28S rRNA；16S rRNA是原核生物核糖体小亚基组分。"},{"q":"抗霉素A对呼吸链（电子传递链）抑制的作用点位于","o":["NADH脱氢酶附近","细胞色素b附近","细胞色素氧化酶","偶联ATP的生成","琥珀酸脱氢酶附近"],"a":1,"e":"抗霉素A阻断复合体Ⅲ中电子由Cyt b向QN的传递，故作用点位于细胞色素b附近，属复合体Ⅲ的抑制剂。"},{"q":"某DNA分子中胸腺嘧啶的含量为20%，则胞嘧啶的含量应为","o":["20%","30%","40%","60%","80%"],"a":1,"e":"双链DNA中A与T配对、G与C配对，故A=T=20%，G+C=60%，胞嘧啶与鸟嘌呤各占30%。"},{"q":"关于端粒酶的叙述，不正确的是","o":["端粒酶具有逆转录酶的活性","端粒酶是DNA与蛋白质的复合物","可维持真核生物DNA的完整性","端粒酶可提供催化时所需模板","端粒酶的催化机制为爬行模型"],"a":1,"e":"端粒酶由端粒酶RNA、端粒酶协同蛋白1和逆转录酶三部分组成，属RNA与蛋白质的复合物，以自身RNA为模板逆转录合成端粒DNA，维持染色体末端完整。"},{"q":"cAMP可通过哪种酶发挥作用","o":["丙酮酸激酶","蛋白激酶","己糖激酶","脂肪酸硫激酶","磷酸化酶激酶"],"a":1,"e":"cAMP作为第二信使与蛋白激酶A调节亚基结合，使催化亚基释放而活化，再磷酸化多种代谢酶，实现激素信号的级联放大。"},{"q":"Cori循环之所以是单向的，是因为","o":["肌细胞内葡萄糖浓度总是较血糖低","肌肉内没有果糖双磷酸酶-1","肝内不进行糖酵解","肝有葡萄糖-6-磷酸酶，肌肉没有","由于缺少相应的运输载体"],"a":3,"e":"肝内存在葡萄糖-6-磷酸酶，可将葡萄糖-6-磷酸水解为葡萄糖释入血；肌组织缺乏此酶，肌内生成的乳酸不能异生为葡萄糖，故乳酸循环呈单向。"},{"q":"鸟氨酸氨甲酰转移酶催化下述哪种反应","o":["鸟氨酸的合成反应","鸟氨酸转变成精氨酸","精氨酸的水解反应","瓜氨酸转变成精氨酸","鸟氨酸转变成瓜氨酸"],"a":4,"e":"鸟氨酸氨甲酰转移酶位于肝细胞线粒体，催化氨基甲酰磷酸的氨基甲酰基转移至鸟氨酸，生成瓜氨酸和磷酸，是尿素合成的第二步。"},{"q":"真核生物体在不同发育阶段，蛋白质的表达谱也发生变化是由于","o":["特异转录因子的差异","基本转录因子的差异","翻译起始因子的差异","衰减子的差异","核心启动子的差异"],"a":0,"e":"特异转录因子为个别基因转录所必需，决定基因表达的时间与空间特异性，其差异导致不同发育阶段表达谱改变。"},{"q":"原癌基因产物不包括","o":["细胞外生长因子","跨膜生长因子受体","细胞内信号转导体","儿茶酚胺类激素","核内转录因子"],"a":3,"e":"原癌基因产物包括细胞外生长因子、跨膜生长因子受体、细胞内信号转导分子和核内转录因子；儿茶酚胺类激素属神经递质，不是其产物。"},{"q":"由鸦片促黑皮质素原（POMC）水解加工生成的物质是","o":["胰岛素","糖蛋白","脂蛋白","ACTH","cAMP"],"a":3,"e":"阿黑皮素原经肽酶水解可生成促肾上腺皮质激素、β-促脂解素、β-内啡肽、促黑激素等多种活性肽，ACTH即其中之一。"},{"q":"维生素B1的生理功能是","o":["增加胆碱酯酶活性","构成转氨酶的辅酶","参与糖代谢过程中的氧化脱羧反应","促进肝脏凝血酶原的合成","参与氧化呼吸链氢的传递"],"a":2,"e":"维生素B1的活性形式TPP是α-酮酸氧化脱羧酶复合体的辅因子，参与丙酮酸和α-酮戊二酸的氧化脱羧，缺乏时引起脚气病。"},{"q":"常规PCR反应体系不含","o":["模板DNA","引物","ddNTP","合适的缓冲液体系","耐热的TaqDNA聚合酶"],"a":2,"e":"常规PCR体系由模板DNA、引物、dNTP、缓冲液和耐热DNA聚合酶组成，ddNTP是测序反应中使链延伸终止的底物。"},{"q":"与原核生物DNA复制比较，真核生物DNA复制特点的描述，正确的是","o":["RNA引物较长","冈崎片段较短","添加新的碱基需要由ATP供给能量","在复制单位中，DNA链的延长速度较慢","仅有一个复制起点"],"a":1,"e":"真核生物冈崎片段约100～200个核苷酸，原核生物约1000～2000个；真核以复制子为单位复制，引物也较短。"},{"q":"关于真核生物的转录特点叙述，正确的是","o":["转录起始辨认位点是TTGACA","形成转录起始复合物","σ因子辨认起始点","需要引物","RNA聚合酶催化转录，此外还需要其他转录因子"],"a":4,"e":"真核生物RNA聚合酶不能单独识别启动子，需多种转录因子协助才能形成转录起始复合物并启动转录。"},{"q":"G蛋白的α亚基具有","o":["GTP酶活性","ATP酶活性","TTP酶活性","CTP酶活性","UTP酶活性"],"a":0,"e":"G蛋白α亚基具有GTP酶活性，可水解GTP为GDP，使活化的α亚基恢复静止构象并与βγ亚基重新结合。"},{"q":"嘌呤核苷酸从头合成的原料，不包括","o":["磷酸核糖","CO2","一碳单位","谷氨酰胺","O2"],"a":4,"e":"嘌呤核苷酸从头合成利用磷酸核糖、氨基酸、一碳单位和CO2为原料，不需O2参与；O2是呼吸链的最终电子受体。"},{"q":"当6-磷酸葡萄糖脱氢受抑制时，影响脂酸生物合成的原因是","o":["乙酰CoA生成减少","柠檬酸减少","ATP形成减少","NADPH生成减少","丙二酰CoA减少"],"a":3,"e":"6-磷酸葡萄糖脱氢酶是磷酸戊糖途径的限速酶，受抑后NADPH生成减少；NADPH为脂肪酸合成提供还原当量，故脂肪酸合成受阻。"},{"q":"糖酵解的速度决定于","o":["磷酸葡糖变位酶","6-磷酸果糖激酶-1","醛缩酶","磷酸甘油激酶","磷酸甘油变位酶"],"a":1,"e":"磷酸果糖激酶-1是糖酵解的首要调控点，其活性决定糖酵解流量，故糖酵解速度决定于6-磷酸果糖激酶-1。该酶催化果糖-6-磷酸磷酸化，是糖酵解三个关键酶中最重要的调节点。"},{"q":"下列关于嘌呤核苷酸从头合成的叙述正确的是","o":["甘氨酸、谷氨酸、天冬氨酸都是合成原料","最先合成的是AMP","由IMP合成AMP和GMP均由ATP供能","一碳单位不是一种必需的合成原料","生成过程中不会产生自由嘌呤碱"],"a":4,"e":"嘌呤核苷酸从头合成是在核糖-5-磷酸分子上逐步建成嘌呤环，不先产生游离嘌呤碱；原料为甘氨酸、谷氨酰胺、天冬氨酸及一碳单位。"},{"q":"1分子葡萄糖经磷酸戊糖途径代谢时可生成","o":["1分子NADH＋H＋","2分子NADH＋H＋","1分子NDPH＋H＋","2分子NADPH＋H＋","2分子CO2"],"a":3,"e":"葡萄糖-6-磷酸经6-磷酸葡萄糖脱氢酶及6-磷酸葡糖酸脱氢酶两次脱氢，以NADP+为受氢体生成2分子NADPH，并释出1分子CO2和核糖-5-磷酸。"},{"q":"催化磷脂酰肌醇-4,5-二磷酸（PIP2）水解为1,4,5-三磷酸肌醇（IP3）的酶是","o":["磷脂酶A","磷脂酶C","磷脂酶A2","蛋白激酶C","蛋白激酶A"],"a":1,"e":"磷脂酰肌醇特异性磷脂酶C催化PIP2水解，生成DAG和IP3，二者均为重要的第二信使。磷脂酶A2水解磷脂的2位酯键释放花生四烯酸。"},{"q":"下列化合物是乙酰CoA羧化酶的别构抑制剂的是","o":["柠檬酸","异柠檬酸","ATP","乙酰CoA","长链脂酰CoA"],"a":4,"e":"长链脂酰CoA使乙酰CoA羧化酶由有活性的多聚体解聚为无活性原聚体，别构抑制该酶；柠檬酸和异柠檬酸则为别构激活剂。"},{"q":"用于双向电泳分析的蛋白质样品制备，不正确的是","o":["待分析的蛋白质样品应处于溶解状态","样品在电泳时不能产生聚集和沉淀","应防止样品在制备过程中发生化学修饰","样品中含有核酸成分不影响蛋白质分离","应尽量除去高丰度的蛋白质"],"a":3,"e":"核酸带负电荷且与蛋白质结合，会改变蛋白质的电荷与迁移率，双向电泳前必须除去核酸。"},{"q":"胆固醇代谢在肝内的最终产物是","o":["7α-胆固醇","脂酰CoA","结合胆汁酸","维生素D3","胆色素"],"a":2,"e":"胆固醇在肝内转化为胆汁酸是其最主要去路，生成的初级胆汁酸再与甘氨酸或牛磺酸结合，以结合胆汁酸形式随胆汁排出。"},{"q":"印迹技术中最常用的固相介质是","o":["琼脂糖凝胶","醋酸纤维素薄膜","琼脂胶","硝酸纤维素膜","聚丙烯酰胺凝胶"],"a":3,"e":"印迹技术将电泳分离的待测大分子转移至硝酸纤维素膜或尼龙膜等固相介质并固定，再与探针杂交检测，其中硝酸纤维素膜最为常用。"},{"q":"使用质谱技术鉴定蛋白质组时，酶解的目的是","o":["使蛋白质降解成为单个氨基酸","使蛋白质降解成为肽段，形成肽质量指纹图谱","将多余的核酸除去","去掉蛋白质的磷酸化修饰","形成可供连接的黏性末端"],"a":1,"e":"质谱鉴定蛋白质时先将蛋白质酶解为肽段，测定各肽段精确质荷比形成肽质量指纹图，再与理论酶切肽段匹配鉴定蛋白质。"},{"q":"下列哪种不是肝在脂类代谢中特有的作用","o":["酮体的生成","LDL的生成","VLDL的生成","胆汁酸的生成","LCAT的生成"],"a":1,"e":"LDL由VLDL在血浆中经甘油三酯水解及载脂蛋白转变生成，并非肝特有作用；酮体、VLDL、胆汁酸及LCAT的生成均为肝特有功能。"},{"q":"与原核生物核糖体小亚基结合的蛋白质合成抑制剂是","o":["链霉素","氯霉素","利福霉素","放线菌素","青霉素"],"a":0,"e":"链霉素结合原核核糖体30S小亚基，引起读码错误并抑制翻译起始，对真核核糖体无作用。"},{"q":"关于应激状态血中成分的改变，错误的是","o":["脂肪动员加速","蛋白质分解减少","胰岛素水平降低","葡萄糖水平增高","肾上腺素水平增高"],"a":1,"e":"应激时交感神经兴奋，肾上腺素、胰高血糖素及皮质激素分泌增多而胰岛素减少，血糖升高、脂肪动员加速，蛋白质分解加强以供糖异生，故分解减少的说法错误。"},{"q":"某RNA为5'-UGACGA-3'，与其对应的DNA双链中的编码链为","o":["5'-ACTGCT-3'","5'-TGACGA-3'","5'-TCGTCA-3'","5'-UCGTCA-3'","5'-ACTGCU-3'"],"a":1,"e":"编码链与mRNA序列相同（仅T代替U），故为5'-TGACGA-3'。模板链才与mRNA互补，为3'-ACTGCT-5'。"},{"q":"一个酶有多个底物时，其最适底物的Km","o":["＞10-3mmol/L","最大","＜10-6mmol/L","最小","与其他底物相同"],"a":3,"e":"Km反映酶与底物的亲和力，Km越小亲和力越大，故同一酶有多个底物时，Km最小的底物为最适底物。"},{"q":"VLDL的生理功能是","o":["转运外源性甘油三酯","转运内源性胆固醇","转运自由脂酸","逆向转运胆固醇","转运内源性甘油三酯和胆固醇"],"a":4,"e":"VLDL由肝细胞合成，主要转运内源性甘油三酯，其表面也含胆固醇；CM转运外源性甘油三酯，LDL转运内源性胆固醇。"},{"q":"苯丙酮尿症绝大多数是由于苯丙氨酸羟化酶基因点突变（多为错义突变），导致肝脏苯丙氨酸羟化酶缺乏，致使苯丙氨酸不能转变为酪氨酸而产生的先天性代谢缺陷病。苯丙氨酸羟化酶催化的反应是","o":["天冬氨酸→苯丙氨酸","酪氨酸→苯丙氨酸","苯丙氨酸→酪氨酸","丙氨酸→苯丙氨酸","苯丙氨酸→苯丙酮酸"],"a":2,"e":"苯丙氨酸羟化酶以四氢生物蝶呤为辅酶，催化苯丙氨酸羟化为酪氨酸，反应不可逆；酶缺陷时苯丙氨酸经转氨基生成苯丙酮酸。"},{"q":"将大肠杆菌的碳源由葡萄糖转变为乳糖时，细菌细胞内不发生","o":["乳糖转变为别乳糖","cAMP浓度升高","半乳糖与阻遏蛋白结合","RNA聚合酶与启动序列结合","阻遏蛋白与操纵序列结合"],"a":4,"e":"乳糖转变为别乳糖后与阻遏蛋白结合，使其构象改变而脱离操纵序列，同时cAMP升高使CAP结合启动子上游，转录开放。"},{"q":"仅在细胞质内进行的代谢途径是","o":["三羧酸循环","氧化磷酸化","丙酮酸羧化","脂酸β-氧化","脂酸合成"],"a":4,"e":"脂肪酸合成酶系存在于细胞质，乙酰CoA需经柠檬酸-丙酮酸循环转运出线粒体，再在胞质中合成软脂酸。"},{"q":"下述哪种物质专一地抑制F0因子","o":["鱼藤酮","抗霉素A","寡霉素","一氧化碳","H2S"],"a":2,"e":"寡霉素与ATP合酶的F0质子通道结合，阻断H+回流，抑制ATP合成，同时使电子传递因质子梯度蓄积而减慢。"},{"q":"反应6-磷酸果糖→1,6-双磷酸果糖，需要哪些条件","o":["果糖双磷酸酶-1、ATP和Mg2+","果糖双磷酸酶-1、ADP、Pi和Mg2+","6-磷酸果糖激酶-1、ATP和Mg2+","6-磷酸果糖激酶-1、ADP、Pi和Mg2+","ATP和Mg2+"],"a":2,"e":"该反应由磷酸果糖激酶-1催化，需ATP和Mg2+，是不可逆的限速步骤；其逆反应由果糖双磷酸酶-1催化。"},{"q":"关于别构调节叙述，错误的是","o":["别构调节具有放大效应","别构酶的动力学特点，是酶促反应速率与底物浓度的关系呈S形而非矩形双曲线","别构效应剂与酶的结合是可逆的","代谢途径的终产物通常是该途径起始反应酶的别构抑制剂","别构调节剂常是些小分子代谢物"],"a":0,"e":"别构调节通过改变酶分子结构快速调节酶活性，不具放大效应；化学修饰调节（如磷酸化）才有级联放大效应。别构效应剂多为小分子代谢物，与酶可逆结合，终产物常别构抑制起始酶。"},{"q":"哺乳类动物自身能合成的脂肪酸是","o":["亚麻酸","软脂酸","花生四烯酸","亚油酸","二十二碳六烯酸"],"a":1,"e":"脂肪酸合酶复合体催化合成16碳的软脂酸，亚油酸、亚麻酸等多不饱和脂肪酸人体不能合成，须由食物供给。"},{"q":"关于天然核酶描述正确的是","o":["是具有酶活性的RNA分子","是具有酶活性的DNA分子","是核酸与蛋白质共同组成的酶","只能水解RNA，不能水解DNA","可以水解多肽链"],"a":0,"e":"核酶是一类具有生物催化功能的RNA分子，即具有酶活性的RNA，可催化RNA剪接等反应。其化学本质为RNA，并非DNA或核酸与蛋白质的复合物。"},{"q":"百日咳毒素主要直接干扰哪种G蛋白活性","o":["激动型G蛋白（Gs）","抑制型G蛋白（Gi）","与视觉相关的G蛋白（Gt）","与离子通道开放相关的G蛋白（Go）","与磷脂酶C（PLC）活化相关的G蛋白（Gq）"],"a":1,"e":"百日咳毒素使Gi的α亚基ADP-核糖化，阻止其与受体解离并维持GDP结合状态，阻断抑制性信号，使腺苷酸环化酶活性升高。"},{"q":"小明因为受伤需要抹点红霉素，红霉素作为一种抗生素，其作用原理是","o":["阻碍翻译起始复合物的形成","抑制氨酰-tRNA与小亚基结合","抑制转肽酶","引起读码错误","抑制EF-G"],"a":2,"e":"红霉素属大环内酯类，与细菌核糖体50S亚基结合，抑制肽酰转移酶（转肽酶）并封阻肽链排出通道，从而阻断原核生物的蛋白质合成。"},{"q":"下列有关蛋白聚糖的叙述，错误的是","o":["蛋白聚糖由糖胺聚糖共价连接于核心蛋白所组成","糖胺聚糖必含有糖胺","糖胺聚糖由二糖单位重复连接形成具有分支的结构","蛋白聚糖糖链的加工修饰主要在高尔基体内进行","糖胺的氨基来自谷氨酰胺"],"a":2,"e":"糖胺聚糖是由二糖单位重复连接而成的杂多糖，不分支，其二糖单位含糖胺与糖醛酸；蛋白聚糖的糖链加工主要在高尔基体内完成。"},{"q":"糖酵解途径中，可以生成ATP的第1个反应是","o":["葡萄糖到G-6-P反应","3-磷酸甘油醛到1,3-二磷酸甘油酸反应","6-磷酸果糖到1,6-双磷酸果糖反应","1,3-二磷酸甘油酸到3-磷酸甘油酸反应","3-磷酸甘油酸到2-磷酸甘油酸反应"],"a":3,"e":"甘油酸-1,3-二磷酸在磷酸甘油酸激酶催化下，将高能磷酸基转移给ADP生成ATP，是糖酵解中第一个底物水平磷酸化反应。"},{"q":"以下哪一项不涉及目的基因与载体的连接","o":["限制酶","单链核酸酶","核酸外切酶","DNA连接酶","末端脱氧核苷酸转移酶"],"a":2,"e":"核酸外切酶水解核酸链末端的磷酸二酯键，不参与目的基因与载体的连接；连接过程需限制酶切割、DNA连接酶封闭切口，末端脱氧核苷酸转移酶可加尾。"},{"q":"环化鸟苷酸（cGMP）能激活","o":["磷脂酶C","蛋白激酶A","蛋白激酶G","酪氨酸蛋白激酶","蛋白激酶C"],"a":2,"e":"cGMP的下游靶分子是蛋白激酶G，cAMP则激活蛋白激酶A。"},{"q":"可激活胰蛋白酶原的是","o":["寡肽酶","二肽酶","肠激酶","胰蛋白酶","胃蛋白酶"],"a":2,"e":"肠激酶由十二指肠黏膜细胞分泌，特异水解胰蛋白酶原第6位赖氨酸与第7位异亮氨酸间的肽键，切除六肽使其形成活性中心而激活。"},{"q":"核苷酸中碱基（N）、戊糖（R）和磷酸（P）之间的连接关系是","o":["N-R-P","N-P-R","R-N-P","P-N-R","R-P-P-N"],"a":0,"e":"核苷酸中碱基连于戊糖的C-1′，磷酸连于戊糖的C-5′，故三者的连接关系为碱基-戊糖-磷酸。"},{"q":"关于DNA损伤修复的SOS系统的叙述正确的是","o":["是一种保真性很高的复制过程","LexA蛋白是一系列操纵子的阻遏物","RecA基因在DNA损伤时被抑制","该系统只能修复嘧啶二聚体","紫外线损伤是主要的信号"],"a":1,"e":"SOS修复由RecA蛋白与LexA阻遏物相互作用引发，LexA是一系列SOS基因操纵子的共同阻遏物，被激活的RecA促其自水解而解离，使修复基因表达，属易错修复。"},{"q":"在糖酵解、三羧酸循环中，都会产生还原型NADH＋H＋。此还原当量含有高电极电势的电子，也就是说，它们将在氧化时释放出大量的能量。然而，细胞不会一次性释放完全的能量，因为在这种情况下，反应将无法控制。相反，电子从NADH释放出来，并通过一系列的酶传递给氧气，其中每步只释放少量的能量。通过氧化磷酸化生成的高能化合物是","o":["ATP","辅酶A","UTP","CTP","磷酸烯醇式丙酮酸"],"a":0,"e":"氧化磷酸化是NADH和FADH2经呼吸链逐步氧化释能，驱动ADP磷酸化生成ATP的过程，生成的高能化合物是ATP。"},{"q":"关于疾病相关基因，以下说法中错误的是","o":["许多疾病都与基因结构或者表达变化有关","疾病相关基因可以分为致病基因和疾病易感基因","在肿瘤、心血管疾病中，通常包含2个以上疾病相关基因","疾病相关基因不具有正常的生物学功能","克隆疾病相关基因与确定基因功能密不可分"],"a":3,"e":"疾病相关基因仍具有正常的生物学功能，其结构改变或表达异常才导致疾病；可分为致病基因与易感基因，肿瘤、心血管疾病常涉及多个相关基因。"},{"q":"有抗动脉粥样硬化作用的脂蛋白是","o":["CM","LDL","VLDL","oxLDL","HDL"],"a":4,"e":"HDL参与胆固醇逆向转运，把肝外组织包括动脉壁的胆固醇运回肝代谢，故有抗动脉粥样硬化作用；LDL及oxLDL则促进斑块形成。"},{"q":"原核生物蛋白质生物合成需要多种酶和蛋白质因子的参与，具有GTP酶活性的是","o":["RF-1","RF-2","RF-3","IF-1","IF-3"],"a":2,"e":"RF-3具有GTP酶活性，肽链释放后水解GTP，促进RF-1或RF-2与核糖体分离。"},{"q":"同工酶是指","o":["催化作用相同，但分子组成和理化性质不同的一类酶","催化相同反应，分子组成相同，但辅酶不同的一类酶","催化同一底物起不同反应的酶的总称","多酶体系中酶组分的统称","催化作用、分子组成及理化性质相同，但组织分布不同的酶"],"a":0,"e":"同工酶催化相同的化学反应，但酶蛋白的分子结构、理化性质和免疫学特性各不相同，不能视为同一种酶。"},{"q":"不以FAD为辅基的脱氢酶是","o":["二氢硫辛酰胺脱氢酶","脂酰CoA脱氢酶","琥珀酸脱氢酶","线粒体内膜磷酸甘油脱氢酶","β-羟脂酰CoA脱氢酶"],"a":4,"e":"β-羟脂酰CoA脱氢酶以NAD+为辅酶，催化β-羟脂酰CoA脱氢生成β-酮脂酰CoA；琥珀酸脱氢酶、脂酰CoA脱氢酶、磷酸甘油脱氢酶及二氢硫辛酰胺脱氢酶均以FAD为辅基。"},{"q":"彻底氧化一分子硬脂酰辅酶A（18∶0）所需消耗氧的分子数是","o":["16","23","26","30","32"],"a":2,"e":"硬脂酰CoA为18碳脂肪酸，经8轮β-氧化生成9分子乙酰CoA、8分子FADH2和8分子NADH，彻底氧化共需26分子氧。"},{"q":"e-PCR比BLAST具有更高的","o":["专一性","稳定性","同源性","保守性","变异性"],"a":0,"e":"e-PCR以序列标签位点设计特异引物进行电子延伸，只能命中高度匹配的序列，故比BLAST比对具有更高的专一性。"},{"q":"维生素B1缺乏时出现的消化道蠕动慢，消化液比较少，食欲缺乏等症状，原因是","o":["维生素B1能促进胰蛋白酶的活性","维生素B1能促进胃蛋白酶的活性","维生素B1能抑制胆碱酯酶的活性","维生素B1能抑制乙酰胆碱的活性","维生素B1能促进胃蛋白酶原的活性"],"a":2,"e":"维生素B1可抑制胆碱酯酶活性，缺乏时乙酰胆碱分解加强，神经传导异常，出现消化液减少、胃蠕动变慢和食欲缺乏。"},{"q":"人类DNA序列最常见的、最稳定的遗传变异是","o":["限制性片段长度多态性","可变数目串联重复序列","单核苷酸多态性","DNA指纹图谱","DNA甲基化"],"a":2,"e":"单核苷酸多态性指基因组中单个核苷酸置换或颠换引起的变异，分布频率高、稳定且易检测，是人类最常见的遗传变异。"},{"q":"cAMP与CAP结合，CAP介导正性调节发生在下列的哪个阶段","o":["有葡萄糖及cAMP较高时","有葡萄糖及cAMP较低时","没有葡萄糖及cAMP较高时","没有葡萄糖及cAMP较低时","葡萄糖及cAMP浓度极高时"],"a":2,"e":"葡萄糖缺乏时细胞内cAMP浓度升高，cAMP与CAP结合后结合于lac启动子上游CAP位点，促进RNA聚合酶转录。"},{"q":"酶化学修饰调节的主要方式是","o":["酶蛋白的合成与降解","磷酸化与去磷酸化","聚合与解聚","甲基化与去甲基化","乙酰化与脱乙酰化"],"a":1,"e":"酶化学修饰以磷酸化与去磷酸化最为多见，分别由蛋白激酶和蛋白磷酸酶催化，使酶在有活性与无活性形式之间转变，并具级联放大效应。"},{"q":"血浆蛋白质pI大多在5～6之间，它们在血液中的主要存在形式是","o":["带正电荷","疏水分子","非极性离子","兼性离子","带负电荷"],"a":4,"e":"血浆pH约7.4，高于血浆蛋白质的等电点，故蛋白质解离成负离子，在血液中主要带负电荷。"},{"q":"通过免疫共沉淀的方法分析与抑癌蛋白TP53的相互作用蛋白质，经质谱分析后，下列哪个数据库可以检索到可能与TP53存在相互作用的蛋白质","o":["Swiss-Prot数据库","KEGG数据库","EST数据库","UniGene","MPSS"],"a":0,"e":"Swiss-Prot是注释完善的蛋白质序列数据库，可检索目的蛋白的序列、功能及相互作用信息；KEGG、EST、UniGene侧重通路或核酸序列。"},{"q":"聚合酶链反应扩增产物片段大小决定于","o":["DNA聚合酶","引物","模板","循环次数","三磷酸脱氧核苷的纯度"],"a":1,"e":"PCR短产物片段的长度严格限定在两引物5′-端之间，故扩增产物大小由引物在模板上的位置及间距决定，与聚合酶种类、循环次数无关。"},{"q":"合成磷脂酰胆碱时所需的活性胆碱是","o":["ADP-胆碱","GDP-胆碱","UDP-胆碱","CDP-胆碱","TDP-胆碱"],"a":3,"e":"磷脂酰胆碱经CDP-胆碱途径合成，胆碱需先活化为CDP-胆碱，再与甘油二酯缩合生成磷脂酰胆碱。CTP参与胆碱活化，故活性形式为CDP-胆碱。"},{"q":"艾滋病（AIDS）是目前威胁人类生命的重要疾病之一。能导致艾滋病的HIV病毒是RNA病毒。它感染人的T淋巴细胞，导致人的免疫力下降，使患者死于广泛感染。该病毒进入细胞后，能以病毒RNA为模板，合成病毒DNA，并整合于人的基因组中。这一过程称为","o":["复制","转录","逆转录","RNA复制","翻译"],"a":2,"e":"以病毒RNA为模板合成互补DNA并整合入宿主基因组，称为逆转录，由逆转录酶催化，是HIV复制前病毒的过程。"},{"q":"生物体内物质代谢调节的基础是","o":["整体水平调节","激素水平调节","细胞水平调节","代谢通路的调节","关键酶的调节"],"a":2,"e":"高等动物的三级代谢调节中，细胞水平调节是基础，激素水平和整体水平调节都必须通过细胞水平调节实现。"},{"q":"在基因治疗中，基因转移的生物学方法主要是用哪项来介导基因导入","o":["质粒载体","病毒载体","脂质体","电穿孔","基因枪"],"a":1,"e":"基因转移的生物学方法即由病毒载体介导，通过病毒感染细胞将治疗基因导入，转移效率高。质粒、脂质体、电穿孔和基因枪均属非生物学方法。"},{"q":"Cori循环以其发现者卡尔·斐迪南·科里（Carl Ferdinand Cori）和盖蒂·科里（Gerty Cori）夫妇命名，因为科里夫妇在糖原分解方面的贡献而与阿根廷的科学家伯纳德·何塞（Bcrnardo Houssay，1887~1971）共同分享1947年的诺贝尔生理学或医学奖。Cori循环是指","o":["肌肉内葡萄糖酵解成乳酸，有氧时乳酸重新合成糖原","肌肉从丙酮酸生成丙氨酸，肝内丙氨酸重新变成丙酮酸","肌肉内蛋白质降解生成丙氨酸，经血液循环至肝内界生为糖原","肌肉内葡萄糖酵解成乳酸，经血液循环至肝内异生为葡萄糖供外周组织利用","肌肉内蛋白质降解生成氨基酸，经转氨酶与腺苷酸脱氨酶偶联脱氨基的循环"],"a":3,"e":"Cori循环即乳酸循环：肌肉糖无氧氧化生成乳酸，经血液入肝异生为葡萄糖，再回到肌肉利用，可避免乳酸堆积并补充血糖。"},{"q":"Gly和Ser在分解代谢中形成的一碳单位均为","o":["二氧化碳","—CH3","＝CH2","≡CH","—CHO"],"a":2,"e":"甘氨酸和丝氨酸分解代谢均生成N5,N10-甲烯四氢叶酸，其携带的一碳单位为亚甲基即＝CH2。"},{"q":"下列关于肽的叙述，错误的是","o":["肽是两个或两个以上氨基酸通过肽键连接而成的化合物","组成肽的氨基酸分子都不完整","肽没有氨基末端和羧基末端","肽链中的氨基酸称为氨基酸残基","肽分为寡肽和多肽"],"a":2,"e":"肽链两端分别有游离的α-氨基和α-羧基，即N-端和C-端。肽由两个以上氨基酸经肽键连接而成，链中氨基酸称残基，可分为寡肽和多肽。"},{"q":"下列哪项不是糖异生途径的关键酶","o":["葡糖-6-磷酸酶","果糖双磷酸酶-1","丙酮酸激酶","磷酸烯醇丙酮酸羧化激酶","丙酮酸羧化酶"],"a":2,"e":"丙酮酸激酶是糖酵解的关键酶，而糖异生的关键酶为丙酮酸羧化酶、磷酸烯醇式丙酮酸羧激酶、果糖二磷酸酶-1和葡糖-6-磷酸酶。"},{"q":"进食后被吸收入血的单糖，最主要的去路是","o":["在肝、肌肉等组织中合成糖原","在组织器官中氧化供能","在体内转变为脂肪","在体内转变为部分氨基酸","进行无氧氧化供能"],"a":1,"e":"吸收入血的葡萄糖主要被各组织器官摄取，经有氧氧化彻底分解供能；合成糖原、转变为脂肪和氨基酸所占比例较小。"},{"q":"有关血浆脂蛋白的叙述正确的是","o":["CM在脂肪组织中合成","HDL是从LDL中转变来","VLDL可转变成LDL","LDL和HDL竞争肝外受体","HDL运输胆固醇到肝外利用"],"a":2,"e":"VLDL在血中经脂蛋白脂肪酶水解甘油三酯、脱去载脂蛋白并接受HDL转移的胆固醇酯，先转变为中间密度脂蛋白，再生成LDL；CM由小肠合成。"},{"q":"视网膜母细胞瘤癌变是RB基因突变为rb或缺失引起的，其中涉及的机制属于","o":["癌基因异常活化","抑癌基因异常失活","基因组不稳定","表观遗传改变","基因重排"],"a":1,"e":"RB是抑癌基因，其两次突变或缺失使RB蛋白失活，细胞周期检查点失控而致瘤，属抑癌基因异常失活的典型。"},{"q":"关于细胞癌基因的叙述正确的是","o":["又称为病毒癌基因","存在于DNA病毒中","存在于RNA病毒中","存在于正常生物基因组中","正常细胞含有即可导致肿瘤的发生"],"a":3,"e":"细胞癌基因即原癌基因，存在于正常生物基因组中，编码生长因子、受体、信号分子或转录因子，只有被活化后才具致癌作用。"},{"q":"心房钠尿肽发挥调节作用的信息通路是","o":["JAK-STAT途径","cGMP-PKG途径","RTK-Ras-MAPK途径","Ca2+-CaM途径","cAMP-PKA途径"],"a":1,"e":"心房钠尿肽与受体结合后激活鸟苷酸环化酶，使cGMP升高并激活PKG，经cGMP-PKG途径发挥调节作用。教材指出cGMP的下游分子是PKG，PKG在心肌及平滑肌收缩调节中起重要作用。"},{"q":"转录前起始复合物（PIC）是指","o":["RNA聚合酶与DNA结合的复合物","RNA聚合酶与pppGpN-OH结合的复合物","各类转录因子与DNA模板结合后的复合物","各种转录因子与RNA聚合酶及DNA模板结合的复合物","各种转录因子与RNA聚合酶结合的复合物"],"a":3,"e":"转录前起始复合物由各种转录因子与RNA聚合酶Ⅱ及DNA模板有序结合形成，可启动转录。"},{"q":"乳糖操纵子及色氨酸操纵子阻遏蛋白去阻遏通过","o":["阻遏蛋白化学修饰","阻遏蛋白变构调节","阻遏蛋白水平改变","组蛋白乙酰化","蛋白水解酶水解"],"a":1,"e":"乳糖操纵子中别乳糖、IPTG等结合阻遏蛋白使其构象改变而去阻遏；色氨酸操纵子中色氨酸作为辅阻遏物与阻遏蛋白结合，均属变构调节。"},{"q":"脂肪酰CoA进行β-氧化的反应顺序为","o":["脱氢、脱水、再脱氢、硫解","硫解、脱氢、加水、再脱氢","脱氢、加水、再脱氢、硫解","脱氢、再脱氢、加水、硫解","加水、脱氢、硫解、再脱氢"],"a":2,"e":"脂酰CoA每轮β-氧化依次经脱氢、加水、再脱氢和硫解四步，碳链缩短两个碳原子，生成乙酰CoA、FADH2和NADH。"},{"q":"下列哪项不是限制性核酸内切酶识别序列的特点","o":["特异性很高","其切口均为黏性末端","一般具有回文结构","有些限制性酶虽然识别的序列不同但是可产生相同的黏端","常由4～6个核苷酸组成"],"a":1,"e":"Ⅱ型限制性核酸内切酶切割后可产生黏性末端，也可产生平端，故“切口均为黏性末端”不成立。"},{"q":"关于脂组学的描述，错误的是","o":["研究生物体内所有脂质分子","不研究蛋白质的脂质化修饰","研究脂质及其代谢物","寻找疾病诊断的脂质标志物","研究血液中的脂质分子"],"a":1,"e":"脂组学分析生物样本中全部脂质及其代谢物，用于发现疾病相关的脂质标志物，也涉及蛋白质脂质化等脂质相关修饰，故不能说其不研究。"},{"q":"通过检测DNA序列线性核苷酸信息来分析基因异常的方法是","o":["基因芯片","DNA测序","核型分析","荧光原位杂交","等位基因特异性寡核苷酸杂交"],"a":1,"e":"DNA测序直接读取片段的碱基排列顺序，可确定点突变、缺失或插入等序列改变，是分析基因异常最直接的方法。"},{"q":"某种遗传性疾病患者，其皮肤对阳光特别敏感，照射后出现红斑、水肿、继而出现色素沉着，儿童期即可诱发皮肤肿瘤。该病发生的分子机制为","o":["LexA类基因缺陷","Uvr类基因缺陷","XP类基因缺陷","光修复基因缺陷","DNA聚合酶基因缺陷"],"a":2,"e":"着色性干皮病患者因XP类基因缺陷致核酸内切酶功能丧失，紫外线所致的嘧啶二聚体不能被切除修复，故易发生皮肤肿瘤。"},{"q":"胰岛素作为抗脂解激素，主要作用是抑制了","o":["磷酸二酯酶","甘油一酯脂肪酶","甘油二酯脂肪酶","甘油三酯脂肪酶","腺苷酸环化酶"],"a":3,"e":"胰岛素升高cAMP磷酸二酯酶活性并激活磷蛋白磷酸酶，使激素敏感性甘油三酯脂肪酶去磷酸化而失活，从而抑制脂肪动员。"},{"q":"关于Lesch-Nyhan综合征，下列叙述有误的是","o":["又称为自毁容貌症","是一种X染色体连锁的隐性遗传的先天性嘧啶代谢缺陷症","主要是由于基因缺陷导致HGPRT完全缺失","患者常出现自残行为","常伴随高尿酸血症"],"a":1,"e":"Lesch-Nyhan综合征是X连锁隐性遗传的嘌呤代谢缺陷病，因HGPRT完全缺失致嘌呤补救合成障碍，表现为自残、高尿酸血症和智力障碍。"},{"q":"1g软脂酸钠（分子量=256）较1g葡萄糖（分子量=180）彻底氧化所释放出的ATP数约高","o":["2倍","2、5倍","3倍","3、5倍","5倍"],"a":1,"e":"1g软脂酸彻底氧化净生成约106分子ATP，1g葡萄糖约生成30分子ATP，按分子数折算软脂酸产ATP约为葡萄糖的2.5倍。"},{"q":"催化单纯电子转移的酶是","o":["以NAD+为辅酶的酶","需氧脱氢酶","加单氧酶","细胞色素氧化酶","泛醌"],"a":3,"e":"细胞色素氧化酶即复合体Ⅳ，接受还原型Cytc的电子并传递给O2生成H2O，催化的是单纯电子转移。需氧脱氢酶以氧为直接受氢体，加单氧酶催化底物掺入一个氧原子。"},{"q":"假设大肠杆菌中cAMP环化酶基因突变，其乳糖操纵子基因表达调控会受到什么影响","o":["β-半乳糖苷酶的表达减少","cAMP-CAP复合物增加","阻遏蛋白不结合在操纵序列上","RNA聚合酶与启动序列结合","可在没有葡萄糖只有乳糖的培养基中正常生长"],"a":0,"e":"cAMP环化酶基因突变使cAMP生成减少，CAP-cAMP复合物不足，CAP不能结合启动子，乳糖操纵子转录效率下降，β-半乳糖苷酶表达减少。"},{"q":"N-连接型聚糖合成时的糖基供体底物必须活化成","o":["UDP或GDP衍生物","UDP或ADP衍生物","UDP或CDP衍生物","ADP或GDP衍生物","ADP或TDP衍生物"],"a":0,"e":"N-连接型聚糖合成时糖基须活化为UDP或GDP衍生物，逐个连接于长萜醇焦磷酸载体，形成十四糖后整体转移至天冬酰胺残基。"},{"q":"下列代谢途径不需要线粒体内反应的是","o":["磷脂合成","酮体合成","糖异生","脂肪酸β-氧化","柠檬酸循环"],"a":0,"e":"甘油磷脂合成的酶系位于内质网，全程不需线粒体参与；酮体生成、糖异生和脂肪酸β-氧化均有线粒体反应。"},{"q":"胰液中的蛋白水解酶最初以酶原形式存在其意义是","o":["抑制蛋白酶的分泌","缺乏适当的酶原激活剂","促进蛋白酶的分泌","避免胰腺自身被消化","抑制蛋白质发挥消化作用"],"a":3,"e":"消化道蛋白酶以酶原形式分泌、进入肠道后才被激活，可避免胰腺组织被自身蛋白酶消化。"},{"q":"下列关于O-连接型聚糖的叙述，不正确的是","o":["核心二糖可形成分支","在多肽链合成的同时进行O-连接型聚糖的合成","合成时需要糖基转移酶","含有N-乙酰半乳糖胺和半乳糖组成的核心二糖","O-连接型聚糖的合成不需要糖链载体"],"a":1,"e":"O-连接型聚糖在多肽链合成后逐个加上糖基，由糖基转移酶催化，不需糖链载体；其核心二糖由N-乙酰半乳糖胺和半乳糖组成。"},{"q":"ATP的功能不包括","o":["为生物反应供能","合成RNA","转变成cAMP","贮存化学能","转变为UDPGA"],"a":4,"e":"ATP可水解释放能量、作为合成RNA的原料、环化生成cAMP并贮存化学能；UDPGA由UTP与葡萄糖醛酸生成，与ATP无关。"},{"q":"1分子琥珀酸脱氢生成延胡索酸时，脱下的1对氢经过呼吸链氧化生成水，同时生成多少分子ATP","o":["1","1、5","2","2、5","3"],"a":1,"e":"琥珀酸脱氢酶以FAD为辅基，脱下的氢经FADH2进入呼吸链氧化，P/O比约1.5，生成1.5分子ATP。"},{"q":"可用于蛋白质乙酰化修饰分析的技术是","o":["NMR","HPLC/MS/MS","2DE/MS","SAGE","SNP分析"],"a":1,"e":"乙酰化修饰发生在赖氨酸残基，修饰肽段经高效液相色谱串联质谱（HPLC/MS/MS）可完成富集后的鉴定与定量，是蛋白质翻译后修饰分析的常用技术。"},{"q":"健康成年人摄入充足的高脂低糖低蛋白膳食1小时后，心肌细胞中哪个酶的活性会明显增强","o":["乙酰CoA羧化酶","磷酸果糖激酶-1","肉碱脂酰转移酶Ⅰ","丙酮酸脱氢酶复合体","L-谷氨酸脱氢酶"],"a":2,"e":"高脂低糖膳食时糖供能不足，机体靠脂肪酸供能，肉碱脂酰转移酶Ⅰ活性升高，促进脂酰CoA进入线粒体进行β-氧化。"},{"q":"下列关于血浆中的胆固醇酯正确的叙述是","o":["由小肠吸收入血","由血浆脂蛋白释出","由肝外组织释放入血","在血浆中经酶的催化生成","由肝脏合成后释放入血"],"a":3,"e":"血浆中的胆固醇酯主要由卵磷脂胆固醇酰基转移酶催化，将卵磷脂2位脂肪酸转移至游离胆固醇而生成。"},{"q":"催化PIP2水解产生第二信使DAG和IP3的酶是","o":["磷脂酶A1","磷脂酶A2","磷脂酶B","磷脂酶C","磷脂酶D"],"a":3,"e":"磷脂酰肌醇特异性磷脂酶C水解PIP2的磷酸二酯键，生成DAG和IP3两种第二信使；磷脂酶A2作用于甘油磷脂2位酯键，磷脂酶D则生成磷脂酸。"},{"q":"生物体内脱氨基主要方式是","o":["直接脱氨基","联合脱氨基","转氨基","氧化脱氨","还原脱氨"],"a":1,"e":"联合脱氨基作用是转氨基作用与L-谷氨酸氧化脱氨基作用的偶联，是体内氨基酸脱氨基的主要方式，可生成游离氨。"},{"q":"现有15N标记DNA双链，当以NH4Cl作为氮源复制DNA时，产生不含15N的子代DNA分子时是","o":["第1代","第2代","第3代","第4代","第5代"],"a":1,"e":"15N-DNA转入14N培养基后，第1代子代DNA均为杂合链仍含15N；第2代才出现不含15N的轻链DNA。"},{"q":"不需要SAM提供甲基生成的物质是","o":["肾上腺素","胸腺嘧啶","胆碱","肌酸","肉碱"],"a":1,"e":"胸腺嘧啶核苷酸由dUMP经胸苷酸合酶催化甲基化生成，甲基由N5，N10-亚甲四氢叶酸提供，并非由SAM提供。"},{"q":"下列关于DNA自动测序技术的描述，正确的是","o":["比传统DNA测序更快捷方便","其基本原理完全不同于Sanger测序法","需要放射性核素处","基本Sanger测序法的原理","4个反应管中的引物所标记的荧光染料波长相同"],"a":0,"e":"DNA自动测序以Sanger双脱氧链终止法为基础，用四色荧光标记ddNTP，经毛细管电泳和激光检测自动读出序列，较手工测序快捷方便且不用放射性核素。"},{"q":"基因重组中对于重组DNA分子的筛选方法，下列哪种不正确","o":["分子杂交和放射自显影法","酶切后电泳方法","表型筛选","基因表达产物的鉴定","DNA分子量分析"],"a":4,"e":"重组体的筛选可依据载体选择标记、酶切电泳、分子杂交及表达产物鉴定；DNA分子量分析不能区分重组与非重组分子。"},{"q":"肝细胞性黄疸，临床生化检查不应该出现","o":["血清结合胆红素上升","血清总胆红素上升","血清未结合胆红素上升","尿胆红素阳性","粪便颜色呈陶土色"],"a":4,"e":"肝细胞性黄疸时肝细胞摄取、结合和排泄胆红素均障碍，进入肠道的胆红素减少使粪色变浅，但并非完全梗阻所致的白陶土色。"},{"q":"转氨酶一般含有哪种维生素","o":["B1","B2","B3","B5","B6"],"a":4,"e":"转氨酶的辅因子是磷酸吡哆醛，即维生素B6的磷酸酯，参与氨基酸的转氨基与脱氨基作用。"},{"q":"下列选项中，一般不用于未知疾病相关基因分离鉴定的方法是","o":["抑制性消减杂交","基因表达阵列分析","基因鉴定集成法","重组克隆表达抗原的血清学鉴定（SEREX）","RT-PCR"],"a":4,"e":"抑制性消减杂交、基因表达阵列、基因鉴定集成法及SEREX均可从背景中分离未知的差异表达基因或抗原相关基因；RT-PCR用于已知序列的扩增与定量。"},{"q":"磷酸戊糖途径的重要生理功能之一是生成","o":["6-磷酸葡萄糖","NADH+H+","NADPH+H+","5-磷酸葡萄糖","生成多碳糖"],"a":2,"e":"戊糖磷酸途径的限速酶葡萄糖-6-磷酸脱氢酶以NADP+为受氢体，生成NADPH供脂肪酸、胆固醇合成及维持谷胱甘肽还原性，是其重要生理功能。"},{"q":"经转氨基作用生成草酰乙酸的氨基酸是","o":["色氨酸","酪氨酸","丙氨酸","谷氨酸","天冬氨酸"],"a":4,"e":"天冬氨酸经谷草转氨酶催化脱去氨基生成草酰乙酸；丙氨酸生成丙酮酸，谷氨酸生成α-酮戊二酸。"},{"q":"下列哪一种氨基酸是亚氨基酸","o":["赖氨酸","脯氨酸","组氨酸","精氨酸","异亮氨酸"],"a":1,"e":"脯氨酸的氨基参与形成吡咯环，属亚氨基酸，其亚氨基仍能与羧基形成肽键；赖氨酸、精氨酸、组氨酸为碱性氨基酸。"},{"q":"肝脏在维生素代谢中的作用不包括","o":["多种B族维生素转变成辅酶成分","肝细胞内加双氧酶可将β-胡萝卜素裂解成维生素A","95%的维生素B1贮存于肝脏","95%的维生素A贮存于肝脏","将维生素D3羟化成25-OH-D3"],"a":2,"e":"维生素A主要储存于肝，约占体内总量的95%，肝并不储存维生素B1。肝还参与B族维生素转变为辅酶、β-胡萝卜素裂解生成维生素A及维生素D3的25-羟化。"},{"q":"1mol葡萄糖经糖的有氧氧化过程，可生成的乙酰CoA是","o":["1mol","2mol","3mol","4mol","5mol"],"a":1,"e":"1mol葡萄糖经糖酵解生成2mol丙酮酸，后者氧化脱羧各生成1mol乙酰CoA，共生成2mol乙酰CoA。乙酰CoA进入三羧酸循环彻底氧化。"},{"q":"限制性内切核酸酶切割5'…GG▼AATTCC…3'序列后应产生","o":["5'突出末端","3'突出末端","5'或3'突出末端","平端","黏性末端与平末端都会生成"],"a":0,"e":"该序列在GG与AA之间切割，产生由AATT构成的5'突出单链末端，即5'黏性末端，属典型的Ⅱ型限制酶交错切割。"},{"q":"下列哪种化合物不是高能化合物","o":["6-磷酸葡萄糖","ATP","琥珀酰辅酶A","PEP","GTP"],"a":0,"e":"6-磷酸葡萄糖的磷酸酯键为低能键，水解时自由能变化小；ATP、GTP、琥珀酰CoA和PEP均含高能键。"},{"q":"患急性肝损伤的病人，其尿液检测指标与正常人不同，通过代谢组学分析，发现其尿液中含量显著升高的是","o":["尿胆素原","尿胆素","尿胆红素","尿素","尿酸"],"a":2,"e":"肝细胞损伤时结合胆红素生成减少、排泄障碍，反流入血使尿胆红素呈阳性，而正常人尿中检测不到尿胆红素。尿胆素原在肝功能障碍时因肠肝循环改变可无明显升高。"},{"q":"可降低细胞内环化腺苷酸（cAMP）含量的酶是","o":["腺苷酸环化酶","ATP酶","磷脂酶","磷酸二脂酶","蛋白激酶"],"a":3,"e":"磷酸二酯酶水解cAMP的3′，5′-磷酸二酯键生成5′-AMP，使细胞内cAMP含量降低；腺苷酸环化酶催化生成cAMP，作用与其相反。"},{"q":"在四氢叶酸中，除了影响蛋白质的合成外，还可以迅速影响下列哪种物质合成","o":["糖","三磷脂酰甘油","胆固醇酯","DNA","磷脂"],"a":3,"e":"四氢叶酸携带的一碳单位用于dTMP及嘌呤合成，N5,N10-甲烯四氢叶酸提供甲基使dUMP生成dTMP，直接影响DNA合成。"},{"q":"下列关于胆红素的叙述，错误的是","o":["完全游离的胆红素可引起大脑不可逆的损害","血液中胆红素与清蛋白结合而被运输","血浆中胆红素含量超过17、1μmol/L，即为高胆红素血症","胆红素本身是强抗氧化剂","正常人血清胆红素中80%是结合胆红素"],"a":4,"e":"正常人血清胆红素以未结合胆红素为主，约占80%，结合胆红素仅占小部分，故该说法错误。"},{"q":"供氧不足时，3-磷酸甘油醛脱氢产生的NADH+H+的主要去路是","o":["参加脂肪酸的合成","使丙酮酸还原生成乳酸","维持GSH处于还原状态","经α-磷酸甘油穿梭进入线粒体氧化","苹果酸-天冬氨酸穿梭进入线粒体氧化"],"a":1,"e":"缺氧时NADH不能经呼吸链氧化，留在细胞质中以丙酮酸为受氢体，使其还原生成乳酸，同时再生NAD+以维持糖酵解进行。"},{"q":"6-磷酸果糖激酶-1的别构抑制剂是","o":["6-磷酸果糖","1，6-双磷酸果糖","柠檬酸","乙酰CoA","AMP"],"a":2,"e":"柠檬酸与ATP是磷酸果糖激酶-1的别构抑制剂，结合别构部位后降低酶活性；AMP和果糖-2，6-二磷酸则是其别构激活剂。"},{"q":"γ-氨基丁酸（GABA）是哪种氨基酸脱羧的产物","o":["谷氨酸","天冬氨酸","甘氨酸","色氨酸","精氨酸"],"a":0,"e":"L-谷氨酸脱羧酶催化谷氨酸脱去α-羧基生成γ-氨基丁酸，该酶在脑和肾活性很高，GABA是中枢神经系统抑制性神经递质。"},{"q":"维生素B2的活性形式是","o":["核黄素","FMN和FAD","CoASH","NAD+","NADH+H+"],"a":1,"e":"维生素B2在小肠黏膜黄素激酶催化下转变为FMN，再经焦磷酸化生成FAD，二者是其活性形式。"},{"q":"下列对嘌呤核苷酸合成的描述，正确的是","o":["利用氨基酸、一碳单位和CO2合成嘌呤环，再与5'-磷酸核糖结合而成","利用天冬氨酸、一碳单位、CO2和5'-磷酸核糖为原料直接合成","在氨基甲酰磷酸的基础上逐步合成","嘌呤核苷酸是在5-磷酸核糖-1-焦磷酸（PRPP）提供磷酸核糖分子的基础上与氨基酸、CO2及一碳单位作用逐步形成","嘌呤核苷酸是先合成黄嘌呤核苷酸（XMP），再转变为AMP、GMP"],"a":3,"e":"嘌呤核苷酸从头合成在PRPP提供磷酸核糖的基础上，逐步加入氨基酸、CO2和一碳单位形成嘌呤环，而非先合成碱基再与核糖结合。"},{"q":"下列是构成磷脂酰胆碱的成分之一的物质是","o":["丝氨酸","乙醇胺","胆碱","胞嘧啶","胆胺"],"a":2,"e":"磷脂酰胆碱经甘油二酯途径合成，胆碱活化为CDP-胆碱后与甘油二酯缩合生成。乙醇胺是磷脂酰乙醇胺的合成原料，丝氨酸为其转化来源。"},{"q":"哺乳动物肝中，2分子乳酸转变成葡萄糖需要","o":["2分子ATP","3分子ATP","4分子ATP","5分子ATP","6分子ATP"],"a":4,"e":"2分子乳酸异生为葡萄糖需消耗6分子ATP：丙酮酸羧化酶消耗2分子，磷酸烯醇式丙酮酸羧激酶消耗2分子，磷酸甘油酸激酶逆反应消耗2分子。"},{"q":"关于胆红素，哪项说法是错误的","o":["在生理条件下它是难溶于水的脂溶性物质","主要由衰老破坏的红细胞中血红素代谢而来","在血中与清蛋白结合成血胆红素的形式运输","在肝细胞内主要与葡萄糖醛酸结合","正常人尿中会出现胆红素"],"a":4,"e":"正常人尿中检测不到尿胆红素，只有血中结合胆红素升高超过肾阈值时才从尿排出。胆红素为脂溶性、主要来自衰老红细胞血红素分解，在肝内与葡萄糖醛酸结合。"},{"q":"受体与其相应配体的结合是","o":["离子键结合","非共价可逆结合","共价可逆结合","非共价不可逆结合","共价不可逆结合"],"a":1,"e":"受体与配体以非共价键结合，结合数目有限且可饱和，生物效应发生后配体即与受体解离，故为可逆性结合。共价结合不可逆，不符合受体-配体结合特征。"},{"q":"葡糖-6-磷酸对己糖激酶活性的调节作用是一种","o":["酶的慢速调节","酶的别构调节","酶的共价修饰调节","酶原激活","反馈促进"],"a":1,"e":"葡糖-6-磷酸与己糖激酶的调节部位可逆性非共价结合，使酶构象改变而活性下降，属别构调节（产物反馈抑制），并非共价修饰或酶原激活。"},{"q":"下列有关脂肪代谢的叙述错误的是","o":["1分子软脂酸彻底氧化生成的ATP分子数少于丙酮酸彻底氧化所生成的ATP","酮体在肝内生成的速度大于肝外组织氧化的速度时即产生酮症","乙酰辅酶A不能净合成葡萄糖","1分子软脂酸在肝脏经β-氧化为乙酰辅酶A时需7分子水参与","胰岛素能促进乙酰辅酶A羧化酶去磷酸化故可增强其活性，从而加速脂肪酸合成"],"a":0,"e":"1分子软脂酸彻底氧化净生成106分子ATP，而1分子丙酮酸彻底氧化仅生成约12.5分子ATP，故该项所述的大小关系颠倒。"},{"q":"核小体是组成染色质的基本单位，它是由DNA和组蛋白构成。下面对核小体构成成分的描述正确的是","o":["目前已知核小体由DNA和非组蛋白共同构成","目前已知核小体由DNA和H1，H2，H3，H4各1分子构成","目前已知构成核小体的组蛋白种类有H1，H2A，H2B，H3和H4","目前已知核小体由DNA和H1，H2，H3，H4各2分子构成","目前已知构成核小体的组蛋白是由组氨酸构成的蛋白质"],"a":2,"e":"核小体由DNA与组蛋白构成，组蛋白有H1、H2A、H2B、H3和H4五种，其中H2A、H2B、H3、H4各两分子构成八聚体核心。"},{"q":"以病毒DNA为载体，将目的基因导入哺乳动物细胞的过程称","o":["感染","转导","转化","转染","转位"],"a":0,"e":"以病毒颗粒作为外源DNA运载体导入宿主细胞的过程称感染，而将裸露DNA导入真核细胞称转染。"},{"q":"糖原合成时，下列哪一个是葡萄糖供体","o":["葡萄糖","6-磷酸葡萄糖","UDPG","CDPG","1-磷酸葡萄糖"],"a":2,"e":"UDPG可看作活性葡萄糖，在体内充当葡萄糖供体，由UDPG焦磷酸化酶催化葡萄糖-1-磷酸与UTP反应生成。糖原合酶利用UDPG中的葡萄糖基延伸糖链。"},{"q":"对于p53蛋白的描述，错误的是","o":["突变后可致癌","能引发修复失败的细胞程序自杀","有“基因卫士”的称号","有转录因子作用","能激活解链酶"],"a":4,"e":"p53是抑癌基因产物，作为转录因子在DNA损伤时启动p21等基因表达，使细胞周期停滞或凋亡，被称为基因组卫士，并无激活解链酶的作用。"},{"q":"谷丙转氨酶的辅酶是","o":["NAD+","NADP+","磷酸吡哆醛","烟酸","核黄素"],"a":2,"e":"谷丙转氨酶的辅基是维生素B6的磷酸酯即磷酸吡哆醛，反应中在磷酸吡哆醛与磷酸吡哆胺之间转变以传递氨基。"},{"q":"参与酮体生成和胆固醇合成的共同中间产物是","o":["乙酰CoA","羟甲基戊二酸单酰CoA","甲羟戊酸","乙酰乙酸","异戊烯焦磷酸"],"a":1,"e":"酮体生成中2分子乙酰CoA缩合生成乙酰乙酰CoA，再与乙酰CoA缩合生成HMG-CoA；胆固醇合成同样以HMG-CoA为中间产物。甲羟戊酸是胆固醇合成特有中间物。"},{"q":"DNA完整克隆过程由哪些步骤组成","o":["载体和目的基因分离、提纯和鉴定","分、选、连、转、筛","将重组体导入宿主细胞，筛出含目的基因菌株","将载体和目的基因连接成重组体","限制性内切核酸酶的应用"],"a":1,"e":"完整DNA克隆包括目的DNA分离获取、载体选择与构建、目的基因与载体连接、重组DNA导入受体细胞及重组体筛选鉴定五个步骤。"},{"q":"与碳酸酐酶作用有关的元素是","o":["锌","铁","铜","硒","锰"],"a":0,"e":"碳酸酐酶是含锌金属酶，锌为其催化活性所必需，可催化CO2与水可逆生成碳酸，参与CO2运输和酸碱平衡调节。"},{"q":"N-连接型聚糖的合成不需要","o":["糖基化位点Asn-X-Ser/Thr","长萜醇载体","活化的单糖","五糖核心","富含脯氨酸的序列"],"a":4,"e":"N-连接型聚糖合成需糖基化位点Asn-X-Ser/Thr、长萜醇载体、活化单糖和五糖核心；富含脯氨酸序列与O-连接型糖基化位点有关。"},{"q":"苯丙酮尿症（PKU）是一种常见的婴儿疾病。这种疾病是由于缺失将苯丙氨酸水解成酪氨酸所需的苯丙氨酸水解酶基因，导致血液中苯丙氨酸累积造成的。若是不能及时检测出这种天生的代谢缺乏，在婴儿出生后9个月内，就会引起无法挽救的大脑损伤。采用下述何种技术可检测患者血清苯丙氨酸含量","o":["液相/质谱技术","二维电泳/质谱技术","串联质谱技术","生物芯片技术","紫外分光技术"],"a":0,"e":"液相色谱与质谱联用可对血清中苯丙氨酸等氨基酸进行准确定量，标本用量少、灵敏度高，适于新生儿筛查。"},{"q":"下列有关生物转化作用的叙述，哪项是正确的","o":["被转化的是营养性物质","被转化的是NADH","被转化的是FADH2","被转化的是NADPH","被转化的是非营养性物质"],"a":4,"e":"生物转化处理的是内源性和外源性非营养物质，使其水溶性增加而便于经胆汁或尿排出；糖、脂、蛋白质等营养性物质不属其对象。"},{"q":"合成CM的主要场所在","o":["小肠","肝","血浆","脑","脂肪组织"],"a":0,"e":"乳糜微粒在小肠黏膜细胞以吸收的甘油一酯和脂肪酸合成甘油三酯，再组装载脂蛋白B48而成，经淋巴入血。"},{"q":"乙酰CoA从线粒体基质进入细胞质通过","o":["柠檬酸-丙酮酸循环","苹果酸-天冬氨酸穿梭","嘌呤核苷酸循环","乳酸循环","葡萄糖-丙氨酸循环"],"a":0,"e":"乙酰CoA不能自由透过线粒体内膜，需经柠檬酸-丙酮酸循环以柠檬酸形式运至细胞质，再裂解释出乙酰CoA供脂肪酸合成。苹果酸-天冬氨酸穿梭用于转运还原当量。"},{"q":"乙酰辅酶A在细胞质中合成一分子软脂酸时需要NADPH的分子数是","o":["10","12","14","16","18"],"a":2,"e":"合成一分子软脂酸需7次循环，每次消耗2分子NADPH，共14分子NADPH，同时消耗8分子乙酰CoA和7分子ATP。"},{"q":"关于氨基酸代谢的错误论述是","o":["氨基酸的吸收是耗能的主动转运","氨基酸经脱氨基后生成α-酮酸和氨","转氨基作用是各种氨基酸共有的代谢途径","氨基酸脱氨基的主要方式是联合脱氨基作用","通过氨基酸脱羧，可以合成一些重要的含氮化合物"],"a":2,"e":"赖氨酸、苏氨酸、脯氨酸及羟脯氨酸不能进行转氨基作用，故转氨基并非各种氨基酸共有的代谢途径；脱氨基的主要方式是联合脱氨基作用。"},{"q":"蛋白质二级结构中，不存在的构象是","o":["α-螺旋","锌指","β-折叠","β-转角","Ω环"],"a":1,"e":"锌指是蛋白质三级结构中的结构模体，由α-螺旋和两个反平行β-折叠组成；二级结构仅指α-螺旋、β-折叠、β-转角和Ω环等局部构象。"},{"q":"下列对结合胆红素的叙述哪一项是错误的","o":["主要是双葡萄糖醛酸胆红素","与重氮试剂呈间接反应","水溶性大","随正常人尿液排出","不易透过生物膜"],"a":1,"e":"结合胆红素由胆红素与葡萄糖醛酸结合生成，分子内氢键被破坏，能直接与重氮试剂呈直接反应；间接反应是未结合胆红素的特点。"},{"q":"线粒体DNA","o":["通常成双股线形","与组蛋白相结合","为线粒体核糖体的rRNA编码","编码三羧酸循环的酶","有损伤修复系统"],"a":2,"e":"线粒体DNA为环状双链，无组蛋白结合，可编码线粒体核糖体的rRNA及部分蛋白质亚基。三羧酸循环的酶由核基因编码。"},{"q":"功能基因组学不包含下列哪项内容","o":["分析基因组DNA序列中的编码序列的功能","分析基因组DNA序列中的非编码序列的功能","测定基因组DNA序列","分析基因组调控的网络及机制","利用基因芯片研究基因组表达谱"],"a":2,"e":"功能基因组学研究基因组的表达、功能注释及表达调控网络，测定基因组DNA序列属结构基因组学的任务。"},{"q":"氨基酸分解产生的氨在体内储存及运输的主要形式是","o":["天冬酰胺","谷氨酸","尿素","谷胱甘肽","谷氨酰胺"],"a":4,"e":"谷氨酰胺既是氨的解毒产物，又是氨的储存及运输形式，在脑和骨骼肌由谷氨酰胺合成酶催化生成，经血液运往肝或肾再分解释氨。尿素是氨的终产物而非运输形式。"},{"q":"真核生物线粒体DNA复制的主要酶是","o":["DNA聚合酶β","DNA聚合酶γ","DNA聚合酶δ","DNA聚合酶ε","DNA聚合酶α"],"a":1,"e":"真核生物线粒体DNA的复制由DNA聚合酶γ催化，该酶位于线粒体，不同于负责核DNA前导链和后随链合成的ε和δ。"},{"q":"关于6-巯基嘌呤的叙述，错误的是","o":["抑制IMP生成GMP","抑制IMP生成AMP","抑制次黄嘌呤生成IMP","抑制鸟嘌呤生成GMP","抑制腺苷生成AMP"],"a":4,"e":"6-MP经磷酸核糖化生成6-MP核苷酸，抑制IMP转变为AMP及GMP，并竞争性抑制次黄嘌呤-鸟嘌呤磷酸核糖转移酶而阻断补救合成；其不抑制腺苷生成AMP。"},{"q":"三羧酸循环中，下列哪一个酶是调控酶","o":["琥珀酸脱氢酶","延胡索酸酶","苹果酸脱氢酶","α-酮戊二酸脱氢酶","顺乌头酸酶"],"a":3,"e":"三羧酸循环主要受柠檬酸合酶、异柠檬酸脱氢酶和α-酮戊二酸脱氢酶复合体三个关键酶调控，其中后两者调节更为重要。琥珀酸脱氢酶、延胡索酸酶、苹果酸脱氢酶和顺乌头酸酶均不是关键酶。"},{"q":"下列关于ribozyme的叙述，正确的是","o":["即核酸酶","本质是蛋白质","本质是核糖核酸","其辅酶是辅酶A","即核酸外切酶"],"a":2,"e":"ribozyme即核酶，是具有催化功能的RNA分子，化学本质为核糖核酸。其发现源于四膜虫rRNA前体自我剪接，不需蛋白质参与。核酸酶是水解核酸的蛋白质酶类，与核酶本质不同。"},{"q":"正常人禁食12小时后，血浆中不含","o":["VLDL","HDL","LDL","IDL","CM"],"a":4,"e":"CM主要转运外源性甘油三酯，半衰期仅5～15分钟，故正常人空腹12～14小时后血浆中不含CM，而VLDL、IDL、LDL、HDL均存在。"},{"q":"电子传递链的组成成分不包括","o":["NAD＋","FMN","FAD","CoA","CoQ"],"a":3,"e":"电子传递链由复合体及泛醌、细胞色素c组成，辅基包括NAD+、FMN、FAD、铁硫中心，CoA不参与电子传递。"},{"q":"下列有关脂肪酸生物合成的叙述中，正确的是","o":["不需乙酰CoA","中间产物是丙二酰CoA","在线粒体内进行","所需的氢来自NADH","最终产物为10碳以下脂酸"],"a":1,"e":"脂肪酸合成的中间产物为丙二酰CoA，由乙酰CoA羧化生成，作为二碳单位供体参与缩合；合成在胞质溶胶进行，供氢体为NADPH。"},{"q":"胰岛素受体具有下列哪种酶的活性","o":["蛋白激酶A（PKA）","蛋白激酶G（PKG）","蛋白激酶C（PKC）","Ca2+-CaM依赖性蛋白激酶","酪氨酸蛋白激酶"],"a":4,"e":"胰岛素受体β亚基胞内结构域具有蛋白质激酶活性，可催化酪氨酸残基磷酸化；胰岛素与α亚基结合后激活β亚基的酪氨酸激酶活性，并催化受体自身磷酸化。"},{"q":"下列属于解偶联剂的是","o":["鱼藤酮","寡霉素","2,4-二硝基苯酚","ADP","AMP"],"a":2,"e":"2,4-二硝基苯酚是脂溶性解偶联剂，可在线粒体内膜两侧往返携带质子，破坏质子电化学梯度，使氧化与磷酸化脱偶联。"},{"q":"DNA载体的最基本性质是","o":["青霉素抗性","自我转录能力","自我复制能力","卡那霉素抗性","自我表达能力"],"a":2,"e":"载体必须能在宿主细胞内独立于染色体自我复制，才能携带目的基因稳定存在并传代，这是其最基本的性质。"},{"q":"肝细胞内合成胆固醇需参与的酶是","o":["磷脂酰胆碱-胆固醇酰基转移酶","HMG-CoA氧化酶","HMG-CoA还原酶","HMG-CoA裂解酶","脂酰COA-胆固醇酰基转移酶"],"a":2,"e":"胆固醇合成以HMG-CoA还原酶为关键酶，催化HMG-CoA还原生成甲羟戊酸，是整条通路的限速步骤。"},{"q":"下列关于P/O比值，叙述错误的是","o":["每消耗1个氧原子所消耗的无机磷的原子数","每消耗1个氧原子所消耗的ADP的分子数","每消耗1/2摩尔O2能生成的ATP的摩尔数","测定底物的P/O比值，可以推测其呼吸链中的偶联部位","琥珀酸通过Cyt c进入呼吸链，其P/O比值为2"],"a":4,"e":"琥珀酸经复合体Ⅱ（琥珀酸-泛醌还原酶）将电子交给泛醌，绕过复合体Ⅰ，故P/O比值约为1.5而非2；直接经Cyt c氧化的是抗坏血酸，比值约1。"},{"q":"酶促反应速率v达到最大反应速率Vmax的80%时，底物浓度[S]为","o":["1Km","2Km","3Km","4Km","5Km"],"a":3,"e":"由米氏方程v=Vmax[S]/(Km+[S])，当v为0.8Vmax时，[S]等于4Km，即底物浓度为Km的四倍。"},{"q":"关于肝细胞性黄疸，下列说法错误的是","o":["常见于肝实质性疾病，如肝炎，肝肿瘤等","肝脏处理胆红素能量下降","也称肝源性黄疸","尿胆红是阴性","血清结合和未结合胆红素都升高"],"a":3,"e":"肝细胞性黄疸时结合胆红素反流入血并经肾排出，尿胆红素呈阳性，故“阴性”的说法错误。"},{"q":"乙酰CoA不能参与的反应是","o":["氧化分解","合成糖原","生成酮体","合成脂酸","合成胆固醇"],"a":1,"e":"乙酰CoA可经三羧酸循环氧化供能，可羧化为丙二酸单酰CoA合成脂肪酸，也可合成胆固醇和酮体；糖原合成需葡萄糖经UDPG途径，乙酰CoA不能净合成糖。"},{"q":"关于核酸结构，叙述错误的是","o":["DNA双螺旋表面有一条大沟和一条小沟","DNA双螺旋结构中相邻碱基之间存在碱基堆积力","碱基位于DNA双螺旋内侧，碱基对形成一种近似平面的环形结构","与DNA相比，RNA种类繁多，分子量相对较大","RNA可形成局部双螺旋结构"],"a":3,"e":"RNA种类繁多但分子量通常较DNA小，DNA分子量更大。DNA双螺旋表面有大沟小沟，碱基位于内侧形成近似平面结构，相邻碱基间存在碱基堆积力，RNA可形成局部双螺旋。"},{"q":"反式作用因子指的是","o":["具有激活功能的调节蛋白","具有抑制功能的调节蛋白","能激活自身基因表达的调节蛋白","能抑制自身基因表达的调节蛋白","能调节另一基因表达的调节蛋白"],"a":4,"e":"反式作用因子由某一基因编码，经扩散后识别并结合另一基因的顺式作用元件，从而激活或抑制该基因转录；调节自身基因者称顺式作用蛋白。"},{"q":"正常染色体内可能存在某些抑制肿瘤发生的基因，它们的丢失、突变或失去功能，使激活的癌基因发挥作用而致癌。与人类肿瘤相关性最高的抑癌基因","o":["RB","P53","PTEN","P16","APC"],"a":1,"e":"TP53基因是迄今为止发现的与人类肿瘤相关性最高的抑癌基因，超过一半以上的人类肿瘤中发生其突变。其编码的p53蛋白具有转录因子活性，一个等位基因突变后可通过显性负效突变抑制野生型p53的功能。"},{"q":"作为目的基因载体的根本条件是","o":["可以独立复制","有多个切口","不能与细菌共存","不应该有基因标志","分子量大"],"a":0,"e":"载体作为携带目的基因的DNA分子，根本条件是能在受体细胞内独立复制，从而使目的基因得以扩增和传代。"},{"q":"有关RNA转录叙述错误的一项是","o":["是以DNA作为模板","遵从碱基配对的规律","新链的延伸方向都是5'→3'方向","核苷酸之间是通过磷酸二酯键相连","底物是NMP"],"a":4,"e":"RNA转录以DNA为模板，遵循碱基配对，新链沿5'→3'延伸，核苷酸间以磷酸二酯键相连，底物为NTP而非NMP。"},{"q":"关于同工酶的描述，错误的是","o":["是一组催化相同化学反应的酶","同工酶免疫学性质相同","酶分子活性中心结构相同","同工酶在体内各组织器官的分布不同","同工酶各成员Km值不同"],"a":1,"e":"同工酶的免疫学特性各不相同，可用免疫学方法加以区分，故“免疫学性质相同”的说法错误。"},{"q":"以下哪一项不属于基因工程中的常用酶","o":["限制性核酸内切酶","DNA聚合酶","DNA连接酶","反转录酶","拓扑异构酶"],"a":4,"e":"重组DNA技术常用工具酶包括限制性核酸内切酶、DNA连接酶、DNA聚合酶、逆转录酶等；拓扑异构酶参与体内DNA复制解链时超螺旋的转型，不属于基因工程常用工具酶。"},{"q":"氰化钾抑制的是","o":["细胞色素c","细胞色素c氧化酶","超氧化物歧化酶","ATP酶","铜离子"],"a":1,"e":"氰化物与复合体Ⅳ中氧化型Cyta3紧密结合，阻断电子由Cyta向CuB-Cyta3的传递，使细胞色素c氧化酶失活、呼吸链中断。"},{"q":"关于谷胱甘肽的叙述，正确的是","o":["是体内重要的氧化剂","含有胱氨酸","其中的谷氨酸α-羧基是游离的","C端羧基是主要的功能基团","所含的肽键均为α-肽键"],"a":2,"e":"谷胱甘肽由谷氨酸、半胱氨酸和甘氨酸组成，第一肽键由谷氨酸γ-羧基形成，其α-羧基游离，半胱氨酸巯基为主要功能基团。"},{"q":"阿糖胞苷抗癌的机制是","o":["类似谷氨酰胺，抑制CTP合成","干扰叶酸代谢","抑制CDP还原成dCDP","使dUMP不能利用一碳单位甲基化生成dTMP","干扰叶酸对一碳单位的运输"],"a":2,"e":"阿糖胞苷是嘧啶类似物，抑制核糖核苷酸还原酶，阻断CDP还原为dCDP，从而抑制DNA合成。"},{"q":"氧化磷酸化的化学渗透假说提出关于ATP形成的原因是","o":["线粒体内膜对ADP渗透性的变化造成的","ADP泵出基质进入膜间隙所致","线粒体蛋白质中形成高能键所","H+被泵出形成线粒体内膜内外质子电化学梯度所致","H+被泵出形成线粒体外膜内外质子电化学梯度所致"],"a":3,"e":"化学渗透假说认为呼吸链将H+从基质泵至膜间隙，形成跨线粒体内膜的质子电化学梯度，质子回流时驱动ATP合酶合成ATP。"},{"q":"蛋白质分子的结构单元是","o":["氢键","肽键平面","肽键","氨基酸残基","二硫键"],"a":1,"e":"肽键平面（肽单元）由Cα1、C、O、N、H、Cα2六个原子共处同一平面构成，是蛋白质二级结构的基本结构单元；氨基酸残基是蛋白质的组成单位，肽键仅为连接方式。"},{"q":"甘油氧化分解和糖分解代谢的共同中间产物是","o":["3-磷酸甘油","β-羟丁酸","磷酸二羟丙酮","乳酸","乙酰乙酸"],"a":2,"e":"甘油在肝内磷酸化生成3-磷酸甘油，脱氢后生成磷酸二羟丙酮而进入糖酵解，故磷酸二羟丙酮是甘油与糖分解代谢的共同中间产物。"},{"q":"人类基因组比大肠杆菌基因组大700倍左右，然而，人类基因组复制的时间仅比大肠杆菌基因组复制长6～8倍。这是因为","o":["组蛋白的存在提高了人染色体DNA的复制速率","人类基因组的GC含量低，两条链更容易解链","人基因组的许多序列在复制中直接跳过去，因为只有3%～5%的序列编码蛋白质","人染色体DNA上具有多个复制起始区，大肠杆菌只有一个","人DNA复制经过整个细胞周期，而大肠杆菌的DNA复制每小时启动一次"],"a":3,"e":"真核生物染色体DNA有多个复制起点，可同时从多个位点双向复制形成多个复制泡，从而缩短庞大基因组的总复制时间。"},{"q":"大鼠饲以去脂膳食一段时间后，其体内主要缺乏的是","o":["磷脂酰胆碱","磷脂酰乙醇胺","前列腺素","胆固醇","1,25-(OH)2D3"],"a":2,"e":"必需脂肪酸是前列腺素、血栓烷和白三烯等廿碳多不饱和脂肪酸衍生物的前体，去脂膳食致亚油酸缺乏，前列腺素合成因而明显减少。"},{"q":"与G蛋白偶联的受体是","o":["环状受体","7个跨膜螺旋受体","催化性受体","细胞核内受体","细胞质内受体"],"a":1,"e":"G蛋白偶联受体为单体蛋白，肽链反复跨膜七次，又称七次跨膜受体，其胞内部分与异源三聚体G蛋白偶联。"},{"q":"1965年澳大利亚科学家发现，结扎鼠门静脉后，电镜观察到肝实质组织中有一些散在的死亡细胞，这些细胞的溶酶体并未被破坏，显然不同于细胞坏死。这些细胞体积收缩、染色质凝集，从其周围的组织中脱落并被吞噬，机体无炎症反应。1972年Kerr等三位科学家首次提出了细胞凋亡的概念。关于细胞凋亡的叙述中，错误的是","o":["某种信号触发的过程","细胞按一定程序缓慢死亡","可诱导肿瘤发生","某些癌基因具有抑制凋亡的作用","生理病理条件下均可发生"],"a":2,"e":"凋亡是受基因编程的主动死亡过程，可清除DNA损伤细胞，从而避免而非诱导肿瘤发生；癌基因激活抑制凋亡、凋亡异常减弱才与肿瘤发生发展相关。"},{"q":"下列维生素中哪种分子中无环状结构","o":["烟酸","叶酸","胆钙化醇","泛酸","生物素"],"a":3,"e":"泛酸由二甲基羟丁酸和β-丙氨酸组成，为链状结构，不含环状结构，其活性形式为辅酶A和酰基载体蛋白。烟酸、叶酸、胆钙化醇、生物素均含环状结构。"},{"q":"竞争性抑制剂对酶促反应速率的影响是","o":["Km升高，Vmax不变","Km下降，Vmax下降","Km不变，Vmax下降","Km下降，Vmax升高","Km下降，Vmax不变"],"a":0,"e":"竞争性抑制剂与底物竞争酶的活性中心，增加底物浓度可解除抑制，表现为表观Km增大而Vmax不变。"},{"q":"DNA水解的最终产物中，不包括","o":["磷酸","嘌呤碱","脱氧核糖","嘧啶碱","腺苷"],"a":4,"e":"DNA水解的最终产物为磷酸、脱氧核糖、嘌呤碱和嘧啶碱。腺苷是腺嘌呤与核糖形成的核苷，属RNA水解产物，不含于DNA水解产物中。"},{"q":"真核生物转录发生的部位是","o":["线粒体","细胞质","细胞核","内质网","微粒体"],"a":2,"e":"真核生物转录发生在细胞核，翻译在细胞质，两过程分隔进行。原核细胞无细胞核，转录与翻译在同一空间偶联进行。"},{"q":"关于痛风症，描述错误的是","o":["分为原发性和继发性两种","原发性痛风多有遗传性","继发性痛风是继发于其他疾病过程中的一种临床表现，也可由于药物导致","女性发病多见于中年","最重要的生化基础是高尿素血症"],"a":4,"e":"痛风症最重要的生化基础是高尿酸血症而非高尿素血症，尿酸盐结晶沉积于关节而致病；原发性者多有遗传性，继发性者可继发于血液病或由药物引起。"},{"q":"下列关于由核糖核苷酸还原成脱氧核糖核苷酸的叙述，错误的是","o":["4种核苷酸都涉及相同的还原酶体系","多发生在二磷酸核苷水平上","还原酶系包括氧化还原蛋白和硫氧化还原蛋白还原酶","GSSG/GSH参与","以上都对"],"a":3,"e":"核糖核苷酸还原酶体系催化NDP还原为dNDP，需硫氧化还原蛋白及硫氧化还原蛋白还原酶传递氢，NADPH为其供氢体，GSSG/GSH不参与该还原过程。"},{"q":"下列直接抑制转肽酶的抗生素是","o":["放线菌酮","四环素","土霉素","链霉素和卡那霉素","利福平"],"a":0,"e":"放线菌酮特异性抑制真核生物核糖体大亚基的肽酰转移酶，阻断肽键形成；四环素、链霉素作用于原核核糖体小亚基，利福平抑制原核RNA聚合酶。"},{"q":"脂肪酸合成时所需的氢来自","o":["NADH","NADPH","FADH2","FMNH2","UQH2"],"a":1,"e":"脂肪酸合成的还原反应由NADPH供氢，NADPH主要来自磷酸戊糖途径，胞质苹果酸酶也可提供少量。"},{"q":"能直接进行氧化脱氨基作用的氨基酸是","o":["甘氨酸","天冬氨酸","谷氨酸","丝氨酸","丙氨酸"],"a":2,"e":"谷氨酸是体内唯一能直接进行氧化脱氨基作用的氨基酸，由L-谷氨酸脱氢酶催化，其余氨基酸多需先转氨基。"},{"q":"Alu高度重复序列","o":["在人的基因组中广泛存在","具有组织特异性","在原核生物基因组中存在","包含限制性内切核酸酶EcoRⅠ的切点","与转录调控有关"],"a":0,"e":"Alu序列是人类基因组中拷贝数最多的短散在重复序列，长约300bp，属高度重复序列，广泛分布于基因组中且不编码蛋白质。"},{"q":"构成需氧脱氢酶辅酶的维生素是","o":["生物素","硫胺素","谷胺素","磷酸吡哆醛","核黄素"],"a":4,"e":"需氧脱氢酶的辅基FMN和FAD由维生素B2即核黄素转变而来，通过异咯嗪环可逆地加氢与脱氢。"},{"q":"线粒体外脂肪酸合成的限速酶是","o":["脂酰CoA合成酶","乙酰CoA羧化酶","肉碱脂酰转移酶Ⅰ","肉碱脂酰转移酶Ⅱ","β-酮脂酰还原酶"],"a":1,"e":"脂肪酸合成在胞质溶胶进行，乙酰CoA羧化酶催化乙酰CoA羧化为丙二酰CoA，是该途径的限速酶，受柠檬酸别构激活、脂酰CoA抑制。"},{"q":"关于真核生物的TATA盒叙述，正确的是","o":["RNA聚合酶与DNA模板稳定结合处","转录起始点","RNA聚合酶的活性中心","转录终止位点","DNA合成的起始位点"],"a":0,"e":"TATA盒位于转录起始点上游约-25bp处，是RNA聚合酶与DNA模板稳定结合并确定转录起始位置的核心序列。"},{"q":"关于天冬氨酸氨基甲酰基转移酶的下列说法，错误的是","o":["CTP是其反馈抑制剂","是嘧啶核苷酸从头合成的调节酶","由多个亚基组成","是变构酶","服从米-曼氏方程"],"a":4,"e":"该酶是嘧啶核苷酸从头合成的调节酶，由多个亚基组成并受CTP反馈抑制，属别构酶，动力学曲线呈S形，不服从米-曼氏方程。"},{"q":"下列哪种物质是甘油磷脂合成必须参加的物质","o":["CTP","UTP","UMP","GMP","TDP"],"a":0,"e":"甘油磷脂合成需ATP供能，CTP参与胆碱、乙醇胺和甘油二酯的活化，生成CDP-胆碱、CDP-乙醇胺和CDP-甘油二酯等中间物。"},{"q":"糖酵解中，下列哪一个酶催化的反应是限速反应","o":["丙酮酸激酶","6-磷酸果糖激酶-1","己糖激酶","磷酸丙糖异构酶","醛缩酶"],"a":1,"e":"磷酸果糖激酶-1催化的反应不可逆且反应速率最慢，是糖酵解流量的首要调控点，也是糖酵解的限速步骤。"},{"q":"可经脱氨基作用直接生成α-酮戊二酸的氨基酸是","o":["丙氨酸","谷氨酸","丝氨酸","色氨酸","甘氨酸"],"a":1,"e":"谷氨酸经L-谷氨酸脱氢酶催化氧化脱氨，直接生成α-酮戊二酸和氨，该酶广泛存在于肝、肾和脑组织。"},{"q":"原核基因表达调控涉及衰减子的是","o":["乳糖操纵子的阻遏蛋白","阿拉伯糖操纵子的阻遏蛋白","色氨酸操纵子的阻遏蛋白","大肠杆菌的Lex阻遏蛋白","沙门氏菌鞭毛素基因阻遏蛋白"],"a":2,"e":"色氨酸操纵子除阻遏蛋白的粗调外，其前导序列中的衰减子随色氨酸浓度升高而终止转录，起精调作用。"},{"q":"关于限制性内切酶的叙述，错误的是","o":["能识别DN特定的碱基顺序并在特定的位点切开DNA","能专一降解经甲基化修饰的DNA","主要从细菌中获得","重组DNA的重要工具酶","切割点附近的碱基顺序一般呈回文结构"],"a":1,"e":"限制酶由细菌产生，识别回文序列并定点切割外源DNA，是重组DNA的重要工具酶；细菌自身DNA经甲基化修饰而受保护，不被自身限制酶降解。"}];
